        printf("Total number of lines: %d\n", num_lines);
    } else if (strcmp(argv[1], "--copy-data") == 0) {
        // Copy specified number of bytes from source to destination without modifying the original data
        char *source = argv[2];
        char *destination = argv[3];
        int num_bytes = atoi(argv[4]);
        FILE *fp1 = fopen(source, "r");
        if (fp1 == NULL) {
