class ConnectionPool {
public:
    // Constructor
    ConnectionPool(const std::string& dbType, const std::string& hostname, const int port, const std::string& username, const std::string& password)
        : dbType_(dbType), hostname_(hostname), port_(port), username_(username), password_(password) {
        // Initialize the connection pool with a fixed number of connections
        numConnections_ = 10;
        connections_.reserve(numConnections_);

        for (int i = 0; i < numConnections_; ++i) {
            connections_.push_back(std::make_unique<Connection>(dbType_, hostname_, port_, username_, password_));
        }
    }

    // Destructor
    ~ConnectionPool() {
        // Close all connections in the pool
        for (auto& connection : connections_) {
            connection->close();
        }
    }

    // Get a connection from the pool
    Connection* getConnection() {
        std::lock_guard<std::mutex> lock(mutex_);

        if (!connections_.empty()) {
            auto connection = connections_.front().release();
            connections_.pop_front();
            return connection;
        } else {
            // If the pool is empty, create a new connection and add it to the pool
            auto connection = std::make_unique<Connection>(dbType_, hostname_, port_, username_, password_);
            connections_.push_back(std::move(connection));
            return connections_.back().get();
        }
    }

    // Return a connection to the pool
    void returnConnection(Connection* connection) {
        std::lock_guard<std::mutex> lock(mutex_);
        connections_.push_front(std::unique_ptr<Connection>(connection));
    }

private:
    class Connection {
    public:
        // Constructor
        Connection(const std::string& dbType, const std::string& hostname, const int port, const std::string& username, const std::string& password)
            : dbType_(dbType), hostname_(hostname), port_(port), username_(username), password_(password) {
        }

