} EncryptionParams;

// Function to initialize the encryption context
int initEncryption(EncryptionParams *params, const unsigned char *key, int keylen) {
    // Check if key is valid
    if (keylen != 16) {
        return -1;
    }

    // Initialize the encryption context
    EVP_CIPHER_CTX_init(params->ctx);

    // Set the cipher mode and key length
    EVP_EncryptInit_ex(params->ctx, "AES-128-ECB", NULL, key, keylen);

