}

// Function to encrypt data using the encryption context
int encryptData(EncryptionParams *params, const unsigned char *data, int datalen) {
    // Check if data is valid
    if (datalen < 0 || data == NULL) {
        return -1;
    }

    // Encrypt the data using the encryption context
    EVP_EncryptUpdate(params->ctx, params->key, datalen);

    return 0;
}

// Function to decrypt data using the encryption context
