    if (inputFile == NULL) {
        printf("Error: Unable to open input file.\n");
        return -1;
    }
    char buffer[BUFSIZ];
    while (!feof(inputFile)) {
        size_t bytesRead = fread(buffer, 1, BUFSIZ, inputFile);
        if (bytesRead > 0) {
            // Encrypt the data
