  int rc = SSL_connect(ssl);

  if (rc <= 0) {
    SSL_free(ssl);
    return ERROR_CONNECTION_FAILED;
  }

  // Check for any errors during the connection establishment process
  long ssl_error = SSL_get_error(ssl, rc);

  if (ssl_error != SSL_ERROR_NONE) {
    SSL_free(ssl);
    return ERROR_INVALID_PARAMETER;
  }

  // Update the backend service connection structure with the new SSL object and network condition
  backend_service_connections[backend_service_index].ssl = ssl;
  backend_service_connections[backend_service_index].current_network_condition = current_network_condition;

  return ERROR_NO_ERROR;
}

// Closes a connection to a specific backend service
