  if (ssl == NULL) {
    return ERROR_INVALID_PARAMETER;
  }

  // Send the data to the client using the SSL object
  int rc = SSL_write(ssl, data, length);

  if (rc <= 0) {
    return ERROR_CONNECTION_FAILED;
  }

  return ERROR_NO_ERROR;
}

// Receives data from a specific backend service connection
error_code_t receive_data(int backend_service_index, char* buffer, size_t length) {
  // Get the SSL object for the backend service connection
  SSL* ssl = backend_service_connections[backend_service_index].ssl;

