#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

// Define constants for the semaphore initial value, name, and logging level
#define INITIAL_VALUE 500
#define SEMAPHORE_NAME "my_semaphore"
#define LOGGING_LEVEL 2

// Structure to store thread-specific data
typedef struct {
    pthread_t thread;
    sem_t *semaphore;
} thread_data_t;

// Function to initialize the semaphore with an initial value
int init_semaphore(int initial_value) {
    int ret = 0;
    sem_t *semaphore = NULL;

    // Create a new semaphore with the given initial value
    if ((semaphore = sem_open(SEMAPHORE_NAME, O_CREAT | O_EXCL, S_IRUSR | S_IWUSR, initial_value)) == SEM_FAILED) {
        ret = -1;
        goto cleanup;
    }

cleanup:
    if (ret != 0) {
        // Close the semaphore on error
        sem_close(semaphore);
        // Unlink the semaphore from the file system
        sem_unlink(SEMAPHORE_NAME);
    }

    return ret;
}

// Function to acquire a semaphore token
int acquire_semaphore(thread_data_t *td) {
    int ret = 0;

    // Acquire a token from the semaphore
    if (sem_wait(td->semaphore) == -1) {
        ret = -1;
        goto cleanup;
    }

cleanup:
    return ret;
}

// Function to release a semaphore token
int release_semaphore(thread_data_t *td) {
    int ret = 0;

    // Release a token from the semaphore
    if (sem_post(td->semaphore) == -1) {
        ret = -1;
        goto cleanup;
    }

cleanup:
    return ret;
}

// Function to delete a semaphore
int delete_semaphore(thread_data_t *td) {
    int ret = 0;

    // Close the semaphore
    if (sem_close(td->semaphore) == -1) {
        ret = -1;
        goto cleanup;
    }

    // Unlink the semaphore from the file system
    if (sem_unlink(SEMAPHORE_NAME) == -1) {
        ret = -1;
        goto cleanup;
    }

cleanup:
    return ret;
}

// Function to handle errors during semaphore operations
void error_handler(int err, char *message) {
    if (err != 0) {
        perror(message);
    }
}

// Function to perform a task in a thread-safe manner
void do_task(thread_data_t *td) {
    // Acquire a token from the semaphore
    acquire_semaphore(td);

    // Perform the task
    printf("Thread %lu: Task\n", td->thread);

    // Release a token to the semaphore
    release_semaphore(td);
}

// Function to clean up resources when a thread exits
void exit_handler(thread_data_t *td) {
    // Delete the semaphore
    delete_semaphore(td);

    // Log the exit
    printf("Thread %lu: Exiting\n", td->thread);
}

// Main function to implement the multi-threaded program
int main() {
    int ret = 0;

    // Initialize the semaphore with an initial value
    if ((ret = init_semaphore(INITIAL_VALUE)) != 0) {
        error_handler(ret, "Semaphore initialization failed");
        goto cleanup;
    }

    // Define a thread-specific data structure for each thread
    thread_data_t td[5];
    for (int i = 0; i < 5; i++) {
        td[i].thread = i;
        td[i].semaphore = sem_open(SEMAPHORE_NAME, O_RDWR);
        if (td[i].semaphore == SEM_FAILED) {
            ret = -1;
            goto cleanup;
        }
    }

    // Create a new thread for each task
    pthread_t thread[5];
    for (int i = 0; i < 5; i++) {
        if ((ret = pthread_create(&thread[i], NULL, do_task, &td[i])) != 0) {
            error_handler(ret, "Thread creation failed");
            goto cleanup;
        }
    }

    // Wait for all threads to finish
    for (int i = 0; i < 5; i++) {
        if ((ret = pthread_join(thread[i], NULL)) != 0) {
            error_handler(ret, "Thread join failed");
            goto cleanup;
        }
    }

cleanup:
    // Clean up resources when necessary
    for (int i = 0; i < 5; i++) {
        exit_handler(&td[i]);
    }

    return ret;
}']

