        let mut reader = BufReader::new(File::open(file)?);
        loop {
            match reader.read_line(&mut llvm_ir) {
                Ok(0) => break, // EOF
                Ok(_) => {},   // Continue reading
                Err(e) => return Err(Box::new(e)),
            }
            // Process the line of LLVM IR
        }
        Ok(())
    }
}

