using namespace std;

bool insertOrLog(const list<string>& strList, const string& targetStr, const string& insertionStr, bool logOnError) {
    // Check if the target string is in the list
    auto it = find(strList.begin(), strList.end(), targetStr);
    if (it == strList.end()) {
        // If not found, append the insertion string to the end of the list
        strList.push_back(insertionStr);
        return true;
    } else {
        // If found, insert the insertion string immediately after the target string
        auto nextIt = it + 1;
        strList.insert(nextIt, insertionStr);
        return true;
    }
}
