  void start() {
    // Initialize the timer for fetching VM status updates
    steady_clock::time_point nextFetchTime = steady_clock::now();
    while (true) {
      // Fetch VM status updates and store them in a local database
      fetchVMStatusUpdates();

      // Log all significant events, including successful updates, retries, and failures
      logEvents();

