    req.target(config_.get<string>("api.path"));
    req.method(request::POST);
    req.body() = "{\"type\": \"VM_STATUS_UPDATE\"}";

    response res;
    boost::asio::write(socket, boost::asio::buffer(req));
    boost::asio::read(socket, boost::asio::buffer(res));

    if (res.result() != response::ok) {
      cout << "Error fetching VM status updates: " << res.body() << endl;
      retryCount_++;
      return;
