    // Parse the JSON response and store the VM status updates in a local database
    ptree pt;
    std::stringstream ss(res.body());
    try {
      boost::property_tree::read_json(ss, pt);
    } catch (const boost::property_tree::json_parser::json_parser_error& e) {
      cout << "Error parsing JSON response: " << e.what() << endl;
      retryCount_++;
      return;
    }

    for (auto it = pt.begin(); it != pt.end(); ++it) {
      // Store the VM status update in a local database
      string vmName = it->second.get<string>("vmName");
      string vmId = it->second.get<string>("vmId");
      bool isActive = it->second.get<bool>("isActive");
      storeVMStatusUpdate(vmName, vmId, isActive);
    }
  }

