    public static class QueryExecutor
    {
        // Validate the connection parameters and external services availability
        private static bool CheckConnectionParameters(DbContext dbContext, string queryTemplate, List<object> paramValues)
        {
            // Validate the DbContext instance and database server connection
            if (dbContext == null || !dbContext.Database.CanConnect())
            {
                return false;
            }

            // Validate the query template syntax and complexity
            if (!IsValidQueryTemplate(queryTemplate))
            {
                return false;
            }

            // Check if all required external services are available and responsive
            if (!AreExternalServicesAvailable())
            {
                return false;
            }

            return true;
        }

        // Execute a parameterized SQL query asynchronously against a specified SQL Server instance
        public static async Task<List<T>> ExecuteParameterizedQueryAsync<T>(DbContext dbContext, string queryTemplate, List<object> paramValues, Action<Exception> errorHandler) where T : class
        {
            // Validate the input parameters and external services availability
            if (!CheckConnectionParameters(dbContext, queryTemplate, paramValues))
            {
                throw new Exception("Invalid connection parameters or external services unavailable");
            }

            // Prepare the SQL query with parameter values
            var query = ReplaceQueryParameters(queryTemplate, paramValues);

            // Execute the SQL query asynchronously and handle any errors
            try
            {
                return await dbContext.Database.ExecuteSqlRawAsync<T>(query);
            }
            catch (Exception ex)
            {
                errorHandler?.Invoke(ex);
                return null;
            }
        }

        // Replace query placeholders with parameter values
        private static string ReplaceQueryParameters(string queryTemplate, List<object> paramValues)
        {
            for (var i = 0; i < paramValues.Count; i++)
            {
                queryTemplate = queryTemplate.Replace($"{{{i}}}", paramValues[i].ToString());
            }
            return queryTemplate;
        }

        // Validate the SQL query template syntax and complexity
        private static bool IsValidQueryTemplate(string queryTemplate)
        {
            // TODO: Implement a more robust query syntax checker
            if (queryTemplate.Contains("'") || queryTemplate.Contains("--"))
            {
                return false;
            }
            return true;
        }

        // Check if all required external services are available and responsive
        private static bool AreExternalServicesAvailable()
        {
            // TODO: Implement a service availability checker
            return true;
        }
    }
}
