package com.example.service;

import org.springframework.stereotype.Service;
import org.springframework.web.client.RestTemplate;
import org.springframework.retry.RetryCallback;
import org.springframework.retry.support.RetryTemplate;
import org.springframework.cache.annotation.Cacheable;
import org.springframework.http.HttpMethod;
import org.springframework.http.ResponseEntity;
import com.example.models.Resource;

@Service
public class ResourceService {

    @Cacheable(value = "resourceCache")
    public Resource updateResource(String resourceId, Resource resource) {
        RestTemplate restTemplate = new RestTemplate();
        RetryTemplate retryTemplate = new RetryTemplate();

        ResponseEntity<Resource> responseEntity = null;
        try {
            responseEntity = (ResponseEntity<Resource>) retryTemplate.execute(
                    new RetryCallback<Object, RuntimeException>() {
                @Override
                public Object doWithRetry(RetryContext context) throws RuntimeException {
                    return restTemplate.exchange(
                            "https://api.example.com/resources/" + resourceId,
                            HttpMethod.PUT,
                            new HttpEntity<Resource>(resource),
                            Resource.class);
                }
            }, retryTemplate);
        } catch (RuntimeException e) {
            // handle error
        }

        if (responseEntity != null && responseEntity.getStatusCode().is2xxSuccessful()) {
            return responseEntity.getBody();
        } else {
            throw new RuntimeException("Error updating resource: " + resourceId);
        }
    }

    public void deleteResource(String resourceId) {
        RestTemplate restTemplate = new RestTemplate();
        RetryTemplate retryTemplate = new RetryTemplate();

        ResponseEntity<Object> responseEntity = null;
        try {
            responseEntity = (ResponseEntity<Object>) retryTemplate.execute(
                    new RetryCallback<Object, RuntimeException>() {
                @Override
                public Object doWithRetry(RetryContext context) throws RuntimeException {
                    return restTemplate.exchange(
                            "https://api.example.com/resources/" + resourceId,
                            HttpMethod.DELETE,
                            null,
                            Void.class);
                }
            }, retryTemplate);
        } catch (RuntimeException e) {
            // handle error
        }

        if (responseEntity != null && responseEntity.getStatusCode().is2xxSuccessful()) {
            return;
        } else {
            throw new RuntimeException("Error deleting resource: " + resourceId);
        }
    }
}
```
