<?php
// Define a class for the AccountManagementService
class AccountManagementService {
  private $db; // Database connection

  public function __construct($db) {
    $this->db = $db;
  }

  // GET /account/{id}
  public function getAccount($id) {
    $sql = "SELECT * FROM accounts WHERE id = ?";
    $stmt = $this->db->prepare($sql);
    $stmt->bind_param("i", $id);
    $stmt->execute();

    $result = $stmt->get_result()->fetch_assoc();
    return $result;
  }

  // POST /account/{id}
  public function createAccount($data) {
    $sql = "INSERT INTO accounts (username, password, email) VALUES (?, ?, ?)";
    $stmt = $this->db->prepare($sql);
    $stmt->bind_param("sss", $data["username"], $data["password"], $data["email"]);
    $stmt->execute();

    return array(
      "id" => $this->db->insert_id,
      "message" => "Account created successfully"
    );
  }

  // PUT /account/{id}
  public function updateAccount($data) {
    $sql = "UPDATE accounts SET username = ?, password = ?, email = ? WHERE id = ?";
    $stmt = $this->db->prepare($sql);
    $stmt->bind_param("sssi", $data["username"], $data["password"], $data["email"], $data["id"]);
    $stmt->execute();

    return array(
      "message" => "Account updated successfully"
    );
  }

  // DELETE /account/{id}
  public function deleteAccount($id) {
    $sql = "DELETE FROM accounts WHERE id = ?";
    $stmt = $this->db->prepare($sql);
    $stmt->bind_param("i", $id);
    $stmt->execute();

    return array(
      "message" => "Account deleted successfully"
    );
  }
}
