    public async Task<bool> PostAsync(string pageSectionId, string elementId, string htmlContent)
    {
        try
        {
            // Validate input and ensure element exists in specified page section
            if (string.IsNullOrEmpty(pageSectionId) || string.IsNullOrEmpty(elementId))
                return false;

            var cacheKey = $"{pageSectionId}:{elementId}";
            var cachedValue = _cache.GetOrAdd(cacheKey, htmlContent);

            if (cachedValue != htmlContent)
            {
                // Update element in external service and update cache
                await _service.UpdateElementAsync(pageSectionId, elementId, htmlContent);
                _cache[cacheKey] = htmlContent;
            }
        }
        catch (Exception ex)
        {
            // Handle network failures or transient errors gracefully by logging failed updates for later retry attempts
