/**
 * A class representing a DOM traversal library for efficiently collecting elements matching a specified CSS selector.
 */
export class DomTraversalLibrary {
  private element: Element;
  private querySelector: QuerySelector;
  private lazyLoadCache: LazyLoadCache;
  private concurrentUpdateManager: ConcurrentUpdateManager;

  /**
   * Creates a new instance of the DOM traversal library.
   * @param element The root element to start the traversal from.
   */
  constructor(element: Element) {
    this.element = element;
    this.querySelector = new QuerySelector();
    this.lazyLoadCache = new LazyLoadCache();
    this.concurrentUpdateManager = new ConcurrentUpdateManager();
  }

  /**
   * Returns an array of elements that match the specified CSS selector.
   * @param cssSelector The CSS selector to use for matching elements.
   */
  collectElements(cssSelector: string): Element[] {
    // Use the lazy load cache to store previously collected elements to reduce the number of DOM traversals.
    const cachedElements = this.lazyLoadCache.get(cssSelector);
    if (cachedElements) {
      return cachedElements;
    }

    // Use the concurrent update manager to handle concurrent updates and ensure thread safety.
    const elements: Element[] = [];
    this.concurrentUpdateManager.run(() => {
      // Traverse the DOM tree starting from the root element, collecting elements that match the specified CSS selector.
      traverse(this.element, (currentElement) => {
        if (this.querySelector.matches(currentElement, cssSelector)) {
          elements.push(currentElement);
        }
      });
    });

    // Store the collected elements in the lazy load cache for future use.
    this.lazyLoadCache.set(cssSelector, elements);

    return elements;
  }
}
