// Define the semaphore for managing concurrent updates
sem_t* updateClinicStatusSem;

// Initialize the semaphore with a value of 1
void initUpdateClinicStatus() {
    updateClinicStatusSem = sem_open("/updateClinicStatus", O_CREAT, 0644, 1);
}

// Clean up the semaphore when the function is finished
void cleanupUpdateClinicStatus() {
    if (updateClinicStatusSem != NULL) {
        sem_close(updateClinicStatusSem);
        sem_unlink("/updateClinicStatus");
    }
}

// Function to update the clinic status, last modified IP, and timestamp
void updateClinicStatus(int clinicId, int newStatus, char* ipAddress, time_t currentTime) {
    // Initialize the MySQL connection
    MYSQL* conn = mysql_init(NULL);
    if (conn == NULL) {
        printf("Error: Could not initialize MySQL connection\n");
        return;
    }

    // Connect to the database
    if (!mysql_real_connect(conn, "localhost", "username", "password", "database_name", 0, NULL, 0)) {
        printf("Error: Could not connect to MySQL database\n");
        mysql_close(conn);
        return;
    }

    // Prepare and execute the SQL statement to update the clinic record
    MYSQL_STMT* stmt = mysql_stmt_init(conn);
    if (!stmt) {
        printf("Error: Could not initialize MySQL statement\n");
        mysql_close(conn);
        return;
    }

    const char* query = "UPDATE clinics SET status=?, last_modified_ip=?, timestamp=? WHERE id=?";
    if (mysql_stmt_prepare(stmt, query, strlen(query))) {
        printf("Error: Could not prepare SQL statement\n");
        mysql_stmt_close(stmt);
        mysql_close(conn);
        return;
    }

    MYSQL_BIND bind[4];
    memset(bind, 0, sizeof(bind));

    // Set the parameters for the SQL statement
    int status = newStatus;
    char* ipAddressString = ipAddress;
    time_t timestamp = currentTime;
    int clinicIdInt = clinicId;

    bind[0].buffer_type = MYSQL_TYPE_LONG;
    bind[0].buffer = &status;
    bind[1].buffer_type = MYSQL_TYPE_STRING;
    bind[1].buffer = ipAddressString;
    bind[2].buffer_type = MYSQL_TYPE_TIMESTAMP;
    bind[2].buffer = &timestamp;
    bind[3].buffer_type = MYSQL_TYPE_LONG;
    bind[3].buffer = &clinicIdInt;

    // Execute the SQL statement with the parameters
    if (mysql_stmt_bind_param(stmt, bind)) {
        printf("Error: Could not bind parameters to SQL statement\n");
        mysql_stmt_close(stmt);
        mysql_close(conn);
        return;
    }

    if (mysql_stmt_execute(stmt)) {
        printf("Error: Could not execute SQL statement\n");
        mysql_stmt_close(stmt);
        mysql_close(conn);
        return;
    }

    // Get the result of the SQL statement
    MYSQL_RES* res = mysql_stmt_use_result(stmt);
    if (res == NULL) {
        printf("Error: Could not get result from SQL statement\n");
        mysql_stmt_close(stmt);
        mysql_close(conn);
        return;
    }

    // Check for any errors during the execution of the statement
    MYSQL_ERROR* error = mysql_stmt_error(stmt);
    if (error != NULL) {
        printf("Error: %s\n", error->message);
        mysql_free_result(res);
        mysql_stmt_close(stmt);
        mysql_close(conn);
        return;
    }

    // Clean up the resources used by the statement and connection
    mysql_free_result(res);
    mysql_stmt_close(stmt);
    mysql_close(conn);

    // Release the semaphore to allow other threads to update the clinic status
    sem_post(&updateClinicStatusSem);
}

// Function to handle errors during external API calls and retry logic if necessary
void handleApiError(char* url, char* error) {
    // Check if the error is a connection timeout or other temporary error
    if (strstr(error, "Connection timed out")) {
        printf("Warning: Connection timed out for %s\n", url);
        sleep(10); // Sleep for 10 seconds to retry the API call
        handleApiError(url, error); // Recursively call the function with the same parameters
    } else if (strstr(error, "Server is down")) {
        printf("Warning: Server is down for %s\n", url);
        sleep(10); // Sleep for 10 seconds to retry the API call
        handleApiError(url, error); // Recursively call the function with the same parameters
    } else if (strstr(error, "Connection refused")) {
        printf("Warning: Connection refused for %s\n", url);
        sleep(10); // Sleep for 10 seconds to retry the API call
        handleApiError(url, error); // Recursively call the function with the same parameters
    } else if (strstr(error, "Invalid IP address")) {
        printf("Warning: Invalid IP address for %s\n", url);
        sleep(10); // Sleep for 10 seconds to retry the API call
        handleApiError(url, error); // Recursively call the function with the same parameters
    } else if (strstr(error, "Invalid API key")) {
        printf("Warning: Invalid API key for %s\n", url);
        sleep(10); // Sleep for 10 seconds to retry the API call
        handleApiError(url, error); // Recursively call the function with the same parameters
    } else if (strstr(error, "Rate limit exceeded")) {
        printf("Warning: Rate limit exceeded for %s\n", url);
        sleep(10); // Sleep for 10 seconds to retry the API call
        handleApiError(url, error); // Recursively call the function with the same parameters
    } else {
        printf("Fatal: Unknown error encountered during API call\n");
        return;
    }
}

// Function to retrieve the current IP address from an external API
char* getCurrentIpAddress() {
    char* url = "https://api.ipify.org?format=json";
    // Make a GET request to the URL
    CURL* curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);
        curl_easy_setopt(curl, CURLOPT_NOPROGRESS, 1L);
        CURLcode res = curl_easy_perform(curl);
        // Check for any errors during the execution of the request
        if (res != CURLE_OK) {
            printf("Error: %s\n", curl_easy_strerror(res));
            handleApiError(url, curl_easy_strerror(res));
        }
        // Get the response from the API call
