};

// Implementation of the file processor that processes files in a directory
class FileProcessor {
 public:
  explicit FileProcessor(const string& dirname) : dirname_(dirname) {}

  void processFiles() {
    // Iterate over all files in the directory and extract metadata for each one
    for (auto& file : fs::directory_iterator(dirname_)) {
      try {
        FileMetadata metadata = extractMetadata(file.path());
        log(metadata);
      } catch (const exception& e) {
        logError("Error processing file " + file.path().string(), e);
      }
    }
  }

 private:
