    logger_.log("Processed file: " + metadata.filename + ", Creation time: " + to_string(metadata.creationTime) + ", Size: " + to_string(metadata.size) + ", MIME type: " + metadata.mimeType);
  }

  void logError(const string& message, const exception& e) {
