  int maxFilenameLength = 256; // Maximum filename length in characters
  string loggingLevel = "info"; // Logging level: info, debug, warn, error

  // Initialize the logging service
  Logger* logger = new FileLogger(loggingLevel);

  // Create a metadata extractor instance
  MetadataExtractor* metadataExtractor = new MetadataExtractor("http://metadata-service.com/extract");

  // Create a file processor instance
  FileProcessor* fileProcessor = new FileProcessor(dirname);

  // Set the logging service for the file processor
  fileProcessor->setLogger(*logger);

  // Set the metadata extractor for the file processor
  fileProcessor->setMetadataExtractor(*metadataExtractor);

  // Process all files in the directory
  fileProcessor->processFiles();

  return 0;
}']

