import java.util.concurrent.Semaphore;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class FileSystemInterface {
    private static final int MAX_CONCURRENT_THREADS = 10;
    private static final Semaphore semaphore = new Semaphore(MAX_CONCURRENT_THREADS);

    public void executeCommand(String command) throws Exception {
        Process process = Runtime.getRuntime().exec(command);
        int exitCode = process.waitFor();
        if (exitCode != 0) {
            throw new Exception("Command execution failed with exit code " + exitCode);
        }
    }

    public void deleteFile(String filePath) throws Exception {
        try {
            semaphore.acquire();
            executeCommand("rm -f " + filePath);
        } finally {
            semaphore.release();
        }
    }

    public void createFile(String filePath, String content) throws Exception {
        try {
            semaphore.acquire();
            executeCommand("echo \"" + content + "\" > " + filePath);
        } finally {
            semaphore.release();
        }
    }

    public void executeConcurrently(String[] commands) throws Exception {
        ExecutorService executor = Executors.newFixedThreadPool(MAX_CONCURRENT_THREADS);
        for (String command : commands) {
            executor.submit(() -> {
                try {
                    semaphore.acquire();
                    executeCommand(command);
                } catch (Exception e) {
                    // handle error
                } finally {
                    semaphore.release();
                }
            });
        }
        executor.shutdown();
    }

