        {
            var encryptedList = EncryptList(integerList);
            var decryptedList = new List<int>();

            foreach (var encryptedInt in encryptedList)
            {
                var decryptedInt = DecryptInteger(encryptedInt);

                if (decryptedInt == null)
                {
                    continue;
                }

                decryptedList.Add(decryptedInt.Value);
            }

            return decryptedList;
        }

        private static List<int> EncryptList(List<int> integerList)
        {
            var encryptedList = new List<int>();

            foreach (var integer in integerList)
            {
                var encryptedInt = EncryptInteger(integer);

                if (encryptedInt == null)
                {
                    continue;
                }

                encryptedList.Add(encryptedInt.Value);
            }

            return encryptedList;
        }

        private static int? DecryptInteger(int encryptedInt)
        {
            try
            {
                var jsonResponse = EncryptionServiceCall(encryptedInt);
                var decryptedInt = JsonConvert.DeserializeObject<int>(jsonResponse.Content);
                return decryptedInt;
            }
            catch (Exception e)
            {
                Console.WriteLine($"Failed to decrypt integer: {e.Message}");
                return null;
            }
        }

        private static int? EncryptInteger(int integer)
        {
            try
            {
                var jsonResponse = EncryptionServiceCall(integer);
                var encryptedInt = JsonConvert.DeserializeObject<int>(jsonResponse.Content);
                return encryptedInt;
            }
            catch (Exception e)
            {
                Console.WriteLine($"Failed to encrypt integer: {e.Message}");
                return null;
            }
