    public class StringHasher : IStringHasher
    {
        private readonly ILogger<StringHasher> _logger;
        private readonly bool _useSha256;

        public StringHasher(ILogger<StringHasher> logger, bool useSha256 = false)
        {
            _logger = logger;
            _useSha256 = useSha256;
        }

        public async Task<string> HashAsync(string input, string salt = null)
        {
            if (input == null) throw new ArgumentNullException(nameof(input));

            var hashAlgorithm = _useSha256 ? SHA256.Create() : MD5.Create();
            var hash = hashAlgorithm.ComputeHash(Encoding.UTF8.GetBytes(input + salt));

            return BitConverter.ToString(hash).Replace("-", "").ToLowerInvariant();
        }

        public async Task<string> HashAsync(byte[] input, string salt = null)
        {
            if (input == null) throw new ArgumentNullException(nameof(input));

            var hashAlgorithm = _useSha256 ? SHA256.Create() : MD5.Create();
            var hash = hashAlgorithm.ComputeHash(input);

            return BitConverter.ToString(hash).Replace("-", "").ToLowerInvariant();
        }
    }
}
