namespace MyService
{
    public class DecryptionService
    {
        private readonly AesCbc _aes = new AesCbc();
        private readonly Dictionary<string, object> _cache = new Dictionary<string, object>();

        public T Deserialize<T>(byte[] ciphertext) where T : class
        {
            string key = GetKey(ciphertext);
            if (_cache.TryGetValue(key, out var obj))
            {
                return (T)obj;
            }

            byte[] decryptedBytes = Decrypt(ciphertext);
            T deserializedObj = Deserialize<T>(decryptedBytes);

            _cache[key] = deserializedObj;

            return deserializedObj;
        }

        public byte[] Encrypt(object obj)
        {
            byte[] plaintext = Serialize(obj);
            string key = GetKey(plaintext);
            byte[] ciphertext = _aes.Encrypt(plaintext, key);

            return ciphertext;
        }

        private byte[] Decrypt(byte[] ciphertext)
        {
            try
            {
                string key = GetKey(ciphertext);
                byte[] decryptedBytes = _aes.Decrypt(ciphertext, key);

                return decryptedBytes;
            }
            catch (CryptographicException ex)
            {
                // Handle decryption failure here
            }

            return null;
        }

        private string GetKey(byte[] ciphertext)
        {
            // Calculate the hash of the IV and key to use as the cache key
            using (SHA256 sha = SHA256.Create())
            {
                byte[] ivAndKey = new byte[ciphertext.Length - AesCbc.IV_LENGTH];
                Buffer.BlockCopy(ciphertext, 0, ivAndKey, 0, ivAndKey.Length);
                return sha.ComputeHash(ivAndKey).ToHexString();
            }
        }

        private T Deserialize<T>(byte[] plaintext) where T : class
        {
            // Use BinaryFormatter to deserialize the data into the specified custom object model
            using (MemoryStream stream = new MemoryStream(plaintext))
            {
                try
                {
                    var formatter = new BinaryFormatter();
                    return (T)formatter.Deserialize(stream);
                }
                catch (SerializationException ex)
                {
                    // Handle deserialization failure here
                }
            }

            return null;
        }

        private byte[] Serialize(object obj)
        {
            using (MemoryStream stream = new MemoryStream())
            {
                try
                {
                    var formatter = new BinaryFormatter();
                    formatter.Serialize(stream, obj);
                    return stream.ToArray();
                }
                catch (SerializationException ex)
                {
                    // Handle serialization failure here
                }
            }

            return null;
        }

