['package com.example.service;

import java.io.IOException;
import java.io.InputStream;
import java.io.ObjectInputStream;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class DeserializationService {
    private static final ConcurrentHashMap<String, Object> deserializedObjects = new ConcurrentHashMap<>();
    private static final ScheduledExecutorService scheduledExecutor = Executors.newSingleThreadScheduledExecutor();

    public <T> T deserialize(byte[] data, Class<T> clazz) {
        String key = createKey(data);
        Object object = deserializedObjects.get(key);
        if (object == null) {
            try (InputStream inputStream = new ByteArrayInputStream(data)) {
                ObjectInputStream ois = new ObjectInputStream(inputStream);
                object = clazz.cast(ois.readObject());
            } catch (IOException | ClassNotFoundException e) {
                // handle deserialization failure gracefully
                e.printStackTrace();
            }
        }
        return (T) object;
    }

    private String createKey(byte[] data) {
        // calculate a unique hash code for the given byte array
        int hashCode = 0;
        for (int i = 0; i < data.length; i++) {
            hashCode += data[i];
        }
        return String.valueOf(hashCode);
    }

    public static void main(String[] args) {
        // test the service with a few deserialization requests
        DeserializationService service = new DeserializationService();
        byte[] data = {1, 2, 3};
        System.out.println(service.deserialize(data, String.class));
        System.out.println(service.deserialize(data, Integer.class));
    }
}

package com.example.service;

import java.util.concurrent.Callable;

public class CachedDeserializationService implements DeserializationService {
    private final DeserializationService delegate;
    private final ConcurrentHashMap<String, Object> deserializedObjects = new ConcurrentHashMap<>();
    private final ScheduledExecutorService scheduledExecutor = Executors.newSingleThreadScheduledExecutor();

    public CachedDeserializationService(DeserializationService delegate) {
        this.delegate = delegate;
    }

    @Override
    public <T> T deserialize(byte[] data, Class<T> clazz) {
        String key = createKey(data);
        Object object = deserializedObjects.get(key);
        if (object == null) {
            object = delegate.deserialize(data, clazz);
            scheduledExecutor.schedule(() -> deserializedObjects.remove(key), 10, TimeUnit.MINUTES); // cache for 10 minutes
        }
        return (T) object;
    }

    private String createKey(byte[] data) {
        // calculate a unique hash code for the given byte array
        int hashCode = 0;
        for (int i = 0; i < data.length; i++) {
            hashCode += data[i];
        }
        return String.valueOf(hashCode);
    }
}']

