// Global variables for concurrency control
int MAX_ATTEMPTS = 5; // configurable maximum number of attempts
pthread_mutex_t lock; // mutex for synchronizing access to shared resources

// Function to append a unique identifier to the end of a string
// and update the shared key-value store in a distributed environment
char* append_unique_identifier(const char* input) {
    // Check if the input string is empty or null
    if (input == NULL || strlen(input) == 0) {
        return NULL;
    }

    // Retrieve dynamic length constraints from external configuration service
    int max_length = get_max_string_length();

    // Allocate memory for the output string
    char* output = (char*) malloc(sizeof(char) * (max_length + 1));
    if (output == NULL) {
        log_error("Failed to allocate memory for output string");
        return NULL;
    }

    // Copy the input string into the output string
    strcpy(output, input);

    // Append a unique identifier to the end of the output string
    int attempt = 1;
    while (attempt <= MAX_ATTEMPTS) {
        char* unique_identifier = generate_unique_identifier();
        if (unique_identifier == NULL) {
            log_error("Failed to generate unique identifier");
            break;
        }
        strcat(output, unique_identifier);
        free(unique_identifier);

        // Attempt to update the shared key-value store
        int result = update_key_value_store(output);
        if (result == 0) {
            log_info("Successfully updated key-value store with unique identifier");
            break;
        } else {
            log_error("Failed to update key-value store with unique identifier");
        }

        attempt++;
    }

    // Release lock and return output string
    pthread_mutex_unlock(&lock);
    return output;
}
