#include <unordered_map>
#include <algorithm>
#include <random>
#include <chrono>
#include <fstream>

// Define a struct for encryption context
struct EncryptionContext {
  std::string key; // AES-256-GCM cipher key
  std::string salt; // Salt used for password-based key derivation function (PBKDF2)
  int iterations; // Number of iterations for enhanced security
  std::vector<unsigned char> iv; // Initialization vector for AES-256-GCM
  bool is_encrypting; // Flag indicating whether the context is for encryption or decryption
};

// Define a class for the encryption service
class EncryptionService {
 private:
  // Map of active encryption contexts
  std::unordered_map<std::string, EncryptionContext> contexts_;

  // Map of active ephemeral symmetric keys
  std::unordered_map<std::string, std::vector<unsigned char>> ephemeral_keys_;

 public:
  EncryptionService() {}

  ~EncryptionService() {
    contexts_.clear();
    ephemeral_keys_.clear();
  }

  // Generate a new encryption context for the given password and salt
  EncryptionContext generateContext(const std::string& password, const std::string& salt) {
    auto ctx = EncryptionContext{};
    ctx.key = password;
    ctx.salt = salt;
    ctx.iterations = 1000;
    ctx.iv = generateIV();
    ctx.is_encrypting = true;
    return ctx;
  }

  // Generate a new ephemeral symmetric key for the given context
  std::vector<unsigned char> generateEphemeralKey(const EncryptionContext& ctx) {
    auto key = std::vector<unsigned char>(32, 0);
    generateRandomBytes(key.data(), key.size());
    return key;
  }

  // Generate a new initialization vector for the given context
  std::vector<unsigned char> generateIV() {
    auto iv = std::vector<unsigned char>(16, 0);
    generateRandomBytes(iv.data(), iv.size());
    return iv;
  }

  // Generate a random byte sequence for the given buffer and length
  void generateRandomBytes(void* buf, size_t len) {
    std::random_device rd;
    auto eng = std::default_random_engine{rd()};
    std::uniform_int_distribution<unsigned char> dist(0, 255);
    for (size_t i = 0; i < len; ++i) {
      *((unsigned char*)buf + i) = dist(eng);
    }
  }

  // Encrypt the given plaintext using the given encryption context and ephemeral symmetric key
  std::vector<unsigned char> encrypt(const EncryptionContext& ctx, const std::vector<unsigned char>& key, const std::string& plaintext) {
    auto cipher = EVP_aes_256_gcm();
    auto iv = ctx.iv;
    auto tag = std::vector<unsigned char>(16, 0);
    auto ciphertext = std::vector<unsigned char>(plaintext.size() + tag.size(), 0);

    // Generate the ephemeral symmetric key and initialization vector for the encryption
    auto ephemeral_key = generateEphemeralKey(ctx);
    auto ephemeral_iv = generateIV();

    // Encrypt the plaintext using AES-256-GCM with the ephemeral symmetric key and initialization vector
    EVP_CIPHER_CTX* ctx_;
    EVP_EncryptInit_ex(ctx_, cipher, nullptr, key.data(), iv.data());
    size_t len;
    EVP_EncryptUpdate(ctx_, ciphertext.data(), &len, plaintext.data(), plaintext.size());
    EVP_EncryptFinal_ex(ctx_, ciphertext.data() + len, &len);
    EVP_CIPHER_CTX_ctrl(ctx_, EVP_CTRL_GCM_GET_TAG, 16, tag.data());
    EVP_CIPHER_CTX_free(ctx_);

    // Delete the ephemeral symmetric key and initialization vector after use
    deleteEphemeralKey(ephemeral_key);
    deleteEphemeralIV(ephemeral_iv);

    return ciphertext;
  }

  // Decrypt the given ciphertext using the given encryption context and ephemeral symmetric key
  std::vector<unsigned char> decrypt(const EncryptionContext& ctx, const std::vector<unsigned char>& key, const std::string& ciphertext) {
    auto cipher = EVP_aes_256_gcm();
    auto iv = ctx.iv;
    auto tag = std::vector<unsigned char>(16, 0);
    size_t len;

    // Extract the ephemeral symmetric key and initialization vector from the ciphertext
    auto ephemeral_key = extractEphemeralKey(ciphertext);
    auto ephemeral_iv = extractEphemeralIV(ciphertext);

    // Decrypt the ciphertext using AES-256-GCM with the ephemeral symmetric key and initialization vector
    EVP_CIPHER_CTX* ctx_;
    EVP_DecryptInit_ex(ctx_, cipher, nullptr, key.data(), iv.data());
    EVP_DecryptUpdate(ctx_, tag.data(), &len, ciphertext.data(), ciphertext.size());
    auto plaintext = std::vector<unsigned char>(ciphertext.size() - len, 0);
    EVP_DecryptFinal_ex(ctx_, plaintext.data() + len, &len);
    EVP_CIPHER_CTX_free(ctx_);

    // Delete the ephemeral symmetric key and initialization vector after use
    deleteEphemeralKey(ephemeral_key);
    deleteEphemeralIV(ephemeral_iv);

    return plaintext;
  }

  // Extract the ephemeral symmetric key from the ciphertext
  std::vector<unsigned char> extractEphemeralKey(const std::string& ciphertext) {
    auto start = ciphertext.find(":");
    auto end = ciphertext.find(",");
    return std::vector<unsigned char>(ciphertext.substr(start + 1, end - start - 1).begin(), ciphertext.substr(start + 1, end - start - 1).end());
  }

  // Extract the ephemeral initialization vector from the ciphertext
  std::vector<unsigned char> extractEphemeralIV(const std::string& ciphertext) {
    auto start = ciphertext.find(",");
    auto end = ciphertext.find(";");
    return std::vector<unsigned char>(ciphertext.substr(start + 1, end - start - 1).begin(), ciphertext.substr(start + 1, end - start - 1).end());
  }

  // Delete the ephemeral symmetric key and initialization vector after use
  void deleteEphemeralKey(const std::vector<unsigned char>& key) {
    memset(key.data(), 0, key.size() * sizeof(unsigned char));
  }

  // Delete the ephemeral initialization vector after use
  void deleteEphemeralIV(const std::vector<unsigned char>& iv) {
    memset(iv.data(), 0, iv.size() * sizeof(unsigned char));
  }
};
