// External logging system interface
void log_error(const char* message);
void log_warning(const char* message);
void log_info(const char* message);

// Function to process a string and append it to an external buffer
char* process_string(const char* input, size_t max_size, char* output, size_t output_size) {
    // Validate the input parameters
    if (input == NULL || max_size < 0 || output == NULL || output_size <= 0) {
        log_error("Invalid input parameter(s) for process_string");
        return NULL;
    }

    // Calculate the maximum size of the resulting string with a trailing slash
    size_t max_result_size = strlen(input) + 2;

    // Check if the buffer can accommodate the resulting string including a trailing slash
    if (max_result_size > max_size) {
        log_warning("Buffer is too small to accommodate input string with trailing slash");
        return NULL;
    }

    // Append a single slash to the buffer if the input string is empty or NULL
    if (input == NULL || *input == '\0') {
        output[output_size] = '/';
        return output;
    }

    // Check if the input string exceeds the maximum size limit
    if (strlen(input) > max_size - 2) {
        log_warning("Input string exceeds maximum size limit");
        return NULL;
    }

    // Append the input string with a trailing slash to the buffer
    strcpy(output + output_size, input);
    output[output_size + strlen(input)] = '/';

    // Update the buffer size and return the modified buffer
    output_size += max_result_size;
    return output;
}
```
