public class GatewayApplication {

    private static final Logger LOGGER = LoggerFactory.getLogger(GatewayApplication.class);

    @Autowired
    private Environment env;

    public static void main(String[] args) {
        SpringApplication.run(GatewayApplication.class, args);
    }

    @Bean
    public RouteLocator routes() {
        return RouteLocatorBuilder.builder()
                .routes()
                    .route("secure_endpoint", r -> r
                            .path("/api/protected")
                            .filters(f -> f.filter(new SecureFilter())
                                    .setEndpointId("secure-endpoint"))
                            .uri("http://localhost:8080"))
                    .build();
    }

    @Bean
    public ReactiveWebFilterChainProxy webFilterChain() {
        return new ReactiveWebFilterChainProxy(webFilters);
    }

    @Bean
    public FilterRegistrationBean<SecureFilter> secureFilterRegistration() {
        FilterRegistrationBean<SecureFilter> registration = new FilterRegistrationBean<>();
        registration.setFilter(new SecureFilter());
        return registration;
    }
}
