import org.springframework.stereotype.Component;
import reactor.core.publisher.Mono;
import javax.servlet.*;

@Component
public class SecureFilter implements Filter {

    @Override
    public void doFilter(ServletRequest request, ServletResponse response, FilterChain chain) throws IOException, ServletException {
        String endpointId = request.getAttribute("endpoint_id");
        if (StringUtils.isEmpty(endpointId)) {
            chain.doFilter(request, response);
            return;
        }
        // Check if the user has access to the resource
        if (hasAccess(request, response, endpointId)) {
            chain.doFilter(request, response);
        } else {
            // If the user doesn't have access, send a 403 error
            ((HttpServletResponse)response).sendError(HttpServletResponse.SC_FORBIDDEN, "Forbidden");
        }
    }
}
