#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <limits.h>

#define MAX_EVENTS 1000000 // maximum number of events in the array
#define EVENT_SIZE sizeof(TrafficEvent) // size of a single event structure
#define PAGE_SIZE 4096 // size of memory page
#define TIMESTAMP_OFFSET 0 // offset of timestamp field in TrafficEvent struct
#define EVENT_TYPE_OFFSET 8 // offset of event type field in TrafficEvent struct
#define DEVICE_ID_OFFSET 12 // offset of associated device ID field in TrafficEvent struct
#define GEOGRAPHIC_COORDINATES_OFFSET 16 // offset of geographical coordinates field in TrafficEvent struct

// structure for traffic events
typedef struct {
    unsigned long timestamp; // timestamp of the event
    int eventType; // type of the event (e.g., traffic jam, construction)
    char associatedDeviceID[256]; // ID of the device associated with the event
    double geographicalCoordinates[3]; // coordinates of the event in geographical space
} TrafficEvent;

// array for storing events
TrafficEvent events[MAX_EVENTS];

// number of events currently stored in the array
int numEvents = 0;

// current index of the next available slot in the array
int nextAvailableIndex = 0;

// mutex for synchronizing access to the shared data structure
pthread_mutex_t mutex;

// initialize the library and allocate memory for the event array
void initLibrary() {
    // create a mutex for synchronizing access to the shared data structure
    pthread_mutex_init(&mutex, NULL);

    // allocate memory for the event array
    events = (TrafficEvent *) malloc(MAX_EVENTS * EVENT_SIZE);
}

// add a new event to the array and update the number of events
void addEvent(unsigned long timestamp, int eventType, char *associatedDeviceID, double geographicalCoordinates[3]) {
    // acquire the mutex for synchronizing access to the shared data structure
    pthread_mutex_lock(&mutex);

    // check if the array is full and reallocate memory if necessary
    if (numEvents == MAX_EVENTS) {
        events = (TrafficEvent *) realloc(events, 2 * MAX_EVENTS * EVENT_SIZE);
    }

    // copy the event data to the next available slot in the array
    memcpy(&events[nextAvailableIndex], &timestamp, sizeof(unsigned long));
    memcpy(&events[nextAvailableIndex].eventType, &eventType, sizeof(int));
    memcpy(&events[nextAvailableIndex].associatedDeviceID, associatedDeviceID, strlen(associatedDeviceID) + 1);
    memcpy(&events[nextAvailableIndex].geographicalCoordinates, geographicalCoordinates, 3 * sizeof(double));

    // update the number of events and the next available index
    numEvents++;
    nextAvailableIndex = (nextAvailableIndex + 1) % MAX_EVENTS;

    // release the mutex for synchronizing access to the shared data structure
    pthread_mutex_unlock(&mutex);
}

// retrieve an event from the array by its index
TrafficEvent getEvent(int index) {
    // acquire the mutex for synchronizing access to the shared data structure
    pthread_mutex_lock(&mutex);

    // copy the event data from the specified index in the array
    TrafficEvent event;
    memcpy(&event, &events[index], EVENT_SIZE);

    // release the mutex for synchronizing access to the shared data structure
    pthread_mutex_unlock(&mutex);

    return event;
}

// update an existing event in the array by its index
void updateEvent(int index, unsigned long timestamp, int eventType, char *associatedDeviceID, double geographicalCoordinates[3]) {
    // acquire the mutex for synchronizing access to the shared data structure
    pthread_mutex_lock(&mutex);

    // copy the new event data to the specified index in the array
    memcpy(&events[index], &timestamp, sizeof(unsigned long));
    memcpy(&events[index].eventType, &eventType, sizeof(int));
    memcpy(&events[index].associatedDeviceID, associatedDeviceID, strlen(associatedDeviceID) + 1);
    memcpy(&events[index].geographicalCoordinates, geographicalCoordinates, 3 * sizeof(double));

    // release the mutex for synchronizing access to the shared data structure
    pthread_mutex_unlock(&mutex);
}

// remove an event from the array by its index
void removeEvent(int index) {
    // acquire the mutex for synchronizing access to the shared data structure
    pthread_mutex_lock(&mutex);

    // shift all subsequent events in the array one position to the left
    memcpy(&events[index], &events[index + 1], (numEvents - index - 1) * EVENT_SIZE);

    // update the number of events and the next available index
    numEvents--;
    nextAvailableIndex = (nextAvailableIndex + 1) % MAX_EVENTS;

    // release the mutex for synchronizing access to the shared data structure
    pthread_mutex_unlock(&mutex);
}

// retrieve all events from the array
int getAllEvents(TrafficEvent *events, int numEvents) {
    // acquire the mutex for synchronizing access to the shared data structure
    pthread_mutex_lock(&mutex);

    // copy all events from the array to the output array
    memcpy(events, &this->events, numEvents * EVENT_SIZE);

    // release the mutex for synchronizing access to the shared data structure
    pthread_mutex_unlock(&mutex);
}
