Here is a sample implementation of the data access layer in C++ that supports multiple database types (PostgreSQL, MySQL, MongoDB) and external data sources:
```c++
#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <unordered_map>
#include <memory>
#include <stdexcept>
#include <chrono>
#include <thread>
#include <future>
#include <boost/asio.hpp>
#include <postgresql/libpq-fe.h>
#include <mysql++/mysqlpp.h>
#include <mongodb++/mongocxx.h>

using namespace std;
using namespace boost::asio;
using namespace std::chrono_literals;

// Define the database types that are supported by the data access layer
enum class DatabaseType { PostgreSQL, MySQL, MongoDB };

// Define a struct to hold information about each database connection
struct ConnectionInfo {
    string host;
    string port;
    string username;
    string password;
};

// Define a map to store the connections for each database type
map<DatabaseType, shared_ptr<ConnectionInfo>> connections;

// Define a function to connect to a database and return a connection object
shared_ptr<ConnectionInfo> connect(DatabaseType type) {
    // Create a new connection info object for the given database type
    auto conn = make_shared<ConnectionInfo>();

    // Set the host, port, username, and password based on the database type
    switch (type) {
        case DatabaseType::PostgreSQL:
            conn->host = "localhost";
            conn->port = "5432";
            conn->username = "postgres";
            conn->password = "mysecretpassword";
            break;
        case DatabaseType::MySQL:
            conn->host = "localhost";
            conn->port = "3306";
            conn->username = "root";
            conn->password = "mysecretpassword";
            break;
        case DatabaseType::MongoDB:
            conn->host = "localhost";
            conn->port = "27017";
            conn->username = "admin";
            conn->password = "mysecretpassword";
            break;
    }

    // Connect to the database using the appropriate library for the given type
    switch (type) {
        case DatabaseType::PostgreSQL:
            conn->conn = PQconnectdb("host=" + conn->host + " port=" + conn->port + " user=" + conn->username + " password=" + conn->password);
            break;
        case DatabaseType::MySQL:
            conn->conn = mysqlpp::Connection(conn->host, conn->port, conn->username, conn->password);
            break;
        case DatabaseType::MongoDB:
            conn->conn = mongocxx::client(mongocxx::uri("mongodb://" + conn->host + ":" + conn->port + "/?authSource=admin"));
            break;
    }

    // Check for connection errors and throw an exception if there are any
    if (conn->conn->error().empty()) {
        connections[type] = conn;
        return conn;
    } else {
        throw runtime_error(conn->conn->error());
    }
}

// Define a function to disconnect from a database and release the connection object
void disconnect(DatabaseType type) {
    // Get the connection info for the given database type
    auto conn = connections[type];

    // Close the database connection
    switch (type) {
        case DatabaseType::PostgreSQL:
            PQfinish(conn->conn);
            break;
        case DatabaseType::MySQL:
            mysqlpp::Connection.disconnect();
            break;
        case DatabaseType::MongoDB:
            mongocxx::client.disconnect();
            break;
    }
}

// Define a function to execute a query on a database and return the results
shared_ptr<vector<string>> query(DatabaseType type, string query) {
    // Get the connection info for the given database type
    auto conn = connections[type];

    // Execute the query on the database using the appropriate library for the given type
    switch (type) {
        case DatabaseType::PostgreSQL:
            PQsendQuery(conn->conn, query.c_str());
            break;
        case DatabaseType::MySQL:
            mysqlpp::Connection.query(query);
            break;
        case DatabaseType::MongoDB:
            mongocxx::client.find(mongocxx::from_json(query));
            break;
    }

    // Get the results of the query and return them as a vector of strings
    auto results = make_shared<vector<string>>();
    while (true) {
        switch (type) {
            case DatabaseType::PostgreSQL:
                if (PQgetResult(conn->conn) == NULL) {
                    break;
                } else {
                    results->push_back(PQresStatus(PQresultStatus(PQgetResult(conn->conn))));
                }
                break;
            case DatabaseType::MySQL:
                if (mysqlpp::Connection.next_result()) {
                    results->push_back(mysqlpp::Connection.result());
                } else {
                    break;
                }
                break;
            case DatabaseType::MongoDB:
                if (mongocxx::client.next() == NULL) {
                    break;
                } else {
                    results->push_back(mongocxx::client.get());
                }
                break;
        }
    }

    return results;
}
```
