    private static JSONObject getResponse(String url) throws Exception {
        // Handle network latency and potential downtime through retry logic with exponential backoff and caching
        int retries = 5;
        while (retries > 0) {
            try {
                URL obj = new URL(url);
                HttpURLConnection con = (HttpURLConnection) obj.openConnection();
                // Add request headers
                con.setRequestMethod("GET");
                con.setRequestProperty("User-Agent", "Mozilla/5.0");
                int statusCode = con.getResponseCode();
                if (statusCode == 200) {
                    BufferedReader in = new BufferedReader(new InputStreamReader(con.getInputStream()));
                    String inputLine;
                    StringBuffer response = new StringBuffer();
                    while ((inputLine = in.readLine()) != null) {
                        response.append(inputLine);
                    }
                    in.close();
                    return new JSONObject(response.toString());
                } else {
                    retries--;
                    System.out.println("Error fetching data, status code: " + statusCode);
                    Thread.sleep(1000);
                }
            } catch (Exception e) {
                retries--;
                System.out.println("Error fetching data: " + e);
                Thread.sleep(1000);
            }
        }
        return null;
    }

