```
import json
from datetime import datetime

from flask import Flask, request, Response
from flask_sqlalchemy import SQLAlchemy
from sqlalchemy.orm import sessionmaker
from sqlalchemy import create_engine

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///database.db'
db = SQLAlchemy(app)

class Resource(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    data = db.Column(db.JSON, nullable=False)
    created_at = db.Column(db.DateTime, default=datetime.utcnow)
    updated_at = db.Column(db.DateTime, onupdate=datetime.utcnow)

    def __repr__(self):
        return f"Resource({self.id})"

engine = create_engine('sqlite:///database.db')
Session = sessionmaker(bind=engine)
session = Session()

@app.route('/resources', methods=['PUT'])
def update_resource():
    try:
        data = request.get_json()
        resource = Resource.query.filter_by(id=data['id']).first()
        if not resource:
            return Response(status=404)
        resource.data = json.dumps(data['data'])
        session.add(resource)
        session.commit()
        return Response(status=201)
    except Exception as e:
        print(f"Error updating resource: {e}")
        return Response(status=500)

@app.route('/resources/<int:id>', methods=['GET'])
def get_resource(id):
    try:
        resource = Resource.query.filter_by(id=id).first()
        if not resource:
            return Response(status=404)
        data = json.loads(resource.data)
        return Response(json.dumps(data), status=200)
    except Exception as e:
        print(f"Error getting resource: {e}")
        return Response(status=500)

@app.route('/resources/<int:id>', methods=['DELETE'])
def delete_resource(id):
    try:
        resource = Resource.query.filter_by(id=id).first()
        if not resource:
            return Response(status=404)
        session.delete(resource)
        session.commit()
        return Response(status=204)
    except Exception as e:
        print(f"Error deleting resource: {e}")
        return Response(status=500)

if __name__ == '__main__':
    app.run(debug=True)
```
