use std::time::Instant;
use std::process::Command;
use std::io::Write;
use rustc_driver::{Driver, catch_with_exit_code};
use rustc_driver::session::Session;
use rustc_driver::hook::Hook;
use rustc_driver::early_error;

fn main() {
    let mut driver = Driver::new();
    let session = Session::create(&mut driver, "rustc", &["--version"]);
    let start_time = Instant::now();
    let resident_set_size = session.resident_set_size;
    let hook = SyncLazy::new(|| {
        Hook::new("custom-logging-hook", |session, message| {
            if message.contains("Compiling") {
                println!("{}", message);
            }
        })
    });
    driver.add_hook(hook);
    let result = catch_with_exit_code(|driver, session| {
        driver.run(session)
    }, driver, session).unwrap();
    let end_time = Instant::now();
    let elapsed = end_time.duration_since(start_time);
    println!("Time taken: {:?}", elapsed);
    println!("Resident set size: {} KB", resident_set_size / 1024);
}
