  string customerName;
  double totalAmount;
};

// Define a class to handle concurrent order confirmations
class OrderConfirmationHandler {
 private:
  // A vector of order confirmations
  vector<OrderConfirmation> orderConfirmations;

  // A mutex to protect the vector of order confirmations
  mutex mtx;

  // A condition variable to signal changes in the vector of order confirmations
  condition_variable cv;

  // A flag to indicate if the function is paused
  atomic<bool> paused{false};

 public:
  OrderConfirmationHandler() {
    orderConfirmations.clear();
  }

  void handleOrderConfirmation(const OrderConfirmation& confirmation) {
    // Acquire the lock on the vector of order confirmations
    unique_lock<mutex> lck(mtx);

    // Add the new order confirmation to the vector
    orderConfirmations.push_back(confirmation);

    // Notify any waiting threads that there is a change in the vector of order confirmations
    cv.notify_all();
  }

  void pause() {
    paused = true;
  }

  void resume() {
    paused = false;
  }

  // A function to process the vector of order confirmations
  // This function is called when a thread is unpaused
  void processOrderConfirmations() {
    while (true) {
      // Acquire the lock on the vector of order confirmations
      unique_lock<mutex> lck(mtx);

      // Wait for any change in the vector of order confirmations
      cv.wait(lck, [this] { return !paused && !orderConfirmations.empty(); });

      if (paused) {
        break;
      }

      // Process each order confirmation in the vector
      for (auto& confirmation : orderConfirmations) {
        // Make an API call to the payment gateway to confirm the order
        // If the API call fails, retry after a certain amount of time
