class ConfigService:
    def __init__(self):
        self.config = {}
        self.profiles = {}
        self.lock = Lock()

    def load_initial_config(self, url):
        # Asynchronous loading of initial configuration data from an external REST API
        while True:
            try:
                response = requests.get(url)
                if response.status_code == 200:
                    self.config = json.loads(response.content)
                    break
