                    logging.info("Synchronized with master server")
            except requests.exceptions.ConnectionError:
                logging.warning("Failed to connect to master server, retrying in 5 seconds...")
                time.sleep(5)

if __name__ == "__main__":
    # Initialize the configuration service and start synchronization with the master server
    config_service = ConfigService()
    config_service.load_initial_config("http://initial_config_url")
    config_service.synchronize_with_master()
