            if ((*it).x == x && (*it).y == y && (*it).z == z) {
                nodes_.erase(it);
                return;
            }
        }
    }

    // Optimize the octree for scalability by resizing nodes and adjusting cache sizes
    void optimize() {
        std::lock_guard<std::mutex> lock(mutex_);
        int32_t numNodes = nodes_.size();
