Here's a possible implementation for the data ingestion pipeline:
```go
package main

import (
	"context"
	"encoding/json"
	"fmt"
	"github.com/Shopify/sarama"
	"github.com/go-redis/redis"
	"github.com/op/go-logging"
	"os"
)

var log = logging.MustGetLogger("data_ingestion")

type Event struct {
	ID          string `json:"id"`
	EventType   string `json:"event_type"`
	Timestamp   int64  `json:"timestamp"`
	Payload     json.RawMessage
}

type KafkaConsumer struct {
	sarama.ConsumerGroup
	topic   string
	groupID string
	client  *sarama.Client
}

func NewKafkaConsumer(topic, groupID string) (*KafkaConsumer, error) {
	config := sarama.NewConfig()
	config.Version = sarama.V2_6_0_0
	config.Consumer.Return.Errors = true
	client, err := sarama.NewClient([]string{"localhost:9092"}, config)
	if err != nil {
		return nil, fmt.Errorf("failed to create Kafka client: %w", err)
	}
	consumerGroup, err := sarama.NewConsumerGroupFromClient(groupID, client)
	if err != nil {
		return nil, fmt.Errorf("failed to create Kafka consumer group: %w", err)
	}
	return &KafkaConsumer{topic: topic, groupID: groupID, client: client}, nil
}

func (c *KafkaConsumer) Consume() error {
	// create a consumer group session
	session, err := c.client.ConsumerGroups[c.groupID].NewSession()
	if err != nil {
		return fmt.Errorf("failed to create Kafka consumer group session: %w", err)
	}

	// subscribe to the topic
	partitionConsumers, err := session.FetchTopicPartition(c.topic)
	if err != nil {
		return fmt.Errorf("failed to fetch Kafka topic partition: %w", err)
	}

	for _, p := range partitionConsumers {
		// create a message channel for each partition consumer
		messageChannel := make(chan *sarama.ConsumerMessage, 1000)

		// start the partition consumer
		go func() {
			for {
				select {
				case <-session.Context().Done():
					return
				default:
				}
				if err := p.Consume(session, messageChannel); err != nil {
					log.Errorf("failed to consume Kafka messages: %v", err)
				}
			}
		}()

		// process the message channel
		go func() {
			for {
				select {
				case <-session.Context().Done():
					return
				default:
				}
				message, ok := <-messageChannel
				if !ok {
					continue
				}
				event, err := c.processMessage(message)
				if err != nil {
					log.Errorf("failed to process Kafka message: %v", err)
				} else {
					log.Infof("received event: %+v", event)
				}
			}
		}()
	}

	return nil
}

func (c *KafkaConsumer) processMessage(message *sarama.ConsumerMessage) (*Event, error) {
	var event Event
	if err := json.Unmarshal(message.Value, &event); err != nil {
		return nil, fmt.Errorf("failed to unmarshal Kafka message value: %w", err)
	}
	return &event, nil
}
```
This implementation uses the `sarama` library for Kafka client and consumer group management. It creates a consumer group session, subscribes to the target topic, and processes each message received from the Kafka broker using the `processMessage()` method. The method deserializes the message value into an `Event` struct, which contains the JSON payload of the message.

The implementation also includes a graceful shutdown mechanism for the consumer group session. When the main process exits or receives a SIGTERM signal, the shutdown context is canceled, and the Kafka consumer group session will close gracefully.

