To handle network timeouts, implement graceful shutdowns, and integrate with an OAuth2-authenticated Kafka broker, you can modify the Go service to include the following additional functionalities:

1. Use a context object to track the state of the application and handle SIGINT/SIGTERM signals. This allows you to gracefully shut down the service when the main process exits or receives a signal.
2. Implement retry logic for network failures, such as connection resets or timeouts. You can use the `backoff` library to implement exponential backoff and retry strategies.
3. Use an OAuth2-authenticated client to connect to the Kafka broker. This allows you to securely authenticate your service with the Kafka broker and consume messages from authorized topics.

For example, here's how you can modify the Go service to use an OAuth2-authenticated client:
```go
package main

import (
	"context"
	"log"
	"os"
	"syscall"

	"github.com/Shopify/sarama"
)

func main() {
	// Create a context object to track the state of the application
	ctx := context.Background()

	// Set up an OAuth2-authenticated Kafka client
	client, err := sarama.NewClient([]string{"localhost:9092"}, &sarama.Config{
		Net: sarama.Net{
			TLS: &tls.Config{}, // use your own TLS configuration here
			OAuth: &oauth2.Config{
				ClientID:     "your_client_id",
				ClientSecret: "your_client_secret",
				Endpoint: oauth2.Endpoint{
					TokenURL: "https://your_token_endpoint",
				},
				Scopes: []string{"your_scope"},
			},
		},
	})
	if err != nil {
		log.Fatalf("failed to create Kafka client: %v", err)
	}
	defer client.Close()

	// Create a consumer group session
	session, err := client.ConsumerGroups().Session([]string{"your_topic"})
	if err != nil {
		log.Fatalf("failed to create Kafka consumer group session: %v", err)
	}
	defer session.Close()

	// Handle SIGINT/SIGTERM signals gracefully
	sigchan := make(chan os.Signal, 1)
	signal.Notify(sigchan, syscall.SIGINT, syscall.SIGTERM)
	go func() {
		for sig := range sigchan {
			log.Printf("received signal %v", sig)
			session.Close() // close the consumer group session gracefully
		}
	}()

	// Consume messages from the target topic using the consumer group session
	for message := range session.Messages() {
		log.Printf("received message: %+v", message)
		// process the message here
	}
}
```
