    double longitude;
};

// Define array to store TrafficEvents
static struct TrafficEvent events[MAX_EVENTS];
static int numEvents = 0;

// Function to add a new TrafficEvent
void addTrafficEvent(struct TrafficEvent *event) {
    if (numEvents < MAX_EVENTS) {
        events[numEvents++] = *event;
    }
}

// Function to retrieve all TrafficEvents within a given time range
struct TrafficEvent* getTrafficEvents(long long startTime, long long endTime) {
    struct TrafficEvent* result = NULL;
    int numResult = 0;
    for (int i = 0; i < numEvents; i++) {
        if (events[i].timestamp >= startTime && events[i].timestamp <= endTime) {
            if (!result) {
                result = malloc(sizeof(struct TrafficEvent) * (numResult + 1));
                memcpy(&result[numResult++], &events[i], sizeof(struct TrafficEvent));
            } else {
                result = realloc(result, sizeof(struct TrafficEvent) * (numResult + 1));
                memcpy(&result[numResult++], &events[i], sizeof(struct TrafficEvent));
            }
        }
    }
    return result;
}

// Function to retrieve all TrafficEvents within a given geographical range
struct TrafficEvent* getTrafficEventsByGeoRange(double minLat, double maxLat, double minLon, double maxLon) {
    struct TrafficEvent* result = NULL;
    int numResult = 0;
    for (int i = 0; i < numEvents; i++) {
        if (events[i].latitude >= minLat && events[i].latitude <= maxLat && events[i].longitude >= minLon && events[i].longitude <= maxLon) {
            if (!result) {
                result = malloc(sizeof(struct TrafficEvent) * (numResult + 1));
                memcpy(&result[numResult++], &events[i], sizeof(struct TrafficEvent));
            } else {
                result = realloc(result, sizeof(struct TrafficEvent) * (numResult + 1));
                memcpy(&result[numResult++], &events[i], sizeof(struct TrafficEvent));
            }
        }
    }
    return result;
}

// Function to prune events older than a certain time
void pruneEventsOlderThan(long long threshold) {
    int i = 0, j = 0;
    while (i < numEvents && events[i].timestamp >= threshold) {
        i++;
    }
    if (i == numEvents) {
        return;
    }
    memcpy(&events[j], &events[i], sizeof(struct TrafficEvent) * (numEvents - i));
    numEvents -= i;
}

// Function to retrieve all events filtered by geographical range and time range
struct TrafficEvent* getFilteredTrafficEvents(double minLat, double maxLat, double minLon, double maxLon, long long startTime, long long endTime) {
