int MAX_RETRY = 5; // maximum number of retries
int RETRY_DELAY = 100; // delay between retries in milliseconds

void retry(DynamicArray* d) {
    int i = 0;
    while (i < MAX_RETRY && !d->events[d->size - 1].timestamp) {
        sleep(RETRY_DELAY); // sleep for a short time before trying again
        i++;
    }
    if (i == MAX_RETRY) {
        printf("Maximum retries reached! Discarding event.\n");
        d->size--; // discard the last event
    } else {
        printf("Retry successful!\n");
    }
}
