```
void TrafficDataSink::start() {
    // Start the data feed from the IoT devices
    std::thread dataProcessingThread([this]() {
        while (true) {
            try {
                const auto& event = getNextEvent(); // Get the next traffic event from the list
                if (event != nullptr) {
                    processEvent(event); // Process the event asynchronously
                }
            } catch (const std::exception& e) {
                std::cerr << "Error processing data: " << e.what() << std::endl;
            }
        }
    });
}
