  NFAPI_CRC_INDICATION_PDU_T *data;
  struct NFAPI_CRC_INDICATION_NODE *next;
} NFAPI_CRC_INDICATION_NODE_T;

// Define the linked list head structure
typedef struct NFAPI_CRC_INDICATION_LIST {
  NFAPI_CRC_INDICATION_NODE_T *head;
  pthread_mutex_t mutex;
} NFAPI_CRC_INDICATION_LIST_T;

// Initialize the linked list with a head node and mutex lock
void nfapi_crc_indication_list_init(NFAPI_CRC_INDICATION_LIST_T *list) {
  list->head = NULL;
  pthread_mutex_init(&list->mutex, NULL);
}

// Insert a new node at the end of the linked list
void nfapi_crc_indication_list_insert(NFAPI_CRC_INDICATION_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *data) {
  pthread_mutex_lock(&list->mutex);
  // Allocate a new node for the data
  NFAPI_CRC_INDICATION_NODE_T *node = malloc(sizeof(NFAPI_CRC_INDICATION_NODE_T));
  node->data = data;
  node->next = NULL;

  // If the list is empty, set the head to the new node
  if (list->head == NULL) {
    list->head = node;
  } else {
    // Otherwise, append the new node at the end of the list
    NFAPI_CRC_INDICATION_NODE_T *curr = list->head;
    while (curr->next != NULL) {
      curr = curr->next;
    }
    curr->next = node;
  }
  pthread_mutex_unlock(&list->mutex);
}

// Delete a node from the linked list by its data pointer
void nfapi_crc_indication_list_delete(NFAPI_CRC_INDICATION_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *data) {
  pthread_mutex_lock(&list->mutex);
  // If the list is empty, do nothing
  if (list->head == NULL) {
    pthread_mutex_unlock(&list->mutex);
    return;
  }

  // Find the node to delete by searching the linked list
  NFAPI_CRC_INDICATION_NODE_T *curr = list->head;
  while (curr != NULL) {
    if (curr->data == data) {
      // If the node is found, remove it from the linked list
      if (curr == list->head) {
        list->head = curr->next;
      } else {
        NFAPI_CRC_INDICATION_NODE_T *prev = curr->prev;
        prev->next = curr->next;
      }
      free(curr);
      break;
    }
    curr = curr->next;
  }
  pthread_mutex_unlock(&list->mutex);
}

// Search for a node in the linked list by its data pointer
NFAPI_CRC_INDICATION_NODE_T *nfapi_crc_indication_list_search(NFAPI_CRC_INDICATION_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *data) {
  pthread_mutex_lock(&list->mutex);
  // If the list is empty, return NULL
  if (list->head == NULL) {
    pthread_mutex_unlock(&list->mutex);
    return NULL;
  }

  // Find the node to search by searching the linked list
  NFAPI_CRC_INDICATION_NODE_T *curr = list->head;
  while (curr != NULL) {
    if (curr->data == data) {
      pthread_mutex_unlock(&list->mutex);
      return curr;
    }
    curr = curr->next;
  }

  // If the node is not found, return NULL
  pthread_mutex_unlock(&list->mutex);
  return NULL;
}

// Traverse all nodes in the linked list and perform a given action on each one
void nfapi_crc_indication_list_traverse(NFAPI_CRC_INDICATION_LIST_T *list, void (*action)(NFAPI_CRC_INDICATION_PDU_T*)) {
  pthread_mutex_lock(&list->mutex);
  // If the list is empty, return immediately
  if (list->head == NULL) {
    pthread_mutex_unlock(&list->mutex);
    return;
  }

  // Iterate over all nodes in the linked list and perform the given action on each one
  NFAPI_CRC_INDICATION_NODE_T *curr = list->head;
  while (curr != NULL) {
    action(curr->data);
    curr = curr->next;
  }
  pthread_mutex_unlock(&list->mutex);
}

// Search for a node in the linked list by its RX UE information and return its data pointer
NFAPI_CRC_INDICATION_PDU_T *nfapi_crc_indication_list_find(NFAPI_CRC_INDICATION_LIST_T *list, RX_UE_INFORMATION_TAG *rx_ue_information) {
  pthread_mutex_lock(&list->mutex);
  // If the list is empty, return NULL
  if (list->head == NULL) {
    pthread_mutex_unlock(&list->mutex);
    return NULL;
  }

  // Find the node to search by searching the linked list
  NFAPI_CRC_INDICATION_NODE_T *curr = list->head;
  while (curr != NULL) {
