```csharp
using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Threading;
using System.Threading.Tasks;

namespace DynamicImageProcessor
{
    public class ImageProcessor
    {
        private const int MaxDimension = 1024; // maximum image dimension in pixels
        private static readonly Dictionary<string, string> SupportedFormats = new Dictionary<string, string>()
        {
            { "jpg", "image/jpeg" },
            { "png", "image/png" }
        };

        public async Task<byte[]> ProcessImageAsync(Stream imageStream, int? maxDimension = null)
        {
            // validate input parameters
            if (imageStream == null || !imageStream.CanRead)
                throw new ArgumentException("Invalid stream", nameof(imageStream));

            if (maxDimension != null && maxDimension > MaxDimension)
                throw new ArgumentOutOfRangeException(nameof(maxDimension), $"Max dimension cannot be greater than {MaxDimension}");

            // read image metadata and validate format
            ImageMetadata metadata = await GetImageMetadataAsync(imageStream);
            if (!SupportedFormats.ContainsKey(metadata.Format))
                throw new NotSupportedException($"Unsupported image format: {metadata.Format}");

            // determine resize algorithm based on dimensions and quality requirements
            ResizeAlgorithm algorithm = DetermineResizeAlgorithm(metadata.Width, metadata.Height);

            // resize image using chosen algorithm
            Bitmap resizedImage = await ResizeImageAsync(imageStream, maxDimension, algorithm);

            // compress image using JPEG or PNG format
            byte[] compressedImage = CompressImage(resizedImage, metadata.Format);

            return compressedImage;
        }

        private async Task<ImageMetadata> GetImageMetadataAsync(Stream stream)
        {
            // read image metadata from stream using a third-party library
            ImageMetadata metadata = await ImageMetadataReader.ReadFromStreamAsync(stream);

            return metadata;
        }

        private ResizeAlgorithm DetermineResizeAlgorithm(int width, int height)
        {
            // determine resize algorithm based on dimensions and quality requirements
            if (width > height)
                return ResizeAlgorithm.Horizontal;
            else if (height > width)
                return ResizeAlgorithm.Vertical;
            else
                return ResizeAlgorithm.FastShrink;
        }

        private async Task<Bitmap> ResizeImageAsync(Stream stream, int? maxDimension = null, ResizeAlgorithm algorithm = ResizeAlgorithm.FastShrink)
        {
            // resize image using chosen algorithm
            Bitmap resizedImage = await ImageHelper.ResizeImageAsync(stream, maxDimension, algorithm);

            return resizedImage;
        }

        private byte[] CompressImage(Bitmap bitmap, string format)
        {
            // compress image using JPEG or PNG format
            if (format == "jpg")
                return ImageHelper.CompressImageJpeg(bitmap);
            else if (format == "png")
                return ImageHelper.CompressImagePng(bitmap);

            throw new NotSupportedException($"Unsupported image format: {format}");
        }
    }
}
```
The `ImageProcessor` class provides a single public method, `ProcessImageAsync`, which processes an input stream and returns a byte array representing the resized and compressed image. The method validates the input parameters, reads image metadata, determines the resize algorithm based on dimensions and quality requirements, resizes the image using the chosen algorithm, compresses the image using JPEG or PNG format, and returns the compressed image as a byte array.

The `ResizeAlgorithm` enum is used to represent the different resize algorithms supported by the library. The `ImageMetadataReader` class is used to read image metadata from a stream, which is then validated using the `GetImageMetadataAsync` method.

The `DetermineResizeAlgorithm` method determines the resize algorithm based on the dimensions and quality requirements, while the `ResizeImageAsync` method resizes the image using the chosen algorithm. The `CompressImage` method compresses the image using JPEG or PNG format.

The library is designed to be efficient, scalable, and secure, with support for a variety of resize algorithms and an optional feature to switch between them based on quality and performance requirements. It also includes robust error handling, resource management, system integration, scalability, usability, maintainability, and security features to ensure seamless image processing and delivery.']

