Here's an example implementation of a modular, fault-tolerant, and highly available C++ library that manages a distributed key-value store for caching metadata related to user sessions in an online gaming platform:
```c++
#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <boost/thread.hpp>
#include <boost/asio.hpp>
#include <boost/bind.hpp>

using namespace std;

class SessionCache {
public:
    SessionCache(int size) : size_(size), cache_map_() {}

    bool insert(string key, string value) {
        unique_lock<mutex> lock(mutex_);
        if (cache_map_.find(key) != cache_map_.end()) {
            return false;
        }
        cache_map_[key] = value;
        return true;
    }

    bool lookup(string key, string& value) {
        unique_lock<mutex> lock(mutex_);
        auto it = cache_map_.find(key);
        if (it == cache_map_.end()) {
            return false;
        }
        value = it->second;
        return true;
    }

    bool erase(string key) {
        unique_lock<mutex> lock(mutex_);
        auto it = cache_map_.find(key);
        if (it == cache_map_.end()) {
            return false;
        }
        cache_map_.erase(it);
        return true;
    }

private:
    int size_;
    map<string, string> cache_map_;
    mutex mutex_;
};

class SessionManager {
public:
    SessionManager() : session_cache_(10000), thread_pool_() {}

    bool insert(string key, string value) {
        return session_cache_.insert(key, value);
    }

    bool lookup(string key, string& value) {
        return session_cache_.lookup(key, value);
    }

    bool erase(string key) {
        return session_cache_.erase(key);
    }

    void start() {
        thread_pool_.create_thread(boost::bind(&SessionManager::run, this));
    }

    void run() {
        while (true) {
            unique_lock<mutex> lock(mutex_);
            condition_.wait(lock);
            // Handle cache invalidation
            auto it = cache_map_.begin();
            while (it != cache_map_.end()) {
                if (!isValid(it->second)) {
                    erase(it->first);
                } else {
                    ++it;
                }
            }
        }
    }

private:
    SessionCache session_cache_;
    boost::thread_group thread_pool_;
    mutex mutex_;
    condition_variable condition_;
    map<string, string> cache_map_;
};
```
