#include <boost/asio.hpp>
#include <boost/bind.hpp>

using namespace boost::asio;

class SandeshClient {
public:
    SandeshClient(io_service& io) : socket_(io) {}

    void connect() {
        socket_.async_connect(endpoint, boost::bind(&SandeshClient::onConnect, this));
    }

    void onConnect(const boost::system::error_code& error) {
        if (!error) {
            // Send GET request to server
            boost::asio::streambuf buffer;
            std::ostream os(&buffer);
            os << "GET / HTTP/1.1\r\n";
            os << "Host: example.com\r\n";
            os << "\r\n";
            socket_.async_write_some(boost::asio::buffer(buffer), boost::bind(&SandeshClient::onWrite, this));
        } else {
            std::cout << "Error: " << error.message() << '\n';
        }
    }

    void onWrite(const boost::system::error_code& error) {
        if (!error) {
            // Read response from server
            socket_.async_read_some(boost::asio::buffer(response), boost::bind(&SandeshClient::onRead, this));
        } else {
            std::cout << "Error: " << error.message() << '\n';
        }
    }

    void onRead(const boost::system::error_code& error) {
        if (!error) {
            // Parse response from server
            boost::asio::streambuf buffer;
            std::ostream os(&buffer);
            os << "GET / HTTP/1.1\r\n";
            os << "Host: example.com\r\n";
            os << "\r\n";
            socket_.async_write_some(boost::asio::buffer(buffer), boost::bind(&SandeshClient::onWrite, this));
        } else {
            std::cout << "Error: " << error.message() << '\n';
        }
    }

private:
    io_service& io_;
    tcp::socket socket_;
    tcp::endpoint endpoint;
    string response;
};
