using PaymentGatewayClient;

namespace MultiTenantPaymentGatewayClient
{
    public class PaymentGatewayClient : IPaymentGatewayClient
    {
        private readonly string _gatewayUrl;
        private readonly HttpClient _httpClient;
        private readonly List<string> _paymentMethods = new List<string> { "credit_card", "paypal", "cryptocurrency" };
        private readonly Dictionary<string, PaymentGatewayInfo> _gatewayInfos = new Dictionary<string, PaymentGatewayInfo>();
        private readonly RetryPolicy _retryPolicy;
        private readonly CircuitBreakerPolicy _circuitBreakerPolicy;
        private readonly Dictionary<string, PaymentGatewayConfig> _configurations = new Dictionary<string, PaymentGatewayConfig>();

        public PaymentGatewayClient(string gatewayUrl)
        {
            _gatewayUrl = gatewayUrl;
            _httpClient = new HttpClient();
            _retryPolicy = new RetryPolicy(_httpClient.Timeout, TimeSpan.FromMilliseconds(10));
            _circuitBreakerPolicy = new CircuitBreakerPolicy(_httpClient.Timeout, 5);
        }

        public async Task<PaymentGatewayResponse> ProcessTransactionAsync(string tenantId, PaymentRequest request)
        {
            var gatewayInfo = GetGatewayInfo(tenantId);
            var config = GetConfiguration(gatewayInfo.GatewayId);
            var client = GetHttpClient(config.ApiUrl);

            using (var content = new StringContent(JsonConvert.SerializeObject(request), Encoding.UTF8, "application/json"))
            {
                var response = await client.PostAsync(_gatewayUrl + "/payments", content).ConfigureAwait(false);
                if (!response.IsSuccessStatusCode)
                {
                    throw new Exception($"Failed to process payment for tenant {tenantId}: {response.ReasonPhrase}");
                }

                var responseJson = await response.Content.ReadAsStringAsync().ConfigureAwait(false);
                var paymentResponse = JsonConvert.DeserializeObject<PaymentGatewayResponse>(responseJson);
                return paymentResponse;
            }
        }

        public async Task<PaymentGatewayInfo> GetGatewayInfoAsync(string tenantId)
        {
            if (_gatewayInfos.TryGetValue(tenantId, out var gatewayInfo))
            {
                return gatewayInfo;
            }

            var config = GetConfiguration(tenantId);
            var client = GetHttpClient(config.ApiUrl);

            using (var request = new HttpRequestMessage(HttpMethod.Get, _gatewayUrl + "/info"))
            {
                var response = await client.SendAsync(request).ConfigureAwait(false);
                if (!response.IsSuccessStatusCode)
                {
                    throw new Exception($"Failed to retrieve gateway information for tenant {tenantId}: {response.ReasonPhrase}");
                }

                var responseJson = await response.Content.ReadAsStringAsync().ConfigureAwait(false);
                gatewayInfo = JsonConvert.DeserializeObject<PaymentGatewayInfo>(responseJson);
                _gatewayInfos.Add(tenantId, gatewayInfo);
                return gatewayInfo;
            }
        }

        public async Task<List<string>> GetAvailablePaymentMethodsAsync(string tenantId)
        {
            var paymentMethods = new List<string>();
