#include <openssl/err.h>

#define PORT 8080
#define MAX_CLIENTS 10
#define MAX_BUFFER_SIZE 2048

struct client_info {
    int socket;
    char buffer[MAX_BUFFER_SIZE];
};

struct backend_service {
    int socket;
    struct sockaddr_in address;
};

struct routing_rule {
    const char *url_regex;
    const char *target_url;
    const char *request_method;
};

struct proxy_config {
    int port;
    int max_clients;
    struct backend_service backend_services[MAX_BACKEND_SERVICES];
    int num_backend_services;
    struct routing_rule routing_rules[MAX_ROUTING_RULES];
    int num_routing_rules;
};

// initialize the proxy configuration
struct proxy_config config = {
    .port = PORT,
    .max_clients = MAX_CLIENTS,
    .num_backend_services = 0,
    .num_routing_rules = 0
};

int main() {
    // create a socket for the proxy server
    int proxy_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (proxy_socket < 0) {
        perror("Socket creation failed");
        exit(-1);
    }

    // bind the socket to a specific address and port
    struct sockaddr_in server_address;
    memset(&server_address, 0, sizeof(struct sockaddr_in));
    server_address.sin_family = AF_INET;
    server_address.sin_port = htons(config.port);
    server_address.sin_addr.s_addr = INADDR_ANY;

    if (bind(proxy_socket, (struct sockaddr *)&server_address, sizeof(struct sockaddr_in)) < 0) {
        perror("Binding failed");
        exit(-1);
    }

    // listen for incoming connections on the socket
    if (listen(proxy_socket, config.max_clients) < 0) {
        perror("Listening failed");
        exit(-1);
    }

    while (1) {
        // accept an incoming connection
        struct sockaddr_in client_address;
        memset(&client_address, 0, sizeof(struct sockaddr_in));
        int client_socket = accept(proxy_socket, (struct sockaddr *)&client_address, &client_address.sin_len);
        if (client_socket < 0) {
            perror("Accepting failed");
            exit(-1);
        }

        // handle the incoming connection
        struct client_info client = {
            .socket = client_socket,
            .buffer[MAX_BUFFER_SIZE] = {}
        };

        // read data from the client and write it to the backend service
        for (int i = 0; i < config.num_backend_services; i++) {
            if (write(client.socket, "GET / HTTP/1.1\r\nHost: localhost\r\n\r\n", sizeof("GET / HTTP/1.1\r\nHost: localhost\r\n\r\n") - 1) < 0) {
                perror("Writing to backend service failed");
            }

            // read data from the backend service and write it to the client
            struct sockaddr_in backend_address;
            memset(&backend_address, 0, sizeof(struct sockaddr_in));
            backend_address.sin_family = AF_INET;
            backend_address.sin_port = htons(config.backend_services[i].socket);
            backend_address.sin_addr.s_addr = INADDR_ANY;

            if (connect(client.socket, (struct sockaddr *)&backend_address, sizeof(struct sockaddr_in)) < 0) {
                perror("Connecting to backend service failed");
            }

            while (1) {
                char buffer[MAX_BUFFER_SIZE];
                memset(buffer, 0, sizeof(char) * MAX_BUFFER_SIZE);

                int read_size = read(client.socket, buffer, sizeof(char) * MAX_BUFFER_SIZE - 1);
                if (read_size < 0) {
                    perror("Reading from backend service failed");
                    break;
                } else if (read_size == 0) {
                    // the connection was closed by the backend service
                    break;
                }

                // write data to the client
                if (write(client.socket, buffer, read_size) < 0) {
                    perror("Writing to client failed");
                }
            }

            // close the connection with the backend service
            if (close(config.backend_services[i].socket) < 0) {
                perror("Closing connection to backend service failed");
            }
        }

        // close the connection with the client
        if (close(client.socket) < 0) {
            perror("Closing connection to client failed");
        }
    }

    return 0;
}
```

This code creates a socket for the proxy server and binds it to a specific address and port using `bind()` and `listen()` respectively. It then accepts incoming connections on the socket using `accept()`. Once an incoming connection is accepted, the program reads data from the client and writes it to the backend service using `write()`. The program then waits for data from the backend service and writes it to the client using `write()`. Finally, the program closes the connection with the client and the backend service.

In this implementation, the proxy server uses a single socket for both incoming connections and outgoing connections to the backend service. This means that the proxy server can handle multiple clients simultaneously and distribute incoming requests to the backend service accordingly.

However, there are some limitations to this implementation. For example, it assumes that all incoming requests are HTTP requests with no authentication or other headers. It also does not handle any errors that may occur during the communication between the client and the backend service. A more robust implementation would need to handle these cases as well.']

