    if (!issuer || !is_trusted_issuer(issuer)) {
        printf("Invalid issuer: %s\n", issuer ? issuer : "null");
        return -1;
    }

    // Check the subject
    char *subject = jwt_get_subject(payload);
    if (!subject || !is_valid_subject(subject)) {
        printf("Invalid subject: %s\n", subject ? subject : "null");
        return -1;
    }

    // Check the expiration time
    int64_t exp = jwt_get_expiration_time(payload);
    if (exp <= time(NULL)) {
        printf("Expired token\n");
        return -1;
    }

    // Check the not-before time
    int64_t nbf = jwt_get_not_before_time(payload);
    if (nbf > time(NULL)) {
