// resource type definitions
typedef struct {
    char *uuid;
    char *metadata;
} Resource;

// cache structure
typedef struct {
    int size;
    int capacity;
    Resource **resources;
} Cache;

// create a new cache with the given capacity
Cache *cache_new(int capacity) {
    Cache *cache = malloc(sizeof(Cache));
    cache->size = 0;
    cache->capacity = capacity;
    cache->resources = calloc(capacity, sizeof(Resource*));
    return cache;
}

// add a resource to the cache
void cache_add(Cache *cache, Resource *resource) {
    if (cache->size >= cache->capacity) {
        // evict oldest entry if capacity is reached
        CacheEntry *evicted = cache->resources[0];
        free(evicted->uuid);
        free(evicted->metadata);
        free(evicted);
        cache->size--;
    }
    Resource *new_resource = malloc(sizeof(Resource));
    new_resource->uuid = strdup(resource->uuid);
    new_resource->metadata = strdup(resource->metadata);
    cache->resources[cache->size++] = new_resource;
}

// get a resource from the cache by UUID
Resource *cache_get(Cache *cache, char *uuid) {
    for (int i=0; i<cache->size; i++) {
        Resource *resource = cache->resources[i];
        if (strcmp(resource->uuid, uuid) == 0) {
            return resource;
        }
    }
    return NULL;
}

// get a list of all resources in the catalog
List *catalog_get_all() {
    // iterate over each data store and fetch all resources
    List *resources = malloc(sizeof(List));
    resources->size = 0;
    resources->capacity = 1000;
    resources->items = calloc(1000, sizeof(Resource*));
