EncryptionService::EncryptionService() :
	m_mutex(), m_cache()
{
}

void EncryptionService::Initialize(const std::string& key, const std::string& salt, size_t iterations)
{
	// Initialize the encryption context with the given key and salt
	m_encryptionContext = EncryptionContext(key, salt, iterations);
}

std::vector<uint8_t> EncryptionService::Encrypt(const std::vector<uint8_t>& plaintext)
{
	// Acquire a lock on the mutex to prevent concurrent access to the cache
	std::lock_guard<std::mutex> lock(m_mutex);

	// Check if the cache contains an encrypted version of the plaintext
	if (m_cache.find(plaintext) != m_cache.end()) {
		return m_cache[plaintext];
	}

	// Encrypt the plaintext using AES-256-GCM and return the ciphertext
	std::vector<uint8_t> ciphertext = m_encryptionContext.Encrypt(plaintext);
	m_cache[plaintext] = ciphertext;
	return ciphertext;
}

void EncryptionService::Decrypt(const std::vector<uint8_t>& ciphertext)
{
	// Acquire a lock on the mutex to prevent concurrent access to the cache
	std::lock_guard<std::mutex> lock(m_mutex);

	// Check if the cache contains a decrypted version of the ciphertext
	if (m_cache.find(ciphertext) != m_cache.end()) {
		return m_cache[ciphertext];
	}

	// Decrypt the ciphertext using AES-256-GCM and return the plaintext
	std::vector<uint8_t> plaintext = m_encryptionContext.Decrypt(ciphertext);
	m_cache[ciphertext] = plaintext;
	return plaintext;
}

EncryptionService::~EncryptionService()
{
	// Clear the cache on destruction to free memory
	m_cache.clear();
}']

