// Coding Task: Design a modular C library to manage a dynamic linked list of NFAPI_CRC_INDICATION_PDU_T structures

#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <unistd.h>
#include <string.h>
#include <stdbool.h>

// Define the struct for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
  unsigned int RX_UE_INFORMATION_TAG;
  unsigned int RNTI;
  unsigned int CRC_INDICATION_REL8_TAG;
  bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the linked list struct
typedef struct LinkedList {
  NFAPI_CRC_INDICATION_PDU_T *data;
  struct LinkedList *next;
} LinkedList;

// Global variables for the linked list and mutex
LinkedList *head = NULL;
pthread_mutex_t mutex;

// Function to create a new node in the linked list
void addToLL(NFAPI_CRC_INDICATION_PDU_T data) {
  LinkedList *newNode = (LinkedList *)malloc(sizeof(LinkedList));
  newNode->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
  memcpy(newNode->data, &data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
  newNode->next = NULL;

  pthread_mutex_lock(&mutex);
  if (head == NULL) {
    head = newNode;
  } else {
    LinkedList *tmp = head;
    while (tmp->next != NULL) {
      tmp = tmp->next;
    }
    tmp->next = newNode;
  }
  pthread_mutex_unlock(&mutex);
}

// Function to retrieve a node from the linked list
NFAPI_CRC_INDICATION_PDU_T *getFromLL(unsigned int index) {
  if (index >= 0 && index < countLL()) {
    pthread_mutex_lock(&mutex);
    LinkedList *tmp = head;
    for (int i = 0; i < index; i++) {
      tmp = tmp->next;
    }
    pthread_mutex_unlock(&mutex);
    return tmp->data;
  } else {
    printf("Index out of bounds\n");
    return NULL;
  }
}

// Function to count the number of nodes in the linked list
int countLL() {
  pthread_mutex_lock(&mutex);
  int count = 0;
  LinkedList *tmp = head;
  while (tmp != NULL) {
    count++;
    tmp = tmp->next;
  }
  pthread_mutex_unlock(&mutex);
  return count;
}

// Function to delete a node from the linked list
void delFromLL(unsigned int index) {
  if (index >= 0 && index < countLL()) {
    pthread_mutex_lock(&mutex);
    LinkedList *tmp = head;
    for (int i = 0; i < index - 1; i++) {
      tmp = tmp->next;
    }
    LinkedList *tmp2 = tmp->next;
    free(tmp2->data);
    free(tmp2);
    tmp->next = NULL;
    pthread_mutex_unlock(&mutex);
  } else {
    printf("Index out of bounds\n");
  }
}

// Function to update a node in the linked list
void updatell(NFAPI_CRC_INDICATION_PDU_T data, unsigned int index) {
  if (index >= 0 && index < countLL()) {
    pthread_mutex_lock(&mutex);
    LinkedList *tmp = head;
    for (int i = 0; i < index - 1; i++) {
      tmp = tmp->next;
    }
    free(tmp->data);
    tmp->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memcpy(tmp->data, &data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_unlock(&mutex);
  } else {
    printf("Index out of bounds\n");
  }
}

// Function to print the linked list
void printLL() {
  pthread_mutex_lock(&mutex);
  LinkedList *tmp = head;
  while (tmp != NULL) {
    NFAPI_CRC_INDICATION_PDU_T *data = tmp->data;
    printf("RX_UE_INFORMATION_TAG: %u, RNTI: %u, CRC_INDICATION_REL8_TAG: %u, CRCFLAG: %d\n", data->RX_UE_INFORMATION_TAG, data->RNTI, data->CRC_INDICATION_REL8_TAG, data->CRCFLAG);
    tmp = tmp->next;
  }
  pthread_mutex_unlock(&mutex);
}

// Function to free the linked list
void freeLL() {
  pthread_mutex_lock(&mutex);
  LinkedList *tmp = head;
  while (tmp != NULL) {
    LinkedList *next = tmp->next;
    free(tmp->data);
    free(tmp);
    tmp = next;
  }
  pthread_mutex_unlock(&mutex);
}
```

This is a C library for managing a dynamic linked list of `NFAPI_CRC_INDICATION_PDU_T` structures. The library supports concurrent access from multiple threads and provides functions for adding, retrieving, updating, counting, and freeing the linked list. The library also provides a function to print the linked list to standard output.

