class ConfigurableTransformationRules {
private:
    unordered_map<string, vector<string>> rules;
    mutex mtx;
public:
    ConfigurableTransformationRules() {}

    void addRule(const string& key, const vector<string>& value) {
        unique_lock<mutex> lock(mtx);
        rules[key] = value;
    }

    bool removeRule(const string& key) {
        unique_lock<mutex> lock(mtx);
        return rules.erase(key);
    }

    const vector<string>& getRules() const {
        return rules;
    }
};

class DataProcessor {
private:
    ConfigurableTransformationRules rules;
    atomic_bool running;
    mutex mtx;
    condition_variable cv;
    thread* worker;
public:
    DataProcessor(const ConfigurableTransformationRules& rules) : rules(rules), running(false) {}

    void start() {
        unique_lock<mutex> lock(mtx);
        if (running.exchange(true)) return; // double-checked locking pattern
        worker = new thread(&DataProcessor::processLoop, this);
    }

    void stop() {
        unique_lock<mutex> lock(mtx);
        running.exchange(false);
        cv.notify_one();
        if (worker) {
            worker->join();
            delete worker;
            worker = nullptr;
        }
    }

    void processLoop() {
        while (running.load()) {
            unique_lock<mutex> lock(mtx);
            cv.wait(lock, [this] { return !running.load(); });
            if (!running) break;
            // implement your data processing logic here
