#ifndef RANDOM_NUMBER_GENERATION_HPP
#define RANDOM_NUMBER_GENERATION_HPP

#include <iostream>
#include <ctime>
#include <chrono>
#include <thread>
#include <mutex>
#include <vector>
#include <string>
#include <algorithm>
#include <cstdlib>
#include <cerrno>

namespace rng {
    using seed_type = std::uint32_t;
    using rng_result = std::pair<seed_type, double>;
    using rng_error = std::runtime_error;
    using time_type = std::chrono::system_clock::time_point;

    class rng {
    private:
        seed_type _seed;
        std::mutex _mutex;

        // Mersenne Twister algorithm
        static constexpr int mt_size = 624;
        std::vector<seed_type> _mt;

        void mt_init(const seed_type& seed) {
            if (seed == 0) {
                throw rng_error("Invalid seed value");
            }

            // Initialize the Mersenne Twister algorithm
            for (int i = 0; i < mt_size; ++i) {
                _mt[i] = 1812433253 * (_mt[i - 1] ^ (_mt[i - 1] >> 30)) + i;
            }
        }

        double mt_generate(const seed_type& seed) {
            if (seed == 0) {
                throw rng_error("Invalid seed value");
            }

            // Generate a random number using the Mersenne Twister algorithm
            std::vector<double> result;
            for (int i = 0; i < mt_size; ++i) {
                const int j = (i + 1) % mt_size;
                const double x = (double)_mt[i] / ((double)_mt[j] + 1.0);
                result.push_back(x);
            }

            return result[result.size() - 1];
        }

    public:
        rng(const seed_type& seed = time_type::clock_type::now().time_since_epoch().count()) {
            mt_init(seed);
        }

        void set_seed(const seed_type& seed) {
            std::lock_guard<std::mutex> lock(_mutex);
            _seed = seed;
            mt_init(seed);
        }

        seed_type get_seed() const {
            return _seed;
        }

        double generate() {
            std::lock_guard<std::mutex> lock(_mutex);
            return mt_generate(_seed);
        }
    };

    // DNS resolution functionality
    class dns_resolver {
    private:
        using result_type = std::pair<std::string, std::vector<std::string>>;
        using error_type = std::runtime_error;

        static constexpr int dns_query_frequency = 1000;
        static constexpr int dns_timeout = 3000; // milliseconds

        bool _is_initialized;
        std::string _dns_server;
        std::vector<std::thread> _dns_threads;

        void dns_init(const std::string& dns_server) {
            if (dns_server.empty()) {
                throw error_type("Invalid DNS server");
            }

            // Initialize the DNS resolver
            _dns_server = dns_server;
            _is_initialized = true;
        }

        result_type dns_resolve(const std::string& hostname) {
            if (hostname.empty()) {
                throw error_type("Invalid hostname");
            }

            // Resolve the DNS query using the DNS server
            const int ipv4_max = 256;
            const int ipv6_max = 8192;
            std::vector<std::string> result;
            for (int i = 0; i < dns_query_frequency && i < ipv4_max + ipv6_max; ++i) {
                const std::string query = hostname + ".";
                struct addrinfo hints, *res;
                memset(&hints, 0, sizeof(hints));
                hints.ai_family = AF_UNSPEC;
                hints.ai_socktype = SOCK_STREAM;
                int err = getaddrinfo(_dns_server.c_str(), nullptr, &hints, &res);
                if (err != 0) {
                    throw error_type(std::string("DNS resolution failed: ") + gai_strerror(err));
                }

                // Iterate through the results and extract IP addresses
                for (struct addrinfo *p = res; p != nullptr && p->ai_addr != nullptr; p = p->ai_next) {
                    char ip[INET6_ADDRSTRLEN];
                    if (getnameinfo(p->ai_addr, p->ai_addrlen, ip, sizeof(ip), nullptr, 0, NI_NUMERICHOST) == 0) {
                        result.push_back(std::string(ip));
                    }
                }
                freeaddrinfo(res);
            }

            return result;
        }

    public:
        dns_resolver(const std::string& dns_server) {
            dns_init(dns_server);
        }

        bool is_initialized() const {
            return _is_initialized;
        }

        void set_dns_server(const std::string& dns_server) {
            std::lock_guard<std::mutex> lock(_mutex);
            dns_init(dns_server);
        }

        std::string get_dns_server() const {
            return _dns_server;
        }

        result_type resolve(const std::string& hostname) {
            std::lock_guard<std::mutex> lock(_mutex);
            if (!is_initialized()) {
                throw error_type("DNS resolver not initialized");
            }
            return dns_resolve(hostname);
        }
    };
}

#endif // RANDOM_NUMBER_GENERATION_HPP
```']

