public class MoSTStateManager {
    private final Semaphore semaphore;
    private final Map<String, Function<MoSTState, Boolean>> validationServices;

    public MoSTStateManager() {
        this.semaphore = new Semaphore(0);
        this.validationServices = new HashMap<>();
    }

    // Add a new validation service to the manager
    public void addValidationService(String name, Function<MoSTState, Boolean> validator) {
        this.validationServices.put(name, validator);
    }

    // Remove an existing validation service from the manager
    public void removeValidationService(String name) {
        this.validationServices.remove(name);
    }

    // Validate a MoSTState object against all registered validation services
    public boolean validateMoSTState(MoSTState state) {
        // Acquire semaphore to limit concurrent access to the manager
        try (SemaphoreLock lock = this.semaphore.acquire()) {
            for (Map.Entry<String, Function<MoSTState, Boolean>> entry : this.validationServices.entrySet()) {
                String serviceName = entry.getKey();
                Function<MoSTState, Boolean> validator = entry.getValue();
                if (!validator.apply(state)) {
                    // If any validation service fails, return false immediately
                    return false;
                }
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new RuntimeException("Error validating MoSTState", e);
        }

        // If all validation services pass, return true
        return true;
    }
}
