use std::time::Instant;
use std::process::{Command, Output};
use sync::{Arc, Mutex};

fn measure_compile_time(program: &str) -> (u64, u64) {
    let start = Instant::now();
    let output = Command::new("rustc")
        .arg(program)
        .output()
        .expect("failed to execute rustc");
    let end = Instant::now();
    (end - start).as_secs(), output.stderr.len() as u64
}
