class CircuitBreaker:
    def __init__(self, timeout=10):
        self.timeout = timeout
        self.last_call = None

    def call(self, function):
        if self.last_call is not None and (datetime.now() - self.last_call).total_seconds() < self.timeout:
            return None

        result = function()
        self.last_call = datetime.now()
        return result
