    SyncLazy::new(|| {
        let logger = Logger::new();
        rustc_driver::set_logger(Box::new(logger));
    });
}

fn compile_with_logging_hook<P: AsRef<Path>>(path: P) -> (bool, i32) {
    // Measure the time taken for compilation.
    let start = time::Instant::now();

    // Compile the Rust code with a custom logging hook installed.
    let exit_code = Command::new("rustc")
        .arg(path)
        .env("RUSTC_LOG", "debug")
        .output()
        .unwrap();

    // Get the resident set size of the process before and after compilation.
    let rss_before = get_resident_set_size().unwrap();
    let rss_after = get_resident_set_size().unwrap();

    // Print the compilation time and memory usage statistics.
