                        if response.is_success() {
                            break;
                        } else {
                            retries -= 1;
                            if retries == 0 {
                                self.errors.push(format!(
                                    "Failed to fetch transaction {} after {} retries",
                                    transaction.id, self.retries
                                ));
                                break;
                            } else {
                                thread::sleep(Duration::from_secs(2));
                            }
                        }
                    }
                    Err(e) => {
                        retries -= 1;
                        if retries == 0 {
                            self.errors.push(format!("Failed to fetch transaction {} after {} retries: {:?}", transaction.id, self.retries, e));
                            break;
                        } else {
                            thread::sleep(Duration::from_secs(2));
                        }
                    }
                }
            }
        }

