using namespace std;

// Define the different resolution levels for the MRG
const int LOW_RESOLUTION = 0;
const int MEDIUM_RESOLUTION = 1;
const int HIGH_RESOLUTION = 2;

// Define a struct to store spatial data at each resolution level
struct SpatialData {
    vector<double> points; // vector of x and y coordinates
    vector<int> ids; // vector of IDs associated with the points
};

// Define a class to manage the MRG
class MrgManager {
private:
    map<int, SpatialData> dataMap; // map from resolution level to spatial data
    mutex mtx; // mutex for synchronizing access to the data map
    condition_variable cv; // condition variable for signaling changes in the data map

public:
    MrgManager() {}

    // Add spatial data at a specific resolution level
    void addData(int resolution, vector<double> points, vector<int> ids) {
        lock_guard<mutex> lck(mtx);
        SpatialData data = {points, ids};
        dataMap[resolution] = data;
    }

    // Remove spatial data at a specific resolution level
    void removeData(int resolution) {
        lock_guard<mutex> lck(mtx);
        dataMap.erase(resolution);
    }

    // Query spatial data at a specific resolution level
    vector<double> queryData(int resolution) {
        lock_guard<mutex> lck(mtx);
        SpatialData data = dataMap[resolution];
        return data.points;
    }

    // Handle incoming spatial data from an external service
    void handleIncomingData(vector<double> points, vector<int> ids) {
