        addData(HIGH_RESOLUTION, points, ids);
    }

    // Handle incoming spatial data from an external service
    void handleIncomingData(vector<double> points) {
        lock_guard<mutex> lck(mtx);
        SpatialData data = queryData(HIGH_RESOLUTION);
        addData(MEDIUM_RESOLUTION, data.points, data.ids);
    }
};

// Define a thread to handle incoming spatial data from an external service
void handleIncomingDataThread() {
    MrgManager mrg;
    while (true) {
