        mrg.handleIncomingData(points);
    }
}

// Define a thread to handle dynamic spatial data operations at different resolution levels
void handleDynamicSpatialDataThread() {
    MrgManager mrg;
    while (true) {
        // Get the next dynamic spatial operation request
        vector<double> points = getNextOperationRequest();

        // Handle the operation and update the MRG accordingly
        mrg.handleDynamicSpatialData(points);
    }
}
