async function processFiles(files) {
    const fileMap = {}; // Map of files to be processed
    const taskQueue = []; // Queue of task objects

    for (let i = 0; i < files.length; i++) {
        const filePath = files[i].filePath;
        if (!fileMap[filePath]) {
            fileMap[filePath] = true;
            taskQueue.push({ filePath });
        }
    }

