// Modular Cryptographic Framework in C

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/aes.h>
#include <openssl/camellia.h>
#include <openssl/md5.h>
#include <openssl/sha.h>
#include <openssl/rsa.h>
#include <openssl/pem.h>
#include <openssl/err.h>

// Define constants for the cryptographic primitives
#define AES_PRIMITIVE 1
#define CAMELLIA_PRIMITIVE 2
#define MD5_DIGEST 3
#define SHA256_DIGEST 4
#define SHA512_DIGEST 5
#define RSA_SIGNATURE 6

// Define structure for the cryptographic context
typedef struct {
    int primitive; // Primitive type (AES, Camellia, MD5, SHA-256, SHA-512, or RSA)
    void *context; // Pointer to the OpenSSL context
} CryptContext;

// Define function pointers for the cryptographic primitives
typedef struct {
    int (*init)(CryptContext *ctx); // Initialization function
    int (*update)(CryptContext *ctx, const void *data, size_t len); // Update function
    int (*finalize)(CryptContext *ctx, unsigned char *digest, size_t *len); // Finalization function
} CryptPrimitive;

// Define the mapping between primitive types and functions
static CryptPrimitive primitives[] = {
    [AES_PRIMITIVE] = { AES_init_ctx, AES_update, AES_final },
    [CAMELLIA_PRIMITIVE] = { Camellia_init_key, Camellia_crypt, Camellia_end },
    [MD5_DIGEST] = { MD5_Init, MD5_Update, MD5_Final },
    [SHA256_DIGEST] = { SHA256_Init, SHA256_Update, SHA256_Final },
    [SHA512_DIGEST] = { SHA512_Init, SHA512_Update, SHA512_Final },
    [RSA_SIGNATURE] = { RSA_sign, NULL, RSA_verify }
};

// Define function to get the number of primitives
int numPrimitives() {
    return sizeof(primitives) / sizeof(primitives[0]);
}

// Function to initialize a cryptographic context
int initCryptContext(CryptContext *ctx, int primitive, void *context) {
    // Set the primitive type and context
    ctx->primitive = primitive;
    ctx->context = context;

    return 0;
}

// Function to update a cryptographic context with new data
int updateCryptContext(CryptContext *ctx, const void *data, size_t len) {
    // Call the update function for the corresponding primitive
    if (primitives[ctx->primitive].update != NULL) {
        return primitives[ctx->primitive].update(ctx->context, data, len);
    } else {
        return -1;
    }
}

// Function to finalize a cryptographic context and get the digest/signature
int finalizeCryptContext(CryptContext *ctx, unsigned char *digest, size_t *len) {
    // Call the finalization function for the corresponding primitive
    if (primitives[ctx->primitive].finalize != NULL) {
        return primitives[ctx->primitive].finalize(ctx->context, digest, len);
    } else {
        return -1;
    }
}

// Function to clean up a cryptographic context and free its resources
int cleanupCryptContext(CryptContext *ctx) {
    // Call the cleanup function for the corresponding primitive
    if (primitives[ctx->primitive].cleanup != NULL) {
        return primitives[ctx->primitive].cleanup(ctx->context);
    } else {
        return -1;
    }
}

// Function to register a custom cryptographic algorithm
int registerCustomPrimitive(const char *name, CryptPrimitive primitive) {
    // Check if the name is already taken
    for (int i = 0; i < numPrimitives(); i++) {
        if (strcmp(name, primitives[i].name) == 0) {
            return -1;
        }
    }

    // Add the new primitive to the list of known primitives
    primitives[numPrimitives()] = primitive;

    return 0;
}

// Function to register a custom digest alias
int registerDigestAlias(const char *name, int primitive) {
    // Check if the name is already taken
    for (int i = 0; i < numPrimitives(); i++) {
        if (strcmp(name, primitives[i].name) == 0) {
            return -1;
        }
    }

    // Add the new primitive to the list of known primitives
    primitives[numPrimitives()] = primitive;

    return 0;
}

// Function to register a custom signature alias
int registerSignatureAlias(const char *name, int primitive) {
    // Check if the name is already taken
    for (int i = 0; i < numPrimitives(); i++) {
        if (strcmp(name, primitives[i].name) == 0) {
            return -1;
        }
    }

    // Add the new primitive to the list of known primitives
    primitives[numPrimitives()] = primitive;

    return 0;
}

// Function to load a cryptographic context from a string
int loadCryptContext(const char *string, CryptContext *ctx) {
    // Initialize the context with the default settings
    initCryptContext(ctx, DEFAULT_PRIMITIVE, NULL);

    // Check if the string is empty
    if (string == NULL || strlen(string) == 0) {
        return -1;
    }

    // Split the input string into tokens
    char *tokens[MAX_TOKENS];
    int numTokens = splitString(string, TOKEN_DELIMITER, tokens);

    // Check if there are enough tokens to load the context
    if (numTokens < MIN_TOKENS) {
        return -1;
    }

    // Load the primitive type and context
    int primitive = getPrimitive(tokens[0]);
    if (primitive == DEFAULT_PRIMITIVE) {
        return -1;
    }

    ctx->primitive = primitive;
    ctx->context = loadContext(tokens[1], primitive);

    // Check if the context was successfully loaded
    if (ctx->context == NULL) {
        return -1;
    }

    return 0;
}

// Function to save a cryptographic context to a string
int saveCryptContext(const CryptContext *ctx, char **string) {
    // Check if the context is valid
    if (ctx == NULL || ctx->context == NULL) {
        return -1;
    }

    // Get the name of the primitive type
    const char *name = getPrimitiveName(ctx->primitive);

    // Allocate memory for the output string
    *string = malloc(MAX_LENGTH * sizeof(char));

    // Build the output string
    sprintf(*string, "%s%c%s", name, TOKEN_DELIMITER, saveContext(ctx->context, name));

    return 0;
}

// Function to get the primitive type from a token
int getPrimitive(const char *token) {
    // Iterate over all known primitives
    for (int i = 0; i < numPrimitives(); i++) {
        if (strcmp(primitives[i].name, token) == 0) {
            return i;
        }
    }

    return DEFAULT_PRIMITIVE;
}

// Function to get the name of a primitive type
const char *getPrimitiveName(int primitive) {
    // Check if the primitive is valid
    if (primitive < 0 || primitive >= numPrimitives()) {
        return NULL;
    }

    return primitives[primitive].name;
}

// Function to load a cryptographic context from a string
void *loadContext(const char *string, int primitive) {
    // Initialize the context with the default settings
    void *ctx = initContext(primitive);

    // Check if the string is empty
    if (string == NULL || strlen(string) == 0) {
        return ctx;
    }

    // Split the input string into tokens
    char *tokens[MAX_TOKENS];
    int numTokens = splitString(string, TOKEN_DELIMITER, tokens);

    // Check if there are enough tokens to load the context
    if (numTokens < MIN_TOKENS) {
        return ctx;
    }

    // Load the context parameters
    for (int i = 1; i < numTokens - 1; i++) {
        int param = getParam(tokens[i], primitive);
        if (param == DEFAULT_PARAM) {
            return ctx;
        }

        setParam(ctx, param, tokens[++i]);
    }

    // Return the loaded context
    return ctx;
}

// Function to save a cryptographic context to a string
char *saveContext(void *context, const char *name) {
    // Check if the context is valid
    if (context == NULL || name == NULL) {
        return "";
    }

    // Allocate memory for the output string
    int length = strlen(name) + 2;
    char *string = malloc(length * sizeof(char));

    // Build the output string
    sprintf(string, "%s%c", name, TOKEN_DELIMITER);

    // Get the parameters of the context
    int numParams = getNumParams(context);
    for (int i = 0; i < numParams; i++) {
        int param = getParam(i, context);
        if (param == DEFAULT_PARAM) {
            return string;
        }

        char *value = saveParam(context, param);
        length += strlen(value);
        string = realloc(string, length * sizeof(char));
        sprintf(string + strlen(string), "%s%c", value, TOKEN_DELIMITER);
    }

    return string;
}

// Function to get the number of parameters for a primitive type
int getNumParams(void *context) {
    // Check if the context is valid
    if (context == NULL) {
        return DEFAULT_NUM_PARAMS;
    }

    // Get the primitive type and return the appropriate number of parameters
    int primitive = getPrimitiveType(context);
    switch (primitive) {
        case HASH:
            return 1;
        case SYMMETRIC_ENCRYPTION:
            return 2;
        case ASYMMETRIC_ENCRYPTION:
            return 3;
        default:
            return DEFAULT_NUM_PARAMS;
    }
}

// Function to get the name of a parameter for a primitive type
const char *getParamName(int param, int primitive) {
    // Check if the parameter is valid
    if (param < 0 || param >= numParams(primitive)) {
        return NULL;
    }

    // Get the name of the parameter
    switch (primitive) {
        case HASH:
            switch (param) {
                case 0:
                    return "hash";
                default:
                    return NULL;
            }
        case SYMMETRIC_ENCRYPTION:
            switch (param) {
                case 0:
                    return "mode";
                case 1:
                    return "keySize";
                default:
                    return NULL;
            }
        case ASYMMETRIC_ENCRYPTION:
            switch (param) {
                case 0:
                    return "cipher";
                case 1:
                    return "curve";
                case 2:
                    return "hash";
                default:
                    return NULL;
            }
        default:
            return NULL;
    }
}

// Function to get the value of a parameter for a primitive type
const char *getParam(int param, void *context) {
    // Check if the context is valid
    if (context == NULL) {
        return NULL;
    }

    // Get the name and value of the parameter
    const char *name = getParamName(param);
    int value = getParamValue(context, name);

    // Return the value as a string
    if (value == DEFAULT_PARAM) {
        return NULL;
    } else {
        return toString(value);
    }
}

// Function to set the value of a parameter for a primitive type
void setParam(void *context, int param, const char *value) {
    // Check if the context is valid
    if (context == NULL || value == NULL) {
        return;
    }

    // Get the name and value of the parameter
    const char *name = getParamName(param);
    int paramValue = getParamValue(context, name);

    // Check if the parameter is valid
    if (paramValue == DEFAULT_PARAM) {
        return;
    }

    // Set the value of the parameter
    switch (param) {
        case 0:
            setHash(context, paramValue, value);
            break;
        case 1:
            setMode(context, paramValue, value);
            break;
        case 2:
            setCurve(context, paramValue, value);
            break;
        default:
            return;
    }
}

// Function to get the hash type of a context
int getHashType(void *context) {
    // Check if the context is valid
    if (context == NULL) {
        return DEFAULT_HASH_TYPE;
    }

    // Get the hash type from the context
    switch (getPrimitiveType(context)) {
        case HASH:
            return getHashTypeFromContext(context);
        default:
            return DEFAULT_HASH_TYPE;
    }
}

// Function to set the hash type of a context
void setHashType(void *context, int value) {
    // Check if the context is valid
    if (context == NULL || value < 0 || value >= NUM_HASHES) {
        return;
    }

    // Set the hash type in the context
    switch (getPrimitiveType(context)) {
        case HASH:
            setHashTypeInContext(context, value);
            break;
        default:
            return;
    }
}

// Function to get the mode of a symmetric encryption algorithm
int getMode(void *context) {
    // Check if the context is valid
    if (context == NULL) {
        return DEFAULT_MODE;
    }

    // Get the mode from the context
    switch (getPrimitiveType(context)) {
        case SYMMETRIC_ENCRYPTION:
            return getModeFromContext(context);
        default:
            return DEFAULT_MODE;
    }
}

// Function to set the mode of a symmetric encryption algorithm
void setMode(void *context, int value) {
    // Check if the context is valid
    if (context == NULL || value < 0 || value >= NUM_SYMMETRIC_ENCRYPTION_MODES) {
        return;
    }

    // Set the mode in the context
    switch (getPrimitiveType(context)) {
        case SYMMETRIC_ENCRYPTION:
            setModeInContext(context, value);
            break;
        default:
            return;
    }
}

// Function to get the curve of an asymmetric encryption algorithm
int getCurve(void *context) {
    // Check if the context is valid
    if (context == NULL) {
        return DEFAULT_CURVE;
    }

    // Get the curve from the context
    switch (getPrimitiveType(context)) {
        case ASYMMETRIC_ENCRYPTION:
            return getCurveFromContext(context);
        default:
            return DEFAULT_CURVE;
    }
}

// Function to set the curve of an asymmetric encryption algorithm
void setCurve(void *context, int value) {
    // Check if the context is valid
    if (context == NULL || value < 0 || value >= NUM_ASYMMETRIC_ENCRYPTION_CURVES) {
        return;
    }

    // Set the curve in the context
    switch (getPrimitiveType(context)) {
        case ASYMMETRIC_ENCRYPTION:
            setCurveInContext(context, value);
            break;
        default:
            return;
    }
}']

