    // Wait for a new unique identifier to become available
    Lock lock(uniqueDataMutex);
    while (true) {
      bool hasAvailableId = false;
      for (auto& id : uniqueIdentifiers) {
        if (!id.available) {
          hasAvailableId = true;
          break;
        }
      }
      if (hasAvailableId) {
        break;
      }
      conditionVariable->wait(lock);
    }

    // Assign the unique identifier to a waiting thread and update the shared data structure
    for (auto& id : uniqueIdentifiers) {
      if (!id.available) {
        id.available = true;
        for (auto& entry : sharedData) {
          if (entry.second == id) {
            conditionVariable->notify_all();
            break;
          }
        }
      }
    }
  }
}

