Here is a sample code block that implements a modular, extensible, and scalable HTTP server framework in C:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>

#define MAX_CONNECTIONS 1024
#define BUFFER_SIZE 4096

struct connection {
    int socket;
    struct sockaddr_in address;
};

struct request {
    char *path;
    char *method;
    char *body;
    size_t body_size;
};

struct response {
    int status;
    char *headers[10];
    char *body;
    size_t body_size;
};

void handle_connection(int socket, struct sockaddr_in address) {
    // Read request from client
    char buffer[BUFFER_SIZE];
    memset(buffer, 0, BUFFER_SIZE);
    ssize_t bytes_read = read(socket, buffer, BUFFER_SIZE);
    if (bytes_read < 0) {
        perror("read");
        exit(EXIT_FAILURE);
    }

    // Parse request
    struct request *request = parse_request(buffer);

    // Handle request
    struct response *response = handle_request(request);

    // Send response to client
    char buffer[BUFFER_SIZE];
    memset(buffer, 0, BUFFER_SIZE);
    ssize_t bytes_written = write(socket, buffer, BUFFER_SIZE);
    if (bytes_written < 0) {
        perror("write");
        exit(EXIT_FAILURE);
    }
}

struct request *parse_request(char *buffer) {
    struct request *request = malloc(sizeof(struct request));
    memset(request, 0, sizeof(struct request));

    // Parse method and path
    char *method = strtok(buffer, " ");
    request->method = method;
    char *path = strtok(NULL, " ");
    request->path = path;

    // Parse headers
    while (1) {
        char *header_name = strtok(NULL, ":");
        if (!header_name) {
            break;
        }
        char *header_value = strtok(NULL, "\r\n");
        request->headers[strlen(header_name)] = header_value;
    }

    // Parse body
    size_t body_size = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (buffer[i] == '\r') {
            body_size = i;
            break;
        }
    }
    request->body = buffer + body_size + 1;
    request->body_size = body_size;

    return request;
}

struct response *handle_request(struct request *request) {
    struct response *response = malloc(sizeof(struct response));
    memset(response, 0, sizeof(struct response));

    // Handle the request based on the method and path
    if (strcmp(request->method, "GET") == 0 && strcmp(request->path, "/") == 0) {
        response->status = 200;
        response->headers[0] = "Content-Type: text/html";
        response->body = "<html><body>Hello World!</body></html>";
    } else if (strcmp(request->method, "POST") == 0 && strcmp(request->path, "/echo") == 0) {
        response->status = 200;
        response->headers[0] = "Content-Type: text/plain";
        char *body = malloc(sizeof(char) * request->body_size);
        memcpy(body, request->body, request->body_size);
        response->body = body;
    } else {
        response->status = 404;
        response->headers[0] = "Content-Type: text/plain";
        response->body = "Not Found";
    }

    return response;
}

int main() {
    int server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket < 0) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_port = htons(8080);
    inet_pton(AF_INET, "127.0.0.1", &address.sin_addr);

    if (bind(server_socket, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind");
        exit(EXIT_FAILURE);
    }

    if (listen(server_socket, MAX_CONNECTIONS) < 0) {
        perror("listen");
        exit(EXIT_FAILURE);
    }

    while (1) {
        struct connection *connection = malloc(sizeof(struct connection));
        memset(connection, 0, sizeof(struct connection));
        connection->socket = accept(server_socket, NULL, NULL);
        if (connection->socket < 0) {
            perror("accept");
            exit(EXIT_FAILURE);
        }

        handle_connection(connection);
    }

    return 0;
}
```
This is a basic web server that listens on port 8080 and responds to GET requests. It uses the `socket` function to create a socket, the `bind` function to bind the socket to a specific address, the `listen` function to listen for incoming connections, and the `accept` function to accept an incoming connection.

The `handle_connection` function is where we handle the request and send the response back to the client. It first parses the request using the `parse_request` function, then handles the request based on the method and path. Finally, it sends the response back to the client using the `send_response` function.

Note that this is just a basic example, you should consider implementing some security measures like sanitizing user input, validating requests, and handling errors appropriately.']

