using System;
using System.Threading.Tasks;
using System.Collections.Generic;
using System.Linq;
using Microsoft.Extensions.Logging;
using Newtonsoft.Json;
using IdentityModel.Client;

public class UserAuthenticationService : IUserAuthenticationService
{
    private readonly ILogger<UserAuthenticationService> _logger;
    private readonly IDictionary<string, ExternalIdentityProviderConfig> _externalIdentityProviders;

    public UserAuthenticationService(ILogger<UserAuthenticationService> logger, IEnumerable<ExternalIdentityProviderConfig> externalIdentityProviders)
    {
        _logger = logger;
        _externalIdentityProviders = externalIdentityProviders.ToDictionary(x => x.Name);
    }

    public async Task<AuthenticatedUser> AuthenticateAsync(string username, string password, string[] scopes)
    {
        var authenticationResult = await AuthenticateViaExternalIdentityProvidersAsync(username, password, scopes);

        if (authenticationResult.Status == AuthenticationStatus.Success)
        {
            return new AuthenticatedUser(authenticationResult.AccessToken, authenticationResult.IdToken, authenticationResult.RefreshToken, authenticationResult.Username);
        }
        else
        {
            throw new Exception("Authentication failed");
        }
    }

    private async Task<AuthenticationResult> AuthenticateViaExternalIdentityProvidersAsync(string username, string password, string[] scopes)
    {
        var authenticationResults = new List<AuthenticationResult>();

        foreach (var externalIdentityProvider in _externalIdentityProviders)
        {
            try
            {
                var result = await AuthenticateViaExternalIdentityProviderAsync(username, password, scopes, externalIdentityProvider.Value);
                authenticationResults.Add(result);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Failed to authenticate via {externalIdentityProvider.Key}");
            }
        }

        var successfulAuthenticationResults = authenticationResults.Where(x => x.Status == AuthenticationStatus.Success);

        if (successfulAuthenticationResults.Any())
        {
            return successfulAuthenticationResults.First();
        }
        else
        {
            throw new Exception("No authentication providers were successful");
        }
    }

    private async Task<AuthenticationResult> AuthenticateViaExternalIdentityProviderAsync(string username, string password, string[] scopes, ExternalIdentityProviderConfig externalIdentityProvider)
    {
        var client = new HttpClient();

        // Configure HTTP client with authentication headers and other options
        client.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", "YOUR_ACCESS_TOKEN");
        client.Timeout = TimeSpan.FromSeconds(5);

        var tokenResponse = await client.RequestClientCredentialsTokenAsync(new ClientCredentialsTokenRequest
        {
            Address = externalIdentityProvider.TokenEndpoint,
            ClientId = "YOUR_CLIENT_ID",
            ClientSecret = "YOUR_CLIENT_SECRET",
            Scope = scopes
        });

        if (tokenResponse.IsError)
        {
            throw new Exception($"Failed to authenticate via {externalIdentityProvider.Name}: {tokenResponse.Error}");
        }
        else
        {
            var usernameClaim = tokenResponse.IdentityToken.Claims.FirstOrDefault(x => x.Type == "username");

            if (usernameClaim != null && usernameClaim.Value == username)
            {
                return new AuthenticationResult
                {
                    Status = AuthenticationStatus.Success,
                    AccessToken = tokenResponse.AccessToken,
                    IdToken = tokenResponse.IdentityToken,
                    RefreshToken = tokenResponse.RefreshToken,
                    Username = usernameClaim.Value
                };
            }
            else
            {
                return new AuthenticationResult { Status = AuthenticationStatus.Failed };
            }
        }
    }
}

public class ExternalIdentityProviderConfig
{
