using System.Threading.Tasks;

namespace WebsiteMetadataExtractor
{
    class Program
    {
        private static readonly string[] _metadataServices = new string[] { "https://example1.com", "https://example2.com" };
        private static readonly int _maxDirectoryPathLength = 100;
        private static readonly bool _enableLogging = true;
        private static readonly LogLevel _logLevel = LogLevel.Debug;
        private static readonly string _outputFormat = "JSON";

        private static void Main(string[] args)
        {
            // Parse command-line arguments
            var options = new Options(args);

            // Initialize logging framework
            if (_enableLogging)
            {
                Log.Initialize();
            }

            // Process each website in the repository
            foreach (var website in GetWebsites())
            {
                try
                {
                    // Validate directory path length and handle missing web.config file gracefully
                    if (website.DirectoryPath.Length > _maxDirectoryPathLength)
                    {
                        Log.Error($"Invalid directory path length for website {website.Name}: {website.DirectoryPath}");
                        continue;
                    }

                    // Extract metadata from each service and append it to the site name in a structured format
                    var metadata = new Dictionary<string, string>();
                    foreach (var service in _metadataServices)
                    {
                        try
                        {
                            var response = await GetMetadataAsync(service, website.Url);
                            metadata[service] = response;
                        }
                        catch (Exception e)
                        {
                            Log.Error($"Failed to retrieve metadata from service {service} for website {website.Name}: {e.Message}");
                        }
                    }

                    // Output results in the requested format
                    var output = FormatOutput(metadata);
                    Console.WriteLine(output);
                }
                catch (Exception e)
                {
                    Log.Error($"Failed to process website {website.Name}: {e.Message}");
                }
            }
        }

        private static IEnumerable<Website> GetWebsites()
        {
            // Read websites from a file or database
            return new List<Website>
            {
                new Website("https://example1.com", "Example 1"),
                new Website("https://example2.com", "Example 2")
            };
        }

        private static async Task<string> GetMetadataAsync(string service, string url)
        {
            // Call the metadata extraction service and return its response
            using (var client = new HttpClient())
            {
                var request = new HttpRequestMessage(HttpMethod.Get, $"{service}?url={url}");
                var response = await client.SendAsync(request);
                return await response.Content.ReadAsStringAsync();
            }
        }

        private static string FormatOutput(Dictionary<string, string> metadata)
        {
            // Use the output format specified in the options to generate a formatted string for each website
            switch (_outputFormat)
            {
                case "JSON":
                    return JsonConvert.SerializeObject(metadata);
                case "CSV":
                    var builder = new StringBuilder();
                    foreach (var entry in metadata)
                    {
                        builder.AppendLine($"{entry.Key},{entry.Value}");
                    }
                    return builder.ToString();
                default:
                    throw new ArgumentException("Invalid output format specified.");
            }
        }
    }

    public class Website
    {
        public string Url { get; set; }
        public string Name { get; set; }
        public string DirectoryPath { get; set; }
    }
}
