// Define the semaphore structure
typedef struct {
    int32_t value; // Current value of the semaphore
    int32_t limit; // Maximum allowed value for the semaphore
    int64_t timestamp; // Timestamp when the semaphore was created or last updated
} Semaphore;

// Define the semaphore state structure
typedef struct {
    int32_t id; // ID of the semaphore
    char *name; // Name of the semaphore
    bool is_deleted; // Whether the semaphore has been deleted or not
    Semaphore *semaphore; // Pointer to the semaphore structure
} SemaphoreState;

// Function prototypes
int32_t createSemaphore(const char *name, int32_t limit);
bool deleteSemaphore(const char *name);
bool modifySemaphore(const char *name, int32_t value);
Semaphore *getSemaphore(const char *name);
void printSemaphoreInfo(const SemaphoreState *state);
int64_t getTimestamp();
void sleepMilliseconds(int32_t milliseconds);
void backoff(int32_t attempts, int32_t minimum_delay, int32_t maximum_delay);

// Main function
int main() {
    // Initialize the semaphore states map
    Map *semaphoreStates = createMap();

    // Create a new semaphore with ID 1 and name "example"
    SemaphoreState *state = createSemaphoreState(1, "example", NULL);
    insertElement(semaphoreStates, &state->id, state);

    // Print the current semaphore states
    printSemaphoreInfo(state);

    // Modify the value of the semaphore with ID 1 to 50
    modifySemaphore("example", 50);
    sleepMilliseconds(1000);

    // Print the current semaphore states
    printSemaphoreInfo(state);

    // Delete the semaphore with ID 1
    deleteSemaphore("example");
    sleepMilliseconds(1000);

    // Print the current semaphore states
    printSemaphoreInfo(state);

    return 0;
}

// Create a new semaphore state with the given ID, name, and semaphore
SemaphoreState *createSemaphoreState(int32_t id, const char *name, Semaphore *semaphore) {
    SemaphoreState *state = malloc(sizeof(SemaphoreState));
    state->id = id;
    state->name = strdup(name);
    state->is_deleted = false;
    if (semaphore == NULL) {
        semaphore = createSemaphore(name, 100);
    }
    state->semaphore = semaphore;
    return state;
}

// Delete the semaphore with the given name and mark it as deleted
bool deleteSemaphore(const char *name) {
    SemaphoreState *state = getSemaphoreState(name);
    if (state == NULL) {
        return false;
    }
    state->is_deleted = true;
    destroySemaphore(state->semaphore);
    return true;
}

// Modify the value of the semaphore with the given name and limit
bool modifySemaphore(const char *name, int32_t value) {
    SemaphoreState *state = getSemaphoreState(name);
    if (state == NULL) {
        return false;
    }
    state->semaphore->value = value;
    return true;
}

// Get the semaphore with the given name and create it if it doesn't exist
Semaphore *getSemaphore(const char *name) {
    SemaphoreState *state = getSemaphoreState(name);
    if (state == NULL) {
        return NULL;
    }
    return state->semaphore;
}

// Print the information of the semaphore with the given name
void printSemaphoreInfo(const SemaphoreState *state) {
    printf("ID: %d\nName: %s\nValue: %d\nLimit: %d\nIs Deleted: %s\n", state->id, state->name, state->semaphore->value, state->semaphore->limit, state->is_deleted ? "true" : "false");
}

// Get the semaphore state with the given name and create it if it doesn't exist
SemaphoreState *getSemaphoreState(const char *name) {
    SemaphoreState *state = (SemaphoreState *)lookupElement(semaphoreStates, name);
    if (state == NULL) {
        state = createSemaphoreState(-1, name, NULL);
        insertElement(semaphoreStates, &state->id, state);
    }
    return state;
}

// Create a new semaphore with the given name and limit
Semaphore *createSemaphore(const char *name, int32_t limit) {
    Semaphore *semaphore = malloc(sizeof(Semaphore));
    semaphore->value = 0;
    semaphore->limit = limit;
    semaphore->timestamp = getTimestamp();
    return semaphore;
}

// Destroy the given semaphore
void destroySemaphore(Semaphore *semaphore) {
    if (semaphore != NULL) {
        free(semaphore);
    }
}

// Get the current timestamp in milliseconds
int64_t getTimestamp() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (int64_t)ts.tv_sec * 1000 + (int64_t)ts.tv_nsec / 1000000;
}

// Sleep for the given number of milliseconds
void sleepMilliseconds(int32_t milliseconds) {
    usleep(milliseconds * 1000);
}
