// Third-party video encoding library
#include "video_encoding_lib.h"

#define BUFFER_SIZE 1024*1024*16 // 16 MB
#define THREAD_COUNT 8

struct node {
    int id;
    pthread_t thread;
};

struct queue {
    struct node *head;
    struct node *tail;
};

struct processing_context {
    int video_id;
    char *video_file;
    char *output_file;
    char *encoding_parameters;
};

struct video_file {
    char *path;
    unsigned long size;
    time_t modified_time;
};

struct node *create_node(int id) {
    struct node *node = malloc(sizeof(struct node));
    if (!node) {
        perror("Failed to allocate memory for node");
        exit(1);
    }
    node->id = id;
    node->thread = 0;
    return node;
}

void enqueue(struct queue *q, struct node *n) {
    if (!q->head) {
        q->head = n;
        q->tail = n;
    } else {
        q->tail->next = n;
        q->tail = n;
    }
}

void dequeue(struct queue *q, struct node *n) {
    if (q->head == n) {
        q->head = n->next;
    } else {
        struct node *prev = q->head;
        while (prev->next != n && prev->next) {
            prev = prev->next;
        }
        if (prev->next == n) {
            prev->next = n->next;
        }
    }
}

void *process_video(void *args) {
    struct node *n = args;
    struct processing_context *ctx = &n->processing_context;

    // Load video file and extract encoding parameters
    FILE *fp = fopen(ctx->video_file, "rb");
    if (!fp) {
        perror("Failed to open video file");
        return NULL;
    }
    unsigned long size = BUFFER_SIZE;
    char *buffer = malloc(size);
    if (!buffer) {
        perror("Failed to allocate memory for video buffer");
        fclose(fp);
        return NULL;
    }
    int read = fread(buffer, 1, size, fp);
    if (read < size) {
        // Video file is smaller than expected, adjust buffer size
        size = read;
    }
    fclose(fp);

    // Encode video using third-party library
    struct video_file *vf = malloc(sizeof(struct video_file));
    if (!vf) {
        perror("Failed to allocate memory for video file structure");
        free(buffer);
        return NULL;
    }
    vf->path = strdup(ctx->video_file);
    vf->size = size;
    time(&vf->modified_time);

    struct encoding_parameters *ep = encode_video(vf, ctx->encoding_parameters);
    if (!ep) {
        perror("Failed to encode video");
        free(buffer);
        free(vf);
        return NULL;
    }

    // Save encoded video file and update output file name
    char *output_file = malloc(strlen(ctx->video_file) + strlen(ep->extension) + 1);
    if (!output_file) {
        perror("Failed to allocate memory for output file name");
        free(buffer);
        free(vf);
        return NULL;
    }
    sprintf(output_file, "%s%s", ctx->video_file, ep->extension);
    fp = fopen(output_file, "wb");
    if (!fp) {
        perror("Failed to create output file");
        free(buffer);
        free(vf);
        return NULL;
    }
    write(fp, ep->data, ep->size);
    fclose(fp);

    // Clean up resources
    free(ep->data);
    free(ep);
    free(output_file);
    free(buffer);
    free(vf);

    dequeue(&q, n);
    pthread_exit(NULL);
}

int main() {
    struct queue q;
    q.head = NULL;
    q.tail = NULL;

    // Create worker threads
    pthread_t workers[THREAD_COUNT];
    for (int i = 0; i < THREAD_COUNT; ++i) {
        if (pthread_create(&workers[i], NULL, process_video, &q)) {
            perror("Failed to create worker thread");
            exit(1);
        }
    }

    // Load video files and enqueue for processing
    DIR *dir = opendir(".");
    if (!dir) {
        perror("Failed to open directory");
        return 1;
    }
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        // Skip hidden files and non-video files
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..")) {
            continue;
        }
        struct video_file vf = {.path = entry->d_name};
        struct encoding_parameters ep = encode_video(&vf);
        if (!ep.data) {
            perror("Failed to encode video");
            closedir(dir);
            return 1;
        }
    }
    closedir(dir);

    // Wait for worker threads to finish
    for (int i = 0; i < THREAD_COUNT; ++i) {
        if (pthread_join(workers[i], NULL)) {
            perror("Failed to join worker thread");
            exit(1);
        }
    }

    return 0;
}
