// Define a struct to represent a SensorNode object
struct SensorNode {
    int id;
    std::string sensorType;
    double location[2];
    bool status;
    double lastKnownValue;
};

// Define a class to manage the graph of SensorNodes
class SensorGraph {
public:
    // Constructor initializes the graph with an empty set of nodes
    SensorGraph() : nodes_(), mutex_(), condVar_() {}

    // Adds a new node to the graph and returns its ID
    int addNode(const std::string& sensorType, double location[2], bool status) {
        std::lock_guard<std::mutex> lock(mutex_);
        nodes_.push_back(SensorNode{nodes_.size(), sensorType, location, status, 0.0});
        return nodes_.back().id;
    }

    // Updates the status of a node in the graph
    void updateStatus(int id, bool status) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto& node : nodes_) {
            if (node.id == id) {
                node.status = status;
                break;
            }
        }
    }

    // Updates the location of a node in the graph
    void updateLocation(int id, double location[2]) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto& node : nodes_) {
            if (node.id == id) {
                node.location[0] = location[0];
                node.location[1] = location[1];
                break;
            }
        }
    }

    // Updates the last known value of a node in the graph
    void updateValue(int id, double value) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto& node : nodes_) {
            if (node.id == id) {
                node.lastKnownValue = value;
                break;
            }
        }
    }

    // Retrieves the status of a node in the graph
    bool getStatus(int id) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto& node : nodes_) {
            if (node.id == id) {
                return node.status;
            }
        }
        return false;
    }

    // Retrieves the location of a node in the graph
    double* getLocation(int id) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto& node : nodes_) {
            if (node.id == id) {
                return &node.location[0];
            }
        }
        return nullptr;
    }

    // Retrieves the last known value of a node in the graph
    double getValue(int id) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto& node : nodes_) {
            if (node.id == id) {
                return node.lastKnownValue;
            }
        }
        return 0.0;
    }

private:
    std::vector<SensorNode> nodes_; // Vector of all nodes in the graph
    std::mutex mutex_; // Mutex for protecting concurrent access to the graph
    std::condition_variable condVar_; // Condition variable for signaling changes to the graph
};

