#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

// Thread-safe queue data structure for concurrent data ingestion and processing
typedef struct Queue {
    int front, rear;
    int size;
    int *data;
} Queue;

// Function to initialize a queue with a given capacity
void initQueue(Queue *queue, int capacity) {
    queue->front = 0;
    queue->rear = -1;
    queue->size = capacity;
    queue->data = (int *)malloc(sizeof(int) * capacity);
}

// Function to enqueue an integer value in the queue
void enqueue(Queue *queue, int value) {
    if (queue->rear == queue->size - 1) {
        // Resize the queue if it is full
        queue->data = (int *)realloc(queue->data, sizeof(int) * (queue->size *= 2));
    }
    queue->data[++queue->rear] = value;
}

// Function to dequeue an integer value from the queue
int dequeue(Queue *queue) {
    if (queue->front > queue->rear) {
        // Return -1 if the queue is empty
        return -1;
    }
    int value = queue->data[queue->front++];
    if (queue->front == queue->size / 4) {
        // Resize the queue if it has become too small
        queue->data = (int *)realloc(queue->data, sizeof(int) * (queue->size /= 2));
    }
    return value;
}

// Function to calculate the number of disjoint pairs of elements in an integer array using a Union-Find data structure
void countPairs(int *arr, int size, int *count) {
    // Initialize the Union-Find data structure with the number of elements in the array
    int n = size;
    int *parent = (int *)malloc(sizeof(int) * n);
    for (int i = 0; i < n; i++) {
        parent[i] = i;
    }

    // Iterate through each element in the array and find its connected components
    for (int i = 0; i < size; i++) {
        int x = arr[i];
        int root = find(parent, x);
        if (root != -1) {
            count[root]++;
        }
    }
}

// Function to find the connected component of an element in the Union-Find data structure
int find(int *parent, int x) {
    if (parent[x] == x) {
        return x;
    } else {
        parent[x] = find(parent, parent[x]);
        return parent[x];
    }
}

// Function to union two elements in the Union-Find data structure
void union(int *parent, int x, int y) {
    int root1 = find(parent, x);
    int root2 = find(parent, y);
    if (root1 != -1 && root2 != -1) {
        parent[root1] = root2;
    }
}

// Main function to process the integers and calculate the number of disjoint pairs
int main() {
    int n; // Number of integers in the array
    scanf("%d", &n);
    int *arr = (int *)malloc(sizeof(int) * n);
    for (int i = 0; i < n; i++) {
        scanf("%d", &arr[i]);
    }

    // Initialize the Union-Find data structure and count the number of disjoint pairs
    int m = n / 4;
    int *parent = (int *)malloc(sizeof(int) * m);
    for (int i = 0; i < m; i++) {
        parent[i] = i;
    }
    int count[m];
    for (int i = 0; i < n; i++) {
        int x = arr[i];
        int root = find(parent, x);
        if (root != -1) {
            count[root]++;
        }
    }

    // Print the number of disjoint pairs and execution time
    for (int i = 0; i < m; i++) {
        printf("%d ", count[i]);
    }
    printf("Execution Time: %lf\n", ((double)clock() - tStart) / CLOCKS_PER_SEC);
    return 0;
}
