        performanceProfilingAndTuning();

        // Sleep for a short period to avoid consuming too much CPU resources
        sleep(1);
    }

    // Shutdown the semaphore and thread
    sem_destroy(&semaphore);
    pthread_join(thread, NULL);

    // Close the socket
    close(sock);

    return 0;
}

// Function to handle incoming data
void handleIncomingData(int socket, void* userdata) {
    int* sock = (int*)userdata;
    while (1) {
        // Read the next integer from the socket
        read(sock, buffer, BUFFER_SIZE);

        // Add the integer to the dynamic array
        sem_wait(&semaphore);
        if (array->size == array->capacity) {
            // Grow the dynamic array by a factor of 2
            int new_size = (int)(array->capacity * GROWTH_FACTOR);
            int* new_data = realloc(array->data, new_size * sizeof(int));
            if (new_data == NULL) {
                // If realloc fails, shrink the dynamic array by a factor of 0.5
                new_size = (int)(array->capacity * RESIZE_FACTOR);
                int* new_data = realloc(array->data, new_size * sizeof(int));
                if (new_data == NULL) {
                    fprintf(stderr, "Error: Failed to grow or shrink the dynamic array.\n");
                    exit(1);
                } else {
                    array->capacity = new_size;
                    array->data = new_data;
                }
            } else {
                array->capacity = new_size;
                array->data = new_data;
            }
        }
        int* data = (int*)array->data;
        data[array->size] = atoi(buffer);
        array->size++;
        sem_post(&semaphore);
    }
}

