// GatewayManager.java

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;

public class GatewayManager {
    private static final int CORE_POOL_SIZE = 10;
    private static final int MAXIMUM_POOL_SIZE = 50;
    private static final int QUEUE_CAPACITY = 1000;

    // ExecutorService for handling incoming requests
    private ExecutorService executor;

    // LinkedBlockingQueue for storing pending requests
    private LinkedBlockingQueue<Runnable> queue;

    public GatewayManager() {
        // Initialize the executor service with the desired core and maximum pool sizes
        this.executor = new ThreadPoolExecutor(CORE_POOL_SIZE, MAXIMUM_POOL_SIZE, 0L, TimeUnit.MILLISECONDS, queue);
    }

    public void handleRequest(Runnable runnable) {
        // Add the request to the pending requests queue
        executor.execute(runnable);
    }
}
