// RateLimiter.java

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;

public class RateLimiter {
    private static final Map<String, Integer> REQUEST_COUNT_MAP = new ConcurrentHashMap<>();

    public void checkRequest(String microserviceName) {
        // Check if the current request exceeds the rate limit for the specified microservice
        int count = REQUEST_COUNT_MAP.getOrDefault(microserviceName, 0);
        if (count >= MAX_REQUESTS) {
            // Block the request and throttle the client
            throw new RateLimitingException("Rate limit exceeded");
        } else {
            // Increment the request count for the microservice
            REQUEST_COUNT_MAP.put(microserviceName, count + 1);
        }
    }
}
