// CircuitBreaker.java

import java.util.concurrent.TimeUnit;

public class CircuitBreaker {
    private static final long MAX_WAIT = TimeUnit.SECONDS.toMillis(5);
    private static final int MAX_FAILURES = 3;
    private static final int SUCCESS_THRESHOLD = 2;

    private long lastFailureTime;
    private long failureCount;

    public void recordFailure() {
        // Record a failure and update the circuit breaker's state
        lastFailureTime = System.currentTimeMillis();
        failureCount++;
    }

    public boolean canTry() {
        // Check if the circuit breaker is open or closed based on the failure count and time
        long currentTime = System.currentTimeMillis();
        return (failureCount < SUCCESS_THRESHOLD || currentTime - lastFailureTime > MAX_WAIT);
    }
}
