import json
import logging
from typing import Dict, List, Tuple

import requests
from elasticsearch import Elasticsearch
from redis import Redis

class LogAggregator:
    def __init__(self, es_host: str = "localhost", es_port: int = 9200, rds_host: str = "localhost", rds_port: int = 6379):
        self.es = Elasticsearch(hosts=[f"{es_host}:{es_port}"])
        self.rds = Redis(host=rds_host, port=rds_port)
        self.logger = logging.getLogger("log-aggregator")

    def ingest_log_entry(self, log_entry: Dict[str, str]) -> None:
        try:
            self._validate_log_entry(log_entry)
            parsed_log_entry = self._parse_log_entry(log_entry["message"])
            self.rds.publish("logs", json.dumps(parsed_log_entry))
        except Exception as e:
            self.logger.exception(f"Error ingesting log entry {log_entry}: {e}")

    def _validate_log_entry(self, log_entry: Dict[str, str]) -> None:
        if "message" not in log_entry:
            raise ValueError("Log entry missing 'message' field")

    def _parse_log_entry(self, message: str) -> Dict[str, str]:
        try:
            parsed_message = json.loads(message)
            return {key: value for key, value in parsed_message.items() if value is not None}
        except ValueError as e:
            self.logger.warning(f"Failed to parse log entry: {e}")
            return {}

    def process_log_entry(self, log_entry: Dict[str, str]) -> None:
        try:
            parsed_log_entry = self._parse_log_entry(log_entry["message"])
            self.es.index("logs", json.dumps(parsed_log_entry))
        except Exception as e:
            self.logger.exception(f"Error processing log entry {log_entry}: {e}")

    def fetch_logs(self, query: Dict[str, str]) -> List[Tuple[Dict[str, str], int]]:
        try:
            hits = self.es.search("logs", json.dumps(query))
            return [(hit["_source"], hit["_id"]) for hit in hits]
        except Exception as e:
            self.logger.exception(f"Error fetching logs: {e}")
            return []
```
