    std::lock_guard<std::mutex> lock(mutex_);
    insertAfterLocked(target, new_element);
}

void DynamicStringListManager::append(const std::string& element) {
    // Acquire the lock and call the private method for appending
    std::lock_guard<std::mutex> lock(mutex_);
    appendLocked(element);
}

bool DynamicStringListManager::remove(const std::string& element) {
    // Acquire the lock and call the private method for removal
    std::lock_guard<std::mutex> lock(mutex_);
    return removeLocked(element);
}

bool DynamicStringListManager::contains(const std::string& element) const {
    // Acquire the lock and call the private method for contains
    std::lock_guard<std::mutex> lock(mutex_);
    return containsLocked(element);
}

size_t DynamicStringListManager::size() const {
    // Acquire the lock and return the size of the list
    std::lock_guard<std::mutex> lock(mutex_);
    return list_.size();
}

void DynamicStringListManager::clear() {
    // Acquire the lock and clear the list
    std::lock_guard<std::mutex> lock(mutex_);
    list_.clear();
}

void DynamicStringListManager::setLoggingServiceUrl(const std::string& url) {
    // Acquire the lock and call the private method for setting the logging service URL
    std::lock_guard<std::mutex> lock(mutex_);
    setLoggingServiceUrlLocked(url);
}

void DynamicStringListManager::log(const std::string& message, LogLevel level) {
    // Acquire the lock and call the private method for logging
    std::lock_guard<std::mutex> lock(mutex_);
    logLocked(message, level);
}

void DynamicStringListManager::flushLogs() {
    // Acquire the lock and call the private method for flushing logs
    std::lock_guard<std::mutex> lock(mutex_);
    flushLogsLocked();
}

// Private methods for managing the list of strings
void DynamicStringListManager::insertAfterLocked(const std::string& target, const std::string& new_element) {
    // Find the first occurrence of the target string in the list
    auto it = std::find(list_.begin(), list_.end(), target);

    // If the target is found, insert the new element after it
    if (it != list_.end()) {
        list_.insert(std::next(it), new_element);
    } else {
        // Otherwise, append the new element to the end of the list
        list_.push_back(new_element);
    }
}

bool DynamicStringListManager::appendLocked(const std::string& element) {
    // Append the new element to the end of the list
    list_.push_back(element);
    return true;
}

bool DynamicStringListManager::removeLocked(const std::string& element) {
    // Remove the first occurrence of the element from the list
    auto it = std::find(list_.begin(), list_.end(), element);
    if (it != list_.end()) {
        list_.erase(it);
        return true;
    } else {
        return false;
    }
}

bool DynamicStringListManager::containsLocked(const std::string& element) const {
    // Check if the element is in the list
    auto it = std::find(list_.begin(), list_.end(), element);
    return (it != list_.end());
}

// Private methods for logging operations
void DynamicStringListManager::setLoggingServiceUrlLocked(const std::string& url) {
    // Set the logging service URL
    log_level_ = LogLevel::INFO;
    logging_service_url_ = url;
