void load_data(const std::string& filename, std::vector<int>& data) {
    // Open the JSON file
    std::ifstream input_file(filename);
    if (!input_file.is_open()) {
        throw std::runtime_error("Failed to open input file: " + filename);
    }

    // Read the JSON data into a string
    std::string json_data;
    input_file >> json_data;

    // Parse the JSON data and extract the "data" field
    nlohmann::json j = nlohmann::json::parse(json_data);
    if (j.find("data") == j.end()) {
        throw std::runtime_error("Invalid JSON format: missing \"data\" field");
    }

    // Deserialize the "data" field into a vector of integers
    data = j["data"].get<std::vector<int>>();
}

// Function to validate the integrity of the compressed JSON file
bool validate_json(const std::string& filename) {
    // Open the JSON file
    std::ifstream input_file(filename);
    if (!input_file.is_open()) {
        throw std::runtime_error("Failed to open input file: " + filename);
    }

    // Read the JSON data into a string
    std::string json_data;
    input_file >> json_data;

    // Parse the JSON data and extract the "integrity" field
    nlohmann::json j = nlohmann::json::parse(json_data);
    if (j.find("integrity") == j.end()) {
        throw std::runtime_error("Invalid JSON format: missing \"integrity\" field");
    }

    // Check the "integrity" field for correctness
    return j["integrity"].get<bool>();
}

