    public class MediaProcessor
    {
        private readonly List<ServiceProvider> serviceProviders = new List<ServiceProvider>();
        private readonly Dictionary<string, ServiceConnection> connections = new Dictionary<string, ServiceConnection>();
        private readonly ConcurrentQueue<MediaStream> streamQueue = new ConcurrentQueue<MediaStream>();
        private readonly object syncRoot = new object();

        public MediaProcessor()
        {
            // Initialize service providers and connections
            var serviceProviders = GetServiceProviders();
            foreach (var serviceProvider in serviceProviders)
            {
                AddServiceConnection(serviceProvider);
            }
        }

        private List<ServiceProvider> GetServiceProviders()
        {
            return new List<ServiceProvider>
            {
                // Add service providers here
            };
        }

        public void AddServiceConnection(ServiceProvider serviceProvider)
        {
            var connection = new ServiceConnection(serviceProvider);
            connections.Add(serviceProvider.Name, connection);
        }

        public async Task<MediaStream> GetNextStreamAsync()
        {
            // Use a concurrent queue to retrieve the next stream from the queue in an async-friendly manner
            while (true)
            {
                MediaStream stream;
                if (!streamQueue.TryDequeue(out stream))
                {
                    await Task.Delay(10);
                }
                else
                {
                    return stream;
                }
            }
        }

        public void EnqueueStream(MediaStream stream)
        {
            // Use a lock to ensure thread-safety when enqueuing streams
            lock (syncRoot)
            {
                streamQueue.Enqueue(stream);
            }
        }

        public async Task ProcessNextStreamAsync()
        {
            // Use a concurrent queue and a lock to ensure thread-safety when processing streams
            while (true)
            {
                MediaStream stream;
                if (!streamQueue.TryDequeue(out stream))
                {
                    await Task.Delay(10);
                }
                else
                {
                    // Process the stream using the appropriate service connection based on its ID and type
                    var serviceConnection = GetServiceConnectionForStream(stream);
                    if (serviceConnection != null)
                    {
                        await serviceConnection.ProcessStreamAsync(stream);
                    }
                }
            }
        }

        private ServiceConnection GetServiceConnectionForStream(MediaStream stream)
        {
            // Use a dictionary to map streams to the appropriate service connection based on their ID and type
            var serviceConnection = connections[stream.Id];
            return serviceConnection;
        }
    }
}
