use std::env;
use std::fs;
use std::path::Path;
use std::sync::Mutex;
use std::time::SystemTime;

const MAX_DIRECTORY_NAME_LENGTH: usize = 128;
const DIRECTORY_NAME_PATTERN: &str = r"^[a-zA-Z0-9_-]{3,}$";
const ENV_VARIABLES: [&str; 4] = ["CLOUD_STORAGE_HOST", "CLOUD_STORAGE_PORT", "CLOUD_STORAGE_USERNAME", "CLOUD_STORAGE_PASSWORD"];

fn validate_directory_name(name: &str) -> bool {
    if name.len() > MAX_DIRECTORY_NAME_LENGTH || !name.is_match(DIRECTORY_NAME_PATTERN) {
        return false;
    }

    // Check for reserved system directories
    if ["/", "..", ".", "/.", "/.."].contains(&name) {
        return false;
    }

    true
}

fn create_directory(path: &Path, recursive: bool) -> Result<(), std::io::Error> {
    let mut directory = path.clone();
    if !recursive {
        // Create the immediate parent directory if it doesn't exist
        if directory.parent().is_some() && !directory.parent().unwrap().exists() {
            create_directory(directory.parent().unwrap(), true)?;
        }
    }

    fs::create_dir(&path).or_else(|e| {
        // Handle concurrent creation of the same directory by retrying with a backoff strategy
        if e.kind() == std::io::ErrorKind::AlreadyExists {
            println!("Directory already exists, retrying");
            let mut backoff = 1;
            while backoff < 32 {
                match fs::create_dir(&path) {
                    Ok(_) => break,
                    Err(e) => if e.kind() == std::io::ErrorKind::AlreadyExists {
                        println!("Directory already exists, retrying with backoff {}", backoff);
                        std::thread::sleep(Duration::from_secs(backoff));
                        backoff *= 2;
                    } else {
                        return Err(e);
                    },
                };
            }
            Ok(())
        } else {
            Err(e)
        }
    })?;

    Ok(())
}

fn validate_and_create_directory(path: &Path, recursive: bool) -> Result<(), std::io::Error> {
    if !validate_directory_name(&path.to_str().unwrap()) {
        return Err(std::io::Error::new(
            std::io::ErrorKind::InvalidInput,
            format!("Invalid directory name: {}", path.to_str().unwrap()),
        ));
    }

    let mut lock = env::var("CLOUD_STORAGE_HOST").ok();
    if lock.is_none() {
        return Err(std::io::Error::new(
            std::io::ErrorKind::InvalidInput,
            "Cloud storage host not configured",
        ));
    }

    create_directory(&path, recursive)?;

    Ok(())
}

fn main() {
    let mut lock = Mutex::new((SystemTime::now(), 0));
    let mut path = Path::new("/");
    let mut recursive = false;
    loop {
        match validate_and_create_directory(&path, recursive) {
            Ok(_) => break,
            Err(e) => println!("Error creating directory: {}", e),
        }
        // Backoff strategy for concurrent creation of the same directory
        let (mutex, path, recursive) = lock.lock().unwrap();
        let time = SystemTime::now();
        if time - *mutex > Duration::from_secs(30) {
            *mutex = time;
            path.clear();
            recursive = false;
        }
    }
}
