# Import necessary libraries
from concurrent import futures
import json
import requests
from typing import Any, List

# Define class for batch processing service
class BatchProcessor:
    def __init__(self) -> None:
        # Initialize variables
        self.data_sources = []
        self.data_transformations = []
        self.data_exports = []

    # Function to add data sources to the batch processor
    def add_data_source(self, source: Any) -> None:
        self.data_sources.append(source)

    # Function to add data transformations to the batch processor
    def add_data_transformation(self, transformation: Any) -> None:
        self.data_transformations.append(transformation)

    # Function to add data exports to the batch processor
    def add_data_export(self, export: Any) -> None:
        self.data_exports.append(export)

    # Function to process data in parallel using multi-threading
    def process_parallel(self, data: List[Any]) -> None:
        with futures.ThreadPoolExecutor() as executor:
            for data_source in self.data_sources:
                yield from (executor.submit(self._process_data, data_source, data) for data_source in self.data_sources)

    # Function to process data sequentially using a for loop
    def process_sequential(self, data: List[Any]) -> None:
        for data_source in self.data_sources:
            yield from (self._process_data(data_source, data) for data_source in self.data_sources)

    # Private function to process individual data sources
    def _process_data(self, data_source: Any, data: List[Any]) -> None:
        transformed_data = []
        for item in data:
            transformed_data.append(data_source(item))
        yield from self._export_data(transformed_data)

    # Private function to export processed data
    def _export_data(self, data: List[Any]) -> None:
        for data_export in self.data_exports:
            data_export(data)

# Define class for data source
class DataSource:
    def __init__(self, url: str) -> None:
        self.url = url

    # Function to retrieve data from the data source
    def get_data(self, params: dict) -> Any:
        response = requests.get(self.url, params=params)
        return json.loads(response.text)

# Define class for data transformation
class DataTransformation:
    def __init__(self, function: Any) -> None:
        self.function = function

    # Function to transform the data
    def transform_data(self, data: List[Any]) -> List[Any]:
        transformed_data = []
        for item in data:
            transformed_data.append(self.function(item))
        return transformed_data

# Define class for data export
class DataExport:
    def __init__(self, function: Any) -> None:
        self.function = function

    # Function to export the processed data
    def export_data(self, data: List[Any]) -> None:
        self.function(data)
