void traffic_event_array_add(struct TrafficEventArray* arr, struct TrafficEvent event) {
    // Acquire the mutex and semaphore
    pthread_mutex_lock(&arr->mutex);
    semaphore_wait(&arr->sem);

    // Check if we need to allocate more memory for the array
    if (arr->count == arr->capacity) {
        arr->capacity *= 2;
        struct TrafficEvent* new_events = realloc(arr->events, sizeof(struct TrafficEvent) * arr->capacity);
