    // Release the mutex and semaphore
    pthread_mutex_unlock(&arr->mutex);
    semaphore_post(&arr->sem);

    return event;
}

// Function to prune old events based on a configurable retention policy
void traffic_event_array_prune(struct TrafficEventArray* arr, size_t threshold) {
    // Acquire the mutex and semaphore
    pthread_mutex_lock(&arr->mutex);
    semaphore_wait(&arr->sem);

    struct TrafficEvent* events = arr->events;
    for (size_t i = 0; i < arr->count; ++i) {
        if (events[i].timestamp < threshold) {
            events[i] = events[arr->count - 1];
            --arr->count;
        }
    }

    // Release the mutex and semaphore
    pthread_mutex_unlock(&arr->mutex);
    semaphore_post(&arr->sem);
}

// Function to support event deduplication
bool traffic_event_array_dedup(struct TrafficEventArray* arr, struct TrafficEvent event) {
    // Acquire the mutex and semaphore
