// Array of events for each thread
static struct TrafficEvent *events[MAX_THREADS];

// Size of the event array for each thread
static size_t event_size = 0;

// Mutex for protecting concurrent access to the event array
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Condition variable for notifying threads of new events
static pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

// Flag indicating whether the library is shutting down
static volatile int shutdown = 0;

// Configuration parameters for the retention policy
struct RetentionPolicyConfig {
    time_t event_retention_time; // Time period for retaining events (in seconds)
    size_t max_event_size;       // Maximum number of events to store
};

// Current configuration of the retention policy
static struct RetentionPolicyConfig config;

// Initializes the traffic monitoring library with the given configuration parameters
void traffic_monitoring_init(struct TrafficEvent *events, size_t event_size, struct RetentionPolicyConfig config) {
    this->events = events;
    this->event_size = event_size;
    this->config = config;
}

// Adds a new traffic event to the library
void traffic_monitoring_add_event(struct TrafficEvent *event) {
    pthread_mutex_lock(&mutex);
    if (shutdown) {
        // Library is shutting down, ignore the new event
        return;
    }

    // Check if the event array needs to be resized
    if (event_size >= config.max_event_size) {
        // Resize the event array by 25%
        size_t new_size = event_size * 1.25;
        struct TrafficEvent **new_events = realloc(events, new_size * sizeof(struct TrafficEvent));
        if (new_events == NULL) {
            // Reallocation failed, exit the function
            pthread_mutex_unlock(&mutex);
            return;
        }

        events = new_events;
        event_size = new_size;
    }

    // Add the new event to the array
    events[event_size++] = event;

    // Notify any waiting threads of the new event
    pthread_cond_broadcast(&cond);
    pthread_mutex_unlock(&mutex);
}

// Retrieves a traffic event from the library
struct TrafficEvent *traffic_monitoring_get_event(size_t index) {
    if (index >= event_size) {
        return NULL;
    }

    pthread_mutex_lock(&mutex);
    struct TrafficEvent *event = events[index];
    pthread_mutex_unlock(&mutex);

    return event;
}

// Prunes old events based on the retention policy
void traffic_monitoring_prune(struct RetentionPolicyConfig config) {
    // Calculate the time threshold for pruning events
    time_t prune_threshold = time(NULL) - config.event_retention_time;

    pthread_mutex_lock(&mutex);
    size_t i = 0;
    while (i < event_size) {
        struct TrafficEvent *event = events[i];
        if (event->timestamp <= prune_threshold) {
            // Free the memory for the old event
            free(event);

            // Shift all subsequent events down to fill the gap
            memmove(&events[i], &events[i + 1], sizeof(struct TrafficEvent) * (event_size - i));
            event_size--;
        } else {
            i++;
        }
    }
    pthread_mutex_unlock(&mutex);
}

// Returns the number of events in the library
size_t traffic_monitoring_get_event_count(void) {
    return event_size;
}

// Shuts down the traffic monitoring library
void traffic_monitoring_shutdown(void) {
