package PaymentProcessingService;

import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class PaymentProcessingService {
    private static final int MAX_BATCH_SIZE = 1000; // maximum number of transactions in a batch
    private static final int MAX_CONCURRENT_REQUESTS = 10000; // maximum number of concurrent requests to the service
    private static final int MIN_LATENCY = 50; // minimum latency in milliseconds for each transaction
    private static final int MAX_LATENCY = 2000; // maximum latency in milliseconds for each transaction
    private static final int LATENCY_BUFFER = 100; // buffer size for latency in milliseconds
    private static final int THROTTLE_THRESHOLD = 100; // throttle threshold for rate limiting
    private static final long DEFAULT_BACKOFF_DELAY = 500; // default backoff delay in milliseconds
    private static final double EXPONENTIAL_BASE = 2.0; // base for exponential backoff
    private static final int MAX_RETRIES = 3; // maximum number of retries for failed transactions

    private Map<String, PaymentGateway> gateways; // map of payment gateways by their API keys
    private Lock gatewayLock; // lock for synchronizing access to the gateway map
    private AtomicInteger requestsInFlight; // atomic integer for tracking number of concurrent requests in flight
    private ConcurrentHashMap<String, Long> requestTimestamps; // concurrent hash map for storing timestamps of recent requests
    private int lastBatchSize; // last batch size used for rate limiting

    public PaymentProcessingService() {
        gateways = new HashMap<>();
        gatewayLock = new ReentrantLock();
        requestsInFlight = new AtomicInteger(0);
        requestTimestamps = new ConcurrentHashMap<>();
        lastBatchSize = 0;
    }

    public void addGateway(PaymentGateway gateway) {
        if (gateways.containsKey(gateway.getApiKey())) {
            throw new IllegalArgumentException("Duplicate API key for payment gateway");
        }
        gateways.put(gateway.getApiKey(), gateway);
    }

    public void removeGateway(String apiKey) {
        if (!gateways.containsKey(apiKey)) {
            throw new IllegalArgumentException("No such API key for payment gateway");
        }
        gateways.remove(apiKey);
    }

    public void processPayment(Transaction transaction) throws PaymentProcessingException {
        // validate the transaction
        if (transaction == null || transaction.getAmount() <= 0) {
            throw new IllegalArgumentException("Invalid transaction");
        }

        // acquire a lock on the gateway map
        gatewayLock.lock();

        try {
            // get the payment gateway for the given API key
            PaymentGateway gateway = gateways.get(transaction.getApiKey());
            if (gateway == null) {
                throw new PaymentProcessingException("No such payment gateway with API key: " + transaction.getApiKey());
            }

            // check the rate limit for the gateway
            long now = System.currentTimeMillis();
            Long lastRequestTimestamp = requestTimestamps.putIfAbsent(transaction.getApiKey(), now);
            if (lastRequestTimestamp != null) {
                int delta = (int)(now - lastRequestTimestamp);
                if (delta < MIN_LATENCY || delta > MAX_LATENCY + LATENCY_BUFFER) {
                    throw new PaymentProcessingException("Rate limit exceeded for payment gateway: " + transaction.getApiKey());
                }
            }

            // throttle the requests if necessary
            if (requestsInFlight.incrementAndGet() > THROTTLE_THRESHOLD) {
                long backoffDelay = calculateBackoffDelay();
                try {
                    Thread.sleep(backoffDelay);
                } catch (InterruptedException e) {
                    throw new PaymentProcessingException("Interrupted while waiting for request throttle", e);
                }
            }

            // process the transaction with exponential backoff and retry
            int retries = 0;
            while (retries <= MAX_RETRIES) {
                try {
                    gateway.processPayment(transaction);
                    return;
                } catch (PaymentProcessingException e) {
                    retries++;
                    long backoffDelay = calculateBackoffDelay(retries);
                    try {
                        Thread.sleep(backoffDelay);
                    } catch (InterruptedException ex) {
                        throw new PaymentProcessingException("Interrupted while waiting for retry", e);
                    }
                }
            }

            // handle failed transactions
            requestsInFlight.decrementAndGet();
            requestTimestamps.remove(transaction.getApiKey());
            throw new PaymentProcessingException("Failed to process payment after " + MAX_RETRIES + " retries", e);
        } finally {
            gatewayLock.unlock();
        }
    }

    public void handlePaymentResult(String apiKey, Transaction transaction) {
        // acquire a lock on the gateway map
        gatewayLock.lock();

        try {
            // get the payment gateway for the given API key
            PaymentGateway gateway = gateways.get(apiKey);
            if (gateway == null) {
                return;
            }

            // handle the payment result
            gateway.handlePaymentResult(transaction);
        } finally {
            gatewayLock.unlock();
        }
    }

    public void handlePaymentError(String apiKey, Transaction transaction) {
        // acquire a lock on the gateway map
        gatewayLock.lock();

        try {
            // get the payment gateway for the given API key
            PaymentGateway gateway = gateways.get(apiKey);
            if (gateway == null) {
                return;
            }

            // handle the payment error
            gateway.handlePaymentError(transaction);
        } finally {
            gatewayLock.unlock();
        }
    }

    private long calculateBackoffDelay() {
        // exponential backoff with jitter
        double delay = DEFAULT_BACKOFF_DELAY * Math.random();
        return (long)(delay + 100);
    }

    private long calculateBackoffDelay(int retries) {
        // linear increase in the backoff delay
        return (long)(DEFAULT_BACKOFF_DELAY * Math.pow(2, retries - 1));
    }
}
```

This code defines a `PaymentProcessor` class that is responsible for processing payments for multiple payment gateways. It uses an `HashMap<String, PaymentGateway>` to store the available payment gateways and their corresponding API keys. The `processPayment()` method checks the rate limit for each payment gateway and throttles the requests if necessary using a simple backoff algorithm with jitter. If a transaction fails, it uses an exponential backoff algorithm with jitter to retry the failed request before returning an error to the client.

The `handlePaymentResult()` and `handlePaymentError()` methods are used to handle the result or error of a payment request from a payment gateway. These methods acquire a lock on the gateway map using `gatewayLock.lock()` before accessing the payment gateway for the given API key and handling the payment result or error.

The `calculateBackoffDelay()` method calculates an exponential backoff delay with jitter, while the `calculateBackoffDelay(int retries)` method calculates a linear increase in the backoff delay based on the number of retries. The `PaymentProcessor` class also defines constants for the default backoff delay and rate limit.

The `PaymentProcessor` class is implemented using an `HashMap<String, PaymentGateway>` to store the available payment gateways and their corresponding API keys. It uses a simple backoff algorithm with jitter to throttle the requests if necessary, and it also implements exponential backoff with jitter to retry failed requests before returning an error to the client. The `PaymentProcessor` class also defines constants for the default backoff delay and rate limit.

The `PaymentProcessor` class is a good example of how to design a high-level abstraction that can handle different variations of a problem, while still maintaining a simple and easy-to-use interface. It uses an `HashMap<String, PaymentGateway>` to store the available payment gateways and their corresponding API keys, which makes it easy to add or remove payment gateways dynamically. The `processPayment()` method also uses an exponential backoff algorithm with jitter to retry failed requests before returning an error to the client, which provides a good balance between performance and reliability.']

