// Directory Management Service
use std::{fs::File, path::Path};

struct Directory {
    name: String,
    owner: String,
    created_at: SystemTime,
    usage: u64,
}

impl Directory {
    fn new(name: &str, owner: &str) -> Self {
        let now = SystemTime::now();
        let usage = 0;
        Self { name, owner, created_at: now, usage }
    }

    fn create(&mut self) -> Result<(), Error> {
        let path = Path::new(&self.name);
        if path.exists() {
            return Err(Error::AlreadyExists);
        }

        File::create(path)?;

        Ok(())
    }
}

// Video Processing Service
use std::{fs::File, io::Read, path::Path};

struct VideoProcessor {
    file: File,
    format: Format,
}

impl VideoProcessor {
    fn new(file: &str, format: Format) -> Self {
        let mut f = File::open(file)?;
        let reader = BufReader::new(f);
        let parser = match format {
            Format::MP4 => MP4Parser::new(reader),
            _ => return Err(Error::UnsupportedFormat),
        };
        Self { file, format, parser }
    }

    fn process(&mut self) -> Result<(), Error> {
        let mut stream = self.parser.read_header()?;
        while !stream.is_empty() {
            // Process frame
            stream.advance(self.parser.process_frame(stream)?);
        }

        Ok(())
    }
}

// Utility Functions
fn calculate_usage(path: &Path) -> u64 {
    let mut usage = 0;
    for entry in path.read_dir()? {
        let file = entry?.file_name();
        if file == "." || file == ".." {
            continue;
        }
        let metadata = entry?.metadata()?;
        if metadata.is_dir() {
            usage += calculate_usage(entry?.path())?;
        } else {
            usage += metadata.len();
        }
    }
    Ok(usage)
}
