      struct Resource* resource1 = catalog->entries[i]->resource;
      i++;
      while (i < catalog->num_entries && catalog->entries[i] != NULL) {
        if (strcmp(catalog->entries[i]->resource->uuid, uuid2) == 0) {
          struct Resource* resource2 = catalog->entries[i]->resource;
          i++;

          // Add the new relationship to the resource
          int num_relationships = resource1->num_relationships + 1;
          if (num_relationships > resource1->max_relationships) {
            printf("Error: failed to allocate memory for relationship\n");
            return;
          }
          struct Relationship* new_relationship = malloc(sizeof(struct Relationship));
          if (new_relationship == NULL) {
            printf("Error: failed to allocate memory for relationship\n");
            return;
          }
          resource1->relationships[resource1->num_relationships] = new_relationship;
          resource1->num_relationships++;
          resource1->relationships[resource1->num_relationships - 1]->type = type;
          resource1->relationships[resource1->num_relationships - 1]->resource2 = resource2;
        } else {
          i++;
        }
      }
    } else {
      i++;
    }
  }
}

// Function to remove a relationship between two resources in the catalog
void catalog_remove_relationship(struct Catalog* catalog, char* uuid1, char* uuid2) {
