      i++;
      while (i < catalog->num_entries && catalog->entries[i] != NULL) {
        if (strcmp(catalog->entries[i]->resource->uuid, uuid2) == 0) {
          struct Resource* resource2 = catalog->entries[i]->resource;
          i++;

          // Remove the relationship from the resource
          int num_relationships = resource1->num_relationships - 1;
          for (int j = 0; j < num_relationships; j++) {
            if (resource1->relationships[j]->type == type && resource1->relationships[j]->resource2 == resource2) {
              free(resource1->relationships[j]);
              for (int k = j; k < num_relationships - 1; k++) {
                resource1->relationships[k] = resource1->relationships[k + 1];
