}

// Function to clear the catalog of all entries and relationships
void catalog_clear(struct Catalog* catalog) {
  assert(catalog != NULL);

  // Free all resources and relationships in the catalog
  for (size_t i = 0; i < catalog->num_entries; i++) {
    if (catalog->entries[i] == NULL) {
