    struct Resource* resource = catalog->entries[i]->resource;
    free(resource->uuid);
    for (int j = 0; j < resource->num_relationships; j++) {
      free(resource->relationships[j]);
    }
    free(resource);
  }

  // Clear the catalog entries and relationships
  catalog->num_entries = 0;
}

// Function to add a resource to the catalog
void catalog_add_resource(struct Catalog* catalog, const char* uuid, void* data) {
  assert(catalog != NULL);
  assert(uuid != NULL);
  assert(data != NULL);

  // Create a new resource and append it to the catalog entries
  struct Resource* resource = malloc(sizeof(struct Resource));
  if (resource == NULL) {
    printf("Error: failed to allocate memory for resource\n");
    return;
  }
  size_t uuid_len = strlen(uuid);
  resource->uuid = malloc(uuid_len + 1);
  if (resource->uuid == NULL) {
    printf("Error: failed to allocate memory for UUID\n");
    free(resource);
    return;
  }
  strncpy(resource->uuid, uuid, uuid_len);
  resource->uuid[uuid_len] = '\0';
  resource->data = data;
  resource->max_relationships = INITIAL_RELATIONSHIPS_CAPACITY;
  resource->num_relationships = 0;
  resource->relationships = malloc(sizeof(struct Relationship*) * INITIAL_RELATIONSHIPS_CAPACITY);
  if (resource->relationships == NULL) {
    printf("Error: failed to allocate memory for relationships\n");
    free(resource->uuid);
    free(resource);
    return;
  }

  // Add the new resource to the catalog entries
  size_t num_entries = catalog->num_entries + 1;
  struct ResourceEntry* entries = realloc(catalog->entries, sizeof(struct ResourceEntry) * num_entries);
  if (entries == NULL) {
    printf("Error: failed to allocate memory for resource entries\n");
    free(resource->relationships);
    free(resource->uuid);
    free(resource);
    return;
  }
  catalog->entries = entries;
  catalog->num_entries = num_entries;
  catalog->entries[catalog->num_entries - 1].resource = resource;
}

// Function to remove a resource from the catalog
void catalog_remove_resource(struct Catalog* catalog, const char* uuid) {
  assert(catalog != NULL);
  assert(uuid != NULL);

  // Find the resource in the catalog entries
  size_t num_entries = catalog->num_entries;
  for (size_t i = 0; i < num_entries; i++) {
    if (strcmp(catalog->entries[i].resource->uuid, uuid) == 0) {
      // Remove the resource from the catalog entries and free its memory
      struct ResourceEntry* entries = realloc(catalog->entries, sizeof(struct ResourceEntry) * (num_entries - 1));
      if (entries != NULL) {
        catalog->entries = entries;
      } else {
        printf("Error: failed to allocate memory for resource entries\n");
      }
      struct Resource* resource = catalog->entries[i].resource;
      free(resource->uuid);
      for (int j = 0; j < resource->num_relationships; j++) {
        free(resource->relationships[j]);
      }
      free(resource->relationships);
      free(resource);
      catalog->num_entries--;
    }
  }
}

// Function to add a relationship between two resources in the catalog
void catalog_add_relationship(struct Catalog* catalog, const char* uuid1, const char* uuid2, int type) {
