  for (size_t i = 0; i < num_entries; i++) {
    if (strcmp(catalog->entries[i].resource->uuid, uuid1) == 0) {
      resource1 = catalog->entries[i].resource;
    } else if (strcmp(catalog->entries[i].resource->uuid, uuid2) == 0) {
