  if (resource1 != NULL && resource2 != NULL) {
    int num_relationships = resource1->num_relationships + 1;
    struct Relationship* relationships = realloc(resource1->relationships, sizeof(struct Relationship*) * num_relationships);
    if (relationships == NULL) {
      printf("Error: failed to allocate memory for relationships\n");
      return;
    }
    resource1->relationships = relationships;
    resource1->num_relationships = num_relationships;
    resource1->relationships[resource1->num_relationships - 1].type = type;
    resource1->relationships[resource1->num_relationships - 1].resource = resource2;
  }
}

// Function to remove a relationship between two resources in the catalog
void catalog_remove_relationship(struct Catalog* catalog, const char* uuid1, const char* uuid2) {
  assert(catalog != NULL);
  assert(uuid1 != NULL);
  assert(uuid2 != NULL);

  // Find the resources in the catalog entries
  size_t num_entries = catalog->num_entries;
  struct Resource* resource1 = NULL;
  struct Resource* resource2 = NULL;
  for (size_t i = 0; i < num_entries; i++) {
    if (strcmp(catalog->entries[i].resource->uuid, uuid1) == 0) {
