// Initialize an encryption context using a X.509 certificate chain
struct EncryptionContext* init_encryption_context(char* cert_path, char* key_path, int algo) {
    struct EncryptionContext* ctx = (struct EncryptionContext*)malloc(sizeof(struct EncryptionContext));
    if (!ctx) {
        return NULL;
    }

    // Load the X.509 certificate chain from disk
    BIO* cert_bio = BIO_new_file(cert_path, "r");
    if (!cert_bio) {
        printf("Error loading certificate chain\n");
        free(ctx);
        return NULL;
    }
    X509_STORE* store = SSL_CTX_get_cert_store(SSL_CTX_new());
    if (!store) {
        BIO_free(cert_bio);
        free(ctx);
        return NULL;
    }
    STACK_OF(X509)* certs = sk_X509_new_null();
    while (1) {
        X509* x509 = PEM_read_bio_X509(cert_bio, NULL, NULL, NULL);
        if (!x509) break;
        sk_X509_push(certs, x509);
    }
    BIO_free(cert_bio);
    X509* issuer = sk_X509_value(certs, 0);
    if (!issuer) {
        printf("Error parsing certificate chain\n");
        sk_X509_pop_free(certs, X509_free);
        free(ctx);
        return NULL;
    }

    // Load the private key from disk
    EVP_PKEY* pkey = EVP_PKEY_new();
    if (!pkey) {
        printf("Error loading private key\n");
        sk_X509_pop_free(certs, X509_free);
        free(ctx);
        return NULL;
    }
    BIO* key_bio = BIO_new_file(key_path, "r");
    if (!key_bio) {
        printf("Error loading private key\n");
        sk_X509_pop_free(certs, X509_free);
        EVP_PKEY_free(pkey);
        free(ctx);
        return NULL;
    }
    if (!PEM_read_bio_PrivateKey(key_bio, &pkey, NULL, NULL)) {
        printf("Error parsing private key\n");
        sk_X509_pop_free(certs, X509_free);
        BIO_free(key_bio);
        EVP_PKEY_free(pkey);
        free(ctx);
        return NULL;
    }
    BIO_free(key_bio);

    // Set up the SSL context
    ctx->ssl_ctx = SSL_CTX_new();
    if (!ctx->ssl_ctx) {
        printf("Error creating SSL context\n");
        sk_X509_pop_free(certs, X509_free);
        EVP_PKEY_free(pkey);
        free(ctx);
        return NULL;
    }
    if (!SSL_CTX_use_certificate(ctx->ssl_ctx, certs)) {
        printf("Error setting up certificate chain\n");
        sk_X509_pop_free(certs, X509_free);
        SSL_CTX_free(ctx->ssl_ctx);
        EVP_PKEY_free(pkey);
        free(ctx);
        return NULL;
    }
    if (!SSL_CTX_use_PrivateKey(ctx->ssl_ctx, pkey)) {
        printf("Error setting up private key\n");
        sk_X509_pop_free(certs, X509_free);
        SSL_CTX_free(ctx->ssl_ctx);
        EVP_PKEY_free(pkey);
        free(ctx);
        return NULL;
    }
    if (!SSL_CTX_check_private_key(ctx->ssl_ctx)) {
        printf("Error checking private key\n");
        sk_X509_pop_free(certs, X509_free);
        SSL_CTX_free(ctx->ssl_ctx);
        EVP_PKEY_free(pkey);
        free(ctx);
        return NULL;
    }
    sk_X509_pop_free(certs, X509_free);
    ctx->algo = algo;

    // Set up the encryption key based on the selected algorithm
    switch (algo) {
        case RSA:
            ctx->key_size = SSL_CTX_get_security_bits(ctx->ssl_ctx);
            break;
        case ECDSA:
            ctx->key_size = SSL_CTX_get_security_bits(ctx->ssl_ctx) * 2;
            break;
        default:
            printf("Error selecting encryption algorithm\n");
            sk_X509_pop_free(certs, X509_free);
            SSL_CTX_free(ctx->ssl_ctx);
            EVP_PKEY_free(pkey);
            free(ctx);
            return NULL;
    }

    // Return the encryption context
    return ctx;
}

// Free an encryption context
void free_encryption_context(struct EncryptionContext* ctx) {
    if (ctx->ssl_ctx) {
        SSL_CTX_free(ctx->ssl_ctx);
    }
    if (ctx->pkey) {
        EVP_PKEY_free(ctx->pkey);
    }
    free(ctx);
}

// Encrypt data using the encryption context
int encrypt(struct EncryptionContext* ctx, char* plaintext, int plaintext_len, char** ciphertext) {
    // Create a new SSL object for the encryption session
    SSL* ssl = SSL_new(ctx->ssl_ctx);
    if (!ssl) {
        printf("Error creating SSL object\n");
        return -1;
    }

    // Set up the encryption algorithm based on the selected algorithm
    switch (ctx->algo) {
        case RSA:
            SSL_set_security_bits(ssl, ctx->key_size);
            break;
        case ECDSA:
            SSL_set_security_bits(ssl, ctx->key_size / 2);
            break;
    }

    // Encrypt the plaintext
    int ciphertext_len = SSL_encrypt(ssl, plaintext, plaintext_len);
    if (ciphertext_len < 0) {
        printf("Error encrypting data\n");
        SSL_free(ssl);
        return -1;
    }

    // Return the encrypted ciphertext
    *ciphertext = malloc(ciphertext_len + 1);
    memcpy(*ciphertext, plaintext, ciphertext_len);
    (*ciphertext)[ciphertext_len] = '\0';
    SSL_free(ssl);
    return ciphertext_len;
}

// Decrypt data using the encryption context
int decrypt(struct EncryptionContext* ctx, char* ciphertext, int ciphertext_len, char** plaintext) {
    // Create a new SSL object for the encryption session
    SSL* ssl = SSL_new(ctx->ssl_ctx);
    if (!ssl) {
        printf("Error creating SSL object\n");
        return -1;
    }

    // Set up the decryption algorithm based on the selected algorithm
    switch (ctx->algo) {
        case RSA:
            SSL_set_security_bits(ssl, ctx->key_size);
            break;
        case ECDSA:
            SSL_set_security_bits(ssl, ctx->key_size / 2);
            break;
    }

    // Decrypt the ciphertext
    int plaintext_len = SSL_decrypt(ssl, ciphertext, ciphertext_len);
    if (plaintext_len < 0) {
        printf("Error decrypting data\n");
        SSL_free(ssl);
        return -1;
    }

    // Return the decrypted plaintext
    *plaintext = malloc(plaintext_len + 1);
    memcpy(*plaintext, ciphertext, plaintext_len);
    (*plaintext)[plaintext_len] = '\0';
    SSL_free(ssl);
    return plaintext_len;
}
