public class MoSTStateLoader {
    private static final int MAX_REQ_PER_MIN = 500;
    private static final int MIN_CONCURRENT_CONN = 10000;
    private static final int INITIAL_CACHE_SIZE = 1 << 30; // 1 GB
    private static final int MAX_CACHE_SIZE = 5 << 30; // 5 GB
    private static final int CACHE_GROWTH_FACTOR = 2;
    private static final int DEFAULT_RETRY_COUNT = 5;
    private static final int DEFAULT_RETRY_DELAY = 1000; // 1 second
    private static final int MAX_RETRY_DELAY = 30000; // 30 seconds
    private static final String REGEX_API_VERSION = "^v(\\d+)$";
    private static final Pattern PATTERN_API_VERSION = Pattern.compile(REGEX_API_VERSION);
    private static final int CACHE_HITS = 0;
    private static final int CACHE_MISSES = 1;
    private static final int CACHE_SIZE = 2;
    private static final int CACHE_EVICTIONS = 3;
    private static final int CACHE_EXPIRATIONS = 4;
    private static final int CACHE_HIT_RATIO = 5;
    private static final int CONN_ESTABLISHED = 0;
    private static final int CONN_CLOSED = 1;
    private static final int REQ_SENT = 2;
    private static final int RESP_RECEIVED = 3;
    private static final int RESP_SIZE = 4;
    private static final int RESP_ERROR = 5;
    private static final String LOG_FORMAT = "%d %s %s %s %s %s %s %s";
    private static final ExecutorService executor = Executors.newFixedThreadPool(MIN_CONCURRENT_CONN);
    private static final AtomicInteger cacheStats[];
    private static final Map<String, Cache> apiCache;
    private static final Logger logger;

    static {
        cacheStats = new AtomicInteger[] {
            new AtomicInteger(0), // hits
            new AtomicInteger(0), // misses
            new AtomicInteger(INITIAL_CACHE_SIZE), // size
            new AtomicInteger(0), // evictions
            new AtomicInteger(0), // expirations
            new AtomicInteger(0)  // hit ratio
        };
        apiCache = new HashMap<>();
        logger = Logger.getLogger("MoSTStateLoader");
    }

    public static void main(String[] args) {
        // Add code to start the service
        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
            shutdown();
        }));

        logger.info("MoSTStateLoader started");
    }

    public static void shutdown() {
        executor.shutdownNow();
        logger.info("MoSTStateLoader stopped");
    }

    private static void loadState(String api, String version) throws Exception {
        // Add code to retrieve state from the specified API and version
        URL url = new URL(api + "/v" + version + "/state");
        HttpURLConnection conn = (HttpURLConnection)url.openConnection();
        try {
            conn.setRequestMethod("GET");
            int statusCode = conn.getResponseCode();
            if (statusCode == 200) {
                logger.debug("Loaded state from " + api + "/v" + version);
                ObjectInputStream ois = new ObjectInputStream(conn.getInputStream());
                try {
                    State state = (State)ois.readObject();
                    cacheState(api, version, state);
                } finally {
                    ois.close();
                }
            } else {
                logger.warn("Failed to load state from " + api + "/v" + version);
            }
        } finally {
            conn.disconnect();
        }
    }

    private static void cacheState(String api, String version, State state) {
        // Add code to cache the specified state object in memory and on disk
        Cache cache = getCache(api, version);
        if (cache != null) {
            synchronized (cache.stateLock) {
                cache.state = state;
                cache.size = state.getSize();
                cache.expirationTime = System.currentTimeMillis() + CACHE_EXPIRATION_TIME;
            }
        }
    }

    private static Cache getCache(String api, String version) {
        // Add code to retrieve the specified cache from memory or disk if it exists
        Cache cache = null;
        synchronized (apiCache) {
            cache = apiCache.get(api + "/v" + version);
            if (cache == null) {
                File cacheFile = new File("state-cache/" + api + "-v" + version + ".dat");
                if (cacheFile.exists()) {
                    try {
                        ObjectInputStream ois = new ObjectInputStream(new FileInputStream(cacheFile));
                        try {
                            State state = (State)ois.readObject();
                            cache = new Cache(api, version, state);
                            cacheStats[CACHE_HITS].incrementAndGet();
                        } finally {
                            ois.close();
                        }
                    } catch (Exception e) {
                        logger.warn("Failed to load cached state from " + api + "/v" + version);
                    }
                }
            } else {
                cacheStats[CACHE_HITS].incrementAndGet();
            }
        }
        return cache;
    }

    private static void evictCache(String api, String version) {
        // Add code to evict the specified cache from memory and disk
        Cache cache = null;
        synchronized (apiCache) {
            cache = apiCache.get(api + "/v" + version);
            if (cache != null) {
                cacheStats[CACHE_EVICTIONS].incrementAndGet();
                File cacheFile = new File("state-cache/" + api + "-v" + version + ".dat");
                try {
                    ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream(cacheFile));
                    try {
                        oos.writeObject(cache.state);
                    } finally {
                        oos.close();
                    }
                } catch (Exception e) {
                    logger.warn("Failed to save cached state to " + api + "/v" + version);
                }
                apiCache.remove(api + "/v" + version);
            }
        }
    }

    private static void expireCache(String api, String version) {
        // Add code to expire the specified cache from memory and disk
        Cache cache = null;
        synchronized (apiCache) {
            cache = apiCache.get(api + "/v" + version);
            if (cache != null && System.currentTimeMillis() > cache.expirationTime) {
                cacheStats[CACHE_EXPIRATIONS].incrementAndGet();
                evictCache(api, version);
            }
        }
    }

    private static class Cache {
        String api;
        String version;
        Object stateLock = new Object();
        State state;
        long size;
        long expirationTime;

        public Cache(String api, String version, State state) {
            this.api = api;
            this.version = version;
            this.state = state;
            cacheStats[CACHE_SIZE].addAndGet(state.getSize());
        }
    }
}
