// Define the `NetworkConnectionEvent` struct to store event metadata
struct NetworkConnectionEvent {
    uint64_t timestamp;
    uint32_t connection_id;
    uint8_t status_flags;
};

// Define a `ConnectionEventQueue` structure to manage events
struct ConnectionEventQueue {
    struct NetworkConnectionEvent* events;
    size_t capacity;
    size_t num_events;
    sem_t semaphore;
};

// Function to create a new queue for storing events
int connection_event_queue_create(struct ConnectionEventQueue** queue) {
    *queue = malloc(sizeof(struct ConnectionEventQueue));
    if (*queue == NULL) {
        return -1;
    }

    // Initialize the queue's capacity and number of events to 0
    (*queue)->capacity = 0;
    (*queue)->num_events = 0;

    // Create a semaphore for signaling when new events are available
    if (sem_init(&(*queue)->semaphore, 0, 0) == -1) {
        return -1;
    }

    return 0;
}

// Function to destroy an existing queue for storing events
int connection_event_queue_destroy(struct ConnectionEventQueue* queue) {
    if (queue == NULL) {
        return -1;
    }

    // Destroy the semaphore
    sem_destroy(&queue->semaphore);

    // Free any allocated memory for events in the queue
    for (size_t i = 0; i < queue->num_events; i++) {
        struct NetworkConnectionEvent* event = &queue->events[i];
        free(event);
    }

    // Free the queue's memory
    free(queue);

    return 0;
}

// Function to add a new event to the queue
int connection_event_queue_push(struct ConnectionEventQueue* queue, struct NetworkConnectionEvent* event) {
    if (queue == NULL || event == NULL) {
        return -1;
    }

    // If the queue is full, double its capacity and reallocate memory for events
    if (queue->num_events >= queue->capacity) {
        size_t new_capacity = 2 * queue->capacity + 1;
        struct NetworkConnectionEvent* new_events = realloc(queue->events, new_capacity * sizeof(struct NetworkConnectionEvent));
        if (new_events == NULL) {
            return -1;
        }

        // Copy the existing events to the new memory location
        memcpy(new_events, queue->events, queue->num_events * sizeof(struct NetworkConnectionEvent));

        // Update the queue's capacity and events pointer
        queue->capacity = new_capacity;
        queue->events = new_events;
    }

    // Add the new event to the end of the queue
    struct NetworkConnectionEvent* current_event = &queue->events[queue->num_events];
    memcpy(current_event, event, sizeof(struct NetworkConnectionEvent));
    queue->num_events++;

    // Signal the semaphore to indicate that new events are available
    if (sem_post(&queue->semaphore) == -1) {
        return -1;
    }

    return 0;
}

// Function to remove an event from the queue
int connection_event_queue_pop(struct ConnectionEventQueue* queue, struct NetworkConnectionEvent** event) {
    if (queue == NULL || event == NULL) {
        return -1;
    }

    // If there are no events in the queue, return an error
    if (queue->num_events <= 0) {
        return -1;
    }

    // Remove the first event from the queue and decrement the number of events
    struct NetworkConnectionEvent* current_event = &queue->events[0];
    memcpy(*event, current_event, sizeof(struct NetworkConnectionEvent));
    queue->num_events--;

    // Shift all subsequent events to fill in the gap
    for (size_t i = 0; i < queue->num_events; i++) {
        struct NetworkConnectionEvent* event = &queue->events[i];
        memcpy(&queue->events[i], &queue->events[i + 1], sizeof(struct NetworkConnectionEvent));
    }

    // Signal the semaphore to indicate that new events are available
    if (sem_post(&queue->semaphore) == -1) {
        return -1;
    }

    return 0;
}

// Function to retrieve an event from the queue without removing it
int connection_event_queue_peek(struct ConnectionEventQueue* queue, struct NetworkConnectionEvent** event) {
    if (queue == NULL || event == NULL) {
        return -1;
    }

    // If there are no events in the queue, return an error
    if (queue->num_events <= 0) {
        return -1;
    }

    // Return a pointer to the first event in the queue without removing it
    *event = &queue->events[0];

    return 0;
}
