  hints.ai_family = AF_UNSPEC;
  hints.ai_socktype = SOCK_STREAM;
  if ((rv = getaddrinfo(host, port, &hints, &servinfo)) != 0) {
    fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(rv));
    return -1;
  }

  // Iterate over the available servers and connect to the first one that works
  for (p = servinfo; p != NULL; p = p->ai_next) {
    if ((sockfd = socket(p->ai_family, p->ai_socktype, p->ai_protocol)) == -1) {
      perror("socket");
      continue;
    }

    if (connect(sockfd, p->ai_addr, p->ai_addrlen) == -1) {
      close(sockfd);
      perror("connect");
      continue;
    }

    break;
  }

  freeaddrinfo(servinfo);

  if (p == NULL) {
    fprintf(stderr, "failed to connect\n");
    return -1;
  }

  return sockfd;
}

// Function to perform SSL handshake and create an SSL context
struct ssl_ctx_st *ssl_create_context() {
  int sockfd = 0;
  struct ssl_ctx_st *ctx = NULL;

  // Create a new SSL context
  ctx = SSL_CTX_new(SSLv23_method());
  if (!ctx) {
    fprintf(stderr, "failed to create SSL context\n");
    return NULL;
  }

  // Set the certificate and private key for the server
  if (SSL_CTX_use_certificate_file(ctx, "/path/to/server.crt", SSL_FILETYPE_PEM) <= 0 ||
      SSL_CTX_use_privatekey_file(ctx, "/path/to/server.key", SSL_FILETYPE_PEM) <= 0) {
    fprintf(stderr, "failed to set certificate and private key\n");
    return NULL;
  }

  // Set the trust store for the server
  if (SSL_CTX_load_verify_locations(ctx, "/path/to/ca-certificates.crt", NULL) <= 0) {
    fprintf(stderr, "failed to set trust store\n");
    return NULL;
  }

  // Set the verify mode for the server
  SSL_CTX_set_verify(ctx, SSL_VERIFY_PEER | SSL_VERIFY_FAIL_IF_NO_PEER_CERT, NULL);

  // Create a new socket and perform SSL handshake
  sockfd = ssl_connect("www.example.com", "443");
  if (sockfd < 0) {
    fprintf(stderr, "failed to connect\n");
    return NULL;
  }

  // Create an SSL object for the socket
  SSL *ssl = SSL_new(ctx);
  if (!ssl) {
    fprintf(stderr, "failed to create SSL object\n");
    return NULL;
  }

  // Set the socket as the underlying transport for the SSL object
  SSL_set_fd(ssl, sockfd);

  // Perform SSL handshake
  if (SSL_connect(ssl) <= 0) {
    fprintf(stderr, "failed to perform SSL handshake\n");
    return NULL;
  }

  // Create a new SSL context for the socket
  struct ssl_ctx_st *new_ctx = SSL_CTX_new(SSLv23_method());
  if (!new_ctx) {
    fprintf(stderr, "failed to create new SSL context\n");
    return NULL;
  }

  // Set the certificate and private key for the client
  if (SSL_CTX_use_certificate_file(new_ctx, "/path/to/client.crt", SSL_FILETYPE_PEM) <= 0 ||
      SSL_CTX_use_privatekey_file(new_ctx, "/path/to/client.key", SSL_FILETYPE_PEM) <= 0) {
    fprintf(stderr, "failed to set certificate and private key\n");
    return NULL;
  }

  // Set the trust store for the client
  if (SSL_CTX_load_verify_locations(new_ctx, "/path/to/ca-certificates.crt", NULL) <= 0) {
    fprintf(stderr, "failed to set trust store\n");
    return NULL;
  }

  // Set the verify mode for the client
  SSL_CTX_set_verify(new_ctx, SSL_VERIFY_PEER | SSL_VERIFY_FAIL_IF_NO_PEER_CERT, NULL);

  return new_ctx;
}

// Function to read data from an SSL socket
int ssl_read(SSL *ssl, void *buf, int num) {
  return SSL_read(ssl, buf, num);
}

// Function to write data to an SSL socket
int ssl_write(SSL *ssl, const void *buf, int num) {
  return SSL_write(ssl, buf, num);
}

// Function to close an SSL socket
void ssl_close(SSL *ssl) {
  SSL_free(ssl);
}
```

This code creates a new SSL context for the server and client. It sets the certificate and private key for both the server and client, as well as the trust store for the server. The `ssl_connect` function is used to establish an SSL connection between the server and client, and the `ssl_read` and `ssl_write` functions are used to read and write data over the SSL connection. Finally, the `ssl_close` function is used to close the SSL socket.

Note that this code assumes that you have the necessary certificates and private keys in place for the server and client. You will need to modify the code to suit your specific needs.']

