void batchProcessOrderRequests(const vector<RequestMetadata>& requests) {
    // Create a thread pool with the same number of threads as the number of requests
    const int numThreads = min(requests.size(), max_threads);
    auto threadPool = make_shared<threadpool>(numThreads);

    // Create a task queue for processing requests
    auto taskQueue = make_shared<queue<function<void()>>>();

    // Create a mutex and condition variable for synchronizing access to the task queue
    mutex taskQueueMutex;
    condition_variable taskQueueCondVar;

    // Initialize the task queue with processing tasks
    for (const auto& request : requests) {
