    // Create a worker thread for executing tasks in the task queue
    auto worker = [taskQueue]() {
        while (true) {
            function<void()> task;

            {
                unique_lock<mutex> lock(taskQueueMutex);
                if (!taskQueue->empty()) {
                    task = move(taskQueue->front());
                    taskQueue->pop();
                } else {
