      .build(new CacheLoader<String, Integer>() {
        @Override
        public Integer load(String key) throws Exception {
          return fetchIntegerFromExternalSource();
        }
      });
    counterMap = new ConcurrentHashMap<>();
    executor = Executors.newFixedThreadPool(MAX_CONCURRENCY);
    client = HttpClient.newHttpClient();
    logger = Logger.getLogger(LOG_FILE);
  }

  private Integer fetchIntegerFromExternalSource() {
    int retryCount = 0;
    while (retryCount < MAX_RETRY_COUNT) {
      try {
        HttpRequest request = new HttpRequestBuilder()
          .url(REST_API_URL)
          .build();
        return client.sendAsync(request, new JsonIntegerHandler())
          .thenApply(json -> json.getAsJsonPrimitive().getAsInt());
      } catch (Exception e) {
        if (logger != null) {
          logger.warning("Failed to fetch integer from external source: " + e.getMessage());
        }
        retryCount++;
        try {
          Thread.sleep(RETRY_BACKOFF.toMillis()); // exponential backoff
        } catch (InterruptedException ex) {
          if (logger != null) {
            logger.warning("Retrying fetch integer from external source was interrupted");
          }
          return null;
        }
      }
    }
    throw new RuntimeException("Exceeded maximum retries for fetching integer from external source");
  }

  private Integer getIntegerFromCache(String key) {
    try {
      if (cache.getIfPresent(key) != null) {
        return cache.get(key);
      } else {
        return null;
      }
    } catch (Exception e) {
      throw new RuntimeException("Failed to get integer from cache: " + e.getMessage());
    }
  }

  private void storeIntegerInCache(String key, Integer value) {
    try {
      cache.put(key, value);
    } catch (Exception e) {
      throw new RuntimeException("Failed to store integer in cache: " + e.getMessage());
    }
  }

  private void updateCounterMap(String key, AtomicInteger counter) {
    try {
      counterMap.putIfAbsent(key, counter);
    } catch (Exception e) {
      throw new RuntimeException("Failed to update counter map: " + e.getMessage());
    }
  }

  public Integer getLargestInteger() {
    int max = 0;
    for (int i = 1; i <= INSTANCE_COUNT; i++) {
      String key = "instance" + i;
      AtomicInteger counter = new AtomicInteger();
      if (counterMap.containsKey(key)) {
        counter = counterMap.get(key);
      } else {
        updateCounterMap(key, counter);
      }
      Integer integer = getIntegerFromCache(key);
      if (integer != null) {
        max = Math.max(max, integer);
        counter.incrementAndGet();
      } else {
        executor.submit(() -> storeIntegerInCache(key, fetchIntegerFromExternalSource()));
      }
    }
    return max;
  }
}
