    // Function to split a large CSV file stored in memory into smaller chunks for parallel processing.
    std::vector<std::vector<std::string>> splitFile(const std::vector<std::string>& file) const {
        auto numChunks = numThreads_;
        if (numChunks > file.size()) {
            numChunks = file.size();
        }
        std::vector<std::vector<std::string>> chunks;
        for (auto i = 0u; i < numChunks; ++i) {
            chunks.push_back(file[i]);
        }
        return chunks;
    }

