bool validateToken(char* access_token) {
    // Check if the token type is 'Bearer'
    if (strcmp(access_token, "Bearer") != 0) {
        return false;
    }

    // Get the expires_in field from the token
    int expires_in = getExpiresInField(access_token);

    // Check if the expires_in field is a positive integer not exceeding 3600 seconds
    if (expires_in < 0 || expires_in > 3600) {
        return false;
    }

    return true;
}

