// Structure definition
typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Linked list definition
typedef struct NFAPI_CRC_INDICATION_PDU_LIST {
    size_t length;
    size_t capacity;
    NFAPI_CRC_INDICATION_PDU_T *pdu;
} NFAPI_CRC_INDICATION_PDU_LIST;

// Function prototypes
NFAPI_CRC_INDICATION_PDU_LIST* nfapi_crc_indication_pdu_list_create();
void nfapi_crc_indication_pdu_list_destroy(NFAPI_CRC_INDICATION_PDU_LIST *list);
bool nfapi_crc_indication_pdu_list_add(NFAPI_CRC_INDICATION_PDU_LIST *list, NFAPI_CRC_INDICATION_PDU_T *pdu);
NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_indication_pdu_list_get(NFAPI_CRC_INDICATION_PDU_LIST *list, size_t index);
void nfapi_crc_indication_pdu_list_remove(NFAPI_CRC_INDICATION_PDU_LIST *list, size_t index);
size_t nfapi_crc_indication_pdu_list_length(NFAPI_CRC_INDICATION_PDU_LIST *list);

// Function implementations
NFAPI_CRC_INDICATION_PDU_LIST* nfapi_crc_indication_pdu_list_create() {
    NFAPI_CRC_INDICATION_PDU_LIST *list = (NFAPI_CRC_INDICATION_PDU_LIST*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_LIST));
    if (!list) {
        return NULL;
    }
    list->length = 0;
    list->capacity = 16; // initial capacity of 16 PDUS
    list->pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->capacity);
    if (!list->pdu) {
        free(list);
        return NULL;
    }
    return list;
}

void nfapi_crc_indication_pdu_list_destroy(NFAPI_CRC_INDICATION_PDU_LIST *list) {
    if (!list) {
        return;
    }
    free(list->pdu);
    free(list);
}

bool nfapi_crc_indication_pdu_list_add(NFAPI_CRC_INDICATION_PDU_LIST *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (!list || !pdu) {
        return false;
    }
    // Ensure capacity is sufficient
    if (list->length >= list->capacity) {
        size_t new_capacity = list->capacity * 2; // double the capacity
        NFAPI_CRC_INDICATION_PDU_T* new_pdu = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
        if (!new_pdu) {
            return false; // realloc failed
        }
        list->pdu = new_pdu;
        list->capacity = new_capacity;
    }
    memcpy(list->pdu + list->length, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T)); // add PDU to end of list
    list->length++;
    return true;
}

NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_indication_pdu_list_get(NFAPI_CRC_INDICATION_PDU_LIST *list, size_t index) {
    if (!list || index >= list->length) {
        return NULL;
    }
    return list->pdu + index;
}

void nfapi_crc_indication_pdu_list_remove(NFAPI_CRC_INDICATION_PDU_LIST *list, size_t index) {
    if (!list || index >= list->length) {
        return;
    }
    // Shift all elements after the target index to left by one
    memmove(list->pdu + index, list->pdu + index + 1, (list->length - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    // Decrement length of list
    list->length--;
}

size_t nfapi_crc_indication_pdu_list_length(NFAPI_CRC_INDICATION_PDU_LIST *list) {
    if (!list) {
        return 0;
    }
    return list->length;
}
```
This code implements the `nfapi_crc_indication_pdu_list` data structure and provides functions for adding, getting, removing, and querying the length of the list. The list is implemented as an array of `NFAPI_CRC_INDICATION_PDU_T` structures, with a variable `length` that indicates the number of elements in the list. The `capacity` member variable is used to keep track of the maximum size of the array, and it is doubled whenever the list runs out of space.

The functions take a pointer to the list as an argument, so they can be called on any instance of the list data structure. The `add` function takes a pointer to a `NFAPI_CRC_INDICATION_PDU_T` structure as an argument and adds it to the end of the list. The `get` function returns a pointer to the `NFAPI_CRC_INDICATION_PDU_T` structure at the specified index in the list, or `NULL` if the index is out of bounds. The `remove` function removes the element at the specified index from the list and shifts all elements after it to the left by one.

The `length` function returns the current length of the list, which can be used for iterating over the elements in the list or other purposes.']

