Here is a possible implementation of the modular C program that manages the creation, deletion, and usage of semaphores with a specified initial value, ensuring proper lifecycle management:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <pthread.h>
#include <semaphore.h>

// Define the struct to hold the semaphore information
typedef struct {
    int value; // initial value of the semaphore
    char *name; // name of the semaphore
    pthread_mutex_t mutex; // mutex for synchronizing access to the semaphore
} semaphore_t;

// Define a function to create a new semaphore
semaphore_t* create_semaphore(const char *name, int value) {
    semaphore_t *sem = malloc(sizeof(semaphore_t));
    if (sem == NULL) {
        perror("Error creating semaphore");
        return NULL;
    }

    // Initialize the mutex for synchronizing access to the semaphore
    pthread_mutex_init(&sem->mutex, NULL);

    // Set the name and initial value of the semaphore
    sem->name = strdup(name);
    sem->value = value;

    return sem;
}

// Define a function to delete a semaphore
void delete_semaphore(semaphore_t *sem) {
    // Check if the semaphore is valid
    if (sem == NULL) {
        perror("Error deleting semaphore");
        return;
    }

    // Destroy the mutex for synchronizing access to the semaphore
    pthread_mutex_destroy(&sem->mutex);

    // Free the memory allocated for the semaphore name and value
    free(sem->name);
    sem->value = 0;

    // Free the memory allocated for the semaphore struct
    free(sem);
}

// Define a function to acquire a semaphore
int acquire_semaphore(semaphore_t *sem) {
    int ret;

    // Check if the semaphore is valid
    if (sem == NULL) {
        perror("Error acquiring semaphore");
        return -1;
    }

    // Lock the mutex for synchronizing access to the semaphore
    pthread_mutex_lock(&sem->mutex);

    // Decrement the value of the semaphore by 1
    sem->value--;

    if (sem->value < 0) {
        perror("Semaphore value is negative");
        ret = -1;
    } else {
        ret = 0;
    }

    // Unlock the mutex for synchronizing access to the semaphore
    pthread_mutex_unlock(&sem->mutex);

    return ret;
}

// Define a function to release a semaphore
int release_semaphore(semaphore_t *sem) {
    int ret;

    // Check if the semaphore is valid
    if (sem == NULL) {
        perror("Error releasing semaphore");
        return -1;
    }

    // Lock the mutex for synchronizing access to the semaphore
    pthread_mutex_lock(&sem->mutex);

    // Increment the value of the semaphore by 1
    sem->value++;

    if (sem->value < 0) {
        perror("Semaphore value is negative");
        ret = -1;
    } else {
        ret = 0;
    }

    // Unlock the mutex for synchronizing access to the semaphore
    pthread_mutex_unlock(&sem->mutex);

    return ret;
}
```
This program defines a struct `semaphore_t` to hold the information of a semaphore, including its name and initial value. It also includes mutexes for synchronizing access to the semaphore and functions to create, delete, acquire, and release the semaphore. The functions check for validity of the semaphore and handle errors appropriately.

To use this program, you can create a semaphore by calling `create_semaphore` function with the name and initial value of the semaphore as arguments. You can then acquire or release the semaphore using the `acquire_semaphore` and `release_semaphore` functions respectively. To delete the semaphore, you can call `delete_semaphore`.

You can also add additional functions to handle token verification and error-handling as per your requirement.']

