    if (status != 0) {
        LOG_ERROR("Failed to encrypt the message");
        return -1;
    }

    // Return the encrypted message
    return encrypted_msg;
}

// Function to decrypt a message using a cryptographic algorithm
int decrypt(const char* key, const char* msg) {
    // Check if the encryption algorithm is supported
    if (key == NULL || strlen(key) == 0) {
        LOG_ERROR("Invalid key for decryption");
        return -1;
    }

    // Find the corresponding cryptographic algorithm in the array of supported algorithms
    struct CryptoInfo* algo = find_crypto_algorithm(key);
    if (algo == NULL) {
        LOG_ERROR("Unsupported decryption algorithm");
        return -1;
    }

    // Call the decrypt function for the selected algorithm
    char* decrypted_msg = NULL;
    int status = algo->decrypt(key, msg, &decrypted_msg);
    if (status != 0) {
        LOG_ERROR("Failed to decrypt the message");
        return -1;
    }

    // Return the decrypted message
    return decrypted_msg;
}

// Function to find a cryptographic algorithm in the array of supported algorithms
struct CryptoInfo* find_crypto_algorithm(const char* key) {
    for (int i = 0; i < sizeof(crypto_algorithms)/sizeof(struct CryptoInfo); i++) {
        if (strcmp(key, crypto_algorithms[i].key) == 0) {
            return &crypto_algorithms[i];
        }
    }
    return NULL;
}
