// RandomNumberGenerator.h
#pragma once
#include <random>
#include <vector>
#include <string>

namespace RNG {
class RandomNumberGenerator {
private:
    std::mt19937 mt;
    std::uniform_int_distribution<int> uniIntDist;
    std::normal_distribution<double> normDist;

public:
    RandomNumberGenerator(std::string seed = "");

    void setSeed(const std::string& seed);

    int getRandomInt();

    double getRandomDouble();

    double getRandomNormal(double mean, double stddev);

    std::vector<int> getRandomIntegers(int n, int min = 0, int max = RAND_MAX);

    std::vector<double> getRandomDoubles(int n, double min = 0, double max = RAND_MAX);

    std::vector<double> getRandomNormals(int n, double mean = 0.0, double stddev = 1.0);
};
} // namespace RNG

// RandomNumberGenerator.cpp
#include "RandomNumberGenerator.h"

namespace RNG {
RandomNumberGenerator::RandomNumberGenerator(const std::string& seed) {
    if (seed == "") {
        mt = std::mt19937(std::random_device()());
    } else {
        // Use a hash function to generate a seed based on the given string
        size_t hash = std::hash<std::string>{}(seed);
        mt = std::mt19937(hash);
    }
}

void RandomNumberGenerator::setSeed(const std::string& seed) {
    // Use a hash function to generate a seed based on the given string
    size_t hash = std::hash<std::string>{}(seed);
    mt.seed(hash);
}

int RandomNumberGenerator::getRandomInt() {
    return uniIntDist(mt);
}

double RandomNumberGenerator::getRandomDouble() {
    return uniIntDist(mt) / (double)RAND_MAX;
}

double RandomNumberGenerator::getRandomNormal(double mean, double stddev) {
    return normDist(mt, mean, stddev);
}

std::vector<int> RandomNumberGenerator::getRandomIntegers(int n, int min, int max) {
    std::vector<int> result;
    for (int i = 0; i < n; ++i) {
        result.push_back(uniIntDist(mt, min, max));
    }
    return result;
}

std::vector<double> RandomNumberGenerator::getRandomDoubles(int n, double min, double max) {
    std::vector<double> result;
    for (int i = 0; i < n; ++i) {
        result.push_back(uniIntDist(mt, min, max) / (double)RAND_MAX);
    }
    return result;
}

std::vector<double> RandomNumberGenerator::getRandomNormals(int n, double mean, double stddev) {
    std::vector<double> result;
    for (int i = 0; i < n; ++i) {
        result.push_back(normDist(mt, mean, stddev));
    }
    return result;
}
} // namespace RNG']

