<?php

// AccountManagementService.php

namespace App\Services;

use App\Authenticators\MultiTenantDatabaseAuthenticator;
use App\PaymentGateways\PCICompliantPaymentGateway;
use Redis;

class AccountManagementService {
    private $authenticator;
    private $paymentGateway;
    private $redisCache;

    public function __construct(MultiTenantDatabaseAuthenticator $authenticator, PCICompliantPaymentGateway $paymentGateway, Redis $redisCache) {
        $this->authenticator = $authenticator;
        $this->paymentGateway = $paymentGateway;
        $this->redisCache = $redisCache;
    }

    public function getAccount($id) {
        // Check if the account exists in cache
        if ($this->redisCache->has('account:' . $id)) {
            return $this->redisCache->get('account:' . $id);
        }

        // Authenticate the user and fetch the account data from the database
        $user = $this->authenticator->authenticate();
        $accountData = $this->database->query("SELECT * FROM accounts WHERE id = :id", ['id' => $id]);

        // Cache the account data for future requests
        $this->redisCache->set('account:' . $id, $accountData);

        return $accountData;
    }

    public function updateAccount($id, $data) {
        // Authenticate the user and fetch the account data from the database
        $user = $this->authenticator->authenticate();
        $accountData = $this->database->query("SELECT * FROM accounts WHERE id = :id", ['id' => $id]);

        // Check if the user has permission to update this account
        if ($user['role'] != 'admin') {
            throw new \Exception('User does not have permission to update this account');
        }

        // Update the account data in the database
        $this->database->query("UPDATE accounts SET name = :name, email = :email WHERE id = :id", [
            'name' => $data['name'],
            'email' => $data['email'],
            'id' => $id
        ]);

        // Update the account data in the cache
        $this->redisCache->set('account:' . $id, $accountData);
    }

    public function deleteAccount($id) {
        // Authenticate the user and fetch the account data from the database
        $user = $this->authenticator->authenticate();
        $accountData = $this->database->query("SELECT * FROM accounts WHERE id = :id", ['id' => $id]);

        // Check if the user has permission to delete this account
        if ($user['role'] != 'admin') {
            throw new \Exception('User does not have permission to delete this account');
        }

        // Delete the account data from the database
        $this->database->query("DELETE FROM accounts WHERE id = :id", ['id' => $id]);

        // Delete the account data from the cache
        $this->redisCache->del('account:' . $id);
    }
}
