    private $accountManagementService;

    public function __construct(AccountManagementService $accountManagementService) {
        $this->accountManagementService = $accountManagementService;
    }

    public function processPayment($paymentData) {
        // Authenticate the user and fetch the account data from the database
        $user = $this->accountManagementService->getAccount($paymentData['userId']);

        // Check if the user has a valid payment method
        if (!$user['hasPaymentMethod']) {
            throw new \Exception('User does not have a valid payment method');
        }

        // Process the payment using the payment gateway
        $response = $this->paymentGateway->processPayment($paymentData);

        // Check if the payment was successful
        if ($response['status'] != 'success') {
            throw new \Exception('Payment failed: ' . $response['message']);
        }
    }
}
