['```php
function handleAccountRequest($method, $data) {
    // Validate the request method
    if (!in_array($method, ['POST', 'PUT', 'DELETE'])) {
        throw new \Exception("Invalid request method");
    }

    // Sanitize and validate the input data
    $data = filter_var_array($data, [
        'username' => FILTER_SANITIZE_STRING,
        'email' => FILTER_VALIDATE_EMAIL,
        'password' => FILTER_VALIDATE_REGEXP,
    ]);

    // Handle the request
    switch ($method) {
        case 'POST':
            createAccount($data['username'], $data['email'], $data['password']);
            break;
        case 'PUT':
            updateAccount($data['username'], $data['email'], $data['password']);
            break;
        case 'DELETE':
            deleteAccount($data['username']);
            break;
    }
}

function createAccount($username, $email, $password) {
    // Validate the input data
    if (empty($username)) {
        throw new \Exception("Username is required");
    } elseif (empty($email)) {
        throw new \Exception("Email is required");
    } elseif (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
        throw new \Exception("Invalid email address");
    } elseif (strlen($password) < 8) {
        throw new \Exception("Password must be at least 8 characters long");
    }

    // Insert the account into the database
    $sql = "INSERT INTO users (username, email, password) VALUES (:username, :email, :password)";
    $stmt = $db->prepare($sql);
    $stmt->bindValue(':username', $username);
    $stmt->bindValue(':email', $email);
    $stmt->bindValue(':password', password_hash($password, PASSWORD_DEFAULT));
    $stmt->execute();
}

function updateAccount($username, $email, $password) {
    // Validate the input data
    if (empty($username)) {
        throw new \Exception("Username is required");
    } elseif (empty($email)) {
        throw new \Exception("Email is required");
    } elseif (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
        throw new \Exception("Invalid email address");
    } elseif (strlen($password) < 8) {
        throw new \Exception("Password must be at least 8 characters long");
    }

    // Update the account in the database
    $sql = "UPDATE users SET username = :username, email = :email WHERE username = :username";
    $stmt = $db->prepare($sql);
    $stmt->bindValue(':username', $username);
    $stmt->bindValue(':email', $email);
    $stmt->execute();
}

function deleteAccount($username) {
    // Validate the input data
    if (empty($username)) {
        throw new \Exception("Username is required");
    }

    // Delete the account from the database
    $sql = "DELETE FROM users WHERE username = :username";
    $stmt = $db->prepare($sql);
    $stmt->bindValue(':username', $username);
    $stmt->execute();
}
```
