// Load Balancer Class
public class ResilientLoadBalancer {
    // Map of backend service URLs to their corresponding weights
    private Map<String, Integer> backendWeights;

    // Round-robin algorithm for distributing traffic across backends
    public String getNextBackend(List<String> backends) {
        int currentIndex = 0;
        while (true) {
            currentIndex = (currentIndex + 1) % backends.size();
            if (backendWeights.get(backends.get(currentIndex)) > 0) {
                break;
            }
        }
        return backends.get(currentIndex);
    }

    // Custom traffic distribution algorithm based on service health metrics
    public String getNextBackend(List<String> backends, Map<String, Integer> serviceHealthMetrics) {
        int currentIndex = 0;
        while (true) {
            currentIndex = (currentIndex + 1) % backends.size();
            if (serviceHealthMetrics.get(backends.get(currentIndex)) > 0) {
                break;
            }
        }
        return backends.get(currentIndex);
    }
}

// Session Persistence Class
public class SessionPersistence {
    // Map of backend service URLs to session IDs
    private Map<String, String> sessions;

    // Add a new session ID for a given backend service URL
    public void addSession(String backendUrl, String sessionId) {
        sessions.put(backendUrl, sessionId);
    }

    // Remove an existing session ID for a given backend service URL
    public void removeSession(String backendUrl) {
        sessions.remove(backendUrl);
    }

    // Get the current session ID for a given backend service URL
    public String getCurrentSession(String backendUrl) {
        return sessions.get(backendUrl);
    }
}

// Dynamic Weighting Class
public class DynamicWeighting {
    // Map of backend service URLs to their corresponding weights
    private Map<String, Integer> backendWeights;

    // Update the weight for a given backend service URL based on its health metrics
    public void updateWeight(String backendUrl, int healthMetrics) {
        if (healthMetrics < 50) {
            backendWeights.put(backendUrl, 1);
        } else {
            backendWeights.put(backendUrl, 2);
        }
    }
}
```
