// DynamicConfigManager.java
import java.util.concurrent.locks.ReentrantLock;
import java.util.concurrent.atomic.AtomicReference;

public class DynamicConfigManager {
    private final AtomicReference<Configuration> config = new AtomicReference<>();
    private final ReentrantLock lock = new ReentrantLock();

    public Configuration getConfig() {
        lock.lock();
        try {
            return config.get();
        } finally {
            lock.unlock();
        }
    }

    public void setConfig(Configuration config) {
        lock.lock();
        try {
            this.config.set(config);
        } finally {
            lock.unlock();
        }
    }

    public void loadConfigFromJSON(String jsonFilePath) throws IOException {
        Configuration newConfig = Configuration.parseJSON(jsonFilePath);
        setConfig(newConfig);
    }

    public void loadConfigFromRESTAPI(String apiEndpoint) throws IOException {
        HttpResponse response = makeRequestToRESTAPI(apiEndpoint);
        if (response.isSuccessful()) {
            Configuration newConfig = Configuration.parseJSON(response.getBody());
            setConfig(newConfig);
        } else {
            // handle failed request
        }
    }

    public void loadConfigFromDatabase(String databaseUrl) throws IOException {
        Connection conn = getConnectionToDatabase(databaseUrl);
        try (Statement stmt = conn.createStatement()) {
            ResultSet rs = stmt.executeQuery("SELECT * FROM config");
            while (rs.next()) {
                Configuration newConfig = new Configuration();
                newConfig.setProperty(rs.getString("property"), rs.getObject("value"));
                setConfig(newConfig);
            }
        } finally {
            conn.close();
        }
    }

    public void saveConfigToJSON(String jsonFilePath) throws IOException {
        Configuration currentConfig = getConfig();
        String configJSON = currentConfig.toJSON();
        Files.write(Paths.get(jsonFilePath), configJSON.getBytes());
    }

    public void saveConfigToRESTAPI(String apiEndpoint) throws IOException {
        HttpRequest request = new HttpRequest();
        request.setMethod("POST");
        request.setHeader("Content-Type", "application/json");
        request.setBody(getConfig().toJSON());
        HttpResponse response = makeRequestToRESTAPI(apiEndpoint, request);
        if (response.isSuccessful()) {
            // handle successful save
        } else {
            // handle failed save
        }
    }

    public void saveConfigToDatabase(String databaseUrl) throws IOException {
        Connection conn = getConnectionToDatabase(databaseUrl);
        try (PreparedStatement stmt = conn.prepareStatement("INSERT INTO config VALUES(?, ?)")) {
            Configuration currentConfig = getConfig();
            for (Map.Entry<String, Object> entry : currentConfig.getProperties().entrySet()) {
                stmt.setString(1, entry.getKey());
                stmt.setObject(2, entry.getValue());
                stmt.addBatch();
            }
            int[] results = stmt.executeBatch();
        } finally {
            conn.close();
        }
    }

    private static HttpResponse makeRequestToRESTAPI(String apiEndpoint, HttpRequest request) throws IOException {
        URL url = new URL(apiEndpoint);
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setRequestMethod(request.getMethod());
        conn.setDoOutput(true);
        if (request.getHeader("Content-Type") != null) {
            conn.setRequestProperty("Content-Type", request.getHeader("Content-Type"));
        }
        conn.setRequestProperty("User-Agent", "DynamicConfigManager");
        OutputStream out = conn.getOutputStream();
        byte[] bodyBytes = request.getBody().getBytes();
        out.write(bodyBytes, 0, bodyBytes.length);
        out.flush();
        out.close();
        return new HttpResponse(conn);
    }

    private static Connection getConnectionToDatabase(String databaseUrl) throws SQLException {
        String dbType = databaseUrl.split(":")[1].toUpperCase();
        switch (dbType) {
            case "MYSQL":
                return DriverManager.getConnection(databaseUrl);
            case "POSTGRES":
                return DriverManager.getConnection(databaseUrl);
            default:
                throw new SQLException("Unsupported database type: " + dbType);
        }
    }
}

// Configuration.java
import java.util.HashMap;
import java.util.Map;

public class Configuration {
    private final Map<String, Object> properties = new HashMap<>();

    public void setProperty(String key, Object value) {
        properties.put(key, value);
    }

    public Object getProperty(String key) {
        return properties.get(key);
    }

    public Map<String, Object> getProperties() {
        return properties;
    }

    public static Configuration parseJSON(String jsonString) throws JSONException {
        JSONObject json = new JSONObject(jsonString);
        Configuration config = new Configuration();
        for (String key : json.keySet()) {
            Object value = json.get(key);
            config.setProperty(key, value);
        }
        return config;
    }

    public String toJSON() throws JSONException {
        JSONObject json = new JSONObject();
        for (Map.Entry<String, Object> entry : properties.entrySet()) {
            json.put(entry.getKey(), entry.getValue());
        }
        return json.toString();
    }
}

