    this.logSink.removeEntry(id);
  }

  // Get all entries in the log sink
  getEntries(): LogEntry[] {
    return this.logSink.getEntries();
  }
}

// Define a class for managing the logging system
class LoggingSystem {
  // Create an instance of the log buffer manager
  private readonly logBufferManager: LogBufferManager = new LogBufferManager();

  // Create an instance of the log sink manager
  private readonly logSinkManager: LogSinkManager = new LogSinkManager();

