    const id = generateId();

    // Add the entry to the log buffer manager
    this.logBufferManager.addEntry(id, entry);

    // Add the entry to the log sink manager
    this.logSinkManager.addEntry(id, entry);
  }

  // Define a function for removing an entry from the logging system
  removeEntry(id: string): void {
    // Remove the entry from the log buffer manager
    this.logBufferManager.removeEntry(id);

    // Remove the entry from the log sink manager
    this.logSinkManager.removeEntry(id);
  }

  // Define a function for getting all entries in the logging system
  getEntries(): LogEntry[] {
    // Get all entries in the log buffer manager
    const bufferEntries = this.logBufferManager.getEntries();

    // Get all entries in the log sink manager
    const sinkEntries = this.logSinkManager.getEntries();

    // Combine the entries from both managers and return them
    return [...bufferEntries, ...sinkEntries];
  }
