    if (list == NULL) {
        return NULL;
    }
    memset(list, 0, sizeof(NFAPI_CRC_INDICATION_LIST_T));

    nfapi_crc_indication_lib_pool = malloc(num_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (nfapi_crc_indication_lib_pool == NULL) {
        free(list);
        return NULL;
    }
    memset(nfapi_crc_indication_lib_pool, 0, num_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Initialize the linked list and custom memory pool
    for (uint32_t i = 0; i < num_entries; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T*) nfapi_crc_indication_lib_pool + i;
        pdu->rx_ue_information_tag = 0x1234;
        pdu->rnti = seed * (i + 1);
        pdu->crc_flag = rand() % 2;
        if (list->head == NULL) {
            list->head = pdu;
        } else {
            list->tail->next = pdu;
        }
        list->tail = pdu;
