    if (list == NULL || pdu == NULL) {
        return false;
    }

    // Insert the new CRC indication PDU into the linked list
    NFAPI_CRC_INDICATION_PDU_T *new_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_pdu == NULL) {
        return false;
    }
    memcpy(new_pdu, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_pdu->next = NULL;

    NFAPI_CRC_INDICATION_PDU_T *tail = list->tail;
    if (tail == NULL) {
        list->head = new_pdu;
    } else {
        tail->next = new_pdu;
    }
    list->tail = new_pdu;

    return true;
