// Function to retrieve the next CRC indication PDU from the linked list
NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_indication_lib_next(NFAPI_CRC_INDICATION_LIST_T *list) {
    // Validate inputs
    if (list == NULL) {
        return NULL;
