    NFAPI_CRC_INDICATION_PDU_T *pdu = list->head;
    if (pdu != NULL) {
        list->head = pdu->next;
        if (list->head == NULL) {
            list->tail = NULL;
        }
    }

    return pdu;
}

// Function to cleanup all allocated resources in the library, including the linked list
void nfapi_crc_indication_lib_cleanup(NFAPI_CRC_INDICATION_LIST_T *list) {
    // Validate inputs
    if (list == NULL) {
        return;
    }

    // Cleanup the linked list and custom memory pool
    NFAPI_CRC_INDICATION_PDU_T *pdu = list->head;
    while (pdu != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *next = pdu->next;
        free(pdu);
        pdu = next;
