// Function to create a new connection
int createConnection(char *host, int port) {
    // Create a new SSL context
    SSL_CTX *ctx = SSL_CTX_new(TLSv1_2_client_method());

    // Create a new SSL object
    SSL *ssl = SSL_new(ctx);

    // Set the host and port for the connection
    SSL_set_fd(ssl, host, port);

    // Return the new connection
    return ssl;
}

// Function to close a connection
int closeConnection(SSL *ssl) {
    // Close the SSL object
    SSL_free(ssl);

    // Return success
    return 1;
}

// Function to establish a TLS/SSL connection
int establishConnection(char *host, int port) {
    // Create a new SSL context
    SSL_CTX *ctx = SSL_CTX_new(TLSv1_2_client_method());

    // Create a new SSL object
    SSL *ssl = SSL_new(ctx);

    // Set the host and port for the connection
    SSL_set_fd(ssl, host, port);

    // Perform the TLS/SSL handshake
    if (SSL_connect(ssl) == 1) {
        printf("Connected to %s:%d\n", host, port);
    } else {
        printf("Failed to connect to %s:%d\n", host, port);
        return -1;
    }

    // Return the SSL object
