}

// Function to read from a connection
int readFromConnection(SSL *ssl) {
    // Read from the connection
    char buffer[1024];
    int bytesRead = SSL_read(ssl, buffer, 1024);

    // Print the data that was read
    printf("Received %d bytes: ", bytesRead);
    for (int i = 0; i < bytesRead; i++) {
        printf("%c", buffer[i]);
    }
    printf("\n");

    // Return the number of bytes read
    return bytesRead;
}

// Function to write to a connection
int writeToConnection(SSL *ssl, char *data) {
    // Write to the connection
    int bytesWritten = SSL_write(ssl, data, strlen(data));

    // Print the data that was written
    printf("Sent %d bytes: %s\n", bytesWritten, data);

    // Return the number of bytes written
    return bytesWritten;
}

// Function to handle certificate renewal
int handleCertificateRenewal(SSL *ssl) {
