    int certNeedsUpdate = SSL_get_verify_result(ssl);

    // If the certificate needs to be renewed, update it
    if (certNeedsUpdate != X509_V_OK) {
        printf("Certificate renewal required\n");
        return 1;
    } else {
        return 0;
    }
}

