// Define a custom memory pool for allocating and deallocating memory efficiently
struct mem_pool {
  size_t capacity; // Maximum number of elements that can be stored in the pool
  size_t size; // Current number of elements stored in the pool
  void **elements; // Array of pointers to allocated memory blocks
};

// Define a record structure for storing an int value and its corresponding CRC flag
struct record {
  int key;
  uint8_t crcflag;
};

// Define a dynamically resizable array of NFAPI_CRC_INDICATION_PDU_T structures
struct crc_indication_pdu_array {
  size_t capacity; // Maximum number of elements that can be stored in the array
  size_t size; // Current number of elements stored in the array
  struct NFAPI_CRC_INDICATION_PDU *elements; // Array of pointers to NFAPI_CRC_INDICATION_PDU structures
};

// Define a thread-safe, lock-free insertion mechanism for the crc_indication_pdu_array
void insert_crc_indication_pdu(struct crc_indication_pdu_array *array, struct NFAPI_CRC_INDICATION_PDU *element) {
  // Acquire a lock on the array to ensure thread safety
  pthread_mutex_lock(&array->lock);

  // Check if the array is full and needs to be resized
  if (array->size == array->capacity) {
    // Double the size of the array
    array->capacity *= 2;
    // Reallocate memory for the elements array
    array->elements = realloc(array->elements, array->capacity * sizeof(struct NFAPI_CRC_INDICATION_PDU));
  }

  // Copy the new element to the end of the array
  memcpy(&array->elements[array->size], element, sizeof(struct NFAPI_CRC_INDICATION_PDU));
  // Increment the size of the array
  array->size++;

  // Release the lock on the array
  pthread_mutex_unlock(&array->lock);
}

// Define a thread-safe, lock-free deletion mechanism for the crc_indication_pdu_array
void delete_crc_indication_pdu(struct crc_indication_pdu_array *array, struct NFAPI_CRC_INDICATION_PDU *element) {
  // Acquire a lock on the array to ensure thread safety
  pthread_mutex_lock(&array->lock);

  // Find the index of the element to be deleted
  size_t index = 0;
  for (; index < array->size; ++index) {
    if (&array->elements[index] == element) break;
  }

  // Check if the element was found in the array
  assert(index < array->size);

  // Shift all elements after the deleted element to their left
  for (int i = index; i < array->size - 1; ++i) {
    memcpy(&array->elements[i], &array->elements[i + 1], sizeof(struct NFAPI_CRC_INDICATION_PDU));
  }

  // Decrement the size of the array
  array->size--;

  // Release the lock on the array
  pthread_mutex_unlock(&array->lock);
}

// Define a function for allocating memory from the custom memory pool
void *mempool_alloc(struct mem_pool *pool, size_t size) {
  if (size > pool->capacity - pool->size) return NULL; // Out of memory

  // Allocate memory from the pool
  void *ptr = malloc(size);
  if (!ptr) return NULL; // Memory allocation failed

  // Increment the size of the pool
  pool->size += size;

  return ptr;
}

// Define a function for deallocating memory from the custom memory pool
void mempool_free(struct mem_pool *pool, void *ptr) {
  // Decrement the size of the pool
  pool->size -= sizeof(struct NFAPI_CRC_INDICATION_PDU);

  // Free the memory
  free(ptr);
}

// Define a function for initializing the custom memory pool
void mempool_init(struct mem_pool *pool, size_t capacity) {
  // Initialize the capacity of the pool
  pool->capacity = capacity;
  // Allocate memory for the elements array
  pool->elements = malloc(capacity * sizeof(struct NFAPI_CRC_INDICATION_PDU));
}

// Define a function for destroying the custom memory pool
void mempool_destroy(struct mem_pool *pool) {
  // Free the memory allocated to the elements array
  free(pool->elements);
}

// Define a function for allocating an array of 'record' structures
struct record *allocate_records(size_t size) {
  struct record *ptr = (struct record *)mempool_alloc(&pool, size * sizeof(struct record));
  if (!ptr) return NULL; // Memory allocation failed

  for (int i = 0; i < size; ++i) {
    ptr[i].key = rand(); // Randomly set the key value
    ptr[i].crcflag = rand() % 2; // Randomly set the CRC flag
  }

  return ptr;
}

// Define a function for deallocating an array of 'record' structures
void deallocate_records(struct record *ptr) {
  mempool_free(&pool, ptr);
}

// Define a function for initializing the 'crc_indication_pdu_array' structure
void init_crc_indication_pdu_array(struct crc_indication_pdu_array *array) {
  // Initialize the capacity of the array
  array->capacity = 10;
  // Allocate memory for the elements array
  array->elements = malloc(array->capacity * sizeof(struct NFAPI_CRC_INDICATION_PDU));
}

// Define a function for destroying the 'crc_indication_pdu_array' structure
void destroy_crc_indication_pdu_array(struct crc_indication_pdu_array *array) {
  // Free the memory allocated to the elements array
  free(array->elements);
}

// Define a function for adding an element to the 'crc_indication_pdu_array' structure
void add_crc_indication_pdu(struct crc_indication_pdu_array *array, struct NFAPI_CRC_INDICATION_PDU *element) {
  // Allocate memory for the new element
  void *ptr = mempool_alloc(&pool, sizeof(struct NFAPI_CRC_INDICATION_PDU));
  if (!ptr) return; // Memory allocation failed

  // Copy the contents of the new element into the allocated memory
  memcpy(ptr, element, sizeof(struct NFAPI_CRC_INDICATION_PDU));

  // Add the new element to the array
  insert_crc_indication_pdu(array, ptr);
}

// Define a function for inserting an element into the 'crc_indication_pdu_array' structure
void insert_crc_indication_pdu(struct crc_indication_pdu_array *array, struct NFAPI_CRC_INDICATION_PDU *element) {
  // Acquire a lock on the array to ensure thread safety
  pthread_mutex_lock(&array->lock);

  // Find the position where the new element should be inserted
  size_t index = 0;
  for (; index < array->size; ++index) {
    if (&array->elements[index] > element) break;
  }

  // Shift all elements after the insertion point to their right
  for (int i = array->size - 1; i >= index + 1; --i) {
    memcpy(&array->elements[i], &array->elements[i - 1], sizeof(struct NFAPI_CRC_INDICATION_PDU));
  }

  // Insert the new element at the insertion point
  memcpy(&array->elements[index], element, sizeof(struct NFAPI_CRC_INDICATION_PDU));

  // Increment the size of the array
  array->size++;

  // Release the lock on the array
  pthread_mutex_unlock(&array->lock);
}
