const char* db_user = "root";
const char* db_pass = "";
const char* db_name = "nfadb";

// Thread-safe global variables for storing configuration and database connection information
pthread_mutex_t config_lock = PTHREAD_MUTEX_INITIALIZER;
MYSQL* db_conn = NULL;

// Function to load the configuration file and update the RNTI set
int load_config(void) {
  // Lock the mutex to ensure thread-safe access to the config variables
  pthread_mutex_lock(&config_lock);

  // Load the configuration file and parse it for the valid RNTI values
  FILE* fp = fopen(config_file, "r");
  if (!fp) {
    printf("Error: unable to open config file\n");
    return -1;
  }

  char line[256];
  while (fgets(line, sizeof(line), fp)) {
    // Parse the line for the RNTI value
    int rnti = atoi(line);
    if (rnti > 0) {
      // Add the RNTI to the set of valid values
      pthread_mutex_lock(&config_lock);
      config.rnti_set[rnti] = true;
      pthread_mutex_unlock(&config_lock);
    }
  }

  // Unlock the mutex and return success
  pthread_mutex_unlock(&config_lock);
  return 0;
}

// Function to validate a received packet against the predefined checksums and protocol specifications
int validate_packet(NFAPI_CRC_INDICATION_PDU_T* pdu) {
  // Lock the mutex to ensure thread-safe access to the config variables
  pthread_mutex_lock(&config_lock);

  // Check if the RNTI is valid according to the current configuration
  if (config.rnti_set[pdu->rx_ue_information_tag] &&
      (pdu->crcflag == NFAPI_CRC_FLAG_TRUE || pdu->crcflag == NFAPI_CRC_FLAG_MAYBE)) {
    // Unlock the mutex and return success
    pthread_mutex_unlock(&config_lock);
    return 0;
  }

  // Unlock the mutex and return failure if the RNTI is not valid
  pthread_mutex_unlock(&config_lock);
  return -1;
}

// Function to store a validated packet in the MySQL database table
int store_packet(NFAPI_CRC_INDICATION_PDU_T* pdu) {
  // Connect to the MySQL database if not already connected
  if (!db_conn) {
    db_conn = mysql_init(NULL);
    if (!db_conn) {
      printf("Error: unable to initialize MySQL connection\n");
      return -1;
    }

    // Connect to the database and check for errors
    if (mysql_real_connect(db_conn, db_host, db_user, db_pass, db_name, db_port, NULL, 0) == NULL) {
      printf("Error: unable to connect to MySQL database\n");
      mysql_close(db_conn);
      return -1;
    }
  }

  // Prepare the SQL INSERT statement for the packet information
  char sql[256];
  sprintf(sql, "INSERT INTO nfadb (rx_ue_information_tag, rnti, crcflag, timestamp) VALUES ('%d', '%d', '%d', '%ld')",
          pdu->rx_ue_information_tag, pdu->rnti, pdu->crcflag, time(NULL));

  // Execute the SQL INSERT statement and check for errors
  if (mysql_real_query(db_conn, sql, strlen(sql)) != 0) {
    printf("Error: unable to execute MySQL query\n");
    mysql_close(db_conn);
    return -1;
  }

  // Commit the transaction and close the database connection if there were no errors
  mysql_commit(db_conn);
  mysql_close(db_conn);
  db_conn = NULL;

  // Return success
  return 0;
}

// Function to handle a received packet, validating it against predefined checksums and protocol specifications and storing it in the MySQL database if valid
int process_packet(NFAPI_CRC_INDICATION_PDU_T* pdu) {
  // Validate the received packet against predefined checksums and protocol specifications
  if (validate_packet(pdu) == 0) {
    // Store the validated packet in the MySQL database table
    store_packet(pdu);
  } else {
    // Log an error message if the packet could not be validated
    printf("Error: unable to validate received packet\n");
  }

  return 0;
}

// Main function that continuously polls for incoming packets and processes them using the `process_packet` function
int main(void) {
  // Load the configuration file and update the RNTI set
  load_config();

  // Define the network interface to poll for incoming packets
  char* iface = "eth0";

  // Continuously poll for incoming packets on the specified network interface
  while (1) {
    // Receive a packet from the network interface
    NFAPI_CRC_INDICATION_PDU_T pdu;
    int ret = recvfrom(iface, &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 0, NULL, NULL);
    if (ret < 0) {
      // Log an error message if the packet could not be received
      printf("Error: unable to receive packet\n");
      continue;
    }

    // Process the received packet using the `process_packet` function
    process_packet(&pdu);
  }

  return 0;
}
