// Define the populateNfapiPduList function
void populateNfapiPduList(int numOfRxUe, int numOfCrFlag, NFAPI_CRC_INDICATION_PDU_T* pduList) {
  // Initialize the RX_UE_INFORMATION_TAG and CRCFLAG values randomly
  srand(time(NULL));

  for (int i = 0; i < numOfRxUe; i++) {
    pduList[i].RX_UE_INFORMATION_TAG = rand() % 10000;

    // Randomly set the CRCFLAG value
    if (rand() % 2 == 0) {
      pduList[i].CRCFLAG = true;
    } else {
      pduList[i].CRCFLAG = false;
    }

    // Set the RNTI value to a random integer between 1 and 65536
    pduList[i].RNTI = rand() % 65536 + 1;
  }

  // Set the number of CRC_INDICATION_REL8_TAG values to be generated
  int numOfCrIndRel8Tag = (numOfCrFlag == 0) ? 0 : numOfRxUe * numOfCrFlag;

  for (int i = 0; i < numOfCrIndRel8Tag; i++) {
    // Generate a random CRC_INDICATION_REL8_TAG value
    int crIndRel8Tag = rand() % 10000;

    // Set the corresponding CRCFLAG value to true
    pduList[i].CRCFLAG = true;

    // Add the CRC_INDICATION_REL8_TAG value to the list
    pduList[i].CRC_INDICATION_REL8_TAG = crIndRel8Tag;
  }
}
