```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <pthread.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

#define MAX_CONFIGS 1024
#define CONFIG_FILE "/path/to/configs"

typedef struct {
    char *key;
    char *value;
} config_t;

static config_t configs[MAX_CONFIGS];
static pthread_rwlock_t config_lock = PTHREAD_RWLOCK_INITIALIZER;

int load_config(const char *filename) {
    int fd, ret = 0;
    ssize_t nread;
    char buffer[1024];
    struct stat st;

    if (stat(filename, &st)) {
        return -errno;
    }

    fd = open(filename, O_RDONLY);
    if (fd == -1) {
        return -errno;
    }

    while ((nread = read(fd, buffer, sizeof(buffer))) > 0) {
        char *line = strtok(buffer, "\n");
        if (!line || line[0] == '#') continue;
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");
        if (!key || !value) {
            ret = -1;
            break;
        }
        config_t config;
        config.key = key;
        config.value = value;
        pthread_rwlock_wrlock(&config_lock);
        configs[ret].key = key;
        configs[ret].value = value;
        ret++;
        pthread_rwlock_unlock(&config_lock);
    }

    close(fd);
    return ret;
}

int get_config(const char *key, char **value) {
    int i;
    for (i = 0; i < MAX_CONFIGS; i++) {
        if (strcmp(key, configs[i].key) == 0) {
            *value = configs[i].value;
            return 0;
        }
    }
    return -1;
}

int set_config(const char *key, const char *value) {
    int i;
    for (i = 0; i < MAX_CONFIGS; i++) {
        if (strcmp(key, configs[i].key) == 0) {
            pthread_rwlock_wrlock(&config_lock);
            free(configs[i].value);
            configs[i].value = strdup(value);
            pthread_rwlock_unlock(&config_lock);
            return 0;
        }
    }
    return -1;
}
```
