    public class ImageProcessor : IImageProcessor
    {
        private readonly ILogger<ImageProcessor> _logger;
        private readonly IServiceProvider _serviceProvider;

        public ImageProcessor(ILogger<ImageProcessor> logger, IServiceProvider serviceProvider)
        {
            _logger = logger;
            _serviceProvider = serviceProvider;
        }

        public async Task ProcessAsync(string imageUrl, string outputPath)
        {
            try
            {
                using var stream = await GetStreamFromCloudStorageAsync(imageUrl);
                if (stream == null) return;

                using var img = Image.Load<Rgba32>(stream);
                img.Mutate(x => x.Resize(new ResizeOptions { Size = new Size(50, 50), Mode = ResizeMode.Crop }));

                await SaveImageAsync(img, outputPath);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error processing image");
            }
        }

        private async Task<Stream> GetStreamFromCloudStorageAsync(string url)
        {
            var cloudStorageService = _serviceProvider.GetRequiredService<ICloudStorageService>();

            try
            {
                return await cloudStorageService.GetObjectAsync(url);
            }
            catch (Exception ex) when (ex is AmazonS3Exception || ex is StorageException || ex is GoogleCloudStorageException)
            {
                _logger.LogError(ex, "Error getting object from cloud storage");
                return null;
            }
        }

        private async Task SaveImageAsync(Image img, string outputPath)
        {
            var fileSystemService = _serviceProvider.GetRequiredService<IFileSystemService>();

            try
            {
                await fileSystemService.SaveStreamAsync(outputPath, img.ToStream());
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error saving image");
            }
        }
    }
}
