Here is a possible implementation of the C++ framework for managing distributed file storage:
```cpp
#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <chrono>
#include <thread>

// Define the data structure to represent a file in the system
struct File {
    std::string name;
    std::vector<char> content;
};

// Define the data structure to represent a file metadata entry
struct MetadataEntry {
    std::string filename;
    std::string hash;
    int size;
    bool is_deleted;
};

// Define the data structure to represent a replication policy
struct ReplicationPolicy {
    int num_replicas;
    int min_replicas;
    bool is_consistent;
    std::vector<std::string> dc_ids;
};

// Define the data structure to represent a distributed storage system
class DistributedStorageSystem {
public:
    // Constructor
    DistributedStorageSystem(const std::vector<std::string>& dc_ids) :
        dc_ids_(dc_ids), replication_policies_(), files_() {}

    // Add a new replication policy to the system
    void addReplicationPolicy(const ReplicationPolicy& policy) {
        replication_policies_.push_back(policy);
    }

    // Remove a replication policy from the system
    void removeReplicationPolicy(const std::string& policy_id) {
        for (auto it = replication_policies_.begin(); it != replication_policies_.end(); ++it) {
            if (it->id == policy_id) {
                replication_policies_.erase(it);
                break;
            }
        }
    }

    // Get the replication policy with the given ID
    const ReplicationPolicy* getReplicationPolicy(const std::string& policy_id) const {
        for (const auto& policy : replication_policies_) {
            if (policy.id == policy_id) {
                return &policy;
            }
        }
        return nullptr;
    }

    // Add a new file to the system
    void addFile(const std::string& filename, const std::vector<char>& content) {
        files_.insert({filename, File{filename, content}});
    }

    // Remove a file from the system
    bool removeFile(const std::string& filename) {
        return files_.erase(filename);
    }

    // Get the metadata entry for a given file
    const MetadataEntry* getMetadataEntry(const std::string& filename) const {
        auto it = files_.find(filename);
        if (it != files_.end()) {
            return &it->second;
        }
        return nullptr;
    }

    // Update the metadata entry for a given file
    void updateMetadataEntry(const std::string& filename, const MetadataEntry& entry) {
        auto it = files_.find(filename);
        if (it != files_.end()) {
            it->second.hash = entry.hash;
            it->second.size = entry.size;
            it->second.is_deleted = entry.is_deleted;
        } else {
            // TODO: handle the case where the file is not found in the system
        }
    }

private:
    std::vector<std::string> dc_ids_;
    std::unordered_map<std::string, ReplicationPolicy> replication_policies_;
    std::unordered_map<std::string, File> files_;
};

int main() {
    // Initialize the distributed storage system with the given data centers
    const std::vector<std::string> dc_ids = {"dc1", "dc2", "dc3"};
    DistributedStorageSystem system(dc_ids);

    // Add a replication policy to the system
    ReplicationPolicy policy;
    policy.id = "policy1";
    policy.num_replicas = 2;
    policy.min_replicas = 1;
    policy.is_consistent = true;
    policy.dc_ids = dc_ids;
    system.addReplicationPolicy(policy);

    // Add a file to the system
    std::string filename = "file1";
    std::vector<char> content = {'h', 'e', 'l', 'l', 'o'};
    system.addFile(filename, content);

    // Remove a replication policy from the system
    system.removeReplicationPolicy("policy1");

    // Get the metadata entry for a given file
    const MetadataEntry* entry = system.getMetadataEntry(filename);
    if (entry != nullptr) {
        std::cout << "File size: " << entry->size << std::endl;
        std::cout << "File hash: " << entry->hash << std::endl;
    }

    // Update the metadata entry for a given file
    MetadataEntry new_entry = {"file1", "hello", 5, false};
    system.updateMetadataEntry(filename, new_entry);

    return 0;
}
```
