        std::lock_guard<std::mutex> lock(m_mutex);
        m_loggers.push_back(logger);
    }

    // Unregister a logger from the system
    void unregisterLogger(ILogger* logger) {
        std::lock_guard<std::mutex> lock(m_mutex);
        for (auto it = m_loggers.begin(); it != m_loggers.end(); ++it) {
            if (*it == logger) {
                m_loggers.erase(it);
                return;
            }
        }
