        std::lock_guard<std::mutex> lock(m_mutex);
        // TODO: implement output format configuration for each logger
    }

    // Log a message to all registered loggers
    void log(const std::string& message) {
        std::lock_guard<std::mutex> lock(m_mutex);
        for (auto logger : m_loggers) {
            logger->log(message);
        }
    }

    // Stop logging and clean up all loggers
    void stop() {
        std::lock_guard<std::mutex> lock(m_mutex);
        m_stop = true;
        for (auto logger : m_loggers) delete logger;
        m_loggers.clear();
