    Logger* logger = new Logger();
    logger->registerLogger(new FileLogger("example.log"));
    logger->registerLogger(new RemoteLogger("http://centralized-logging.com/api/logs"));

    // Set the log level for each logger to INFO
    logger->setLogLevel(logger->getLoggerByName("FileLogger"), LogLevel::INFO);
    logger->setLogLevel(logger->getLoggerByName("RemoteLogger"), LogLevel::INFO);

    // Set the output format for each logger to JSON
    logger->setOutputFormat(logger->getLoggerByName("FileLogger"), "json");
    logger->setOutputFormat(logger->getLoggerByName("RemoteLogger"), "json");

    // Start logging and wait for new logs to arrive
    logger->start();
    while (true) {
        std::string message;
        if (!std::cin.eof()) {
            std::getline(std::cin, message);
            logger->log(message);
        } else {
            break;
        }
    }

    // Stop logging and clean up all loggers
    logger->stop();
    delete logger;
    return 0;
}
```
