    'spaCy': {'version': '2.3.5', 'model_name': 'en_core_web_sm'},
    'NLTK': {'version': '3.6.4', 'model_name': 'punkt'}
}

# Set up the NLP models
nlp_models = {}
for lib in nlp_libraries:
    nlp_models[lib] = None

# Set up the text analysis service
class TextAnalysisService():
    def __init__(self, nlp_library='spaCy'):
        self.nlp_library = nlp_library
        self.nlp_model = nlp_models[nlp_library]

    @lru_cache(maxsize=1024)
    def analyze_text(self, text):
        try:
            # Load the NLP model if it's not already loaded
            if self.nlp_model is None:
                self.load_nlp_model()

            # Analyze the text using the NLP library and model
            return self.nlp_library.analyze_text(self.nlp_model, text)
        except Exception as e:
            logger.exception('Error occurred during text analysis')
            raise e

    def load_nlp_model(self):
        try:
            # Load the NLP model from disk if it exists
            if os.path.exists(f'{self.nlp_library}_models/{self.nlp_models[self.nlp_library]}.json'):
                with open(f'{self.nlp_library}_models/{self.nlp_models[self.nlp_library]}.json', 'r') as f:
                    self.nlp_model = json.load(f)
            else:
                # Otherwise, download the model from a remote URL
                response = requests.get(f'{self.nlp_models[self.nlp_library]}.json')
                if response.status_code == 200:
                    with open(f'{self.nlp_library}_models/{self.nlp_models[self.nlp_library]}.json', 'wb') as f:
                        f.write(response.content)
                    self.nlp_model = json.load(open(f'{self.nlp_library}_models/{self.nlp_models[self.nlp_library]}.json', 'r'))
                else:
                    raise Exception('Failed to download NLP model')
        except Exception as e:
            logger.exception('Error occurred while loading NLP model')
            raise e

    def save_nlp_model(self):
        try:
            # Save the NLP model to disk
            with open(f'{self.nlp_library}_models/{self.nlp_models[self.nlp_library]}.json', 'wb') as f:
                json.dump(self.nlp_model, f)
        except Exception as e:
            logger.exception('Error occurred while saving NLP model')
            raise e

    def process_text_data(self, text_data):
        try:
            # Process the text data using the NLP library and model
            processed_data = []
            for text in text_data:
                processed_data.append(self.analyze_text(text))
            return processed_data
        except Exception as e:
            logger.exception('Error occurred during text processing')
            raise e

