        # Get the text data from the request body
        text_data = request.get_json()['text']

        # Instantiate the text analysis service with the requested NLP library
        text_analysis_service = TextAnalysisService(request.args.get('nlp_library'))

        # Process the text data using the text analysis service
        processed_data = text_analysis_service.process_text_data(text_data)

        # Return the processed data as a JSON response
        return jsonify({'processed_data': processed_data})
    except Exception as e:
