void *execute_js(const char *filepath, void *data) {
    // Check if the file exists
    if (!access(filepath, R_OK)) {
        printf("Error: %s does not exist\n", filepath);
        return NULL;
    }

    // Load the JavaScript file into a string
    char *js_string = readFile(filepath);

    // Create a new web page context for the JavaScript file
    void *ctx = nfa_create_web_page_context();

    // Execute the JavaScript file within the new context
    nfa_execute_javascript(ctx, js_string);

    // Free the JavaScript string and return the web page context
    free(js_string);
    return ctx;
}

// Define a function to dynamically load and execute multiple JavaScript files within a specified web page context
void *load_and_execute_js(const char **filepaths, void *data) {
    // Iterate over the list of file paths
    for (int i = 0; i < sizeof(filepaths); i++) {
        // Load and execute each JavaScript file within a new web page context
        nfa_crc_ind_pdu_t* pdu = execute_js(filepaths[i], data);

        // Add the newly created NFAPI_CRC_INDICATION_PDU_T structure to the list
