            nfa_crc_ind_list = realloc(nfa_crc_ind_list, (i + 1) * sizeof(nfa_crc_ind_pdu_t));
        }

        // Set the valid flag for the newly created NFAPI_CRC_INDICATION_PDU_T structure
        nfa_crc_ind_list[i].valid = 1;

        // Set the RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG fields for the newly created NFAPI_CRC_INDICATION_PDU_T structure
        nfa_crc_ind_list[i].rx_ue_information_tag = pdu->rx_ue_information_tag;
        nfa_crc_ind_list[i].rnti = pdu->rnti;
        nfa_crc_ind_list[i].crc_indication_rel8_tag = pdu->crc_indication_rel8_tag;
    }

    // Return the list of NFAPI_CRC_INDICATION_PDU_T structures
    return nfa_crc_ind_list;
}
