public class LoggingFramework {
  private static final Logger LOGGER = Logger.getLogger(LoggingFramework.class);
  private AWSLogs awsLogsClient;
  private Splunk splunkClient;
  private ElasticSearch elasticSearchClient;

  public LoggingFramework() {
    this.awsLogsClient = new AWSLogs();
    this.splunkClient = new Splunk();
    this.elasticSearchClient = new ElasticSearch();
  }

  public void log(String message, Level level) {
    // Log to local file system
