    };

    using SessionMap = std::map<std::string, std::shared_ptr<Session>>;

    // session cache for efficient lookup and management
    SessionMap sessions_;

    // callback function to handle authentication events
    SessionCallback onAuthEvent_;

public:
    AuthSystem() {
        // set the default session callback function
        onAuthEvent_ = std::bind(&SessionManager::onAuthEvent, this, std::placeholders::_1);
    }

    void login(const std::string& userId) {
        // create a new session for the user and cache it
        auto session = std::make_shared<Session>(Session{generateSessionId(), userId, true});
        sessions_.emplace(session->id, session);

        // notify the session manager of the login event
        onAuthEvent_(AuthEvent{AuthEventType::Login, userId});
    }

    void logout(const std::string& userId) {
        auto it = sessions_.find(userId);
        if (it != sessions_.end()) {
            // notify the session manager of the logout event
            onAuthEvent_(AuthEvent{AuthEventType::Logout, userId});

            // remove the session from the cache
            sessions_.erase(it);
        }
    }

    void activityUpdate(const std::string& userId) {
        auto it = sessions_.find(userId);
        if (it != sessions_.end()) {
            // notify the session manager of the activity update event
            onAuthEvent_(AuthEvent{AuthEventType::ActivityUpdate, userId});
        }
    }

private:
    std::string generateSessionId() {
        // generate a unique session ID using a cryptographically secure random number generator
        return "session_" + Utils::randomString(16);
    }
};

// LoggingSystem Library

#include <iostream>
#include <map>
#include <memory>
#include <string>
#include <vector>

class LoggingSystem {
public:
    using SessionCallback = std::function<void(const LogEvent&)>;

private:
    struct LogEntry {
        std::string message;
        time_t timestamp;
    };

    using LogMap = std::map<std::string, std::vector<LogEntry>>;

    // log cache for efficient lookup and management
    LogMap logs_;

    // callback function to handle log events
    SessionCallback onLogEvent_;

public:
    LoggingSystem() {
        // set the default session callback function
        onLogEvent_ = std::bind(&SessionManager::onLogEvent, this, std::placeholders::_1);
    }

    void log(const std::string& message) {
        auto it = logs_.find("session_id");
        if (it != logs_.end()) {
            // update the session's log entry with the new message and timestamp
            it->second.emplace_back(LogEntry{message, time(nullptr)});

            // notify the session manager of the log event
            onLogEvent_(LogEvent{message});
        }
    }

private:
    void onLogEvent(const LogEvent& event) {
        // handle the log event accordingly, e.g., update the session state based on the log message
    }
};
