pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Define function to allocate memory from pool
void *allocate_memory(size_t size) {
    void *ptr = NULL;

    // Acquire lock before allocating memory
    pthread_mutex_lock(&lock);

    // Check if memory pool is full
    if (sizeof(memory_pool) - sizeof(memory_pool[0]) <= 0) {
        printf("Memory pool is full. Unable to allocate memory.\n");
        return NULL;
    }

    // Allocate memory from pool
    ptr = &memory_pool[0];
    memset(ptr, 0, size);

    // Release lock after allocating memory
    pthread_mutex_unlock(&lock);

    return ptr;
}

// Define function to free memory from pool
void free_memory(void *ptr) {
    if (ptr == NULL) {
        return;
    }

    // Acquire lock before freeing memory
    pthread_mutex_lock(&lock);

    // Free memory from pool
    memset(ptr, 0, sizeof(ptr));

    // Release lock after freeing memory
    pthread_mutex_unlock(&lock);
}

