    if (record == NULL) {
        return -1;
    }

    // Acquire lock before deleting record
    pthread_mutex_lock(&lock);

    // Check if array is empty
    if (sizeof(record_array) <= 0) {
        printf("Record array is empty. Unable to delete record.\n");
        return -1;
    }

    // Delete record from array
    memmove(&record_array[0], &record_array[1], sizeof(record_array) - sizeof(record_array[0]));
    free_memory(record);

    // Release lock after deleting record
    pthread_mutex_unlock(&lock);

    return 0;
}

// Define function to update record in array
