    if (record == NULL) {
        return -1;
    }

    // Acquire lock before updating record
    pthread_mutex_lock(&lock);

    // Check if array is full
    if (sizeof(record_array) - sizeof(record_array[0]) <= 0) {
        printf("Record array is full. Unable to update record.\n");
        return -1;
    }

    // Update record in array
    memcpy(&record_array[sizeof(record_array) / sizeof(record_array[0])], record, sizeof(record));

    // Release lock after updating record
    pthread_mutex_unlock(&lock);

    return 0;
}

// Define function to search for record in array
nfapi_crc_indication_pdu_t *search_record(int key) {
    if (key < 0 || key >= 1024) {
        return NULL;
    }

    // Acquire lock before searching for record
    pthread_mutex_lock(&lock);

    // Search for record in array
    int i = 0;
    while (i < sizeof(record_array) / sizeof(record_array[0])) {
        if (record_array[i].value == key) {
            return &record_array[i];
        }
        i++;
    }

    // Release lock after searching for record
    pthread_mutex_unlock(&lock);

    return NULL;
}

// Define function to print records in array
