import hashlib
from collections import namedtuple
from concurrent.futures import ThreadPoolExecutor
from datetime import datetime
from enum import Enum
from typing import List

NetworkConnectionEvent = namedtuple("NetworkConnectionEvent", ["timestamp", "event_type", "data"])

class EventType(Enum):
    CONNECTED = 1
    DISCONNECTED = 2
    RECEIVED = 3
    SENT = 4

class NetworkConnectionManager:
    def __init__(self, api_urls: List[str], cache_size=500):
        self.api_urls = api_urls
        self.cache_size = cache_size
        self.event_log = []
        self.connection_status = {}
        self.executor = ThreadPoolExecutor(max_workers=10)

    def handle_event(self, event: NetworkConnectionEvent):
        timestamp = datetime.now().timestamp()
        event_type = EventType(event.event_type)
        data = event.data

        if event_type == EventType.CONNECTED:
            self._handle_connected_event(event)
        elif event_type == EventType.DISCONNECTED:
            self._handle_disconnected_event(event)
        elif event_type == EventType.RECEIVED:
            self._handle_received_event(event)
        elif event_type == EventType.SENT:
            self._handle_sent_event(event)

    def _handle_connected_event(self, event):
        timestamp = datetime.now().timestamp()
        api_url = event.data["api_url"]
        self.connection_status[api_url] = True
        self._log_event(EventType.CONNECTED, data={"api_url": api_url})

    def _handle_disconnected_event(self, event):
        timestamp = datetime.now().timestamp()
        api_url = event.data["api_url"]
        self.connection_status[api_url] = False
        self._log_event(EventType.DISCONNECTED, data={"api_url": api_url})

    def _handle_received_event(self, event):
        timestamp = datetime.now().timestamp()
        api_url = event.data["api_url"]
        self._log_event(EventType.RECEIVED, data={"api_url": api_url})

    def _handle_sent_event(self, event):
        timestamp = datetime.now().timestamp()
        api_url = event.data["api_url"]
        self._log_event(EventType.SENT, data={"api_url": api_url})

    def _log_event(self, event_type: EventType, data: dict):
        self.event_log.append((timestamp, event_type, data))
        if len(self.event_log) > self.cache_size:
            self._flush_event_log()

    def _flush_event_log(self):
        for api_url in self.connection_status:
            if not self.connection_status[api_url]:
                continue
            event = NetworkConnectionEvent(timestamp=datetime.now().timestamp(), event_type=EventType.RECEIVED, data={"api_url": api_url})
            self.executor.submit(self._handle_received_event, event)

    def get_event_log(self):
        return self.event_log
