// Thread-local storage for storing the OpenSSL context
__thread SSL_CTX* ssl_ctx;

// Initialize the cryptographic subsystem
int init_crypto_system(void) {
  // Create a new SSL_CTX instance
  ssl_ctx = SSL_CTX_new(TLS_method());
  if (!ssl_ctx) {
    ERR_print_errors_fp(stderr);
    return -1;
  }

  // Load the TLS certificates and key repositories
  int ret = SSL_CTX_use_certificate_file(ssl_ctx, "server.crt", SSL_FILETYPE_PEM);
  if (ret <= 0) {
    ERR_print_errors_fp(stderr);
    SSL_CTX_free(ssl_ctx);
    return -1;
  }

  ret = SSL_CTX_use_PrivateKey_file(ssl_ctx, "server.key", SSL_FILETYPE_PEM);
  if (ret <= 0) {
    ERR_print_errors_fp(stderr);
    SSL_CTX_free(ssl_ctx);
    return -1;
  }

  // Configure the context for client-side verification
  SSL_CTX_set_verify(ssl_ctx, SSL_VERIFY_PEER | SSL_VERIFY_FAIL_IF_NO_PEER_CERT, NULL);

  return 0;
}

// Generate a random value within the specified range
unsigned long generate_random(unsigned long min, unsigned long max) {
  // Create a new RAND_bytes instance
  RAND_bytes* rand = RAND_bytes_new(256);
  if (!rand) {
    ERR_print_errors_fp(stderr);
    return -1;
  }

  // Generate random bytes until we get the desired number of bytes
  while (RAND_bytes_num(rand) < max - min + 1) {}

  // Get the random value and free the instance
  unsigned long result = RAND_bytes_get(rand);
  RAND_bytes_free(rand);

  return result % (max - min + 1) + min;
}

// Generate a cryptographically secure hash of the input data
void generate_hash(const unsigned char* data, size_t length, unsigned char* hash) {
  // Create a new SHA256 instance
  SHA256_CTX* ctx = SHA256_CTX_new();
  if (!ctx) {
    ERR_print_errors_fp(stderr);
    return;
  }

  // Update the hash with the input data
  SHA256_Update(ctx, data, length);

  // Finalize the hash and store it in the output buffer
  unsigned char* hash_out = malloc(32);
  if (!hash_out) {
    ERR_print_errors_fp(stderr);
    SHA256_CTX_free(ctx);
    return;
  }
  SHA256_Final(hash_out, ctx);

  // Free the instance and copy the output buffer to the destination
  SHA256_CTX_free(ctx);
  memcpy(hash, hash_out, 32);

  free(hash_out);
}

// Encrypt the input data using AES-GCM with the specified key and nonce
void encrypt(const unsigned char* data, size_t length, const unsigned char* key, const unsigned char* nonce) {
  // Create a new AES-GCM instance
  EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
  if (!ctx) {
    ERR_print_errors_fp(stderr);
    return;
  }

  // Initialize the encryption context with the specified key and nonce
  int ret = EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, nonce);
  if (ret <= 0) {
    ERR_print_errors_fp(stderr);
    EVP_CIPHER_CTX_free(ctx);
    return;
  }

  // Update the encryption context with the input data and finalize it
  ret = EVP_EncryptUpdate(ctx, NULL, NULL, data, length);
  if (ret <= 0) {
    ERR_print_errors_fp(stderr);
    EVP_CIPHER_CTX_free(ctx);
    return;
  }
  ret = EVP_EncryptFinal_ex(ctx, NULL, NULL);
  if (ret <= 0) {
    ERR_print_errors_fp(stderr);
    EVP_CIPHER_CTX_free(ctx);
    return;
  }

  // Free the instance and copy the output buffer to the destination
  EVP_CIPHER_CTX_free(ctx);
}

// Decrypt the input data using AES-GCM with the specified key and nonce
void decrypt(const unsigned char* data, size_t length, const unsigned char* key, const unsigned char* nonce) {
  // Create a new AES-GCM instance
  EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
  if (!ctx) {
    ERR_print_errors_fp(stderr);
    return;
  }

  // Initialize the decryption context with the specified key and nonce
  int ret = EVP_DecryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, nonce);
  if (ret <= 0) {
    ERR_print_errors_fp(stderr);
    EVP_CIPHER_CTX_free(ctx);
    return;
  }

  // Update the decryption context with the input data and finalize it
  ret = EVP_DecryptUpdate(ctx, NULL, NULL, data, length);
  if (ret <= 0) {
    ERR_print_errors_fp(stderr);
    EVP_CIPHER_CTX_free(ctx);
    return;
  }
  ret = EVP_DecryptFinal_ex(ctx, NULL, NULL);
  if (ret <= 0) {
    ERR_print_errors_fp(stderr);
    EVP_CIPHER_CTX_free(ctx);
    return;
  }

  // Free the instance and copy the output buffer to the destination
  EVP_CIPHER_CTX_free(ctx);
}
```

### How do I use these functions?

To use these functions, you will need to include the `crypto.h` header file in your code, and link it with the `-lcrypto` library when building your project. You can then call the functions using their respective names, passing in the necessary arguments. For example:
```c
#include <crypto.h>

int main() {
    // Generate a random nonce for encryption
    unsigned char* nonce = generate_nonce(16);

    // Encrypt some data using AES-GCM with the specified key and nonce
    const unsigned char* plaintext = "Hello, world!";
    size_t plaintext_len = strlen((const char*)plaintext);
    unsigned char* ciphertext = malloc(plaintext_len + 16);
    encrypt(plaintext, plaintext_len, key, nonce, ciphertext);

    // Decrypt the encrypted data using AES-GCM with the specified key and nonce
    const unsigned char* ciphertext_enc = ciphertext;
    size_t ciphertext_len = strlen((const char*)ciphertext);
    unsigned char* plaintext_dec = malloc(plaintext_len + 16);
    decrypt(ciphertext_enc, ciphertext_len, key, nonce, plaintext_dec);

    // Free the nonce and output buffers
    free(nonce);
    free(ciphertext);
    free(plaintext_dec);

    return 0;
}
```
This code generates a random nonce for encryption, encrypts some data using AES-GCM with the specified key and nonce, decrypts it using the same parameters, and then frees the nonce and output buffers.']

