#define MASKING_RULE_SOCIAL_SECURITY_NUMBER "*********"

// Define the retry mechanisms with exponential backoff strategies for transient failures
#define RETRY_ATTEMPTS 3
#define RETRY_DELAY 1000 // milliseconds
#define RETRY_EXPONENTIAL_BACKOFF true

// Define the thread safety and efficient memory management features
#define THREAD_SAFETY true
#define MEMORY_MANAGEMENT true

// Define the health check feature for monitoring the logging service's availability
#define HEALTH_CHECK_ENABLED true
#define HEALTH_CHECK_INTERVAL 30 // seconds

// Define the notification service for system administrators in case of failures
#define NOTIFICATION_SERVICE_ENABLED true
#define NOTIFICATION_SERVICE_ADDRESS "https://example.com/notification"

// Define the performance optimization features for multi-threaded environment
#define PERFORMANCE_OPTIMIZATIONS true
#define MIN_THREAD_COUNT 2
#define MAX_THREAD_COUNT 10
#define THREAD_BALANCE_INTERVAL 30 // seconds

// Define the SLA for logging rate
