    // Initialize the logging module
    initializeLogging();
    // Set the logging level and context for the log messages
    int level = LOG_INFO;
    LogContext* context = (LogContext*) malloc(sizeof(LogContext));
    context->message = "Hello, World!";
    // Log a message with the given logging level and context
    log(level, context);
    return 0;
