from datetime import datetime
from typing import List, Tuple

# Define custom log levels
LEVELS = {
    "DEBUG": 10,
    "INFO": 20,
    "WARNING": 30,
    "ERROR": 40,
}

# Define custom log format
FORMAT = "%(asctime)s - %(levelname)s - %(message)s"

# Create logger instance with custom settings
logger = logging.getLogger("Logging System")
logger.setLevel(logging.DEBUG)
logger.addHandler(logging.StreamHandler())

class LoggingSystem:
    def __init__(self, lms_url: str):
        self.lms_url = lms_url
        self.loggers = {}  # dictionary of loggers by name

    def add_logger(self, logger_name: str):
        """Add a new logger to the system."""
        if logger_name in self.loggers:
            raise ValueError("Logger already exists")
        self.loggers[logger_name] = logging.getLogger(logger_name)
        self.loggers[logger_name].setLevel(logging.DEBUG)
        self.loggers[logger_name].addHandler(logging.StreamHandler())

    def remove_logger(self, logger_name: str):
        """Remove a logger from the system."""
        if logger_name not in self.loggers:
            raise ValueError("Logger does not exist")
        del self.loggers[logger_name]

    def get_logger(self, logger_name: str) -> logging.Logger:
        """Get a logger by name."""
        if logger_name in self.loggers:
            return self.loggers[logger_name]
        else:
            raise ValueError("Logger does not exist")

    def log(self, message: str, level: int, logger_names: List[str]) -> None:
        """Log a message to the specified loggers."""
        for name in logger_names:
            self.get_logger(name).log(level, message)

    def handle_error(self, error: Exception, logger_names: List[str]) -> None:
        """Handle an error by logging it to the specified loggers."""
        for name in logger_names:
            self.get_logger(name).exception("Exception occurred", exc_info=error)

    def format_message(self, message: str, level: int, timestamp: datetime) -> Tuple[str, int]:
        """Format a log message with the specified level and timestamp."""
        return (f"{timestamp.isoformat()} - {LEVELS[level]} - {message}", level)

