    logger1 = logging_system.add_logger("Logger 1")
    logger2 = logging_system.add_logger("Logger 2")
    logger3 = logging_system.add_logger("Logger 3")

    # Log messages with different levels to each logger
    logger1.debug("Debug message")
    logger2.info("Info message")
    logger3.warning("Warning message")
    logger3.error("Error message")

    # Handle an error by logging it to the specified loggers
    try:
        raise Exception("Example exception")
    except Exception as e:
        logging_system.handle_error(e, ["Logger 1", "Logger 2"])']

