// DynamicStringListManager.h

#ifndef DYNAMIC_STRING_LIST_MANAGER_H
#define DYNAMIC_STRING_LIST_MANAGER_H

#include <list>
#include <string>
#include <mutex>
#include <atomic>
#include <condition_variable>
#include <memory>
#include <future>

class DynamicStringListManager {
public:
    // Constructor and Destructor
    DynamicStringListManager();
    ~DynamicStringListManager();

    // Public Methods
    bool insertAfter(const std::string& target, const std::string& value);
    void append(const std::string& value);
    size_t size() const;
    bool empty() const;
    void clear();
    void log(const std::string& message) const;

private:
    // Private Methods
    void insertAfterImpl(const std::string& target, const std::string& value);
    void appendImpl(const std::string& value);
    bool checkIfTargetExists(const std::string& target) const;

    // Members
    std::list<std::string> list_;
    mutable std::mutex mutex_;
    std::condition_variable cv_;
    size_t size_;
    std::atomic<bool> isLoggingEnabled_;
    std::future<void> loggingFuture_;
    std::unique_ptr<ExternalLoggingService> externalLoggingService_;
};

#endif // DYNAMIC_STRING_LIST_MANAGER_H

// DynamicStringListManager.cpp

#include "DynamicStringListManager.h"

// External logging service interface
class ExternalLoggingService {
public:
    virtual void log(const std::string& message) = 0;
};

DynamicStringListManager::DynamicStringListManager() : size_(0), isLoggingEnabled_(false) {}

DynamicStringListManager::~DynamicStringListManager() {
    // Clean up logging service if needed
}

bool DynamicStringListManager::insertAfter(const std::string& target, const std::string& value) {
    bool result = false;

    // Acquire lock before modifying the list
    std::unique_lock<std::mutex> lock(mutex_);

    // Check if target exists in the list
    if (checkIfTargetExists(target)) {
        // Insert value after first occurrence of target
        insertAfterImpl(target, value);
        result = true;
    } else {
        // Append value to end of list
        appendImpl(value);
    }

    lock.unlock();

    return result;
}

void DynamicStringListManager::append(const std::string& value) {
    // Acquire lock before modifying the list
    std::unique_lock<std::mutex> lock(mutex_);

    appendImpl(value);

    lock.unlock();
}

size_t DynamicStringListManager::size() const {
    return size_;
}

bool DynamicStringListManager::empty() const {
    return size_ == 0;
}

void DynamicStringListManager::clear() {
    // Acquire lock before modifying the list
    std::unique_lock<std::mutex> lock(mutex_);

    list_.clear();
    size_ = 0;

    lock.unlock();
}

void DynamicStringListManager::log(const std::string& message) const {
    if (isLoggingEnabled_) {
        externalLoggingService_->log(message);
    } else {
        // Local logging is enabled, log to console or file
        // ...
    }
}

// Private methods
void DynamicStringListManager::insertAfterImpl(const std::string& target, const std::string& value) {
    auto it = list_.begin();
    for (; it != list_.end() && *it != target; ++it);
    if (it != list_.end()) {
        // Insert value after first occurrence of target
        it = list_.insert(++it, value);
    } else {
        // Target not found in the list, append to end
        list_.push_back(value);
    }
}

void DynamicStringListManager::appendImpl(const std::string& value) {
    list_.push_back(value);
}

bool DynamicStringListManager::checkIfTargetExists(const std::string& target) const {
    auto it = list_.begin();
    for (; it != list_.end() && *it != target; ++it);
    return it != list_.end();
}
