    return res.status(errors.NOT_FOUND.code).send({ message: errors.NOT_FOUND.message });
  }
  if (data.name && !validator.isString(data.name) || data.email && !validator.isEmail(data.email) || data.phoneNumber && !validator.isMobilePhone(data.phoneNumber)) {
    return res.status(errors.INVALID_DATA.code).send({ message: errors.INVALID_DATA.message });
  }

  // Retrieve user profile and perform update
  UserProfile.findOne({ _id: id })
    .then((profile) => {
      if (!profile) {
        return res.status(errors.NOT_FOUND.code).send({ message: errors.NOT_FOUND.message });
      }

      // Perform optimistic locking to prevent data anomalies
      const etag = req.headers['if-none-match'];
      if (etag && etag !== profile._id) {
        return res.status(errors.CONCURRENCY_ERROR.code).send({ message: errors.CONCURRENCY_ERROR.message });
      }

      // Update user profile and send response
      profile.name = data.name || profile.name;
      profile.email = data.email || profile.email;
      profile.phoneNumber = data.phoneNumber || profile.phoneNumber;
      return profile.save()
        .then(() => res.sendStatus(204))
        .catch((error) => {
          console.log(error);
          return res.status(errors.INVALID_DATA.code).send({ message: errors.INVALID_DATA.message });
        });
    })
    .catch((error) => {
      console.log(error);
      return res.status(errors.CONCURRENCY_ERROR.code).send({ message: errors.CONCURRENCY_ERROR.message });
    });
});

app.delete('/users/:id', (req, res) => {
  const id = req.params.id;

  // Validate input data
  if (!validator.isUUID(id)) {
    return res.status(errors.NOT_FOUND.code).send({ message: errors.NOT_FOUND.message });
  }

  // Retrieve user profile and perform deletion
  UserProfile.findOne({ _id: id })
    .then((profile) => {
      if (!profile) {
        return res.status(errors.NOT_FOUND.code).send({ message: errors.NOT_FOUND.message });
      }

      // Perform optimistic locking to prevent data anomalies
      const etag = req.headers['if-none-match'];
      if (etag && etag !== profile._id) {
        return res.status(errors.CONCURRENCY_ERROR.code).send({ message: errors.CONCURRENCY_ERROR.message });
      }

      // Delete user profile and send response
      return profile.deleteOne()
        .then(() => res.sendStatus(204))
        .catch((error) => {
          console.log(error);
          return res.status(errors.CONCURRENCY_ERROR.code).send({ message: errors.CONCURRENCY_ERROR.message });
        });
    })
    .catch((error) => {
      console.log(error);
      return res.status(errors.CONCURRENCY_ERROR.code).send({ message: errors.CONCURRENCY_ERROR.message });
    });
});

// Set up route handlers for system integration and error handling
app.post('/users', (req, res) => {
  // Handle external service authentication and billing integration
  const authService = request('https://auth.example.com/authenticate');
  if (!authService || !authService.success) {
    return res.status(errors.AUTHENTICATION_FAILURE.code).send({ message: errors.AUTHENTICATION_FAILURE.message });
  }

  // Integrate with billing service for subscription creation
  const billingService = request('https://billing.example.com/create-subscription');
  if (!billingService || !billingService.success) {
    return res.status(errors.CONCURRENCY_ERROR.code).send({ message: errors.CONCURRENCY_ERROR.message });
  }

  // Create new user profile and send response
  const user = new UserProfile();
  user.name = req.body.name;
  user.email = req.body.email;
  user.phoneNumber = req.body.phoneNumber;
  return user.save()
    .then(() => res.sendStatus(201))
    .catch((error) => {
      console.log(error);
      return res.status(errors.INVALID_DATA.code).send({ message: errors.INVALID_DATA.message });
    });
});

// Set up route handlers for error handling
app.use((req, res, next) => {
  const error = new Error('Not found');
  error.status = 404;
  next(error);
});

app.use((error, req, res, next) => {
  console.log(error);
  return res.status(errors.NOT_FOUND.code).send({ message: errors.NOT_FOUND.message });
});
```

This code uses the Express framework to set up a RESTful API for managing user profiles. The `/users` endpoint allows users to create new profiles, while the `/users/:id` endpoint allows updates and deletions of existing profiles.

The `app.put()` method is used to handle PUT requests to the `/users/:id` endpoint, which allows updating an existing profile. The input data is validated using the `validator` module to ensure that the request body contains the correct format for a user profile update. If the input data is invalid, an error message is returned with a 400 status code.

The `app.delete()` method is used to handle DELETE requests to the `/users/:id` endpoint, which allows deleting an existing profile. The input data is validated using the `validator` module in the same way as for the PUT request. If the input data is invalid, an error message is returned with a 400 status code.

The `app.post()` method is used to handle POST requests to the `/users` endpoint, which allows creating new profiles. The input data is validated using the `validator` module to ensure that the request body contains the correct format for a user profile creation. If the input data is invalid, an error message is returned with a 400 status code.

The `app.use()` method is used to handle errors that occur during the execution of the API. The first callback function checks if the error is not found and returns a 404 status code with a custom error message. The second callback function catches any other errors and returns a 500 status code with a generic error message.

This code uses the `request` module to handle external service authentication and billing integration, and the `errors` object to define custom error messages for various scenarios. The `validator` module is used to validate input data for create, update, and delete requests. The `UserProfile` model is used to manage user profiles in the database."]

