// Implement a regex-based parser to extract references to books from the Bible's Old Testament
fn parseOldTestamentReferences(text: &str) -> Vec<String> {
  let mut references = vec![];

  // Define regex pattern for matching whole words in the text
  let pattern = r"\b[A-Z][a-z]+\s\d+:\d+\b";

  // Use regex to extract matches from the text
  for cap in Regex::new(pattern).unwrap().captures_iter(text) {
    references.push(cap[0].to_string());
  }

  // Return the list of references found in the text
  return references;
}
