// Function to execute a command in the background and return its PID
int exec_cmd(char *command) {
    // Create a new process group for the command execution
    pid_t child_pid = fork();
    if (child_pid == 0) {
        // Execute the command in the background
        system(command);
        exit(0);
    } else {
        // Return the PID of the created process group
        return child_pid;
    }
}

