#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>
#include "traffic_event_manager.h"
#include "union_find.h"

struct traffic_event {
    uint64_t timestamp;
    enum event_type type;
    uint32_t device_id;
};

struct traffic_event_queue {
    struct traffic_event* events;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
    semaphore_t semaphore;
};

static struct traffic_event_queue* queue = NULL;
static union_find_data_structure* ufds = NULL;

void init_traffic_event_manager(size_t capacity) {
    // Initialize the event queue and union-find data structure.
    queue = malloc(sizeof(struct traffic_event_queue));
    memset(queue, 0, sizeof(struct traffic_event_queue));
    pthread_mutex_init(&queue->mutex, NULL);
    semaphore_init(&queue->semaphore, 0, capacity);
    queue->capacity = capacity;
    queue->size = 0;
    ufds = union_find_create(capacity);
}

void add_traffic_event(struct traffic_event* event) {
    // Add the event to the queue.
    pthread_mutex_lock(&queue->mutex);
    if (queue->size >= queue->capacity) {
        semaphore_wait(&queue->semaphore);
    }
    queue->events[queue->size] = *event;
    union_find_add(ufds, event->device_id, -1);
    queue->size++;
    pthread_mutex_unlock(&queue->mutex);
}

struct traffic_event* get_traffic_event() {
    // Get an event from the queue.
    struct traffic_event* event = NULL;
    pthread_mutex_lock(&queue->mutex);
    if (queue->size > 0) {
        event = &queue->events[--queue->size];
        union_find_add(ufds, event->device_id, -1);
    }
    semaphore_post(&queue->semaphore);
    pthread_mutex_unlock(&queue->mutex);
    return event;
}

void cleanup_traffic_event_manager() {
    // Clean up the event queue and union-find data structure.
    if (queue) {
        semaphore_destroy(&queue->semaphore);
        pthread_mutex_destroy(&queue->mutex);
        free(queue);
    }
    if (ufds) {
