```java
import java.util.concurrent.*;
import java.nio.file.*;
import java.security.*;
import org.apache.commons.lang3.StringUtils;

public class FileSystemCommandLineInterface {
  private final ExecutorService executor = Executors.newCachedThreadPool();
  private final Path rootPath;
  private final Set<File> files;
  private final Map<User, List<File>> userFiles;
  private final Map<String, String> config;

  public FileSystemCommandLineInterface(Path rootPath) {
    this.rootPath = rootPath;
    this.files = new HashSet<>();
    this.userFiles = new HashMap<>();
    this.config = new HashMap<>();
  }

  public void init() throws IOException {
    Files.walkFileTree(rootPath, new SimpleFileVisitor<>() {
      @Override
      public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) {
        files.add(file);
        return FileVisitResult.CONTINUE;
      }

      @Override
      public FileVisitResult preVisitDirectory(Path dir, BasicFileAttributes attrs) {
        return FileVisitResult.SKIP_SUBTREE;
      }
    });
  }

  public void addUser(User user) {
    userFiles.put(user, new ArrayList<>());
  }

  public void removeUser(User user) {
    userFiles.remove(user);
  }

  public void addFile(File file) {
    files.add(file);
  }

  public void removeFile(File file) {
    files.remove(file);
  }

  public List<File> getUserFiles(User user) {
    return userFiles.getOrDefault(user, Collections.emptyList());
  }

  public File getFile(String name) {
    return files.stream()
        .filter(file -> file.getName().equals(name))
        .findFirst()
        .orElseThrow(() -> new IllegalArgumentException("No such file"));
  }

  public void executeCommand(String command, User user) throws IOException {
    switch (command) {
      case "ls":
        getUserFiles(user).forEach(System.out::println);
        break;
      case "cd":
        System.out.println("Current directory is: " + rootPath.toAbsolutePath());
        break;
      default:
        throw new IllegalArgumentException("Unknown command");
    }
  }

  public void close() throws IOException {
    executor.shutdown();
    Files.walkFileTree(rootPath, new SimpleFileVisitor<>() {
      @Override
      public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) {
        files.remove(file);
        return FileVisitResult.CONTINUE;
      }
    });
  }
}
```
