    public class TripleDesEncryptionProvider : EncryptionProvider
    {
        private readonly byte[] _key;
        private readonly byte[] _iv;

        public TripleDesEncryptionProvider(byte[] key, byte[] iv)
        {
            _key = key ?? throw new ArgumentNullException(nameof(key));
            _iv = iv ?? throw new ArgumentNullException(nameof(iv));
        }

        public override string EncryptMessage(string message)
        {
            // Check if the key and IV are valid lengths
            if (_key.Length != 192 || _iv.Length != 8)
                throw new ArgumentException("Invalid key or IV length", nameof(message));

            // Create a new instance of the TripleDESCryptoServiceProvider class
            using (var des = new TripleDESCryptoServiceProvider())
            {
                // Set the key and IV on the DES provider object
                des.Key = _key;
                des.IV = _iv;

                // Create a memory stream to hold the encrypted data
                using (var ms = new MemoryStream())
                {
                    // Create a CryptoStream on the MemoryStream, with write access to the input stream
                    using (var cs = new CryptoStream(ms, des.CreateEncryptor(), CryptoStreamMode.Write))
                    {
                        // Write the input string to the crypto stream and flush it
                        var sw = new StreamWriter(cs);
                        sw.Write(message);
                        sw.Flush();

                        // Return the Base64-encoded encrypted data
                        return Convert.ToBase64String(ms.ToArray());
                    }
                }
            }
        }

        public override string DecryptMessage(string message)
        {
            // Check if the key and IV are valid lengths
            if (_key.Length != 192 || _iv.Length != 8)
                throw new ArgumentException("Invalid key or IV length", nameof(message));

            // Create a new instance of the TripleDESCryptoServiceProvider class
            using (var des = new TripleDESCryptoServiceProvider())
            {
                // Set the key and IV on the DES provider object
                des.Key = _key;
                des.IV = _iv;

                // Create a memory stream to hold the encrypted data
                using (var ms = new MemoryStream(Convert.FromBase64String(message)))
                {
                    // Create a CryptoStream on the MemoryStream, with write access to the input stream
                    using (var cs = new CryptoStream(ms, des.CreateDecryptor(), CryptoStreamMode.Read))
                    {
                        // Read the decrypted bytes from the crypto stream
                        byte[] buffer = new byte[1024];
                        var msr = new MemoryStream();
                        int read;

                        while ((read = cs.Read(buffer, 0, buffer.Length)) > 0)
                        {
                            msr.Write(buffer, 0, read);
                        }

                        // Return the decrypted message string
                        return Encoding.UTF8.GetString(msr.ToArray());
                    }
                }
            }
        }
    }
}
```
