    public class Processor
    {
        private readonly IConfiguration _configuration;
        private readonly IDataStorage _dataStorage;
        private readonly IDataTransformer _dataTransformer;
        private readonly IPipeline _pipeline;

        public Processor(IConfiguration configuration, IDataStorage dataStorage, IDataTransformer dataTransformer)
        {
            _configuration = configuration;
            _dataStorage = dataStorage;
            _dataTransformer = dataTransformer;
            _pipeline = new Pipeline();
        }

        public async Task Process(IList<string> inputStream, Action<IList<string>> outputHandler)
        {
            var pipeline = CreatePipeline();
            await pipeline.RunAsync(inputStream);
            var output = pipeline.Output;
            outputHandler(output);
        }

        public async Task RunAsync(IList<string> inputStream)
        {
            // Load configuration and initialize dependencies
            _configuration.Load();
            await _dataStorage.InitializeAsync();
            await _dataTransformer.InitializeAsync();

            var pipeline = CreatePipeline();
            await pipeline.RunAsync(inputStream);
            var output = pipeline.Output;

            // Persist output to data storage and invoke output handler
            await _dataStorage.SaveAsync(output);
        }

        private Pipeline CreatePipeline()
        {
            return new Pipeline(_configuration, _dataStorage, _dataTransformer);
        }
    }
}
