                    }
                }
                Err(_) => {
                    // Handle the error and continue
                }
            }
        }
        Ok(())
    }

    fn stop(&self) -> Result<(), LogAggregatorError> {
        self.consumer.lock().await?.stop()?;
        self.producer.lock().await?.stop()?;
        Ok(())
    }
