```java
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingDeque;
import java.util.concurrent.TimeUnit;

public class Cache {
    private static final int DEFAULT_MAX_SIZE = 1000000;
    private static final int DEFAULT_EXPIRATION_TIME = 3600; // in seconds
    private static final int DEFAULT_BATCH_SIZE = 5000;

    private BlockingQueue<CacheItem> cache;

    public Cache() {
        this.cache = new LinkedBlockingDeque<>();
    }

    public void put(Integer item) throws Exception {
        if (item == null || cache.size() >= DEFAULT_MAX_SIZE) {
            return;
        }

        CacheItem cacheItem = new CacheItem();
        cacheItem.setKey(item);
        cacheItem.setValue(item);

        boolean added = cache.offer(cacheItem, DEFAULT_EXPIRATION_TIME, TimeUnit.SECONDS);
        if (!added) {
            throw new Exception("Failed to add item to cache");
        }
    }

    public Integer get(Integer key) throws Exception {
        CacheItem cacheItem = cache.poll(DEFAULT_EXPIRATION_TIME, TimeUnit.SECONDS);
        if (cacheItem == null || cacheItem.getKey() != key) {
            return null;
        }

        return cacheItem.getValue();
    }

    public void remove(Integer key) throws Exception {
        boolean removed = cache.remove(key);
        if (!removed) {
            throw new Exception("Failed to remove item from cache");
        }
    }

    public int size() {
        return cache.size();
    }
}
```
