public class DataValidator {
    private static final int DEFAULT_MAX_CONCURRENT_VALIDATIONS = 100;
    private static final int DEFAULT_VALIDATION_TIMEOUT = 3000; // in milliseconds

    private ConcurrentHashMap<Integer, Boolean> validationResults;
    private BlockingQueue<Integer> validationQueue;

    public DataValidator() {
        this.validationResults = new ConcurrentHashMap<>();
        this.validationQueue = new LinkedBlockingDeque<>();
    }

    public void validate(List<Integer> items) throws Exception {
        if (items == null || items.isEmpty()) {
            return;
        }

        for (Integer item : items) {
            validationQueue.offer(item);
        }

        while (!validationQueue.isEmpty()) {
            Integer item = validationQueue.poll();
            if (item != null && !validationResults.containsKey(item)) {
                try {
                    Boolean isValid = validateItem(item);
                    validationResults.put(item, isValid);
                } catch (Exception e) {
                    logError("Failed to validate item " + item, e);
                }
            }
        }
    }

    public void removeValidationResult(Integer item) throws Exception {
        boolean removed = validationResults.remove(item);
        if (!removed) {
            throw new Exception("Failed to remove validation result for item " + item);
        }
    }

