uint32_t resolveHostnameToIp(const char *hostname, bool *dns_resolution_failed) {
    // Initialize variables
    struct addrinfo hints;
    struct addrinfo *result, *rp;
    int status;

    // Set DNS resolution failed flag to false by default
    *dns_resolution_failed = false;

    // Get address information for the hostname
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;
    status = getaddrinfo(hostname, NULL, &hints, &result);
    if (status != 0) {
        *dns_resolution_failed = true;
        return -1;
    }

    // Get the IP address from the result
    for (rp = result; rp != NULL; rp = rp->ai_next) {
        void *addr = &((struct sockaddr_in *)rp->ai_addr)->sin_addr;
        char ipstr[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, addr, ipstr, sizeof(ipstr));
        printf("IP address: %s\n", ipstr);
    }

    // Free memory allocated by getaddrinfo()
    freeaddrinfo(result);

    // Return the IP address as a uint32_t
    return inet_pton(AF_INET, ipstr, &ip);
}
