    int RNTI; // Unique identifier for the UE
    int CRCFLAG; // Randomly generated flag to avoid pattern collisions
} NFAPI_CRC_INDICATION_PDU_T;

// Function to generate and manage a list of NFAPI_CRC_INDICATION_PDU_T structures
void *crcIndicationManager(int N) {
    // Initialize variables
    int i, j, k = 0;
    NFAPI_CRC_INDICATION_PDU_T *pduList[N];
    for (i = 0; i < N; i++) {
        pduList[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pduList[i]) {
            printf("Error: Out of memory\n");
            exit(1);
        }
    }

    // Generate timestamps for each structure
    time_t now;
    struct tm *timeinfo = NULL;
    char timestamp[20];
    for (i = 0; i < N; i++) {
        now = time(NULL);
        timeinfo = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
        pduList[i]->timestamp = malloc(strlen(timestamp) + 1);
        if (!pduList[i]->timestamp) {
            printf("Error: Out of memory\n");
            exit(1);
        }
        strcpy(pduList[i]->timestamp, timestamp);
    }

    // Generate RNTIs for each structure
    for (i = 0; i < N; i++) {
        pduList[i]->RNTI = rand() % 1000 + 1;
    }

    // Generate CRCFLAGs for each structure randomly
    for (i = 0; i < N; i++) {
        k++;
        if (k >= 3) {
            pduList[i]->CRCFLAG = rand() % 10 + 1;
            k = 0;
        } else {
            pduList[i]->CRCFLAG = pduList[i-1]->CRCFLAG;
        }
    }

    // Integrate with external database to log creation details of each structure
    sqlite3 *db = NULL;
    char *zErrMsg = NULL;
    int rc = 0;
    db = sqlite3_open("crc_indication.db", &zErrMsg);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Error: %s\n", zErrMsg);
        sqlite3_close(db);
        return NULL;
    }
    for (i = 0; i < N; i++) {
        char *query = malloc(256);
        sprintf(query, "INSERT INTO crc_indication VALUES('%s', %d, %d)", pduList[i]->timestamp, pduList[i]->RNTI, pduList[i]->CRCFLAG);
        rc = sqlite3_exec(db, query, NULL, 0, &zErrMsg);
        if (rc != SQLITE_OK) {
            fprintf(stderr, "Error: %s\n", zErrMsg);
            sqlite3_close(db);
            return NULL;
        }
        free(query);
    }
    sqlite3_close(db);

    // Implement robust error handling to manage invalid RNTI values and duplicate CRCFLAG patterns
    for (i = 0; i < N; i++) {
        if (!pduList[i]->RNTI) {
            printf("Error: Invalid RNTI value\n");
            return NULL;
        }
        for (j = i + 1; j < N; j++) {
            if (pduList[i]->CRCFLAG == pduList[j]->CRCFLAG) {
                printf("Error: Duplicate CRCFLAG pattern\n");
                return NULL;
            }
        }
    }

    // Optimize for performance by minimizing memory allocations and ensuring thread safety
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);
    for (i = 0; i < N; i++) {
        pthread_mutex_lock(&lock);
        // Perform database operation in a single-threaded manner to avoid contention
        // Insert each structure into the database
        char *query = malloc(256);
        sprintf(query, "INSERT INTO crc_indication VALUES('%s', %d, %d)", pduList[i]->timestamp, pduList[i]->RNTI, pduList[i]->CRCFLAG);
        rc = sqlite3_exec(db, query, NULL, 0, &zErrMsg);
        if (rc != SQLITE_OK) {
            fprintf(stderr, "Error: %s\n", zErrMsg);
            pthread_mutex_unlock(&lock);
            return NULL;
        }
        free(query);
        pthread_mutex_unlock(&lock);
    }

    // Ensure that all allocated memory is freed when the function completes, even in the event of an error
    for (i = 0; i < N; i++) {
        free(pduList[i]->timestamp);
    }
    free(pduList);
}

