void flexible_data_retention_policies(struct TrafficEvent *event) {
    // Check if the event is older than 30 days
    if (time_elapsed(event->timestamp) > 30 * 24 * 60 * 60) {
        // If so, prune the event based on the user-defined retention policy
        prune_event(event);
    } else {
        // If not, keep the event and update its timestamp accordingly
        update_timestamp(event);
    }
}

void time_elapsed(int64_t timestamp) {
    // Calculate the time elapsed since the given timestamp in seconds
    return (time() - timestamp) / 1000;
}

void prune_event(struct TrafficEvent *event) {
    // Prune the event based on the user-defined retention policy
    remove(event);
}

void update_timestamp(struct TrafficEvent *event) {
    // Update the timestamp of the event to ensure it is not pruned later
    event->timestamp = time();
}

