// Define the structure for the resource bundle
typedef struct {
    char *identifier;
    char *name;
    json_t *metadata;
} ResourceBundle;

// Define the structure for the category and item
typedef struct {
    char *category;
    ResourceBundle *items;
} CategoryItem;

// Define the function to load a resource bundle from disk
int loadResourceBundle(const char *filePath, json_t **bundle) {
    // Open the file for reading
    FILE *fp = fopen(filePath, "r");
    if (fp == NULL) {
        return -1;
    }

    // Parse the JSON data from the file into a JSON object
    json_t *json = json_loadf(fp, 0, NULL);
    if (json == NULL) {
        fclose(fp);
        return -2;
    }

    // Close the file
    fclose(fp);

    // Create a new resource bundle struct and allocate memory for it
    ResourceBundle *bundle = malloc(sizeof(ResourceBundle));
    if (bundle == NULL) {
        json_decref(json);
        return -3;
    }

    // Parse the JSON object into the resource bundle struct
    bundle->identifier = json_string_value(json_object_get(json, "id"));
    bundle->name = json_string_value(json_object_get(json, "name"));
    bundle->metadata = json;

    // Return a pointer to the resource bundle struct
    return bundle;
}

// Define the function to unload a resource bundle from memory
void unloadResourceBundle(ResourceBundle *bundle) {
    // Free the memory allocated for the resource bundle struct
    free(bundle);
}

// Define the function to persist a resource bundle to disk
int persistResourceBundle(const char *filePath, ResourceBundle *bundle) {
    // Open the file for writing
    FILE *fp = fopen(filePath, "w");
    if (fp == NULL) {
        return -1;
    }

    // Serialize the resource bundle struct into JSON format and write it to the file
    json_t *json = json_object();
    json_object_set_new(json, "id", json_string(bundle->identifier));
    json_object_set_new(json, "name", json_string(bundle->name));
    json_object_set_new(json, "metadata", bundle->metadata);
    json_dumpf(json, fp, 0);

    // Close the file
    fclose(fp);

    // Return a success code
    return 0;
}

// Define the function to load a category and item from disk
int loadCategoryItem(const char *filePath, json_t **category, json_t **item) {
    // Open the file for reading
    FILE *fp = fopen(filePath, "r");
    if (fp == NULL) {
        return -1;
    }

    // Parse the JSON data from the file into a JSON object
    json_t *json = json_loadf(fp, 0, NULL);
    if (json == NULL) {
        fclose(fp);
        return -2;
    }

    // Close the file
    fclose(fp);

    // Create a new category and item structs and allocate memory for them
    CategoryItem *category = malloc(sizeof(CategoryItem));
    if (category == NULL) {
        json_decref(json);
        return -3;
    }

    // Parse the JSON object into the category and item structs
    category->category = json_string_value(json_object_get(json, "category"));
    category->items = malloc(sizeof(ResourceBundle));
    if (category->items == NULL) {
        free(category);
        return -4;
    }

    // Initialize the item struct and allocate memory for it
    ResourceBundle *item = malloc(sizeof(ResourceBundle));
    if (item == NULL) {
        free(category->items);
        free(category);
        json_decref(json);
        return -5;
    }

    // Parse the JSON object into the item struct
    item->identifier = json_string_value(json_object_get(json, "id"));
    item->name = json_string_value(json_object_get(json, "name"));
    item->metadata = json;

    // Return a pointer to the category and item structs
    return category;
}

// Define the function to unload a category and item from memory
