    json_object_set_new(json, "name", json_string(item->name));
    json_object_set_new(json, "metadata", item->metadata);
    json_dumpf(json, fp, 0);

    // Close the file
    fclose(fp);

    // Return a success code
    return 0;
}

// Define the function to manage a resource management system for large-scale JSON-based resource bundles
int resourceManagementSystem(const char *filePath, json_t **bundle) {
    // Load the resource bundle from disk and validate it
    loadResourceBundle(filePath, bundle);
    if (*bundle == NULL) {
        return -1;
    }

    // Create a new category and item structs and allocate memory for them
    CategoryItem *category = malloc(sizeof(CategoryItem));
    if (category == NULL) {
        unloadResourceBundle(*bundle);
        return -2;
    }

    // Initialize the category and item structs with default values
    strcpy(category->category, "default");
    category->items = malloc(sizeof(ResourceBundle));
    if (category->items == NULL) {
        free(category);
        unloadResourceBundle(*bundle);
        return -3;
    }

    // Initialize the item struct with default values
    strcpy(item->identifier, "default");
    strcpy(item->name, "default");
    item->metadata = json_object();
    if (item->metadata == NULL) {
        free(category->items);
        free(category);
        unloadResourceBundle(*bundle);
        return -4;
    }

    // Add the category and item to the resource bundle struct
    bundle->categories = malloc(sizeof(CategoryItem));
    if (bundle->categories == NULL) {
        free(item->metadata);
        free(category->items);
        free(category);
        unloadResourceBundle(*bundle);
        return -5;
    }

    // Return a success code
    return 0;
}
