import json

class ResourceManagementSystem:
    def __init__(self, file_path):
        self.file_path = file_path
        self.bundle = None

    def load(self):
        try:
            with open(self.file_path) as f:
                data = json.load(f)
                self.bundle = data
        except FileNotFoundError:
            print("ResourceBundle file not found.")
            return
        except json.JSONDecodeError:
            print("Invalid ResourceBundle file format.")
            return

    def save(self):
        try:
            with open(self.file_path, "w") as f:
                json.dump(self.bundle, f)
        except FileNotFoundError:
            print("ResourceBundle file not found.")
            return
        except json.JSONDecodeError:
            print("Invalid ResourceBundle file format.")
            return

    def add_category(self, category):
        if self.bundle is None:
            self.load()
        if self.bundle is None:
            return False
        self.bundle["categories"].append(category)
        return True

    def remove_category(self, category):
        if self.bundle is None:
            self.load()
        if self.bundle is None:
            return False
        self.bundle["categories"] = [cat for cat in self.bundle["categories"] if cat != category]
        return True

    def add_item(self, item):
        if self.bundle is None:
            self.load()
        if self.bundle is None:
            return False
        self.bundle["items"].append(item)
        return True

    def remove_item(self, item):
        if self.bundle is None:
            self.load()
        if self.bundle is None:
            return False
        self.bundle["items"] = [itm for itm in self.bundle["items"] if itm != item]
        return True
