@app.route("/resource", methods=["GET"])
def get_resource():
    # Get the requested resource from the cache or persistent storage
    resource_id = request.args.get("id")
    if resource_id in cache:
        return jsonify(cache[resource_id])
    else:
        row = sql_cursor.execute(f"SELECT * FROM resources WHERE id={resource_id};").fetchone()
        if row is None:
            # Return a 404 Not Found error
            return jsonify({"message": f"Resource {resource_id} not found."}), 404
        else:
            resource = {"id": row[0], "name": row[1], "metadata": row[2]}
            cache[resource_id] = resource
            return jsonify(cache[resource_id])

@app.route("/resource", methods=["POST"])
def create_resource():
    # Create a new resource and store it in the cache and persistent storage
    body = request.get_json()
    if not body:
        # Return a 400 Bad Request error
        return jsonify({"message": "Invalid JSON payload."}), 400
    else:
        resource = {"id": random.randint(1, 100), "name": body["name"], "metadata": body["metadata"]}
        cache[resource["id"]] = resource
        sql_cursor.execute(f"INSERT INTO resources (id, name, metadata) VALUES ({resource['id']}, '{resource['name']}', '{resource['metadata']}');")
        redis_client.set("resources", json.dumps(cache))
        return jsonify(resource), 201

@app.route("/resource", methods=["PUT"])
def update_resource():
    # Update a resource in the cache and persistent storage
    body = request.get_json()
    if not body:
        # Return a 400 Bad Request error
        return jsonify({"message": "Invalid JSON payload."}), 400
    else:
        resource_id = body["id"]
        if resource_id not in cache:
            # Return a 404 Not Found error
            return jsonify({"message": f"Resource {resource_id} not found."}), 404
        else:
            cache[resource_id]["name"] = body["name"]
            cache[resource_id]["metadata"] = body["metadata"]
            sql_cursor.execute(f"UPDATE resources SET name='{body['name']}', metadata='{body['metadata']}' WHERE id={resource_id};")
            redis_client.set("resources", json.dumps(cache))
            return jsonify({"message": f"Resource {resource_id} updated."}), 201

@app.route("/resource", methods=["DELETE"])
def delete_resource():
    # Delete a resource from the cache and persistent storage
    body = request.get_json()
    if not body:
        # Return a 400 Bad Request error
        return jsonify({"message": "Invalid JSON payload."}), 400
    else:
        resource_id = body["id"]
        if resource_id not in cache:
            # Return a 404 Not Found error
            return jsonify({"message": f"Resource {resource_id} not found."}), 404
        else:
            del cache[resource_id]
            sql_cursor.execute(f"DELETE FROM resources WHERE id={resource_id};")
            redis_client.set("resources", json.dumps(cache))
            return jsonify({"message": f"Resource {resource_id} deleted."}), 201

@app.route("/resource/categories", methods=["GET"])
def get_categories():
    # Get all categories from the cache or persistent storage
    if "categories" in cache:
        return jsonify(cache["categories"])
    else:
        rows = sql_cursor.execute("SELECT DISTINCT category FROM resources;").fetchall()
        categories = [row[0] for row in rows]
        cache["categories"] = categories
        redis_client.set("categories", json.dumps(cache))
        return jsonify(cache["categories"])

@app.route("/resource/items", methods=["GET"])
def get_items():
    # Get all items from the cache or persistent storage for a given category
    category = request.args.get("category")
    if "items" in cache and category in cache["categories"]:
        return jsonify(cache["items"][category])
    else:
        rows = sql_cursor.execute(f"SELECT * FROM resources WHERE category='{category}';").fetchall()
        items = [{"id": row[0], "name": row[1], "metadata": row[2]} for row in rows]
        cache["items"][category] = items
        redis_client.set("items", json.dumps(cache))
        return jsonify(cache["items"][category])

if __name__ == "__main__":
    app.run(debug=True)
