import java.util.concurrent.ConcurrentHashMap;

public class UserAuthSessionManager {
    private static final ConcurrentHashMap<String, UserAuthSession> sessions = new ConcurrentHashMap<>();

    public void addUserAuthSession(String userId) {
        UserAuthSession session = new UserAuthSession(userId);
        sessions.putIfAbsent(session.getUserId(), session);
    }

    public void removeUserAuthSession(String userId) {
        sessions.remove(userId);
    }

    public boolean hasUserAuthSession(String userId) {
        return sessions.containsKey(userId);
    }

    public UserAuthSession getUserAuthSession(String userId) {
        return sessions.get(userId);
    }
}
```
