#include <boost/asio.hpp>
#include <aws/s3.h>

using namespace std;
using namespace rapidjson;
using namespace boost::asio;
using namespace aws::s3;

// Constants and configuration
const int MAX_CONCURRENT_STREAMS = 100000;
const int BATCH_SIZE = 1000;
const int MIN_BATCH_INTERVAL = 1000; // milliseconds
const int MAX_BATCH_INTERVAL = 5000; // milliseconds
const string ENDPOINT = "https://example.com";
const string ACCESS_KEY = "<your access key>";
const string SECRET_KEY = "<your secret key>";
const string BUCKET_NAME = "<your bucket name>";

// Data structures for processing streams
struct Stream {
  int id;
  string device_id;
  chrono::system_clock::time_point timestamp;
  vector<float> data;
};

vector<Stream> streams;
mutex stream_lock;
condition_variable stream_cv;
bool shutdown = false;

// Function to process a single stream
void process_stream(int id, string device_id, chrono::system_clock::time_point timestamp, vector<float> data) {
  // Implement anomaly detection and machine learning models here
}

// Function to process batches of streams
void process_batch() {
  // Batch processing logic goes here
}

// Thread-safe function to add a new stream to the list of active streams
void add_stream(int id, string device_id, chrono::system_clock::time_point timestamp) {
  lock_guard<mutex> lock(stream_lock);
  streams.push_back({id, device_id, timestamp});
}

// Thread-safe function to remove an existing stream from the list of active streams
void remove_stream(int id) {
  lock_guard<mutex> lock(stream_lock);
  auto it = find(begin(streams), end(streams), [&](const Stream &s) { return s.id == id; });
  if (it != streams.end()) {
    streams.erase(it);
  }
}

// Main loop for processing streams in parallel
void process_streams() {
  while (!shutdown) {
    // Wait until there are streams to process
    unique_lock<mutex> lock(stream_lock);
    stream_cv.wait(lock, [&] { return !streams.empty(); });

    // Process each stream in parallel
    vector<future<void>> futures;
    for (const Stream &stream : streams) {
      int id = stream.id;
      string device_id = stream.device_id;
      chrono::system_clock::time_point timestamp = stream.timestamp;
      vector<float> data = stream.data;
      futures.push_back(async([=] { process_stream(id, device_id, timestamp, data); }));
    }

    // Wait for all threads to finish processing streams
    for (future<void> &f : futures) {
      f.wait();
    }

    // Remove processed streams from the list of active streams
    lock_guard<mutex> lock(stream_lock);
    for (auto it = streams.begin(); it != streams.end(); ++it) {
      Stream &stream = *it;
      if (chrono::system_clock::now() - stream.timestamp > chrono::milliseconds(MAX_BATCH_INTERVAL)) {
        remove_stream(stream.id);
      }
    }
  }
}

// Main function for the application
int main() {
  // Initialize the IoT device connection and message broker
  IoTDeviceConnection conn;
  MessageBroker broker;

  // Set up the data lake integration
  Aws::S3::Client s3_client(AWSAuthV2::Credentials(), AWSAuthV2::Region("us-east-1"), "s3");
  DataLakeIntegration data_lake(s3_client);

  // Set up the thread pool for parallel stream processing
  vector<thread> threads;
  for (int i = 0; i < MAX_CONCURRENT_STREAMS; ++i) {
    threads.push_back(thread(process_streams));
  }

  // Main loop for handling incoming data from the IoT devices
  while (!shutdown) {
    // Wait for incoming data from the IoT devices
    vector<IncomingMessage> messages = broker.receiveMessages();

    // Parse and process each incoming message
    for (const IncomingMessage &message : messages) {
      Document doc;
      if (doc.Parse(message.payload).HasParseError()) {
        continue;
      }

      int id = doc["id"].GetInt();
      string device_id = doc["device_id"].GetString();
      chrono::system_clock::time_point timestamp = doc["timestamp"].GetTimePoint<chrono::system_clock>();
      vector<float> data = doc["data"].GetArray().begin().ToList<float>();

      // Add the stream to the list of active streams
      add_stream(id, device_id, timestamp);

      // Process the stream in parallel
      for (int i = 0; i < BATCH_SIZE && !shutdown; ++i) {
        if (!streams.empty()) {
          process_batch();
        }
      }
    }
  }

  // Shut down the thread pool and data lake integration
  shutdown = true;
  for (thread &t : threads) {
    t.join();
  }

  return 0;
}
```
This code uses a `MessageBroker` to handle incoming messages from the IoT devices, parses each message using the `Document` class from RapidJSON, and adds the parsed stream to the list of active streams if it is valid. The main loop for handling incoming data then checks if there are any active streams that need to be processed, and processes each stream in parallel using a thread pool.

The code also includes an example integration with AWS S3 for storing the processed data lake, which can be used as needed.

This is just one possible way to implement the requirements you mentioned, and there are many other ways to do it. The important thing is to choose the approach that best fits your specific needs and constraints.']

