const asyncReduce = (inputArray) => {
  const apiCallsInProgress = {}; // tracks API calls in progress
  const apiCallCache = new Map(); // caches API responses for faster retrieval
  let processedElements = 0; // counts the number of elements processed
  let failedApiCalls = 0; // tracks failed API calls
  let lastProcessedElement = null; // tracks the last element processed
  let lastFailedApiCall = null; // tracks the last failed API call

  return new Promise((resolve, reject) => {
    asyncReduceInner(inputArray);

    function asyncReduceInner(array) {
      const apiCallsInProgressCount = Object.keys(apiCallsInProgress).length;
      if (apiCallsInProgressCount > 0) {
        // handle API calls in progress
        for (const url of Object.keys(apiCallsInProgress)) {
          const call = apiCallsInProgress[url];
          if (call.readyState === XMLHttpRequest.DONE && call.status !== 200) {
            failedApiCalls++;
            lastFailedApiCall = url;
            delete apiCallsInProgress[url]; // remove the failed API call from in progress
          } else if (call.readyState === XMLHttpRequest.DONE && call.status === 200) {
            apiCallCache.set(url, JSON.parse(call.responseText)); // cache the successful API response
            delete apiCallsInProgress[url]; // remove the successful API call from in progress
          }
        }
      } else if (array.length === 0) {
        // handle array length of 0
        resolve();
      } else {
        // handle the first element
        const currentElement = array[0];
        processedElements++;
        lastProcessedElement = currentElement;

        // make API call
        const url = getApiUrl(currentElement);
        if (!apiCallsInProgress[url]) {
          apiCallsInProgress[url] = new XMLHttpRequest();
        }
        apiCallsInProgress[url].onreadystatechange = () => {
          asyncReduceInner(array.slice(1)); // recursive call with the remaining elements in the array
        };
        apiCallsInProgress[url].open("GET", url, true);
        apiCallsInProgress[url].send();
      }
    }
  });
}

function getApiUrl(element) {
  return `https://example.com/api/data?id=${element}`;
}
