#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <assert.h>
#include <pthread.h>
#include <semaphore.h>
#include "json-c/json.h"

#define BUFFER_SIZE 1024 * 1024 * 5 // 5 MB buffer size for input/output files
#define MAX_THREADS 16
#define DEFAULT_LOGGING_LEVEL "INFO"
#define DEFAULT_INTERVAL 60 // seconds
#define DEFAULT_BUFFER_SIZE 1024 * 1024 * 1 // 1 MB buffer size for logging service
#define SKIP_LOGGING_ON_SUCCESS 0 // do not skip logging on successful completion

// data structures and constants
typedef enum { INFO, WARNING, ERROR } LoggingLevel;
typedef struct ThreadData {
    int threadId;
    char *inputFilePath;
    char *outputFilePath;
    json_t *config;
} ThreadData;

// functions and variables
void *processFile(void *data);
void transformAndWrite(FILE *in, FILE *out, json_t *config);
int getLoggingLevel(json_t *config);
int getInterval(json_t *config);
int getBufferSize(json_t *config);
int shouldSkipLoggingOnSuccess(json_t *config);
void logError(const char *message, int lineNum);
pthread_mutex_t loggingMutex = PTHREAD_MUTEX_INITIALIZER;
FILE *logFile = NULL;

int main(int argc, char **argv) {
    // validate input arguments and load configuration
    if (argc < 3 || !strcmp(argv[1], "-h") || !strcmp(argv[1], "--help")) {
        fprintf(stderr, "Usage: %s <input_file> <output_file> [config.json]\n", argv[0]);
        return 1;
    }
    char *inputFilePath = argv[1];
    char *outputFilePath = argv[2];
    json_t *config = NULL;
    if (argc >= 4) {
        config = json_load_file(argv[3], JSON_DECODE_ANY, &err);
        if (!config) {
            fprintf(stderr, "Error: failed to load configuration file %s\n", argv[3]);
            return 1;
        }
    } else {
        config = json_object(); // empty object
    }

    // initialize logging
    int loggingLevel = getLoggingLevel(config);
    char *loggingFilePath = NULL;
    if (json_object_get_boolean(config, "logging.enabled")) {
        loggingFilePath = json_string_value(json_object_get(config, "logging.file"));
    }
    if (!loggingLevel && !loggingFilePath) {
        fprintf(stderr, "Error: no logging configuration provided\n");
        return 1;
    }
    if (logFile = fopen(loggingFilePath, "a")) {
        setbuf(logFile, NULL); // disable buffering for unbuffered writes
    } else {
        fprintf(stderr, "Error: failed to open log file %s\n", loggingFilePath);
        return 1;
    }

    // initialize input and output files
    FILE *in = fopen(inputFilePath, "r");
    if (!in) {
        fprintf(stderr, "Error: failed to open input file %s\n", inputFilePath);
        return 1;
    }
    FILE *out = fopen(outputFilePath, "w");
    if (!out) {
        fprintf(stderr, "Error: failed to open output file %s\n", outputFilePath);
        return 1;
    }

    // initialize thread pool and semaphore
    pthread_mutex_lock(&loggingMutex);
    if (json_object_get_boolean(config, "multithreading")) {
        int numThreads = json_integer_value(json_object_get(config, "threads"));
        if (numThreads > 0) {
            pthread_t threads[MAX_THREADS];
            semaphore_t semaphore;
            semaphore_init(&semaphore, 1, 0);
            for (int i = 0; i < numThreads && fgets(buf, BUFFER_SIZE, in) != NULL; i++) {
                ThreadData *data = malloc(sizeof(ThreadData));
                data->threadId = i;
                data->inputFilePath = inputFilePath;
                data->outputFilePath = outputFilePath;
                data->config = config;
                pthread_create(&threads[i], NULL, processFile, (void *)data);
            }
            for (int i = 0; i < numThreads; i++) {
                pthread_join(threads[i], NULL);
            }
        } else {
            logError("Invalid number of threads: %d\n", argv[3]);
            return 1;
        }
    } else {
        processFile((void *)&data);
    }
    fclose(in);
    fclose(out);

    // flush and close log file
    pthread_mutex_unlock(&loggingMutex);
    fflush(logFile);
    fclose(logFile);

    return 0;
}

void *processFile(void *data) {
    ThreadData *threadData = (ThreadData *)data;
    int threadId = threadData->threadId;
    char *inputFilePath = threadData->inputFilePath;
    char *outputFilePath = threadData->outputFilePath;
    json_t *config = threadData->config;

    // initialize input and output files
    FILE *in = fopen(inputFilePath, "r");
    if (!in) {
        logError("Thread %d: failed to open input file %s\n", threadId);
        return NULL;
    }
    FILE *out = fopen(outputFilePath, "w");
    if (!out) {
        logError("Thread %d: failed to open output file %s\n", threadId);
        return NULL;
    }

    // process input file line by line
    char buf[BUFFER_SIZE];
    while (fgets(buf, BUFFER_SIZE, in) != NULL) {
        // apply transformations to the current line
        int lineNum = 1;
        json_t *transforms = json_object_get(config, "transforms");
        if (transforms && json_is_array(transforms)) {
            size_t transformCount = json_array_size(transforms);
            for (int i = 0; i < transformCount; i++) {
                json_t *transform = json_array_get(transforms, i);
                if (!transform) continue;
                const char *type = json_string_value(json_object_get(transform, "type"));
                if (strcmp(type, "replace") == 0) {
                    lineNum += replaceLine(buf, transform);
                } else if (strcmp(type, "trim") == 0) {
                    lineNum += trimLine(buf, transform);
                } else {
                    logError("Thread %d: invalid transformation type '%s'\n", threadId);
                }
            }
        }

        // write the transformed line to output file
        fprintf(out, "%s", buf);

        // log errors and warnings
        int errorCount = json_integer_value(json_object_get(config, "errors"));
        if (errorCount && strstr(buf, ERROR_TOKEN)) {
            pthread_mutex_lock(&loggingMutex);
            logError("Thread %d: Error on line %d: %s\n", threadId, lineNum, buf);
            pthread_mutex_unlock(&loggingMutex);
        } else {
            int warningCount = json_integer_value(json_object_get(config, "warnings"));
            if (warningCount && strstr(buf, WARNING_TOKEN)) {
                pthread_mutex_lock(&loggingMutex);
                logError("Thread %d: Warning on line %d: %s\n", threadId, lineNum, buf);
                pthread_mutex_unlock(&loggingMutex);
            }
        }
    }

    fclose(in);
    fclose(out);
    return NULL;
}

int replaceLine(char *buf, json_t *transform) {
    int lineNum = 1;
    const char *regex = json_string_value(json_object_get(transform, "regex"));
    const char *replacement = json_string_value(json_object_get(transform, "replacement"));
    if (!regex || !replacement) {
        logError("Invalid transformation parameters\n");
        return 0;
    }
    char *result = regexReplace(buf, regex, replacement);
    if (result) {
        strcpy(buf, result);
        free(result);
    }
    lineNum += countLines(buf);
    return lineNum;
}

int trimLine(char *buf, json_t *transform) {
    int lineNum = 1;
    const char *chars = json_string_value(json_object_get(transform, "chars"));
    if (!chars) {
        logError("Invalid transformation parameters\n");
        return 0;
    }
    size_t len = strlen(buf);
    while (len && strchr(chars, buf[len - 1])) {
        buf[len - 1] = '\0';
        len--;
    }
    lineNum += countLines(buf);
    return lineNum;
}

int countLines(char *str) {
    int lines = 0;
    for (const char *p = str; p; p++) {
        if (*p == '\n') {
            lines++;
        }
    }
    return lines + 1;
}

char *regexReplace(const char *subject, const char *pattern, const char *replacement) {
    int subjectLen = strlen(subject);
    int patternLen = strlen(pattern);
    int replacementLen = strlen(replacement);

    // Calculate the length of the result string.
    int resultLen = subjectLen;
    for (int i = 0; i < subjectLen - patternLen; i++) {
        if (strncmp(subject + i, pattern, patternLen) == 0) {
            resultLen += replacementLen - patternLen;
        }
    }

    // Allocate memory for the result string.
    char *result = malloc((resultLen + 1) * sizeof(char));
    if (!result) {
        return NULL;
    }

    // Copy the subject string to the result string.
    strcpy(result, subject);

    // Replace the patterns in the result string.
    for (int i = 0; i < subjectLen - patternLen; i++) {
        if (strncmp(subject + i, pattern, patternLen) == 0) {
            int replacementPos = i + strlen(result);
            strcpy(result + replacementPos, replacement);
            result[replacementPos + replacementLen] = '\0';
        }
    }

    return result;
}']

