// Define a class to represent a distributed dataset across multiple nodes
class DistributedDataset {
 public:
  // Constructor and destructor
  DistributedDataset(const std::string& name) : name_(name) {}
  ~DistributedDataset() = default;

  // Methods for adding, removing, and querying elements in the dataset across all nodes
  void add(const std::pair<double, double>& element) {
    // Distribute the element to all nodes in a round-robin fashion
    for (auto& node : nodes_) {
      node->add(element);
    }
  }

  void remove(const std::pair<double, double>& element) {
    // Remove the element from all nodes in a round-robin fashion
