    // Check if the element is present on any of the nodes in a round-robin fashion
    for (auto& node : nodes_) {
      if (node->contains(element)) {
        return true;
      }
    }
    return false;
  }

  // Method for retrieving all elements in the dataset across all nodes
  const std::vector<std::pair<double, double>>& getData() const {
    // Combine the data from all nodes into a single vector
    std::vector<std::pair<double, double>> data;
    for (auto& node : nodes_) {
      auto node_data = node->getData();
      data.insert(data.end(), node_data.begin(), node_data.end());
    }
    return data;
  }

 private:
  // Name of the distributed dataset
