#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>

#define MAX_RECORDS 10000000
#define MAX_KEY_LENGTH 64
#define MAX_PAYLOAD_LENGTH 1024

typedef struct {
    char key[MAX_KEY_LENGTH];
    char payload[MAX_PAYLOAD_LENGTH];
    time_t timestamp;
} Record;

typedef struct {
    int num_records;
    int capacity;
    Record* records;
} Database;

// Initialize the database with a given capacity.
void init_database(Database* db, int capacity) {
    assert(capacity > 0);

    // Allocate memory for the records array.
    db->records = (Record*) malloc(capacity * sizeof(Record));
    if (!db->records) {
        fprintf(stderr, "Failed to allocate memory for records.\n");
        exit(1);
    }

    // Initialize the number of records and capacity.
    db->num_records = 0;
    db->capacity = capacity;
}

// Destroy the database and free all allocated memory.
void destroy_database(Database* db) {
    if (db->records) {
        free(db->records);
    }
}

// Insert a new record into the database.
int insert_record(Database* db, char* key, time_t timestamp, char* payload) {
    // Check for a valid key and payload length.
    if (!key || !payload || strlen(key) > MAX_KEY_LENGTH || strlen(payload) > MAX_PAYLOAD_LENGTH) {
        return -1;
    }

    // Hash the key to determine the index where the record should be stored.
    int index = hash(key);

    // Check if there is already a record with the given key in the database.
    if (db->records[index].key[0]) {
        return -1;
    }

    // Copy the key and payload into the record structure.
    strcpy(db->records[index].key, key);
    db->records[index].timestamp = timestamp;
    strcpy(db->records[index].payload, payload);

    // Increment the number of records in the database.
    db->num_records++;

    return 0;
}

// Lookup a record by its key in the database.
int lookup_record(Database* db, char* key, Record* result) {
    // Check for a valid key and pointer to the result structure.
    if (!key || !result) {
        return -1;
    }

    // Hash the key to determine the index where the record should be stored.
    int index = hash(key);

    // Check if there is already a record with the given key in the database.
    if (!db->records[index].key[0]) {
        return -1;
    }

    // Copy the record structure from the database to the result pointer.
    memcpy(result, &db->records[index], sizeof(Record));

    return 0;
}

// Remove a record by its key from the database.
int remove_record(Database* db, char* key) {
    // Check for a valid key.
    if (!key) {
        return -1;
    }

    // Hash the key to determine the index where the record should be stored.
    int index = hash(key);

    // Check if there is already a record with the given key in the database.
    if (!db->records[index].key[0]) {
        return -1;
    }

    // Remove the record from the database by resetting its fields to empty strings.
    memset(&db->records[index], 0, sizeof(Record));

    // Decrement the number of records in the database.
    db->num_records--;

    return 0;
}

// Implement a simple hash function for the keys.
int hash(char* key) {
    int hash = 0;

    // Iterate through each character in the key and calculate the sum of its ASCII values.
    for (int i = 0; i < strlen(key); i++) {
        hash += (int) key[i];
    }

    return hash % MAX_RECORDS;
}
