Here is an example implementation of a modular, fault-tolerant, and highly available C++ library that manages a distributed key-value store for caching metadata related to user sessions in an online gaming platform:
```cpp
#include <iostream>
#include <map>
#include <string>
#include <vector>
#include <unordered_map>
#include <memory>
#include <mutex>
#include <thread>
#include <condition_variable>
#include <chrono>
#include <boost/asio.hpp>

class SessionCache {
public:
    SessionCache(const std::string& name) : name_(name) {}

    void addSession(const std::string& sessionId, const std::map<std::string, std::string>& metadata) {
        // Add the session to the cache
        sessions_[sessionId] = metadata;
    }

    bool getSession(const std::string& sessionId, std::map<std::string, std::string>& metadata) {
        // Check if the session exists in the cache
        auto it = sessions_.find(sessionId);
        if (it == sessions_.end()) {
            return false;
        }

        // Return the session metadata
        metadata = it->second;
        return true;
    }

    void removeSession(const std::string& sessionId) {
        // Remove the session from the cache
        sessions_.erase(sessionId);
    }

private:
    const std::string name_;
    std::unordered_map<std::string, std::map<std::string, std::string>> sessions_;
};

class SessionManager {
public:
    SessionManager() {}

    void addSession(const std::string& sessionId, const std::map<std::string, std::string>& metadata) {
        // Add the session to the cache
        auto it = caches_.find(sessionId);
        if (it == caches_.end()) {
            caches_[sessionId] = std::make_shared<SessionCache>(sessionId);
        }

        caches_[sessionId]->addSession(sessionId, metadata);
    }

    bool getSession(const std::string& sessionId, std::map<std::string, std::string>& metadata) {
        // Check if the session exists in any cache
        auto it = caches_.find(sessionId);
        if (it == caches_.end()) {
            return false;
        }

        // Return the session metadata
        metadata = it->second->getSession(sessionId);
        return true;
    }

    void removeSession(const std::string& sessionId) {
        // Remove the session from all caches
        for (auto it = caches_.begin(); it != caches_.end(); ++it) {
            if (it->second->getSession(sessionId)) {
                it->second->removeSession(sessionId);
            }
        }
    }

private:
    std::unordered_map<std::string, std::shared_ptr<SessionCache>> caches_;
};

class SessionClient {
public:
    SessionClient() {}

    bool getSession(const std::string& sessionId, std::map<std::string, std::string>& metadata) {
        // Send a GET request to the server
        auto response = boost::asio::post(boost::asio::use_service(boost::asio::io_context()), [this]() {
            return doGetSession(sessionId);
        });

        if (response) {
            metadata = response->metadata;
            return true;
        } else {
            return false;
        }
    }

private:
    std::map<std::string, std::shared_ptr<SessionCache>> caches_;

    struct SessionResponse {
        std::map<std::string, std::string> metadata;
    };

    std::shared_ptr<SessionResponse> doGetSession(const std::string& sessionId) {
        // Simulate a slow response from the server
        boost::this_thread::sleep_for(boost::chrono::seconds(1));

        // Return the session metadata
        auto it = caches_.find(sessionId);
        if (it == caches_.end()) {
            return nullptr;
        } else {
            return std::make_shared<SessionResponse>(it->second->getSession(sessionId));
        }
    }
};
