class NetworkEvent {
public:
    NetworkEvent(Timestamp timestamp, EventType event_type, PriorityLevel priority_level, const std::string& metadata) :
        timestamp_(timestamp), event_type_(event_type), priority_level_(priority_level), metadata_(metadata) {}

    Timestamp get_timestamp() const { return timestamp_; }
    EventType get_event_type() const { return event_type_; }
    PriorityLevel get_priority_level() const { return priority_level_; }
    std::string get_metadata() const { return metadata_; }

private:
    Timestamp timestamp_;
    EventType event_type_;
    PriorityLevel priority_level_;
    std::string metadata_;
};

class NetworkEventManager {
public:
    void add_event(const NetworkEvent& event) {
        // Use a mutex to protect the map from concurrent access
        std::lock_guard<std::mutex> lock(mutex_);

        events_.push_back(event);

        // Trigger notifications if necessary
        if (events_.size() >= min_notify_threshold_) {
            notify_listeners();
        }
    }

    void update_event(const NetworkEvent& event) {
        // Use a mutex to protect the map from concurrent access
        std::lock_guard<std::mutex> lock(mutex_);

        auto it = std::find(events_.begin(), events_.end(), event);
        if (it != events_.end()) {
            *it = event;
        } else {
            // Event not found, ignore update
        }
    }

    void delete_event(const NetworkEvent& event) {
        // Use a mutex to protect the map from concurrent access
        std::lock_guard<std::mutex> lock(mutex_);

        auto it = std::find(events_.begin(), events_.end(), event);
        if (it != events_.end()) {
            events_.erase(it);
        } else {
            // Event not found, ignore delete
        }
    }

    void add_listener(NetworkEventManagerListener* listener) {
        // Use a mutex to protect the list of listeners from concurrent access
        std::lock_guard<std::mutex> lock(mutex_);

        listeners_.push_back(listener);
    }

    void remove_listener(NetworkEventManagerListener* listener) {
        // Use a mutex to protect the list of listeners from concurrent access
        std::lock_guard<std::mutex> lock(mutex_);

        auto it = std::find(listeners_.begin(), listeners_.end(), listener);
        if (it != listeners_.end()) {
            listeners_.erase(it);
        } else {
            // Listener not found, ignore remove
        }
    }

private:
    void notify_listeners() {
        // Use a mutex to protect the list of listeners from concurrent access
        std::lock_guard<std::mutex> lock(mutex_);

        for (auto& listener : listeners_) {
            listener->notify(events_);
        }
    }

    // Minimum number of events to trigger notifications
    size_t min_notify_threshold_;

    // Map of events by timestamp
    std::map<Timestamp, NetworkEvent> events_;

    // List of listeners that want to be notified when events are added or deleted
    std::vector<NetworkEventManagerListener*> listeners_;
};
