public class IntegerService {
    private static final int MAX_INTEGERS = 1000;
    private static final int MEMORY_LIMIT = 2 * 1024 * 1024; // 2 GB
    private static final int NUM_THREADS = 5;

    private static final HashMap<Integer, Integer> cache = new HashMap<>();
    private static final LinkedBlockingQueue<Integer> queue = new LinkedBlockingQueue<>();

    public static void main(String[] args) throws InterruptedException {
        // Start threads for data source management and processing
        ThreadManager.startThreads();

        while (true) {
            Integer largestInteger = getLargestIntegerFromCache();
            if (largestInteger != null) {
                System.out.println("Largest integer: " + largestInteger);
            } else {
                Thread.sleep(1000); // Wait for 1 second before checking again
            }
        }
    }

    private static Integer getLargestIntegerFromCache() {
        if (cache.isEmpty()) {
            return null;
        }
        int largest = Integer.MIN_VALUE;
        for (Map.Entry<Integer, Integer> entry : cache.entrySet()) {
            if (entry.getValue() > largest) {
                largest = entry.getKey();
            }
        }
        return largest;
    }

    public static void addToCache(int integer) throws InterruptedException {
        // Check if the cache is full
        if (cache.size() >= MAX_INTEGERS) {
            throw new RuntimeException("Cache is full");
        }
        // Add the integer to the cache and the queue
        cache.put(integer, integer);
        queue.add(integer);
    }

    public static void processQueue() throws InterruptedException {
        // Process the queue in parallel using multiple threads
        for (int i = 0; i < NUM_THREADS; i++) {
            Thread thread = new Thread(() -> {
                try {
                    while (!queue.isEmpty()) {
                        Integer integer = queue.poll();
                        if (integer != null) {
                            // Add the integer to the cache
                            cache.put(integer, integer);
                        }
                    }
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            });
            thread.start();
        }
    }
}
