```
#include <iostream>
#include <vector>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <thread>
#include <unordered_map>

// Semaphore types
enum class ResourceType {
  CPU,
  MEMORY,
  DISK
};

// Node states
struct NodeState {
  std::vector<ResourceType> resources;
  std::chrono::time_point<std::chrono::system_clock> lastHeartbeat;
};

// Resource allocation algorithm parameters
const int NUM_RESOURCE_TYPES = 3;
const int RESOURCE_THRESHOLD[NUM_RESOURCE_TYPES] = {2, 10, 5};
const double LOAD_BALANCING_FACTOR = 0.75;

// Global variables
std::vector<NodeState> nodes;
std::mutex nodeMutex;
std::condition_variable nodeCondVar;
std::unordered_map<ResourceType, int> availableResources;

void updateAvailableResources() {
  // Update the available resources for each resource type
  std::lock_guard<std::mutex> lock(nodeMutex);
  for (auto& node : nodes) {
    for (int i = 0; i < NUM_RESOURCE_TYPES; ++i) {
      availableResources[static_cast<ResourceType>(i)] +=
          node.resources[i];
    }
  }
}

void allocateResource(const ResourceType& resourceType, int numRequested) {
  // Allocate the requested number of resources for the given resource type
  std::lock_guard<std::mutex> lock(nodeMutex);
  if (availableResources[resourceType] >= numRequested) {
    availableResources[resourceType] -= numRequested;
  } else {
    throw std::runtime_error("Not enough resources available");
  }
}

void releaseResource(const ResourceType& resourceType, int numReleased) {
  // Release the requested number of resources for the given resource type
  std::lock_guard<std::mutex> lock(nodeMutex);
  if (availableResources[resourceType] + numReleased <= RESOURCE_THRESHOLD[resourceType]) {
    availableResources[resourceType] += numReleased;
  } else {
    throw std::runtime_error("Resource limit exceeded");
  }
}

void addNode(const NodeState& newNode) {
  // Add a new node to the list of nodes and update the available resources
  std::lock_guard<std::mutex> lock(nodeMutex);
  nodes.push_back(newNode);
  updateAvailableResources();
}

void removeNode(const int& nodeIdx) {
  // Remove a node from the list of nodes and update the available resources
  std::lock_guard<std::mutex> lock(nodeMutex);
  if (nodeIdx >= nodes.size()) {
    throw std::runtime_error("Invalid node index");
  }
  nodes.erase(nodes.begin() + nodeIdx);
  updateAvailableResources();
}

void allocateResource(const int& nodeIdx, const ResourceType& resourceType, int numRequested) {
  // Allocate the requested number of resources for the given node and resource type
  std::lock_guard<std::mutex> lock(nodeMutex);
  if (nodes[nodeIdx].resources[static_cast<int>(resourceType)] >= numRequested) {
    nodes[nodeIdx].resources[static_cast<int>(resourceType)] -= numRequested;
  } else {
    throw std::runtime_error("Not enough resources available");
  }
}

void releaseResource(const int& nodeIdx, const ResourceType& resourceType, int numReleased) {
  // Release the requested number of resources for the given node and resource type
  std::lock_guard<std::mutex> lock(nodeMutex);
  if (nodes[nodeIdx].resources[static_cast<int>(resourceType)] + numReleased <= RESOURCE_THRESHOLD[static_cast<int>(resourceType)]) {
    nodes[nodeIdx].resources[static_cast<int>(resourceType)] += numReleased;
  } else {
    throw std::runtime_error("Resource limit exceeded");
  }
}

void handleExternalData() {
  // Handle external data sources for resource availability updates
  while (true) {
    // Check for new node connections and add them to the list of nodes
    if (hasNewNodeConnection()) {
      NodeState newNode;
      // Read new node information from the connection
      // ...
      addNode(newNode);
    }
    // Check for node disconnections and remove them from the list of nodes
    if (hasNodeDisconnection()) {
      int nodeIdx = getNodeIndexFromConnection();
      removeNode(nodeIdx);
    }
    // Update the available resources based on the new data
    updateAvailableResources();
  }
}

void handleResourceAllocation() {
  // Handle resource allocation requests
  while (true) {
    // Check for new allocation requests and allocate the requested resources
    if (hasNewAllocationRequest()) {
      int nodeIdx = getNodeIndexFromRequest();
      ResourceType resourceType = getResourceTypeFromRequest();
      int numRequested = getNumRequestedResourcesFromRequest();
      allocateResource(nodeIdx, resourceType, numRequested);
    }
    // Check for new release requests and release the requested resources
    if (hasNewReleaseRequest()) {
      int nodeIdx = getNodeIndexFromRequest();
      ResourceType resourceType = getResourceTypeFromRequest();
      int numReleased = getNumReleasedResourcesFromRequest();
      releaseResource(nodeIdx, resourceType, numReleased);
    }
  }
}

int main() {
  // Initialize the global variables and start threads for handling external data and resource allocation
  initializeGlobalVariables();
  std::thread handleExternalDataThread(handleExternalData);
  std::thread handleResourceAllocationThread(handleResourceAllocation);
  // Wait for the threads to finish
  handleExternalDataThread.join();
  handleResourceAllocationThread.join();
}
```
This implementation uses a vector of `NodeState` structures to store information about each node in the distributed system, and a map of available resources to keep track of which nodes have which resources available. The `handleExternalData()` function is used to handle external data sources for resource availability updates, and the `handleResourceAllocation()` function is used to handle resource allocation requests. Both functions use locking mechanisms to ensure thread-safety when accessing the global variables.

The main function initializes the global variables and starts two threads for handling external data and resource allocation. The `handleExternalData()` function runs in an infinite loop, checking for new node connections and disconnections and updating the available resources accordingly. The `handleResourceAllocation()` function also runs in an infinite loop, checking for new allocation requests and releasing the requested resources. Both functions use locking mechanisms to ensure thread-safety when accessing the global variables.

This is a basic example of how a distributed system could be implemented using threads and locks to handle external data sources and resource allocation requests in a concurrent and efficient manner. The specific implementation details would depend on the requirements of the distributed system, such as the type of resources being managed, the frequency of updates, and the desired level of performance.']

