    Cache::Value cached_value = ctx.cache_value;
    if (cached_value) {
      // Found in cache, update expiration time and return
      auto& cache_entry = cached_value->as<CacheEntry>();
      cache_entry.expires = std::chrono::steady_clock::now() + Config.cache_timeout;
      return;
    } else {
      // Cache miss, retrieve from IDP and update cache
      auto idp_session = ctx.session.get();
      if (idp_session) {
        auto cache_entry = std::make_shared<CacheEntry>(idp_session);
        ctx.cache->put(ctx.cache_key, cache_entry);
        return;
      } else {
        std::cout << "Failed to retrieve session information from IDP." << std::endl;
        return;
      }
    }
  } else {
