    if (idp_session) {
      auto cache_entry = std::make_shared<CacheEntry>(idp_session);
      ctx.cache->put(ctx.cache_key, cache_entry);
      return;
    } else {
      std::cout << "Failed to retrieve session information from IDP." << std::endl;
      return;
    }
  }
}

// Cache entry structure
struct CacheEntry {
  IdentityProvider::Session session;
  int64_t expires = 0; // cache entry timeout (epoch seconds)
};

// Cache eviction policy implementation
class Evictor : public Cache::EvictionPolicy {
public:
  void evict(Cache::Key& key, Cache::Value& value) override {
    auto& cache_entry = value->as<CacheEntry>();
    if (cache_entry.expires < std::chrono::steady_clock::now()) {
      // Remove expired entry from cache
      ctx.cache->remove(key);
    } else {
      // Move to front of LRU list
      ctx.cache->move_to_front(key);
    }
  }
};

// Request processing pipeline implementation
class Processor : public Cache::Processor<RequestContext, void> {
public:
  void process(const RequestContext& ctx) override {
    // Step 1: Validate user token and device ID with IDP
    if (ctx.session.isValid()) {
      std::cout << "User token and device ID are valid." << std::endl;
    } else {
