// Define a struct to hold the parsed data
typedef struct {
    int num_items;
    void **items;
} resource_bundle_t;

// Global variables to manage memory and synchronization
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static resource_bundle_t *bundle = NULL;
static int error_code = 0;

int loadResourceBundle(const char *filePath, void **bundle, size_t *numItems, int *error_code) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&lock);

    // Check if a bundle has already been loaded
    if (bundle != NULL) {
        // If so, free the existing bundle and reset variables
        freeResourceBundle();
    }

    // Parse the JSON file using the JSON parser library
    json_t *json = parseJSONFile(filePath);
    if (json == NULL) {
        error_code = -1; // Indicate an error occurred during parsing
        pthread_mutex_unlock(&lock);
        return -1;
    }

    // Allocate memory for the parsed data
    bundle = malloc(sizeof(resource_bundle_t));
    if (bundle == NULL) {
        error_code = -2; // Indicate an error occurred during memory allocation
        pthread_mutex_unlock(&lock);
        return -2;
    }

    // Initialize the bundle and parse the JSON data
    bundle->num_items = 0;
    bundle->items = NULL;
    json_t *json_item = NULL;
    while ((json_item = json_array_next(json)) != NULL) {
        // Parse each item in the array and add it to the bundle
        void *item = parseJSONItem(json_item);
        if (item == NULL) {
            error_code = -3; // Indicate an error occurred during parsing of a single item
            pthread_mutex_unlock(&lock);
            return -3;
        }
        bundle->items = realloc(bundle->items, sizeof(void *) * (bundle->num_items + 1));
        if (bundle->items == NULL) {
            error_code = -4; // Indicate an error occurred during memory allocation for the item list
            pthread_mutex_unlock(&lock);
            return -4;
        }
        bundle->items[bundle->num_items] = item;
        bundle->num_items++;
    }

    // Free the JSON data and unlock the mutex
    json_decref(json);
    pthread_mutex_unlock(&lock);

    // Return the parsed data and the number of items in the bundle
    *bundle = bundle;
    *numItems = bundle->num_items;
    return 0;
}

void freeResourceBundle() {
    // Free any memory allocated for the bundle and reset variables
    if (bundle != NULL) {
        for (int i = 0; i < bundle->num_items; i++) {
            free(bundle->items[i]);
        }
        free(bundle->items);
        bundle = NULL;
    }
}
