class UserSessionManager {
 public:
  // Constructor
  UserSessionManager();

  // Methods for creating, updating, and retrieving user sessions
  void createUserSession(std::string userId, std::string deviceInfo, std::string geolocation);
  void updateUserSession(std::string sessionId, std::string log);
  const UserSession* getUserSession(std::string sessionId) const;

  // Getters for total number of active sessions and inactive sessions
  size_t getNumActiveSessions() const;
  size_t getNumInactiveSessions() const;

 private:
  // Map from session ID to UserSession object
  std::unordered_map<std::string, UserSession> userSessions_;

  // Vector of inactive sessions (sorted by creation time)
  std::vector<std::pair<std::string, std::chrono::system_clock::time_point>> inactiveSessions_;

  // Mutex for synchronizing access to the session data
  mutable std::mutex mutex_;
};
```

```
// UserSessionManager.cpp
#include <chrono>

void UserSessionManager::createUserSession(std::string userId, std::string deviceInfo, std::string geolocation) {
  // Create a new UserSession object with the given user ID, device information, and geolocation
  auto session = std::make_unique<UserSession>(userId, deviceInfo, geolocation);

  // Add the session to the map of active sessions
  mutex_.lock();
  userSessions_.emplace(session->getSessionId(), std::move(session));
  mutex_.unlock();
}

void UserSessionManager::updateUserSession(std::string sessionId, std::string log) {
  // Get the UserSession object for the given session ID
  auto session = getUserSession(sessionId);
  if (session == nullptr) {
    return;
  }

  // Add the activity log to the session
  mutex_.lock();
  session->addActivityLog(log);
  mutex_.unlock();
}

const UserSession* UserSessionManager::getUserSession(std::string sessionId) const {
  // Check if the session ID is in the map of active sessions
  auto it = userSessions_.find(sessionId);
  if (it != userSessions_.end()) {
    return &it->second;
  }

  // If not, check if the session ID is in the vector of inactive sessions
  auto it2 = std::lower_bound(inactiveSessions_.begin(), inactiveSessions_.end(), sessionId);
  if (it2 != inactiveSessions_.end() && it2->first == sessionId) {
    return &it2->second;
  }

  // If the session ID is not found, return nullptr
  return nullptr;
}

size_t UserSessionManager::getNumActiveSessions() const {
  mutex_.lock();
  auto numActive = userSessions_.size();
  mutex_.unlock();
  return numActive;
}

size_t UserSessionManager::getNumInactiveSessions() const {
  mutex_.lock();
  auto numInactive = inactiveSessions_.size();
  mutex_.unlock();
  return numInactive;
}
