#include <mutex>

class SessionPruner {
 public:
  // Constructor
  SessionPruner(UserSessionManager* sessionManager);

  // Method for pruning inactive sessions according to the user-defined rules or external alerts
  void pruneInactiveSessions();

 private:
  // UserSessionManager object
  UserSessionManager* sessionManager_;

  // Mutex for synchronizing access to the session data
  mutable std::mutex mutex_;
};
