Here is an example of a modular C-based video processing service that integrates with a legacy video encoding library and supports batch processing for large-scale video conversion tasks:
```
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <math.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <errno.h>
#include <pthread.h>
#include <semaphore.h>
#include <queue>
#include <mutex>
#include <condition_variable>
#include "video_converter.h"
#include "legacy_encoding_library.h"

// Global variables for managing concurrent processing of videos
std::queue<VideoConversionJob*> video_jobs;
std::mutex job_lock;
std::condition_variable job_cv;
int num_active_jobs = 0;

// Function to filter transactions based on a set of criteria: transaction age, number of transactions in the past 3 seconds, and transaction's weighted sum
void filterTransactions(VideoConversionJob* job) {
    // Calculate the current time
    struct timespec current_time;
    clock_gettime(CLOCK_REALTIME, &current_time);

    // Calculate the age of the transaction in seconds
    long transaction_age = (long)(current_time.tv_sec - job->timestamp) / 1000;

    // Calculate the number of transactions in the past 3 seconds
    int num_transactions = 0;
    for (VideoConversionJob* other_job : video_jobs) {
        long other_transaction_age = (long)(current_time.tv_sec - other_job->timestamp) / 1000;
        if (other_transaction_age < 3) {
            num_transactions++;
        }
    }

    // Calculate the weighted sum of the transactions
    float weighted_sum = 0;
    for (VideoConversionJob* other_job : video_jobs) {
        long other_transaction_age = (long)(current_time.tv_sec - other_job->timestamp) / 1000;
        if (other_transaction_age < 3) {
            weighted_sum += pow(2, num_transactions) * other_job->weight;
        }
    }

    // Update the metrics and return the maximum weighted sum
    job->num_transactions = num_transactions;
    job->weighted_sum = weighted_sum;
    return weighted_sum;
}

// Function to convert a video file using the legacy encoding library
void convertVideo(VideoConversionJob* job) {
    // Create a new thread for converting the video file
    pthread_t converter_thread;
    if (pthread_create(&converter_thread, NULL, &convertVideoFile, job)) {
        printf("Error creating conversion thread\n");
        return;
    }

    // Wait for the conversion to complete and update the job status
    pthread_join(converter_thread, NULL);
    job->status = COMPLETED;
}

// Function to convert a video file using the legacy encoding library
void* convertVideoFile(void* job) {
    VideoConversionJob* my_job = (VideoConversionJob*)job;
    LegacyEncodingLibrary::encodeVideo(my_job->filepath, my_job->output_filename);
    return NULL;
}

// Function to handle concurrent processing of videos
void handleVideoConversion(VideoConversionJob* job) {
    // Filter the transaction based on the criteria
    filterTransactions(job);

    // Convert the video file using the legacy encoding library
    convertVideo(job);
}

// Function to monitor and log resource usage
void monitorResources() {
    struct timespec current_time;
    clock_gettime(CLOCK_REALTIME, &current_time);

    // Get the CPU usage
    long cpu_usage = 0;
    FILE* stat_file = fopen("/proc/stat", "r");
    if (stat_file) {
        char buffer[1024];
        while (fgets(buffer, sizeof(buffer), stat_file)) {
            if (strncmp(buffer, "cpu ", 4) == 0) {
                cpu_usage = atoi(buffer + 4);
            }
        }
        fclose(stat_file);
    }

    // Get the memory usage
    struct sysinfo mem_info;
    if (sysinfo(&mem_info) == 0) {
        long free_memory = mem_info.freeram / 1024 / 1024;
        long total_memory = mem_info.totalram / 1024 / 1024;
    }

    // Get the I/O usage
    struct statvfs disk_stats;
    if (statvfs("/", &disk_stats) == 0) {
        long free_disk = disk_stats.f_bavail / 1024 / 1024;
        long total_disk = disk_stats.f_blocks / 1024 / 1024;
    }
}

// Function to handle errors and provide detailed logs for troubleshooting
void handleError(VideoConversionJob* job, const char* message) {
    // Log the error message
    printf("Error: %s\n", message);

    // Update the job status to FAILED
    job->status = FAILED;
}

// Function to start the video processing service
void startService() {
    // Initialize the queue for video jobs
    video_jobs = std::queue<VideoConversionJob*>();

    // Start a thread for handling concurrent processing of videos
    pthread_t handler_thread;
    if (pthread_create(&handler_thread, NULL, &handleVideoConversion, NULL)) {
        printf("Error creating video conversion handler\n");
        return;
    }

    // Start a thread for monitoring and logging resource usage
    pthread_t monitor_thread;
    if (pthread_create(&monitor_thread, NULL, &monitorResources, NULL)) {
        printf("Error creating resource monitoring handler\n");
        return;
    }

    // Start a thread for handling errors and providing detailed logs
    pthread_t error_handler_thread;
    if (pthread_create(&error_handler_thread, NULL, &handleError, NULL)) {
        printf("Error creating error handler\n");
        return;
    }
}

// Function to stop the video processing service
void stopService() {
    // Terminate the threads for handling concurrent processing of videos
    pthread_cancel(handler_thread);
    pthread_join(handler_thread, NULL);

    // Terminate the threads for monitoring and logging resource usage
    pthread_cancel(monitor_thread);
    pthread_join(monitor_thread, NULL);

    // Terminate the threads for handling errors and providing detailed logs
    pthread_cancel(error_handler_thread);
    pthread_join(error_handler_thread, NULL);
}
```

This code is a simple example of how to create a video processing service using C++. The service uses a thread-safe queue for handling concurrent requests and monitors the CPU usage and memory usage for troubleshooting purposes. The `handleVideoConversion` function filters the transaction based on the criteria and converts the video file using the legacy encoding library. The `monitorResources` function gets the CPU usage, memory usage, and I/O usage of the system and logs it to a file. The `handleError` function handles errors by logging detailed error messages and updating the job status to FAILED. The `startService` function starts the threads for handling concurrent processing of videos, monitoring and logging resource usage, and handling errors and providing detailed logs. The `stopService` function stops the service by terminating the threads.

This code is just an example and may need to be modified to meet specific requirements. Additionally, it is important to test the performance and scalability of this code on a specific hardware configuration before deploying it in production.']

