private Type queryInternalDB(String type) {
    // Query the internal database for the specified type
    String sql = "SELECT name, weaknesses, resistances, immunities FROM types WHERE name = ?";
    PreparedStatement ps = conn.prepareStatement(sql);
    ps.setString(1, type);
    ResultSet rs = ps.executeQuery();

    // If the type is found in the internal DB, return it
    if (rs.next()) {
        Type t = new Type();
        t.setName(rs.getString("name"));
        t.setWeaknesses(Arrays.asList(rs.getString("weaknesses").split(",")));
        t.setResistances(Arrays.asList(rs.getString("resistances").split(",")));
        t.setImmunities(Arrays.asList(rs.getString("immunities").split(",")));
        return t;
    }

    // If not found in the internal DB, return null
    return null;
}
