// Define the logging interface
class ILogger {
 public:
  virtual void log(const std::string& message) = 0;
};

// Define the ELK Stack logging service interface
class IELKStackLogger : public ILogger {
 public:
  virtual bool sendLogsToELKStack() = 0;
};

// Define the third-party data processing API interface
class IDPAPIDataProcessor : public ILogger {
 public:
  virtual std::string processData(const std::string& data) = 0;
};

// Define the DynamicStringListManager class
class DynamicStringListManager {
 private:
  // The doubly linked list of strings
  std::list<std::string> str_list_;

  // The mutex used to protect the list from concurrent access
  std::mutex str_list_mutex_;

  // The condition variable used to signal when the list is modified
  std::condition_variable str_list_cv_;

  // The fallback mechanism for logging locally in case of service outages
  ILogger* local_logger_;

  // The ELK Stack logging service
  IELKStackLogger* elk_stack_logger_;

  // The third-party data processing API
  IDPAPIDataProcessor* dpapi_;

  // The cache for the list of strings
  std::vector<std::string> str_cache_;

  // The bloom filter for cached items
  std::unordered_set<std::string> str_bloom_filter_;

  // The memory pool for the list of strings
  std::shared_ptr<std::vector<std::string>> str_memory_pool_;

  // The priority-based queue for handling operations that may need to bypass certain checks or optimizations for timely execution
  std::priority_queue<Task> task_queue_;

  // The memory pressure detector for the list of strings
  MemoryPressureDetector mem_pressure_detector_;

 public:
  DynamicStringListManager(ILogger* local_logger, IELKStackLogger* elk_stack_logger, IDPAPIDataProcessor* dpapi)
      : str_list_(),
        str_list_mutex_(),
        str_list_cv_(),
        local_logger_(local_logger),
        elk_stack_logger_(elk_stack_logger),
        dpapi_(dpapi),
        str_cache_(),
        str_bloom_filter_(),
        str_memory_pool_(),
        task_queue_(),
        mem_pressure_detector_() {}

  // Insert a string after the first occurrence of a target string in the list, appending it to the end if not found.
  void insertStringAfter(const std::string& target, const std::string& str) {
    std::lock_guard<std::mutex> lock(str_list_mutex_);
    auto it = std::find(str_list_.begin(), str_list_.end(), target);
    if (it != str_list_.end()) {
      // Insert the string after the target
      auto idx = std::distance(str_list_.begin(), it) + 1;
      str_list_.insert(idx, str);
    } else {
      // Append the string to the end of the list
      str_list_.push_back(str);
    }
    // Log the insertion
    logInsertion(target, str);
  }

  // Append a string to the end of the list
  void appendString(const std::string& str) {
    std::lock_guard<std::mutex> lock(str_list_mutex_);
    str_list_.push_back(str);
    logInsertion("", str);
  }

  // Retrieve a string from the list by its index
  std::string getStringByIndex(size_t idx) {
    std::lock_guard<std::mutex> lock(str_list_mutex_);
    return str_list_.at(idx);
  }

  // Remove a string from the list by its index
  void removeStringByIndex(size_t idx) {
    std::lock_guard<std::mutex> lock(str_list_mutex_);
    auto it = str_list_.begin() + idx;
    str_list_.erase(it);
  }

 private:
  // Log an insertion to the local logger, ELK Stack logging service, and third-party data processing API
  void logInsertion(const std::string& target, const std::string& str) {
    // Use the cached string if available
    auto it = str_bloom_filter_.find(str);
    if (it != str_bloom_filter_.end()) {
      return;
    }
    // Log to the local logger
    local_logger_->log("Inserted " + str + " after " + target);
    // Log to the ELK Stack logging service, with graceful degradation if the service is down
    if (elk_stack_logger_ != nullptr && elk_stack_logger_->sendLogsToELKStack()) {
      elk_stack_logger_->log("Inserted " + str + " after " + target);
    } else {
      std::cout << "WARNING: ELK Stack logging service is down. Logging to local logger only." << std::endl;
    }
    // Process the string using the third-party data processing API, with graceful degradation if the API is down
    if (dpapi_ != nullptr) {
      dpapi_->process(str);
    } else {
      std::cout << "WARNING: Third-party data processing API is down. Skipping." << std::endl;
    }
    // Update the cache and bloom filter
    str_cache_.push_back(str);
    str_bloom_filter_.insert(str);
  }
};

// Task queue for handling operations that may need to bypass certain checks or optimizations for timely execution
class Task {
 public:
  virtual void execute() = 0;
};

// Memory pressure detector for the list of strings, which evicts the oldest strings when memory is low
class MemoryPressureDetector {
 private:
  // The cache for the list of strings
  std::vector<std::string> str_cache_;

  // The bloom filter for cached items
  std::unordered_set<std::string> str_bloom_filter_;

 public:
  MemoryPressureDetector(const std::vector<std::string>& str_cache, const std::unordered_set<std::string>& str_bloom_filter)
      : str_cache_(str_cache), str_bloom_filter_(str_bloom_filter) {}

  // Evict the oldest string in the cache when memory is low
  void evictOldestString() {
    if (str_memory_pool_.size() > kMaxMemPoolSize) {
      std::string oldest = str_cache_.front();
      str_cache_.erase(str_cache_.begin());
      str_bloom_filter_.erase(oldest);
    }
  }
};
