    public class ErrorHandler
    {
        private readonly Dictionary<string, List<Exception>> _errors = new Dictionary<string, List<Exception>>();
        private readonly int _maxErrorCount;

        public ErrorHandler(int maxErrorCount)
        {
            _maxErrorCount = maxErrorCount;
        }

        public void LogError(string message, Exception ex)
        {
            // Check if the error is already logged and add it to the list
            List<Exception> errors = _errors.GetValueOrDefault(message);
            if (errors == null || errors.Count >= _maxErrorCount)
