        ObjectMapper mapper = new ObjectMapper();
        DynamicFileConfiguration config;
        try {
            config = mapper.readValue(configJson, DynamicFileConfiguration.class);
        } catch (IOException e) {
            throw new RuntimeException("Failed to parse configuration JSON");
        }

        if (!config.isValid()) {
            throw new RuntimeException("Invalid configuration object");
        }

        // Handle potential network latency and service unavailability during configuration retrieval
        CompletableFuture<DynamicFileConfiguration> future = CompletableFuture.supplyAsync(() -> {
            return retrieveConfiguration(config.getConfigUrl());
        }, executor);

        DynamicFileConfiguration resolvedConfig;
        try {
            resolvedConfig = future.join();
        } catch (InterruptedException | ExecutionException e) {
            throw new RuntimeException("Failed to retrieve configuration from external API");
        }

        // Implement support for real-time data streaming, allowing the service to process incoming data in batches with varying sizes and frequencies. Develop a pipeline that supports transformations, aggregations, and filtering of streamed data, ensuring data is processed and stored efficiently without loss or duplication. Integrate with a distributed event-driven architecture to handle high-throughput and low-latency requirements, leveraging a message broker for reliable message delivery and acknowledgment.
        // ...
    }

    /**
     * Retrieve the configuration from the external RESTful API.
     */
    public DynamicFileConfiguration retrieveConfiguration(String url) {
        HttpGet request = new HttpGet(url);
        request.setHeader("Authorization", "Bearer <access token>");
        request.setHeader("Content-Type", "application/json");

        CloseableHttpResponse response = httpClient.execute(request);
        try {
            if (response.getStatusLine().getStatusCode() == 200) {
