using System;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.Logging;
using DocumentService = MyCompany.DocumentService;
using NotificationService = MyCompany.NotificationService;

public class UpdateDocumentController : ControllerBase
{
    private readonly ILogger<UpdateDocumentController> _logger;
    private readonly IDocumentService _documentService;
    private readonly INotificationService _notificationService;

    public UpdateDocumentController(ILogger<UpdateDocumentController> logger, IDocumentService documentService, INotificationService notificationService)
    {
        _logger = logger;
        _documentService = documentService;
        _notificationService = notificationService;
    }

    [HttpPost]
    public async Task<IActionResult> UpdateDocumentAsync([FromBody] DocumentUpdateRequest request)
    {
        try
        {
            // Validate the request
            if (!ModelState.IsValid)
            {
                return BadRequest(ModelState);
            }

            // Authenticate the user and validate their session token
            var user = await _documentService.AuthenticateUserAsync(request.Token);
            if (user == null || !user.TenantId.Equals(request.TenantId))
            {
                return Unauthorized();
            }

            // Enforce tenant-specific access controls and document versioning policies
            var canUpdate = await _documentService.CanUpdateDocumentAsync(user, request.DocumentId);
            if (!canUpdate)
            {
                return Forbidden();
            }

            // Update the document in the database
            var updatedDocument = await _documentService.UpdateDocumentAsync(request.DocumentId, request.Content, user.TenantId);

            // Notify other tenants that the document has been updated
            await _notificationService.NotifyUpdatedDocumentAsync(user.TenantId, request.DocumentId);

            // Return the updated document
            return Ok(updatedDocument);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error updating document");
            return StatusCode(500, new ErrorResponse("Error updating document"));
        }
    }
}

public class DocumentUpdateRequest
{
    public string Token { get; set; }
    public string TenantId { get; set; }
    public Guid DocumentId { get; set; }
    public string Content { get; set; }
}

public class ErrorResponse
{
    public string Message { get; set; }
}
```
