const paymentGateway = express();
paymentGateway.post('/payments', (req, res) => {
  const paymentDetails = req.body;
  const paymentMethod = paymentDetails.method;
  if (paymentMethod === 'paypal') {
    paypalClient.makePayment(paymentDetails).then((response) => {
      res.send(response);
    }).catch((err) => {
      console.error(err);
      res.status(500).send('Error processing payment');
    });
  } else if (paymentMethod === 'stripe') {
    stripeClient.makePayment(paymentDetails).then((response) => {
      res.send(response);
    }).catch((err) => {
      console.error(err);
      res.status(500).send('Error processing payment');
    });
  } else {
    res.status(400).send('Invalid payment method');
  }
});
paymentGateway.listen(3001, () => {
  console.log('Payment Gateway Service running on port 3001');
});

// Fraud Detection Service
const fraudDetection = require('fraud-detection');
const userRiskProfileService = require('user-risk-profile-service');
const { Server } = require('restify');
const server = new Server();
server.get('/users/:id/risk-profile', (req, res) => {
  const userId = req.params.id;
  userRiskProfileService.getUserRiskProfile(userId).then((riskProfile) => {
    res.send(riskProfile);
  }).catch((err) => {
    console.error(err);
    res.status(500).send('Error retrieving risk profile');
  });
});
server.post('/users/:id/payments', (req, res) => {
  const paymentDetails = req.body;
  fraudDetection.detectFraud(paymentDetails).then((isFraudulent) => {
    if (isFraudulent) {
      res.status(403).send('Forbidden: Fraud detected');
    } else {
      res.send();
    }
  }).catch((err) => {
    console.error(err);
    res.status(500).send('Error detecting fraud');
  });
});
server.listen(3002, () => {
  console.log('Fraud Detection Service running on port 3002');
});
```
