from concurrent.futures import ThreadPoolExecutor
from threading import Lock
from collections import defaultdict

# Define constants for payment gateways and currency exchange rates
PAYMENT_GATEWAYS = {
    'A': {'name': 'Payment Gateway A', 'url': 'https://gateway-a.com'},
    'B': {'name': 'Payment Gateway B', 'url': 'https://gateway-b.com'},
    'C': {'name': 'Payment Gateway C', 'url': 'https://gateway-c.com'}
}
CURRENCY_EXCHANGE_RATES = {
    'USD': 1.0,
    'EUR': 0.856,
    'GBP': 0.792,
    'JPY': 114.85
}

# Define a class for handling payment processing requests
class PaymentProcessor:
    def __init__(self):
        self.gateways = PAYMENT_GATEWAYS.values()
        self.lock = Lock()
        self.cache = defaultdict(lambda: None)

    # Method to perform a payment using the specified gateway and currency
    def pay(self, amount, currency, gateway):
        if not amount or not currency or not gateway:
            raise ValueError('Invalid input')

        with self.lock:
            # Check if the requested currency is supported by the gateway
            if currency not in PAYMENT_GATEWAYS[gateway]['currencies']:
                raise ValueError(f'Unsupported currency {currency} for gateway {gateway}')

            # Convert the amount to the appropriate currency
            converted_amount = self._convert_amount(amount, currency)

            # Perform the payment using the specified gateway
            response = requests.post(PAYMENT_GATEWAYS[gateway]['url'], json={'amount': converted_amount})

            if not response.ok:
                raise Exception('Payment failed')

            return response.json()['transactionId']

    # Method to convert an amount from one currency to another
    def _convert_amount(self, amount, from_currency, to_currency):
        rate = CURRENCY_EXCHANGE_RATES[from_currency] / CURRENCY_EXCHANGE_RATES[to_currency]
        return round(rate * amount)

# Define a class for handling user requests and managing payment processing
class PaymentHandler:
    def __init__(self):
        self.processor = PaymentProcessor()

    # Method to handle incoming payment requests from users
    def process_payment(self, request):
        if not request or not request['amount'] or not request['currency'] or not request['gateway']:
            raise ValueError('Invalid input')

        try:
            response = self.processor.pay(request['amount'], request['currency'], request['gateway'])
            return {'transactionId': response}
        except Exception as e:
            logging.error(f'Payment failed for user {request["userId"]}: {e}')
            return None
```
