    public class MessageProcessor
    {
        private const string _key = "123456789012345678901234567890123";
        private const string _iv = "12345678901234567";

        public Task<string> EncryptMessage(string plaintext)
        {
            return Task.Run(() =>
            {
                var sessionId = Guid.NewGuid().ToString();

                try
                {
                    var encryptedBytes = TripleDesEncrypt(Encoding.UTF8.GetBytes(plaintext), _key, _iv);
                    var base64EncodedMessage = Convert.ToBase64String(encryptedBytes);

                    return base64EncodedMessage;
                }
                catch (Exception ex)
                {
                    // Log error information for failed encryption attempts
                    Console.WriteLine($"Error occurred during encryption with session ID {sessionId}: {ex.Message}");
                    throw;
                }
            });
        }

        public Task<string> DecryptMessage(string base64EncodedMessage)
        {
            return Task.Run(() =>
            {
                var sessionId = Guid.NewGuid().ToString();

                try
                {
                    var encryptedBytes = Convert.FromBase64String(base64EncodedMessage);
                    var plaintext = TripleDesDecrypt(encryptedBytes, _key, _iv);
                    var decodedPlaintext = Encoding.UTF8.GetString(plaintext);

                    return decodedPlaintext;
                }
                catch (Exception ex)
                {
                    // Log error information for failed decryption attempts
                    Console.WriteLine($"Error occurred during decryption with session ID {sessionId}: {ex.Message}");
                    throw;
                }
            });
        }

        private byte[] TripleDesEncrypt(byte[] plaintext, string key, string iv)
        {
            using (var des = new DESCryptoServiceProvider())
            {
                var keyBytes = Encoding.UTF8.GetBytes(key);
                var ivBytes = Encoding.UTF8.GetBytes(iv);

                des.IV = ivBytes;
                des.Key = keyBytes;
                des.Padding = PaddingMode.PKCS7;
                des.Mode = CipherMode.CBC;

                return des.CreateEncryptor().TransformFinalBlock(plaintext, 0, plaintext.Length);
            }
        }

        private byte[] TripleDesDecrypt(byte[] ciphertext, string key, string iv)
        {
            using (var des = new DESCryptoServiceProvider())
            {
                var keyBytes = Encoding.UTF8.GetBytes(key);
                var ivBytes = Encoding.UTF8.GetBytes(iv);

                des.IV = ivBytes;
                des.Key = keyBytes;
                des.Padding = PaddingMode.PKCS7;
                des.Mode = CipherMode.CBC;

                return des.CreateDecryptor().TransformFinalBlock(ciphertext, 0, ciphertext.Length);
            }
        }
    }
}
