    sprintf(key, "%s%s", KEY_PREFIX, base64_encode(rand_key));
}

// Function to encrypt a file using OpenSSL
void encryptFile(string& filename, string& iv, string& key) {
    // Initialize the encryption library
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    AES_KEY enc_key;

    // Set the IV and key for encryption
    if (!EVP_EncryptInit_ex(ctx, EVP_aes_128_cbc(), NULL, (unsigned char*)iv.c_str(), (unsigned char*)key.c_str())) {
        cout << "Failed to initialize AES encryption: " << filename << endl;
    }

    // Open the input file for reading and output file for writing
    FILE* in = fopen(filename.c_str(), "rb");
    FILE* out = fopen((filename + ".enc").c_str(), "wb");

    // Encrypt the file in chunks
    size_t len;
    unsigned char buffer[BUFFER_SIZE];
    while ((len = fread(buffer, 1, BUFFER_SIZE, in)) > 0) {
        if (!EVP_EncryptUpdate(ctx, buffer, &len, buffer, len)) {
            cout << "Failed to encrypt file: " << filename << endl;
        }
        fwrite(buffer, 1, len, out);
    }

    // Finalize the encryption
    if (!EVP_EncryptFinal_ex(ctx, buffer, &len)) {
        cout << "Failed to finalize AES encryption: " << filename << endl;
    }

    // Clean up resources
    EVP_CIPHER_CTX_free(ctx);
    fclose(in);
    fclose(out);
}

// Function to decrypt a file using OpenSSL
void decryptFile(string& filename, string& iv, string& key) {
    // Initialize the decryption library
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    AES_KEY dec_key;

    // Set the IV and key for decryption
    if (!EVP_DecryptInit_ex(ctx, EVP_aes_128_cbc(), NULL, (unsigned char*)iv.c_str(), (unsigned char*)key.c_str())) {
        cout << "Failed to initialize AES decryption: " << filename << endl;
    }

    // Open the input file for reading and output file for writing
    FILE* in = fopen(filename.c_str(), "rb");
    FILE* out = fopen((filename + ".dec").c_str(), "wb");

    // Decrypt the file in chunks
    size_t len;
    unsigned char buffer[BUFFER_SIZE];
    while ((len = fread(buffer, 1, BUFFER_SIZE, in)) > 0) {
        if (!EVP_DecryptUpdate(ctx, buffer, &len, buffer, len)) {
            cout << "Failed to decrypt file: " << filename << endl;
        }
        fwrite(buffer, 1, len, out);
    }

    // Finalize the decryption
    if (!EVP_DecryptFinal_ex(ctx, buffer, &len)) {
        cout << "Failed to finalize AES decryption: " << filename << endl;
    }

    // Clean up resources
    EVP_CIPHER_CTX_free(ctx);
    fclose(in);
    fclose(out);
}

// Function to upload a file to the server
void uploadFile(string& filename, string& iv, string& key) {
    // Initialize the curl library
    CURL* curl = curl_easy_init();

    // Set the URL and HTTP method for the upload request
    curl_easy_setopt(curl, CURLOPT_URL, "https://example.com/upload");
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, filename);

    // Set the HTTP headers for the upload request
    struct curl_slist* headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/octet-stream");
    headers = curl_slist_append(headers, ("X-IV: " + iv).c_str());
    headers = curl_slist_append(headers, ("X-Key: " + key).c_str());
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

    // Perform the upload request
    CURLcode res = curl_easy_perform(curl);

    // Check for errors and clean up resources
    if (res != CURLE_OK) {
        cout << "Failed to upload file: " << filename << endl;
    } else {
        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
    }
}

// Function to download a file from the server
void downloadFile(string& filename, string& iv, string& key) {
    // Initialize the curl library
    CURL* curl = curl_easy_init();

    // Set the URL and HTTP method for the download request
    curl_easy_setopt(curl, CURLOPT_URL, "https://example.com/download");
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, ("X-IV: " + iv).c_str());
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, ("X-Key: " + key).c_str());

    // Perform the download request
    CURLcode res = curl_easy_perform(curl);

    // Check for errors and clean up resources
    if (res != CURLE_OK) {
        cout << "Failed to download file: " << filename << endl;
    } else {
        curl_easy_cleanup(curl);
    }
}

// Main function that handles the processing of files
int main(int argc, char* argv[]) {
    // Check if there are any command-line arguments
    if (argc <= 1) {
        cout << "Usage: ./example [file] [iv] [key]" << endl;
        return 0;
    }

    // Get the file name, IV, and key from the command-line arguments
    string filename = argv[1];
    string iv = argv[2];
    string key = argv[3];

    // Check if the file exists and is readable
    ifstream in(filename.c_str());
    if (!in) {
        cout << "Failed to open file: " << filename << endl;
        return 0;
    }

    // Decrypt the file using OpenSSL
    decryptFile(filename, iv, key);

    // Upload the decrypted file to the server using cURL
    uploadFile(filename + ".dec", iv, key);

    // Download the uploaded file from the server using cURL
    downloadFile(filename + ".dec", iv, key);

    // Encrypt the downloaded file using OpenSSL
    encryptFile(filename + ".dec", iv, key);

    // Clean up resources and exit
    return 0;
}']

