// Define the structure for SensorNode
struct SensorNode {
  int nodeID;
  string sensorType;
  float locationX;
  float locationY;
  bool status;
  float lastValue;
};

// Define the structure for GraphNode
struct GraphNode {
  int nodeID;
  set<int> neighbors;
  map<int, float> weights;
  SensorNode sensorNode;
};

// Define the class for Graph
class Graph {
 public:
  // Constructor to initialize graph with given number of nodes
  explicit Graph(int numNodes) : numNodes_(numNodes) {}

  // Add a new node to the graph
  void addNode(const SensorNode &sensorNode, const int &nodeID) {
    if (graph_.find(nodeID) != graph_.end()) {
      throw invalid_argument("Node ID already exists");
    }
    graph_[nodeID] = GraphNode{nodeID, set<int>{}, map<int, float>{}, sensorNode};
  }

  // Add a new edge to the graph between two nodes with given weights
  void addEdge(const int &sourceID, const int &targetID, const float &weight) {
    if (graph_.find(sourceID) == graph_.end() || graph_.find(targetID) == graph_.end()) {
      throw invalid_argument("Node ID not found");
    }
    graph_[sourceID].neighbors.insert(targetID);
    graph_[sourceID].weights[targetID] = weight;
  }

  // Get the node with given ID
  const GraphNode& getNode(const int &nodeID) {
    if (graph_.find(nodeID) == graph_.end()) {
      throw invalid_argument("Node ID not found");
    }
    return graph_[nodeID];
  }

  // Get all the nodes in the graph
  const map<int, GraphNode>& getNodes() {
    return graph_;
  }

 private:
  int numNodes_;
  map<int, GraphNode> graph_;
};

// Define the class for GraphManager
class GraphManager {
 public:
  // Constructor to initialize graph manager with given number of nodes and edges
  explicit GraphManager(const int &numNodes, const vector<pair<int, float>> &edges) : numNodes_(numNodes), edges_(edges) {}

  // Add a new node to the graph
  void addNode(const SensorNode &sensorNode, const int &nodeID) {
    if (graph_.find(nodeID) != graph_.end()) {
      throw invalid_argument("Node ID already exists");
    }
    graph_[nodeID] = Graph{numNodes_};
    graph_[nodeID].addNode(sensorNode, nodeID);
  }

  // Add a new edge to the graph between two nodes with given weights
  void addEdge(const int &sourceID, const int &targetID, const float &weight) {
    if (graph_.find(sourceID) == graph_.end() || graph_.find(targetID) == graph_.end()) {
      throw invalid_argument("Node ID not found");
    }
    graph_[sourceID].addEdge(targetID, weight);
  }

  // Get the node with given ID
  const Graph& getGraph() {
    return graph_;
  }

 private:
  int numNodes_;
  vector<pair<int, float>> edges_;
  map<int, Graph> graph_;
};

// Define the class for SensorManager
class SensorManager {
 public:
  // Constructor to initialize sensor manager with given number of sensors and their types
  explicit SensorManager(const int &numSensors, const vector<string> &sensorTypes) : numSensors_(numSensors), sensorTypes_(sensorTypes) {}

  // Add a new sensor node to the graph with given ID and type
  void addNode(const int &nodeID, const string &type) {
    if (sensors_.find(nodeID) != sensors_.end()) {
      throw invalid_argument("Sensor ID already exists");
    }
    sensors_[nodeID] = SensorNode{nodeID, type, 0, 0, true};
  }

  // Add a new sensor reading to the graph for given node and value
  void addReading(const int &nodeID, const float &value) {
    if (sensors_.find(nodeID) == sensors_.end()) {
      throw invalid_argument("Sensor ID not found");
    }
    sensors_[nodeID].lastValue = value;
  }

  // Get the sensor node with given ID
  const SensorNode& getSensor(const int &nodeID) {
    if (sensors_.find(nodeID) == sensors_.end()) {
      throw invalid_argument("Sensor ID not found");
    }
    return sensors_[nodeID];
  }

  // Get all the sensor nodes in the graph
  const map<int, SensorNode>& getSensors() {
    return sensors_;
  }

 private:
  int numSensors_;
  vector<string> sensorTypes_;
  map<int, SensorNode> sensors_;
};
```

This code defines three classes for managing a graph of nodes and edges, a sensor manager class to manage the sensors in the network, and a graph manager class to manage the graph and its nodes and edges. The graph is represented as a map of node IDs to `GraphNode` objects, which contain the node's ID, a set of neighboring node IDs, and a map of edge weights between those nodes. Similarly, the sensor manager class manages the sensors in the network by maintaining a map of sensor IDs to `SensorNode` objects, which contain the sensor's ID, type, and last reported value.

The graph manager class takes care of managing the graph as a whole, including adding new nodes and edges between them. The sensor manager class takes care of managing the sensors in the network, including adding new sensors and updating their readings. Both classes provide methods to get the relevant information for each node or edge, such as its ID, type, weight, or last reported value.

This code is a simple example of how you could use these classes to manage a graph of nodes and edges in your system. You may need to modify it to fit your specific requirements and add additional features as needed.']

