from urllib.parse import urljoin

import requests

API_ENDPOINT = "https://api.autonomousvehiclefleet.com"
AUTHORIZATION_URL = urljoin(API_ENDPOINT, "/oauth2/token")
VEHICLE_STATUS_URL = urljoin(API_ENDPOINT, "/vehicles/{}/status")
CACHE_KEY = "status-cache"

def parse_args():
    parser = argparse.ArgumentParser()
    parser.add_argument("--api-key", required=True)
    parser.add_argument("--vehicle-id", required=True)
    parser.add_argument("--operation-mode", choices=["diagnostic", "maintenance", "route-optimization"])
    parser.add_argument("--fetch-status", action="store_true")
    return parser.parse_args()

def get_access_token(api_key):
    headers = {
        "Authorization": f"Basic {api_key}",
        "Content-Type": "application/x-www-form-urlencoded"
    }
    data = {"grant_type": "client_credentials"}
    response = requests.post(AUTHORIZATION_URL, headers=headers, data=data)
    if response.status_code == 200:
        return json.loads(response.content)["access_token"]
    else:
        raise Exception("Failed to get access token")

def fetch_vehicle_status(api_key, vehicle_id):
    headers = {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json"
    }
    response = requests.get(VEHICLE_STATUS_URL.format(vehicle_id), headers=headers)
    if response.status_code == 200:
        return json.loads(response.content)["data"]
    else:
        raise Exception("Failed to fetch vehicle status")

def get_cached_status(redis, key):
    cached_status = redis.get(key)
    if cached_status is not None:
        return json.loads(cached_status)
    else:
        return None

def update_cache(redis, key, status):
    redis.setex(key, 3600, json.dumps(status))

def main():
    args = parse_args()
    api_key = args.api_key
    vehicle_id = args.vehicle_id
    operation_mode = args.operation_mode
    fetch_status = args.fetch_status

    redis = Redis(host="localhost", port=6379, db=0)
    cache_key = f"{CACHE_KEY}-{vehicle_id}"

    access_token = get_access_token(api_key)
    vehicle_status = None

    if fetch_status:
        try:
            vehicle_status = fetch_vehicle_status(access_token, vehicle_id)
        except Exception as e:
            print(f"Failed to fetch vehicle status: {e}")

    cached_status = get_cached_status(redis, cache_key)

    if vehicle_status is not None:
        update_cache(redis, cache_key, vehicle_status)

    if cached_status is not None:
        print("Cached status:")
        print(json.dumps(cached_status))
    else:
        print("No cached status found.")
