#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/aes.h>
#include <openssl/hmac.h>
#include <openssl/sha.h>
#include <openssl/pbm.h>
#include <openssl/rand.h>
#include <openssl/evp.h>

#define INPUT_FILE "input.txt"
#define OUTPUT_FILE "output.bin"

int main() {
    // Open the input file and read its contents
    FILE *fptr = fopen(INPUT_FILE, "r");
    if (fptr == NULL) {
        perror("Failed to open input file");
        return 1;
    }

    char buffer[4096];
    size_t bytes_read = fread(buffer, sizeof(char), 4096, fptr);
    if (bytes_read == 0) {
        perror("Failed to read input file");
        return 1;
    }

    // Encrypt the data using AES-256-CBC
    unsigned char iv[AES_BLOCK_SIZE];
    RAND_bytes(iv, AES_BLOCK_SIZE);

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, NULL, iv) != 1) {
        perror("Failed to initialize AES encryption");
        return 1;
    }

    unsigned char *encrypted = (unsigned char *)malloc(bytes_read + AES_BLOCK_SIZE);
    memcpy(encrypted, iv, AES_BLOCK_SIZE);

    int bytes_written = EVP_EncryptUpdate(ctx, encrypted + AES_BLOCK_SIZE, &bytes_read, buffer, bytes_read);
    if (bytes_written == -1) {
        perror("Failed to encrypt data");
        return 1;
    }

    free(buffer);
    fclose(fptr);

    // Write the encrypted data to an output file
    FILE *out = fopen(OUTPUT_FILE, "wb");
    if (out == NULL) {
        perror("Failed to open output file");
        return 1;
    }

    int bytes_written2 = fwrite(encrypted, sizeof(char), bytes_read + AES_BLOCK_SIZE, out);
    if (bytes_written2 == -1) {
        perror("Failed to write encrypted data to file");
        return 1;
    }

    free(encrypted);
    fclose(out);

    return 0;
}
