import requests
from datetime import datetime
from threading import Thread
from multiprocessing import Pool

class DataAggregator:
    def __init__(self):
        self.data = {}
        self.cached_data = {}

    def get_data(self, url):
        if url in self.cached_data:
            return self.cached_data[url]
        else:
            response = requests.get(url)
            data = response.json()
            self.cached_data[url] = data
            return data

    def update_data(self, url):
        data = self.get_data(url)
        if url in self.data:
            self.data[url].update(data)
        else:
            self.data[url] = data

class LogProcessor:
    def __init__(self):
        self.log_list = []

    def process_logs(self, logs):
        for log in logs:
            log['timestamp'] = datetime.fromisoformat(log['timestamp'])
            if 'message' in log:
                log['message'] = log['message'].lower()
        self.log_list.extend(logs)

    def get_logs(self):
        return self.log_list

class AlertHandler:
    def __init__(self, alert_rules):
        self.alert_rules = alert_rules

    def check_alerts(self, data):
        for rule in self.alert_rules:
            if rule['condition'](data):
                yield rule['message']

class Dashboard:
    def __init__(self, aggregator, processor, alert_handler):
        self.aggregator = aggregator
        self.processor = processor
        self.alert_handler = alert_handler

    def update(self):
        self.aggregator.update_data('http://localhost:8000/data')
        self.processor.process_logs(['log1', 'log2'])
        alerts = self.alert_handler.check_alerts(self.aggregator.get_data())
        for alert in alerts:
            print(alert)

if __name__ == '__main__':
    aggregator = DataAggregator()
    processor = LogProcessor()
    alert_handler = AlertHandler([{'condition': lambda data: len(data['errors']) > 0, 'message': 'Error threshold exceeded'}])
    dashboard = Dashboard(aggregator, processor, alert_handler)
    while True:
        dashboard.update()
