// Initialize library with default values for capacity and retention policy
void traffic_monitoring_lib_init(size_t capacity, int retention_policy) {
    // Check if the library has already been initialized
    assert(!initialized);

    // Initialize event array with provided capacity and set retention policy
    event_array.capacity = capacity;
    event_array.count = 0;
    event_array.events = (struct TrafficEvent**)malloc(sizeof(struct TrafficEvent*) * capacity);
    memset(event_array.events, 0, sizeof(struct TrafficEvent*) * capacity);
