    plugins = (struct PluginLoadInfo*)malloc(sizeof(struct PluginLoadInfo) * num_plugins);
    memset(plugins, 0, sizeof(struct PluginLoadInfo) * num_plugins);

    // Initialize mutex and semaphore for thread-safe access to event array
    pthread_mutex_init(&mutex, NULL);
    semaphore = SEMAPHORE_INITIALIZER;

    initialized = true;
}

// Add a new traffic event to the library
void traffic_monitoring_lib_add_event(struct TrafficEvent* event) {
    // Check if the library has been initialized
    assert(initialized);

    pthread_mutex_lock(&mutex);

    // Ensure that the event array has enough capacity for the new event
    if (event_array.count >= event_array.capacity) {
        // TODO: Handle out-of-memory condition and potential data loss
        printf("Error: Event array is full, cannot add new event\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Add the new event to the event array
    event_array.events[event_array.count++] = event;

    // Notify all waiting threads that a new event has been added
    semaphore_post(semaphore);

    pthread_mutex_unlock(&mutex);
}

// Retrieve a traffic event from the library based on its ID
struct TrafficEvent* traffic_monitoring_lib_get_event(int id) {
    // Check if the library has been initialized
    assert(initialized);

    pthread_mutex_lock(&mutex);

    // Search for the event with the specified ID in the event array
    struct TrafficEvent* event = NULL;
    for (size_t i = 0; i < event_array.count; i++) {
        if (event_array.events[i]->id == id) {
            event = event_array.events[i];
            break;
        }
    }

    pthread_mutex_unlock(&mutex);

    return event;
}

// Update a traffic event in the library based on its ID
void traffic_monitoring_lib_update_event(struct TrafficEvent* event) {
    // Check if the library has been initialized
    assert(initialized);

    pthread_mutex_lock(&mutex);

    // Search for the event with the specified ID in the event array
    size_t index = -1;
    for (size_t i = 0; i < event_array.count; i++) {
        if (event_array.events[i]->id == event->id) {
            index = i;
            break;
        }
    }

    // Update the event in the array if found, otherwise ignore
    if (index != -1) {
        event_array.events[index] = event;
    }

    pthread_mutex_unlock(&mutex);
}

// Remove a traffic event from the library based on its ID
void traffic_monitoring_lib_remove_event(int id) {
    // Check if the library has been initialized
    assert(initialized);

    pthread_mutex_lock(&mutex);

    // Search for the event with the specified ID in the event array
    size_t index = -1;
    for (size_t i = 0; i < event_array.count; i++) {
        if (event_array.events[i]->id == id) {
            index = i;
            break;
        }
    }

    // Remove the event from the array if found, otherwise ignore
    if (index != -1) {
        for (size_t i = index; i < event_array.count - 1; i++) {
            event_array.events[i] = event_array.events[i + 1];
        }
        event_array.count--;
    }

    pthread_mutex_unlock(&mutex);
}

// Clean up the library and release resources
void traffic_monitoring_lib_destroy() {
    // Check if the library has been initialized
    assert(initialized);

    pthread_mutex_lock(&mutex);

    // Release memory for event array and plugin load info
    free(event_array.events);
    free(plugins);

    // Reset library to uninitialized state
    initialized = false;

    pthread_mutex_unlock(&mutex);
}
