/**
* Data processing pipeline for real-time data ingestion and transformation using Apache Kafka, Spark, and REST APIs
*/

// Import required libraries and dependencies
import org.apache.kafka.streams.KafkaStreams;
import org.apache.spark.api.java.JavaRDD;
import java.io.Serializable;
import java.util.Map;
import org.apache.commons.lang3.SerializationUtils;
import org.apache.http.client.fluent.Request;
import java.net.URI;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.core.JsonProcessingException;
import java.util.List;

// Define data processing primitives and integration with third-party APIs
public class DataPipeline implements Serializable {
  // Define Kafka Streams for real-time data ingestion
  private final KafkaStreams kafkaStreams;

  // Define Spark for batch processing
  private final JavaRDD<String> sparkRDD;

  // Define REST APIs for external data sources
  private final Map<URI, List<ObjectMapper>> restAPIs;

  /**
   * Constructor for DataPipeline
   */
  public DataPipeline(KafkaStreams kafkaStreams, JavaRDD<String> sparkRDD, Map<URI, List<ObjectMapper>> restAPIs) {
    this.kafkaStreams = kafkaStreams;
    this.sparkRDD = sparkRDD;
    this.restAPIs = restAPIs;
  }

  /**
   * Method to process data from Kafka Streams and Spark, handling errors and exceptions
   */
  public void processData(String input) {
    try {
      // Process data from Kafka Streams using the KafkaStreams object
      String output = kafkaStreams.processData(input);

      // Process data from Spark RDD using the JavaRDD object
      String transformedOutput = sparkRDD.transformData(output);

      // Send data to external REST APIs using the Map of URI and ObjectMapper
      for (URI uri : restAPIs.keySet()) {
        List<ObjectMapper> objectMappers = restAPIs.get(uri);
        for (ObjectMapper objectMapper : objectMappers) {
          String outputString = objectMapper.writeValueAsString(transformedOutput);
          Request request = Request.Post(uri).bodyString(outputString, org.apache.http.entity.ContentType.APPLICATION_JSON);
          request.execute().returnResponse();
        }
      }
    } catch (Exception e) {
      // Log error and exception for debugging purposes
      System.out.println("Error processing data: " + e.getMessage());
      e.printStackTrace();
    }
  }
}']

