struct JSONHelper;

impl JSONHelper {
    pub fn serialize<T>(data: T) -> Result<String>
    where
        T: Serialize,
    {
        let j = serde_json::to_string(&data)?;
        Ok(j)
    }

    pub fn deserialize<'a, T>(json: &'a str) -> Result<T>
    where
        T: Deserialize<'a>,
    {
        let j = serde_json::from_str(json)?;
        Ok(j)
    }
}
