  def serialize[T](data: T): String = mapper.writeValueAsString(data)

  def deserialize[T](json: String)(implicit mf: Manifest[T]): T = {
    val clazz = Class.forName(mf.toString)
    mapper.readValue[T](json, clazz)
  }
}
