```
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>

// Define the structure for TrafficEvent
typedef struct {
    uint64_t timestamp;
    char event_type[32];
    int device_id;
    double latitude;
    double longitude;
} TrafficEvent;

// Define the dynamic array for storing TrafficEvents
typedef struct {
    TrafficEvent *events;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    semaphore_t semaphore;
} DynamicArray;

// Function to initialize the dynamic array
void initialize_dynamic_array(DynamicArray *array) {
    array->events = NULL;
    array->capacity = 0;
    array->count = 0;
    pthread_mutex_init(&array->mutex, NULL);
    semaphore_init(&array->semaphore, 0, SAFE_WAIT);
}

// Function to add a TrafficEvent to the dynamic array
void add_traffic_event(DynamicArray *array, TrafficEvent event) {
    pthread_mutex_lock(&array->mutex);
    if (array->count == array->capacity) {
        // Reallocate memory for the events array if necessary
        size_t new_capacity = array->capacity * 2;
        TrafficEvent *new_events = realloc(array->events, sizeof(TrafficEvent) * new_capacity);
        if (new_events == NULL) {
            // Handle the error case
        }
        array->events = new_events;
        array->capacity = new_capacity;
    }
    array->events[array->count++] = event;
    pthread_mutex_unlock(&array->mutex);
}

// Function to retrieve a TrafficEvent from the dynamic array
TrafficEvent get_traffic_event(DynamicArray *array, int index) {
    if (index < 0 || index >= array->count) {
        return NULL;
    }
    pthread_mutex_lock(&array->mutex);
    TrafficEvent event = array->events[index];
    pthread_mutex_unlock(&array->mutex);
    return event;
}

// Function to prune old events from the dynamic array
void prune_old_events(DynamicArray *array, size_t max_age) {
    pthread_mutex_lock(&array->mutex);
    // Iterate over all events and remove any that are older than the maximum age
    for (int i = 0; i < array->count; i++) {
        TrafficEvent event = array->events[i];
        if (event.timestamp < time(NULL) - max_age) {
            memmove(&array->events[i], &array->events[i + 1], sizeof(TrafficEvent) * (array->count - i));
            array->count--;
        }
    }
    pthread_mutex_unlock(&array->mutex);
}
```
This library provides a modular, scalable, and resilient way to manage a dynamic array of `TrafficEvent` structures. The library uses a mutex to protect the array from concurrent access, and it uses a semaphore to signal when new events are available for retrieval. The library also includes functions for adding, removing, and retrieving events, as well as pruning old events based on a maximum age threshold.

