    int level;
};

// Function to format log message based on log level
void formatLogMessage(char *message, int level) {
    char *formatted_message = malloc(strlen(message) + 20);
    sprintf(formatted_message, LOG_FORMAT, "myapp", time(NULL), message);
}

// Function to flush log data to file
void flushLogDataToFile() {
    // Open log file for writing
    int fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (fd < 0) {
        perror("Error opening log file");
        return;
    }

    // Write formatted message to log file
    for (struct LogData *log = logs; log->message != NULL; log++) {
        char *formatted_message = formatLogMessage(log->message, log->level);
        write(fd, formatted_message, strlen(formatted_message));
        free(formatted_message);
    }

    // Close log file
    close(fd);
}

// Function to flush log data to console
void flushLogDataToConsole() {
    for (struct LogData *log = logs; log->message != NULL; log++) {
        printf("%s", formatLogMessage(log->message, log->level));
    }
}

// Function to add log data to queue
void addLogData(char *message, int level) {
    struct LogData *log = malloc(sizeof(struct LogData));
    log->message = message;
    log->level = level;
    logs = append(logs, log);
}

// Function to remove log data from queue
void removeLogData() {
    // Remove oldest log data from queue
    struct LogData *log = pop(logs);
    free(log->message);
    free(log);
}

// Main function for testing
int main() {
    setvbuf(stdout, NULL, _IONBF, 0);

    // Set log level threshold to INFO
    int log_level = LOG_INFO;

    while (1) {
        // Add log data to queue
        addLogData("Test message", LOG_DEBUG);

        // Flush log data to file and console
        flushLogDataToFile();
        flushLogDataToConsole();

        // Remove oldest log data from queue
        removeLogData();

        sleep(1);
    }
}
```
