    lock_dynamic_array(arr);
    int index = -1;
    for (int i=0; i<arr->size; i++) {
        if (arr->events[i].device_id == device_id && arr->events[i].timestamp == timestamp) {
            index = i;
            break;
        }
    }
    unlock_dynamic_array(arr);
