    LTE_PDCP_PDU pdu;
    struct QueueNode* next;
} QueueNode;

// Global variables for the queue and mutex
static QueueNode* head = NULL;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new packet to the queue
void addPacket(LTE_PDCP_PDU pdu) {
