    // Lock the mutex
    pthread_mutex_lock(&mutex);

    while (current != NULL) {
        if (current->pdu.sequenceNumber == sequenceNumber) {
            LTE_PDCP_PDU* packet = malloc(sizeof(LTE_PDCP_PDU));
            memcpy(packet, &current->pdu, sizeof(LTE_PDCP_PDU));

            // Remove the node from the queue
            if (head == current) {
                head = head->next;
            } else {
                QueueNode* previous = head;
                while (previous->next != current) {
                    previous = previous->next;
                }
                previous->next = current->next;
            }

            // Unlock the mutex
            pthread_mutex_unlock(&mutex);

            return packet;
        }
        current = current->next;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);

    return NULL;
}

// Function to remove a packet from the queue based on sequence number
void removePacket(int sequenceNumber) {
    QueueNode* current = head;

    // Lock the mutex
    pthread_mutex_lock(&mutex);

    while (current != NULL) {
        if (current->pdu.sequenceNumber == sequenceNumber) {
            // Remove the node from the queue
            if (head == current) {
                head = head->next;
            } else {
                QueueNode* previous = head;
