// Function to log messages to the error log when a specified condition is met
void logMessage(char* format, ...) {
    va_list args;
    char message[1024];

    // Initialize variable arguments
    va_start(args, format);

    // Create the formatted message
    vsnprintf(message, sizeof(message), format, args);

    // Log the message to the error log
    fprintf(stderr, "%s", message);

    // Clean up
    va_end(args);
}

// Function to handle errors and exceptions
void errorHandler(char* errorMessage) {
    logMessage("Error: %s\n", errorMessage);
}

// Function to retry an operation with a configurable backoff strategy
bool retryOperation(int retries, int backoffMultiplier, int backoffMaxDelay, char* errorMessage) {
    bool success = false;

    for (int i = 0; i < retries; i++) {
        if (success) {
            break;
        } else {
            // Sleep with the backoff strategy
            int delay = backoffMultiplier * (pow(2, i) - 1);
            delay = delay > backoffMaxDelay ? backoffMaxDelay : delay;
            sleep(delay);
        }
    }

    if (!success) {
        errorHandler(errorMessage);
    }

    return success;
}']

