#include <semaphore.h>
#include <unistd.h>
#include <stdbool.h>

// Define the TrafficEvent structure
struct TrafficEvent {
    int64_t timestamp;
    uint32_t eventType;
    uint32_t deviceId;
    double latitude;
    double longitude;
};

// Define the TrafficEvents array
struct TrafficEvent events[1000];

// Define the size of the TrafficEvents array
int numEvents = 1000;

// Define the current index in the TrafficEvents array
int currIndex = 0;

// Define the mutex for synchronizing access to the TrafficEvents array
pthread_mutex_t eventsMutex = PTHREAD_MUTEX_INITIALIZER;

// Define the semaphore for controlling access to the TrafficEvents array
sem_t eventsSemaphore;

// Initialize the semaphore for controlling access to the TrafficEvents array
sem_init(&eventsSemaphore, 0, numEvents);

// Define the method for adding a new TrafficEvent to the array
void addTrafficEvent(struct TrafficEvent *event) {
    // Acquire the mutex for synchronizing access to the TrafficEvents array
    pthread_mutex_lock(&eventsMutex);

    // Check if the capacity of the array has been reached
    if (currIndex == numEvents - 1) {
        // Increase the size of the array by a factor of 2
        numEvents *= 2;

        // Reallocate memory for the TrafficEvent array
        events = realloc(events, sizeof(struct TrafficEvent) * numEvents);
    }

    // Copy the new TrafficEvent to the next available index in the array
    memcpy(&events[currIndex], event, sizeof(struct TrafficEvent));

    // Increment the current index
    currIndex++;

    // Release the mutex for synchronizing access to the TrafficEvents array
    pthread_mutex_unlock(&eventsMutex);
}

// Define the method for retrieving a TrafficEvent from the array by its index
struct TrafficEvent *getTrafficEvent(int index) {
    // Acquire the mutex for synchronizing access to the TrafficEvents array
    pthread_mutex_lock(&eventsMutex);

    // Check if the requested index is within the bounds of the array
    if (index >= 0 && index < numEvents) {
        // Return a pointer to the TrafficEvent at the requested index
        return &events[index];
    } else {
        // Return NULL if the requested index is out of bounds
        return NULL;
    }

    // Release the mutex for synchronizing access to the TrafficEvents array
    pthread_mutex_unlock(&eventsMutex);
}

// Define the method for updating a TrafficEvent in the array by its index
void updateTrafficEvent(int index, struct TrafficEvent *event) {
    // Acquire the mutex for synchronizing access to the TrafficEvents array
    pthread_mutex_lock(&eventsMutex);

    // Check if the requested index is within the bounds of the array
    if (index >= 0 && index < numEvents) {
        // Copy the new TrafficEvent to the requested index in the array
        memcpy(&events[index], event, sizeof(struct TrafficEvent));
    }

    // Release the mutex for synchronizing access to the TrafficEvents array
    pthread_mutex_unlock(&eventsMutex);
}

// Define the method for deleting a TrafficEvent from the array by its index
void deleteTrafficEvent(int index) {
    // Acquire the mutex for synchronizing access to the TrafficEvents array
    pthread_mutex_lock(&eventsMutex);

    // Check if the requested index is within the bounds of the array
    if (index >= 0 && index < numEvents) {
        // Shift all subsequent TrafficEvents down one index in the array
        for (int i = index; i < currIndex - 1; i++) {
            memcpy(&events[i], &events[i + 1], sizeof(struct TrafficEvent));
        }

        // Decrement the current index
        currIndex--;
    }

    // Release the mutex for synchronizing access to the TrafficEvents array
    pthread_mutex_unlock(&eventsMutex);
}

// Define the method for retrieving all TrafficEvents from the array
struct TrafficEvent *getAllTrafficEvents() {
    // Acquire the mutex for synchronizing access to the TrafficEvents array
    pthread_mutex_lock(&eventsMutex);

    // Return a pointer to the entire TrafficEvents array
    return events;

    // Release the mutex for synchronizing access to the TrafficEvents array
    pthread_mutex_unlock(&eventsMutex);
}
```
This library provides several features that support high performance, modularity, and scalability:

* Synchronization using a mutex ensures that multiple threads can safely access the TrafficEvent array concurrently.
* A semaphore is used to control access to the TrafficEvent array, allowing only a limited number of threads to add or remove TrafficEvents at any given time.
* The addTrafficEvent, getTrafficEvent, updateTrafficEvent, and deleteTrafficEvent methods provide an API for adding, retrieving, updating, and deleting TrafficEvents in the array, respectively.
* The getAllTrafficEvents method allows all TrafficEvents to be retrieved at once.

This library also provides several benefits over a simple linked list implementation:

* Scalability: The library can grow or shrink dynamically as needed by reallocating memory for the TrafficEvent array, making it more suitable for applications with unpredictable data volumes.
* Efficient search and retrieval: The library allows for efficient search and retrieval of TrafficEvents by their index in the array, making it easier to iterate over or manipulate the TrafficEvent array.
* Thread safety: The library uses a mutex to ensure that multiple threads can safely access the TrafficEvent array concurrently, making it more suitable for multi-threaded applications.
* Code reuse: The library provides a reusable API for adding, retrieving, updating, and deleting TrafficEvents in the array, making it easier to reuse code in different parts of an application.']

