    TrafficEvent *event;
    struct EventList *next;
};

// Function to add an event to the linked list
void add_event(TrafficEvent *event) {
    struct EventList *new_node = (struct EventList *)malloc(sizeof(struct EventList));
    new_node->event = event;
    new_node->next = NULL;

    // Check if the linked list is empty
    if (head == NULL) {
        head = new_node;
        return;
    }

    // Find the end of the linked list and add the new node
    struct EventList *current = head;
    while (current->next != NULL) {
        current = current->next;
    }
    current->next = new_node;
}

// Function to retrieve an event from the linked list
TrafficEvent *get_event(int index) {
    // Check if the index is valid
    if (index < 0 || index >= length) {
        return NULL;
    }

    struct EventList *current = head;
    for (int i = 0; i < index; i++) {
        current = current->next;
    }
    return current->event;
}

// Function to prune events from the linked list based on a specified retention policy
void prune_events(float retention) {
    // Check if the retention value is valid
    if (retention < 0 || retention > 1) {
        return;
    }

    // Get the current time in seconds
    time_t now = time(NULL);

    // Traverse the linked list and remove events that are older than the specified retention period
    struct EventList *current = head;
    while (current != NULL) {
        if (now - current->event->timestamp > retention * 86400) {
            // Remove the event from the linked list
            TrafficEvent *old_event = current->event;
            current->event = current->next->event;
            free(current);

            // Update the length and head pointers
            length--;
            if (head == NULL) {
                break;
            } else if (head == current) {
                head = current->next;
            }
        } else {
            current = current->next;
        }
    }
}

// Function to update the linked list based on new events and existing events
