void printUsage() {
  printf("Usage: ./log_manager [OPTIONS]...\n");
  printf("\t-i, --input=FILE\tInput file to read from\n");
  printf("\t-o, --output=FILE\tOutput file to write to\n");
  printf("\t-c, --count\tCount the number of lines in the input file\n");
  printf("\t-m, --manpage\tPrint this manual page\n");
}

int main(int argc, char **argv) {
  // Parse command line arguments
  int c;
  char *input_file = NULL;
  char *output_file = NULL;
  while ((c = getopt(argc, argv, "i:o:cm")) != -1) {
    switch (c) {
      case 'i':
        input_file = optarg;
        break;
      case 'o':
        output_file = optarg;
        break;
      case 'c':
        count_lines(input_file);
        return 0;
      case 'm':
        printUsage();
        return 0;
    }
  }

  if (input_file == NULL) {
    fprintf(stderr, "Error: no input file specified\n");
    return 1;
  }

  // Read the input file line by line and print the number of lines
  FILE *fp = fopen(input_file, "r");
  if (fp == NULL) {
    perror("Error opening input file");
    return 1;
  }

  int count = 0;
  char *line = NULL;
  size_t len = 0;
  while (getline(&line, &len, fp) != -1) {
    count++;
  }

  if (output_file == NULL) {
    printf("Number of lines: %d\n", count);
  } else {
    FILE *fp = fopen(output_file, "w");
    if (fp == NULL) {
      perror("Error opening output file");
      return 1;
    }

    fprintf(fp, "%d\n", count);
    fclose(fp);
  }

  free(line);
  fclose(fp);
  return 0;
}

// Helper function to count the number of lines in a file
void count_lines(char *input_file) {
  FILE *fp = fopen(input_file, "r");
  if (fp == NULL) {
    perror("Error opening input file");
    return;
  }

  int count = 0;
  char *line = NULL;
  size_t len = 0;
  while (getline(&line, &len, fp) != -1) {
    count++;
  }

  printf("Number of lines: %d\n", count);
  free(line);
  fclose(fp);
}
