#define MAX_MSG_PROCESSING_THREADS 8
#define MSG_TYPE_NAS "NAS"
#define MSG_TYPE_DRB "DRB"
#define MSG_TYPE_PDU "PDU"

typedef struct {
    char* message;
    int type; //0 for NAS, 1 for DRB, 2 for PDU
} nfdata_message;

typedef struct {
    int msg_type;
    int urgency;
} message_priority;

typedef struct {
    char* message;
    int type; //0 for NAS, 1 for DRB, 2 for PDU
    int urgency;
} nfdata_message_with_priority;

//Thread function to process NFData messages
void* msg_processing_thread(void* arg) {
    nfdata_message* msg = (nfdata_message*)arg;
    printf("Processing message: %s\n", msg->message);
    free(msg);
    return NULL;
}

//Function to process NFData messages
void processNFData(char* nfdata_message) {
    int msg_type = getMsgType(nfdata_message);
    message_priority priority;
    if (msg_type == 0) { //NAS message
        priority.msg_type = 0;
        priority.urgency = getUrgencyLevel(nfdata_message);
    } else if (msg_type == 1) { //DRB message
        priority.msg_type = 1;
        priority.urgency = getUrgencyLevel(nfdata_message);
    } else { //PDU message
        priority.msg_type = 2;
        priority.urgency = getUrgencyLevel(nfdata_message);
    }
    nfdata_message* msg_with_priority = (nfdata_message*)malloc(sizeof(nfdata_message));
    msg_with_priority->message = nfdata_message;
    msg_with_priority->type = msg_type;
    msg_with_priority->urgency = priority.urgency;
    pthread_t thread_id;
    int rc = pthread_create(&thread_id, NULL, msg_processing_thread, (void*)msg_with_priority);
    if (rc) {
        printf("Error creating thread for message %s\n", nfdata_message);
    }
}

//Function to get message type from NFData message
int getMsgType(char* nfdata_message) {
    int msg_type = 0; //NAS by default
    if (strncmp(MSG_TYPE_DRB, nfdata_message, strlen(MSG_TYPE_DRB)) == 0) {
        msg_type = 1;
    } else if (strncmp(MSG_TYPE_PDU, nfdata_message, strlen(MSG_TYPE_PDU)) == 0) {
        msg_type = 2;
    }
    return msg_type;
}

//Function to get urgency level from NFData message
int getUrgencyLevel(char* nfdata_message) {
    //Implement logic to determine urgency level based on message content
    int urgency = 0;
    return urgency;
}

//Main function for processing NFData messages
int main() {
    char* nfdata_messages[MAX_NFDATA_MESSAGES];
    //Initialize semaphore to control access to message queue
    sem_t msg_sem;
    int rc = sem_init(&msg_sem, 0, MAX_NFDATA_MESSAGES);
    if (rc) {
        printf("Error initializing message semaphore\n");
        return -1;
    }
    //Initialize thread pool for message processing
    pthread_t msg_processing_threads[MAX_MSG_PROCESSING_THREADS];
    int num_msg_processing_threads = MIN_MSG_PROCESSING_THREADS;
    for (int i = 0; i < MAX_MSG_PROCESSING_THREADS; i++) {
        pthread_create(&msg_processing_threads[i], NULL, msg_processing_thread, NULL);
    }
    //Initialize message queue and start processing messages
    for (int i = 0; i < MAX_NFDATA_MESSAGES; i++) {
        char* nfdata_message = (char*)malloc(sizeof(char) * 1024);
        if (nfdata_message == NULL) {
            printf("Error allocating memory for message\n");
            return -1;
        }
        int rc = sem_wait(&msg_sem);
        if (rc) {
            printf("Error waiting for message semaphore\n");
            return -1;
        }
        //Populate NFData message from external REST API or database
        strcpy(nfdata_message, "Example NAS message");
        //Add message to queue and signal semaphore
        nfdata_messages[i] = nfdata_message;
        rc = sem_post(&msg_sem);
        if (rc) {
            printf("Error posting message semaphore\n");
            return -1;
        }
    }
    //Process messages in queue until empty
    while (!isEmpty(nfdata_messages)) {
        char* nfdata_message = popMessage(nfdata_messages);
        processNFData(nfdata_message);
    }
    //Wait for message processing threads to finish and clean up resources
    for (int i = 0; i < num_msg_processing_threads; i++) {
        pthread_join(msg_processing_threads[i], NULL);
    }
    sem_destroy(&msg_sem);
    return 0;
}

//Check if message queue is empty
bool isEmpty(char* nfdata_messages[]) {
    bool empty = true;
    for (int i = 0; i < MAX_NFDATA_MESSAGES; i++) {
        if (nfdata_messages[i] != NULL) {
            empty = false;
            break;
        }
    }
    return empty;
}

//Pop message from queue and update semaphore count
char* popMessage(char* nfdata_messages[]) {
    char* nfdata_message = nfdata_messages[0];
    for (int i = 1; i < MAX_NFDATA_MESSAGES; i++) {
        nfdata_messages[i - 1] = nfdata_messages[i];
    }
    nfdata_messages[MAX_NFDATA_MESSAGES - 1] = NULL;
    return nfdata_message;
}
