import hashlib
import logging
import time
from typing import Dict

import requests

LOGGER = logging.getLogger(__name__)

class FileIntegrityUtils:
    def __init__(self, api_url: str):
        self.api_url = api_url

    def validate_file_integrity(self, file_path: str) -> Dict[str, bool]:
        """
        Validate the integrity of a file by computing and comparing its MD5 hash with the one provided by an external API endpoint.
        :param file_path: The path to the file to be validated.
        :return: A dictionary with two keys: 'valid' (a boolean indicating whether the file is valid), and 'error' (an optional error message).
        """
        # Set up logging for this method
        start_time = time.time()
        LOGGER.info(f"Starting validate_file_integrity for {file_path}")

        # Check if the file exists and can be read
        try:
            with open(file_path, "rb") as f:
                file_size = os.stat(file_path).st_size
        except FileNotFoundError:
            return {"valid": False, "error": f"File {file_path} not found."}
        except PermissionError:
            return {"valid": False, "error": f"Insufficient permissions to read file {file_path}."}

        # Compute the MD5 hash of the file in fixed-size chunks
        hash_value = hashlib.md5()
        chunk_size = 64 * 1024  # Read in 64KB chunks to minimize memory usage
        with open(file_path, "rb") as f:
            while True:
                data = f.read(chunk_size)
                if not data:
                    break
                hash_value.update(data)

        # Send the computed hash value to the API for verification
        try:
            response = requests.post(self.api_url, json={"hash": hash_value.hexdigest()})
            response.raise_for_status()
        except requests.exceptions.HTTPError as e:
            return {"valid": False, "error": f"API error {e} while validating file integrity."}
        except requests.exceptions.ConnectionError as e:
            return {"valid": False, "error": f"Network connection error {e} while validating file integrity."}

        # Check the response from the API and update the logs accordingly
        if response.json()["status"] == "success":
            LOGGER.info(f"File integrity verified for {file_path}")
            return {"valid": True, "error": None}
        else:
            LOGGER.warning(f"File integrity verification failed for {file_path}.")
            return {"valid": False, "error": f"Invalid hash value {response.json()['hash']} from API."}

# Test the module with a sample file
if __name__ == "__main__":
    api_url = "https://example.com/api/v1/verify-file-integrity"
    utils = FileIntegrityUtils(api_url)
    result = utils.validate_file_integrity("/path/to/file")
    print(f"File integrity valid: {result['valid']}")
    if not result["valid"]:
        print(f"Error message: {result['error']}")
