using namespace std;

class FinancialTransaction {
    private:
        string date;
        double amount;
        int type;
        string description;

    public:
        FinancialTransaction(string date, double amount, int type, string description) {
            this->date = date;
            this->amount = amount;
            this->type = type;
            this->description = description;
        }

        void setDate(string date) {
            this->date = date;
        }

        void setAmount(double amount) {
            this->amount = amount;
        }

        void setType(int type) {
            this->type = type;
        }

        void setDescription(string description) {
            this->description = description;
        }

        string getDate() {
            return date;
        }

        double getAmount() {
            return amount;
        }

        int getType() {
            return type;
        }

        string getDescription() {
            return description;
        }
};

class FinancialTransactionManager {
    private:
        queue<FinancialTransaction> transactionQueue;
        mutex transactionMutex;
        condition_variable transactionCondVar;
        thread transactionProcessorThread;

        vector<string> pluginPaths;
        vector<unique_ptr<FinancialTransactionPlugin>> plugins;

        int maxConcurrentTransactions = 100;
        int concurrentTransactions = 0;

        bool isRunning = true;

    public:
        FinancialTransactionManager() {
            transactionProcessorThread = thread([this]() {
                while (isRunning) {
                    this->processNextTransaction();
                }
            });
        }

        ~FinancialTransactionManager() {
            isRunning = false;
            transactionProcessorThread.join();
        }

        void addTransaction(const FinancialTransaction& transaction) {
            unique_lock<mutex> lock(transactionMutex);
            transactionQueue.push(transaction);
            transactionCondVar.notify_one();
        }

        void removeTransaction(const string& id) {
            unique_lock<mutex> lock(transactionMutex);
            auto it = find_if(transactionQueue.begin(), transactionQueue.end(), [id](const FinancialTransaction& transaction) { return transaction.getId() == id; });
            if (it != transactionQueue.end()) {
                transactionQueue.erase(it);
            }
        }

        void loadPlugin(const string& pluginPath) {
            unique_ptr<FinancialTransactionPlugin> plugin = make_unique<FinancialTransactionPlugin>(pluginPath);
            plugins.push_back(move(plugin));
        }

        void unloadPlugin(const string& pluginPath) {
            for (auto it = plugins.begin(); it != plugins.end(); ++it) {
                if ((*it)->getPluginPath() == pluginPath) {
                    plugins.erase(it);
                    break;
                }
            }
        }

        void processNextTransaction() {
            unique_lock<mutex> lock(transactionMutex);
            while (concurrentTransactions >= maxConcurrentTransactions) {
                transactionCondVar.wait(lock);
            }
            if (!isRunning || transactionQueue.empty()) {
                return;
            }
            FinancialTransaction transaction = move(transactionQueue.front());
            transactionQueue.pop();
            concurrentTransactions++;
            lock.unlock();
            for (auto& plugin : plugins) {
                plugin->processTransaction(transaction);
            }
            lock.lock();
            concurrentTransactions--;
        }
};

class FinancialTransactionPlugin {
    private:
        string pluginPath;

    public:
        FinancialTransactionPlugin(const string& pluginPath) {
            this->pluginPath = pluginPath;
        }

        const string& getPluginPath() {
            return pluginPath;
        }

        virtual void processTransaction(FinancialTransaction& transaction) = 0;
};
```']

