void logMessage(int level, const char *message) {
    // Check if the message should be logged based on the current logging level
    if (level <= currentLoggingLevel) {
        printf("[%d] %s\n", level, message);
    }
}

// Define a function to load a resource bundle from a specified path
int loadResourceBundle(const char *path, void **bundle) {
    // Check if the path is valid and points to a file
    if (!path || !*path || access(path, F_OK)) {
        logMessage(LOG_LEVEL_ERROR, "Failed to load resource bundle: Invalid or non-existent path");
        return 1;
    }

    // Open the file and check for errors
    FILE *file = fopen(path, "r");
    if (!file) {
        logMessage(LOG_LEVEL_ERROR, "Failed to load resource bundle: %s", strerror(errno));
        return 1;
    }

    // Read the file and parse its contents
    char *buffer = malloc(BUFSIZ);
    size_t length = fread(buffer, 1, BUFSIZ, file);
    if (length == -1) {
        logMessage(LOG_LEVEL_ERROR, "Failed to load resource bundle: %s", strerror(errno));
        return 1;
    }

    // Close the file and check for errors
    int result = fclose(file);
    if (result == -1) {
        logMessage(LOG_LEVEL_ERROR, "Failed to close resource bundle file: %s", strerror(errno));
        return 1;
    }

    // Allocate memory for the resource bundle and populate it with the parsed data
    *bundle = malloc(length);
    memcpy(*bundle, buffer, length);
    free(buffer);

    // Return success
    return 0;
}
