#include <iostream>
#include <vector>
#include <string>
#include <map>
#include <fstream>
#include <sstream>
#include <chrono>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <memory>
#include <stdexcept>
#include <algorithm>

// Custom data structures for storing and processing data
struct DataPoint {
  double timestamp;
  int sensor_id;
  float temperature;
};

class DataStream {
 public:
  virtual ~DataStream() = default;
  virtual void add(const DataPoint& point) = 0;
  virtual std::vector<DataPoint> get_data() const = 0;
};

class RealTimeDataStream : public DataStream {
 private:
  std::vector<DataPoint> data_;
  std::mutex mutex_;
  std::condition_variable condition_;
  bool stop_;

 public:
  RealTimeDataStream() : stop_(false) {}
  ~RealTimeDataStream() override = default;
  void add(const DataPoint& point) override {
    std::lock_guard<std::mutex> lock(mutex_);
    data_.push_back(point);
    condition_.notify_all();
  }
  std::vector<DataPoint> get_data() const override {
    std::unique_lock<std::mutex> lock(mutex_);
    while (data_.empty()) {
      condition_.wait(lock);
    }
    return data_;
  }
  void stop() {
    stop_ = true;
  }
};

class BatchDataStream : public DataStream {
 private:
  std::vector<DataPoint> data_;
  mutable std::mutex mutex_;

 public:
  BatchDataStream(const std::vector<DataPoint>& data) : data_(data) {}
  ~BatchDataStream() override = default;
  void add(const DataPoint& point) override {
    std::lock_guard<std::mutex> lock(mutex_);
    data_.push_back(point);
  }
  std::vector<DataPoint> get_data() const override {
    return data_;
  }
};

class DataProcessor {
 private:
  // Map of data streams by sensor ID
  std::map<int, std::shared_ptr<DataStream>> streams_;
  // Vector of custom transformation functions
  std::vector<std::function<void(const DataPoint&)>> transformations_;
  // Mutex for synchronizing access to the processor
  std::mutex mutex_;
  // Flag indicating whether the processor is stopped
  bool stop_;

 public:
  DataProcessor() : stop_(false) {}
  ~DataProcessor() override = default;
  void add_stream(int sensor_id, const std::shared_ptr<DataStream>& stream) {
    streams_.emplace(sensor_id, stream);
  }
  void remove_stream(int sensor_id) {
    streams_.erase(sensor_id);
  }
  void add_transformation(const std::function<void(const DataPoint&)>& transformation) {
    transformations_.push_back(transformation);
  }
  void remove_transformation(int index) {
    if (index < transformations_.size()) {
      transformations_.erase(transformations_.begin() + index);
    }
  }
  // Process data from all streams and apply custom transformations
  void process() {
    std::unique_lock<std::mutex> lock(mutex_);
    if (stop_) return;
    for (const auto& stream : streams_) {
      const auto& sensor_id = stream.first;
      const auto& data = stream.second->get_data();
      for (const auto& point : data) {
        for (auto& transformation : transformations_) {
          transformation(point);
        }
      }
    }
  }
  void stop() {
    std::lock_guard<std::mutex> lock(mutex_);
    stop_ = true;
  }
};

class DataPipeline {
 private:
