#include <openssl/md5.h>

#define TOKEN_LENGTH 32
#define REFRESH_TOKEN_LENGTH 64
#define MAX_REQUESTS 1000

struct Token {
    char access_token[TOKEN_LENGTH];
    char refresh_token[REFRESH_TOKEN_LENGTH];
    time_t expires;
};

struct OAuth2Token {
    struct Token token;
    struct OAuth2Token *next;
};

int main(void) {
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("socket");
        return EXIT_FAILURE;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(80);
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

    if (connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("connect");
        return EXIT_FAILURE;
    }

    char buffer[1024];
    while (true) {
        int read = read(sock, buffer, sizeof(buffer));
        if (read <= 0) break;

        struct OAuth2Token *token = parse_token(buffer);
        if (token != NULL) {
            validate_token(token);
            free(token);
        }
    }

    close(sock);

    return EXIT_SUCCESS;
}

struct OAuth2Token *parse_token(const char *buffer) {
    struct OAuth2Token *token = (struct OAuth2Token *)malloc(sizeof(struct OAuth2Token));
    if (token == NULL) {
        perror("malloc");
        return NULL;
    }

    memset(token, 0, sizeof(struct OAuth2Token));
    token->token.access_token = (char *)malloc(TOKEN_LENGTH);
    if (token->token.access_token == NULL) {
        perror("malloc");
        free(token);
        return NULL;
    }
    memset(token->token.access_token, 0, TOKEN_LENGTH);

    token->token.refresh_token = (char *)malloc(REFRESH_TOKEN_LENGTH);
    if (token->token.refresh_token == NULL) {
        perror("malloc");
        free(token->token.access_token);
        free(token);
        return NULL;
    }
    memset(token->token.refresh_token, 0, REFRESH_TOKEN_LENGTH);

    char *access_token = strstr(buffer, "\"access_token\":\"");
    if (access_token != NULL) {
        access_token += sizeof("\"access_token\":\"") - 1;
        memcpy(token->token.access_token, access_token, TOKEN_LENGTH);
    }

    char *refresh_token = strstr(buffer, "\"refresh_token\":\"");
    if (refresh_token != NULL) {
        refresh_token += sizeof("\"refresh_token\":\"") - 1;
        memcpy(token->token.refresh_token, refresh_token, REFRESH_TOKEN_LENGTH);
    }

    char *expires = strstr(buffer, "\"expires_in\":");
    if (expires != NULL) {
        expires += sizeof("\"expires_in\":") - 1;
        token->token.expires = atoi(expires);
    }

    return token;
}

void validate_token(struct OAuth2Token *token) {
    if (strcmp(token->token.token_type, "Bearer") != 0) {
        fprintf(stderr, "Invalid token type: %s\n", token->token.token_type);
        return;
    }

    if (token->token.expires <= 0 || token->token.expires > 365 * 24 * 60 * 60) {
        fprintf(stderr, "Invalid expiration time: %ld\n", token->token.expires);
        return;
    }

    MD5_CTX ctx;
    MD5_Init(&ctx);
    MD5_Update(&ctx, token->token.access_token, TOKEN_LENGTH);
    MD5_Final(token->hash, &ctx);

    if (token->token.refresh_token != NULL) {
        if (!is_base64(token->token.refresh_token)) {
            fprintf(stderr, "Invalid refresh token: %s\n", token->token.refresh_token);
            return;
        }
    }
}

bool is_base64(const char *string) {
    const size_t len = strlen(string);
    for (size_t i = 0; i < len; ++i) {
        if (!isxdigit(string[i]) && string[i] != '+' && string[i] != '/' && string[i] != '=' && string[i] != ' ') {
            return false;
        }
    }

    return true;
}
```

This code uses the `read()` function to read data from a socket, and then uses the `parse_token()` function to parse the received data into an `OAuth2Token` structure. If the token is valid, it is then passed to the `validate_token()` function to check if it's valid. The `is_base64()` function checks if a given string is in base64 format or not.

The `parse_token()` function uses the `strstr()` and `memcpy()` functions to extract the access token, refresh token and expiration time from the received data. It then uses the `malloc()` function to allocate memory for the `OAuth2Token` structure and initializes it with the extracted values.

The `validate_token()` function checks if the received token is valid by checking if it's of type "Bearer", has a valid expiration time (between 1 day and 365 days), and that the access token and refresh token are in base64 format. If any of these conditions are not met, it returns an error message to the client.

The `is_base64()` function uses the `isxdigit()` function to check if a given string is in base64 format or not. It first checks if all the characters in the string are hexadecimal digits (i.e. 0-9, A-F) and then checks if the string contains only valid base64 characters (i.e. A-Z, a-z, 0-9, +, /, =, or space).

Note that this is just an example code and you should always validate user input to prevent any potential security issues.']

