#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <fstream>
#include <chrono>
#include <thread>

using namespace std;

// Define the supported cryptographic hash algorithms
enum class HashAlgorithm { MD5, SHA256 };

// Define the cloud storage providers and their respective API versions
struct CloudProvider {
  string name; // e.g., "Amazon S3", "Google Cloud Storage", etc.
  int apiVersion; // e.g., 1 for v1, 2 for v2, etc.
};

// Define the file metadata structure
struct FileMetadata {
  string path;
  size_t size;
  HashAlgorithm hashAlgorithm;
};

// Define the cloud storage API interface
class CloudStorageAPI {
 public:
  virtual ~CloudStorageAPI() {}
  virtual void uploadFile(const string& filePath, const string& remotePath) = 0;
  virtual void downloadFile(const string& remotePath, const string& filePath) = 0;
  virtual size_t getFileSize(const string& remotePath) = 0;
  virtual HashAlgorithm getHashAlgorithm() = 0;
};

// Define the file verification module
class FileVerifier {
 public:
  // Constructor
  FileVerifier(vector<CloudProvider> providers, unordered_map<string, CloudStorageAPI*> apis) : providers_(providers), apis_(apis) {}

  // Upload a file to all supported cloud storage providers
  void uploadFile(const string& localPath) {
    for (CloudProvider provider : providers_) {
      apis_[provider.name]->uploadFile(localPath, provider.apiVersion);
    }
  }

  // Download a file from all supported cloud storage providers
  void downloadFile(const string& remotePath) {
    for (CloudProvider provider : providers_) {
      apis_[provider.name]->downloadFile(remotePath, provider.apiVersion);
    }
  }

  // Calculate the hash of a file using the specified algorithm
  HashAlgorithm getHash(const string& path) {
    ifstream stream;
    stream.open(path, ios::binary | ios::in);

    if (!stream.is_open()) {
      throw runtime_error("Unable to open file");
    }

    HashAlgorithm hashAlgorithm = providers_.front().hashAlgorithm;

    switch (hashAlgorithm) {
      case HashAlgorithm::MD5:
        return md5(stream);
      case HashAlgorithm::SHA256:
        return sha256(stream);
      default:
        throw runtime_error("Unsupported hash algorithm");
    }
  }

 private:
  // Calculate the MD5 hash of a file
  string md5(ifstream& stream) {
    const int BUFFER_SIZE = 1024;
    char buffer[BUFFER_SIZE];
    MD5_CTX context;
    MD5Init(&context);

    while (stream.read(buffer, BUFFER_SIZE)) {
      MD5Update(&context, buffer, stream.gcount());
    }

    MD5Final(buffer, &context);

    return string(buffer, 16); // 16 bytes for MD5 hash
  }

  // Calculate the SHA256 hash of a file
  string sha256(ifstream& stream) {
    const int BUFFER_SIZE = 1024;
    char buffer[BUFFER_SIZE];
    SHA256_CTX context;
    SHA256Init(&context);

    while (stream.read(buffer, BUFFER_SIZE)) {
      SHA256Update(&context, buffer, stream.gcount());
    }

    SHA256Final(buffer, &context);

    return string(buffer, 32); // 32 bytes for SHA256 hash
  }

  vector<CloudProvider> providers_; // Supported cloud storage providers
  unordered_map<string, CloudStorageAPI*> apis_; // API interfaces for each provider
};

int main() {
  // Define the supported cloud storage providers and their respective API versions
  vector<CloudProvider> providers = {{"Amazon S3", 1}, {"Google Cloud Storage", 2}};

  // Initialize the cloud storage APIs
  unordered_map<string, CloudStorageAPI*> apis;
  for (CloudProvider provider : providers) {
    // Create an instance of the API interface for each provider
    CloudStorageAPI* api = new CloudStorageAPI(provider.name, provider.apiVersion);
    apis[provider.name] = api;
  }

  // Define the file metadata structure
  FileMetadata file1 = {"/path/to/file1", 1024, HashAlgorithm::MD5};
  FileMetadata file2 = {"/path/to/file2", 512, HashAlgorithm::SHA256};
  vector<FileMetadata> files = {file1, file2};

  // Create an instance of the file verifier
  FileVerifier verifier(providers, apis);

  // Verify the hashes of the files against the cloud storage providers
  for (FileMetadata file : files) {
    verifier.uploadFile(file.path);
    cout << "Uploaded file to cloud storage: " << file.path << endl;
    string remotePath = verifier.downloadFile(file.path);
    cout << "Downloaded file from cloud storage: " << remotePath << endl;
    HashAlgorithm hashAlgorithm = verifier.getHash(file.path);
    cout << "Calculated hash of file: " << hashAlgorithm << endl;
  }

  return 0;
}
```

This program will upload the specified files to all supported cloud storage providers, download them back from the cloud storage providers, and calculate the hashes of the files using the specified algorithm. The output will show which files have been uploaded and downloaded successfully, as well as the calculated hashes of each file.

Please note that this is just a sample program and you should adapt it to your specific needs. For example, you may need to modify the code to handle errors, implement additional features, or use different data structures.']

