#include "traffic_manager.h"

// Define constants for retention policy
const int EVENTS_PER_SECOND = 10000;
const int MIN_RETENTION_TIME = 60; // seconds
const int MAX_RETENTION_SIZE = 1000; // number of events

// Define functions for managing TrafficManager
void traffic_manager_init(TrafficManager* manager) {
    manager->events = NULL;
    manager->numEvents = 0;
    manager->maxNumEvents = MAX_RETENTION_SIZE;
}

void traffic_manager_add_event(TrafficManager* manager, const char* deviceID, long long timestamp, int eventType) {
    // Check if the event should be added to the array
    if (manager->numEvents >= manager->maxNumEvents || (int)timestamp % EVENTS_PER_SECOND != 0) {
        return;
    }

    // Allocate memory for the new event
    TrafficEvent* newEvent = malloc(sizeof(TrafficEvent));
    if (!newEvent) {
        return;
    }

    // Copy the data from the input parameters into the new event
    strcpy(newEvent->deviceID, deviceID);
    newEvent->timestamp = timestamp;
    newEvent->eventType = eventType;

    // Add the new event to the array
    manager->events[manager->numEvents++] = newEvent;
}

void traffic_manager_get_events(TrafficManager* manager, TrafficEvent** events, int numEvents) {
    // Check if there are enough events in the array
    if (manager->numEvents < numEvents) {
        return;
    }

    // Copy the necessary number of events from the array to the output parameter
    for (int i = 0; i < numEvents; i++) {
        events[i] = manager->events[manager->numEvents - i - 1];
    }
}

void traffic_manager_destroy(TrafficManager* manager) {
    // Free the memory allocated for the array of TrafficEvents
    free(manager->events);
}
