    FILE* fp = fopen(filename, "rb");
    if (!fp) {
        printf("Error: failed to open input file %s\n", filename);
        return;
    }

    // Initialize variables for parsing the file
    char buffer[BUFFER_SIZE];
    int numBytes = 0;
    int numEventsParsed = 0;

    // Loop through the file line by line
    while (fgets(buffer, BUFFER_SIZE, fp)) {
        // Parse each line of the file according to the transformation rules
        TrafficEvent* event = parse_line(buffer);
        if (event) {
            events[numEventsParsed++] = event;
        }
    }

    // Close the input file
    fclose(fp);
}

// Function to parse a single line of the binary file containing transformation rules
TrafficEvent* parse_line(const char* buffer) {
    // Initialize variables for parsing the line
    TrafficEvent* event = NULL;
    int numBytes = 0;

    // Check if the line is empty or comment
    if (buffer[numBytes] == '\n' || buffer[numBytes] == '#') {
        return NULL;
    }

    // Allocate memory for the new event
    event = malloc(sizeof(TrafficEvent));
    if (!event) {
        printf("Error: failed to allocate memory for a TrafficEvent\n");
        return NULL;
    }

    // Parse each field of the event according to the transformation rules
    char* token = strtok(buffer, " \t\r\n");
    while (token) {
        if (!strcmp(token, "${DEVICE_ID}")) {
            numBytes += strlen(token);
            token = strtok(NULL, " \t\r\n");
            event->deviceID = strdup(token);
        } else if (!strcmp(token, "${TIMESTAMP}")) {
            numBytes += strlen(token);
            token = strtok(NULL, " \t\r\n");
            event->timestamp = (long)strtol(token, NULL, 10);
        } else if (!strcmp(token, "${EVENT_TYPE}")) {
            numBytes += strlen(token);
            token = strtok(NULL, " \t\r\n");
            event->eventType = (int)strtol(token, NULL, 10);
        } else {
            // The line contains an unknown field, ignore it
            return NULL;
        }
    }

    // Check if all fields of the event are parsed correctly
    if (!event->deviceID || !event->timestamp || !event->eventType) {
        printf("Error: failed to parse a TrafficEvent\n");
        free(event);
        return NULL;
    }

    // Return the parsed event
    return event;
}

// Function to write the transformed traffic data to an output file
void write_output(const char* filename, TrafficEvent** events, int numEvents) {
    // Open the output file in text mode
    FILE* fp = fopen(filename, "wt");
    if (!fp) {
        printf("Error: failed to open output file %s\n", filename);
        return;
    }

    // Loop through the array of TrafficEvents and write each event to the output file
    for (int i = 0; i < numEvents; i++) {
        fprintf(fp, "%s %ld %d\n", events[i]->deviceID, events[i]->timestamp, events[i]->eventType);
    }

    // Close the output file
    fclose(fp);
}
