// Modular, scalable, and resilient C++ framework for managing user sessions
#include <iostream>
#include <map>
#include <memory>
#include <string>
#include <vector>

class UserSession {
public:
    // Constructor
    UserSession(const std::string& sessionID, const std::string& userIP, int loginTime, int lastActivityTimestamp, bool activeStatus, int sessionExpirationSettings) : sessionID_(sessionID), userIP_(userIP), loginTime_(loginTime), lastActivityTimestamp_(lastActivityTimestamp), activeStatus_(activeStatus), sessionExpirationSettings_(sessionExpirationSettings) {}

    // Getters and setters for session ID, user IP address, login time, last activity timestamp, active status, and session expiration settings
    const std::string& getSessionID() const { return sessionID_; }
    void setSessionID(const std::string& sessionID) { sessionID_ = sessionID; }

    const std::string& getUserIP() const { return userIP_; }
    void setUserIP(const std::string& userIP) { userIP_ = userIP; }

    int getLoginTime() const { return loginTime_; }
    void setLoginTime(int loginTime) { loginTime_ = loginTime; }

    int getLastActivityTimestamp() const { return lastActivityTimestamp_; }
    void setLastActivityTimestamp(int lastActivityTimestamp) { lastActivityTimestamp_ = lastActivityTimestamp; }

    bool isActiveStatus() const { return activeStatus_; }
    void setActiveStatus(bool activeStatus) { activeStatus_ = activeStatus; }

    int getSessionExpirationSettings() const { return sessionExpirationSettings_; }
    void setSessionExpirationSettings(int sessionExpirationSettings) { sessionExpirationSettings_ = sessionExpirationSettings; }

private:
    std::string sessionID_;
    std::string userIP_;
    int loginTime_;
    int lastActivityTimestamp_;
    bool activeStatus_;
    int sessionExpirationSettings_;
};

class UserSessionManager {
public:
    // Constructor
    UserSessionManager() {}

    // Add a new user session to the manager
    void addUserSession(const std::string& sessionID, const std::string& userIP) {
        userSessions_.insert({sessionID, std::make_shared<UserSession>(sessionID, userIP)});
    }

    // Remove a user session from the manager
    void removeUserSession(const std::string& sessionID) {
        userSessions_.erase(sessionID);
    }

    // Update the login time for a user session
    void updateLoginTime(const std::string& sessionID, int newLoginTime) {
        auto it = userSessions_.find(sessionID);
        if (it != userSessions_.end()) {
            it->second->setLoginTime(newLoginTime);
        } else {
            throw std::runtime_error("Session ID not found");
        }
    }

    // Update the last activity timestamp for a user session
    void updateLastActivityTimestamp(const std::string& sessionID, int newLastActivityTimestamp) {
        auto it = userSessions_.find(sessionID);
        if (it != userSessions_.end()) {
            it->second->setLastActivityTimestamp(newLastActivityTimestamp);
        } else {
            throw std::runtime_error("Session ID not found");
        }
    }

    // Update the active status for a user session
    void updateActiveStatus(const std::string& sessionID, bool newActiveStatus) {
        auto it = userSessions_.find(sessionID);
        if (it != userSessions_.end()) {
            it->second->setActiveStatus(newActiveStatus);
        } else {
            throw std::runtime_error("Session ID not found");
        }
    }

    // Update the session expiration settings for a user session
    void updateSessionExpirationSettings(const std::string& sessionID, int newSessionExpirationSettings) {
        auto it = userSessions_.find(sessionID);
        if (it != userSessions_.end()) {
            it->second->setSessionExpirationSettings(newSessionExpirationSettings);
        } else {
            throw std::runtime_error("Session ID not found");
        }
    }

private:
    // Map of user sessions, keyed by session ID
    std::map<std::string, std::shared_ptr<UserSession>> userSessions_;
};
