#include <iostream>
#include <string>
#include <vector>
#include <cmath>
#include <ctime>

using namespace std;

class IoTDevice {
public:
    string deviceId;
    vector<double> sensorData;
    double currentTemperature;
    double averageTemperature;
    double maximumTemperature;
    double minimumTemperature;
    time_t timestamp;

    IoTDevice(string id) {
        deviceId = id;
        sensorData.reserve(1000);
        currentTemperature = 0.0;
        averageTemperature = 0.0;
        maximumTemperature = -std::numeric_limits<double>::infinity();
        minimumTemperature = std::numeric_limits<double>::infinity();
    }

    void addSensorData(double temperature) {
        sensorData.push_back(temperature);
        currentTemperature = temperature;
        averageTemperature += temperature / sensorData.size();
        maximumTemperature = max(maximumTemperature, temperature);
        minimumTemperature = min(minimumTemperature, temperature);
    }

    void computeAverage() {
        if (sensorData.empty()) return;

        averageTemperature /= sensorData.size();
    }

    void clearSensorData() {
        sensorData.clear();
        currentTemperature = 0.0;
        averageTemperature = 0.0;
        maximumTemperature = -std::numeric_limits<double>::infinity();
        minimumTemperature = std::numeric_limits<double>::infinity();
    }
};

class IoTNetwork {
public:
    string networkId;
    vector<IoTDevice> devices;

    IoTNetwork(string id) {
        networkId = id;
        devices.reserve(1000);
    }

    void addDevice(string deviceId) {
        devices.emplace_back(deviceId);
    }

    void removeDevice(string deviceId) {
        for (auto it = devices.begin(); it != devices.end(); ++it) {
            if (it->deviceId == deviceId) {
                devices.erase(it);
                break;
            }
        }
    }

    void clearDevices() {
        devices.clear();
    }
};

class IoTSystem {
public:
    vector<IoTNetwork> networks;

    IoTSystem() {
        networks.reserve(100);
    }

    void addNetwork(string networkId) {
        networks.emplace_back(networkId);
    }

    void removeNetwork(string networkId) {
        for (auto it = networks.begin(); it != networks.end(); ++it) {
            if (it->networkId == networkId) {
                networks.erase(it);
                break;
            }
        }
    }

    void clearNetworks() {
        networks.clear();
    }
};

int main() {
    IoTSystem system;
    string deviceId, networkId, sensorData;
    double temperature;

    while (true) {
        cout << "Enter device ID: ";
        cin >> deviceId;
        if (deviceId == "") break;

        cout << "Enter network ID: ";
        cin >> networkId;

        cout << "Enter sensor data: ";
        cin >> sensorData;

        istringstream(sensorData) >> temperature;

        IoTDevice device(deviceId);
        device.addSensorData(temperature);
        system.networks[0].devices.emplace_back(device);
    }

    return 0;
}
```
