const fetchScripts = async (apiUrls) => {
  const scriptObjects = [];
  for (const apiUrl of apiUrls) {
    try {
      const response = await fetch(apiUrl);
      if (!response.ok) {
        throw new Error(`Failed to fetch scripts from ${apiUrl}`);
      }
      scriptObjects.push(...await response.json());
    } catch (error) {
      console.log(`Error fetching scripts from ${apiUrl}: ${error}`);
    }
  }
  return scriptObjects;
};

const transformScripts = (scriptObjects, cache) => {
  const transformedScripts = [];
  for (const scriptObject of scriptObjects) {
    const key = scriptObject.id || Math.random().toString(36).substring(2);
    if (!cache[key]) {
      cache[key] = scriptObject;
    }
    transformedScripts.push(`<script key="${key}">${scriptObject.code}</script>`);
  }
  return transformedScripts;
};

const renderFooter = (transformedScripts) => {
  const footerHtml = `<footer>
    <h2>Powered by our modular JavaScript service</h2>
    ${transformedScripts.join('')}
  </footer>`;
  return footerHtml;
};

