        throw new Error(`Failed to fetch scripts from ${apiUrl}`);
      }
      scriptObjects = [...scriptObjects, ...await response.json()];
    } catch (error) {
      console.log(`Error fetching scripts from ${apiUrl}: ${error}`);
    }
  }
  const transformedScripts = transformScripts(scriptObjects, cache);
  return renderFooter(transformedScripts);
};

const service = async (input) => {
  if (!Array.isArray(input)) {
    throw new Error('Input must be an array');
  }
  const apiUrls = input.map((item) => item.url);
  const scriptObjects = await fetchScripts(apiUrls);
  const transformedScripts = transformScripts(scriptObjects, cache);
  return renderFooter(transformedScripts);
};
```
