// C-based component for managing a list of NFAPI_CRC_INDICATION_PDU_T structures
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <pthread.h>
#include <errno.h>
#include <stdio.h>

// Define the structure for an NFAPI_CRC_INDICATION_PDU_T element in the list
typedef struct {
    RX_UE_INFORMATION_TAG rxUeInformationTag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
    bool crcFlag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the list structure and its associated functions
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *list; // Array of elements in the list
    int size; // Current size of the list
    pthread_mutex_t mutex; // Mutex for synchronizing access to the list
} LIST;

// Function to initialize a new list
void initList(LIST **list) {
    *list = (LIST*) malloc(sizeof(LIST));
    if (*list == NULL) {
        printf("Error: could not allocate memory for list\n");
        exit(1);
    }
    (*list)->size = 0;
    pthread_mutex_init(&(*list)->mutex, NULL);
}

// Function to add a new element to the end of the list
void addElementToList(LIST *list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->mutex);
    // Grow the list if it is full
    if (list->size == 0 || list->size % 10 == 0) {
        int newSize = list->size + 10;
        NFAPI_CRC_INDICATION_PDU_T *newList = (NFAPI_CRC_INDICATION_PDU_T*) realloc(list->list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * newSize);
        if (newList == NULL) {
            printf("Error: could not allocate memory for list\n");
            exit(1);
        }
        list->list = newList;
        list->size = newSize;
    }
    // Add the new element to the end of the list
    list->list[list->size++] = element;
    pthread_mutex_unlock(&list->mutex);
}

// Function to remove an element from the list based on its index
void removeElementFromList(LIST *list, int index) {
    pthread_mutex_lock(&list->mutex);
    // Check if the index is valid
    if (index < 0 || index >= list->size) {
        printf("Error: invalid index for removing element from list\n");
        exit(1);
    }
    // Shift all elements after the specified index to the left
    int i;
    for (i = index + 1; i < list->size; i++) {
        list->list[i - 1] = list->list[i];
    }
    list->size--;
    pthread_mutex_unlock(&list->mutex);
}

// Function to retrieve an element from the list based on its index
NFAPI_CRC_INDICATION_PDU_T getElementFromList(LIST *list, int index) {
    NFAPI_CRC_INDICATION_PDU_T element;
    pthread_mutex_lock(&list->mutex);
    // Check if the index is valid
    if (index < 0 || index >= list->size) {
        printf("Error: invalid index for retrieving element from list\n");
        exit(1);
    }
    element = list->list[index];
    pthread_mutex_unlock(&list->mutex);
    return element;
}

// Function to check if an element is present in the list based on its index
bool isElementInList(LIST *list, int index) {
    bool present = false;
    pthread_mutex_lock(&list->mutex);
    // Check if the index is valid
    if (index < 0 || index >= list->size) {
        printf("Error: invalid index for checking element in list\n");
        exit(1);
    }
    present = true;
    pthread_mutex_unlock(&list->mutex);
    return present;
}

// Function to free the memory of the list
void freeList(LIST **list) {
    if (*list == NULL) {
        return;
    }
    pthread_mutex_destroy(&(*list)->mutex);
    free((*list)->list);
    free(*list);
    *list = NULL;
}

// Function to handle memory allocation failures and other errors
void errorHandler(int err) {
    printf("Error: %s\n", strerror(err));
    exit(1);
}

// Main function for demonstration purposes
int main() {
    LIST *list = NULL;
    initList(&list);
    // Add some elements to the list
    NFAPI_CRC_INDICATION_PDU_T element1 = {0, 1234, 0};
    addElementToList(list, element1);
    NFAPI_CRC_INDICATION_PDU_T element2 = {0, 5678, 0};
    addElementToList(list, element2);
    // Remove an element from the list based on its index
    removeElementFromList(list, 0);
    // Check if an element is present in the list based on its index
    bool present = isElementInList(list, 1);
    printf("Is element at index 1 present? %s\n", present ? "Yes" : "No");
    // Retrieve an element from the list based on its index
    NFAPI_CRC_INDICATION_PDU_T retrievedElement = getElementFromList(list, 0);
    printf("Retrieved element: %d\n", retrievedElement.rnti);
    // Free the memory of the list
    freeList(&list);
    return 0;
}']

