class Account:
    user_id: str
    balance: float

class UserNotFoundError(Exception):
    pass

class AccountNotFoundError(Exception):
    pass

def create_user(user: User) -> None:
    # Simulate a slow database write operation.
    time.sleep(1)
    logging.info("User created with ID %s", user.id)

def get_user(user_id: str) -> Optional[User]:
    # Simulate a slow database read operation.
    time.sleep(0.5)
    if user_id in ["1234567890", "2345678901"]:
        return User(id="1234567890", name="John Doe", email="johndoe@example.com", password="password")
    else:
        raise UserNotFoundError("User not found.")

def get_account(user_id: str, account_id: Optional[str] = None) -> Optional[Account]:
    # Simulate a slow database read operation.
    time.sleep(0.5)
    if user_id in ["1234567890", "2345678901"]:
        if account_id is None:
            return Account(user_id="1234567890", balance=100.0)
        elif account_id == "1":
            return Account(user_id="1234567890", balance=50.0)
        else:
