    time.sleep(1)
    logging.info("Account updated with ID %s and balance %s", user_id, balance)

@app.post("/users")
async def create_user_endpoint(user: User):
    create_user(user)
    return JSONResponse({"message": "User created successfully."}, status_code=201)

@app.get("/users/{user_id}")
async def get_user_endpoint(user_id: str):
    user = get_user(user_id)
    if user is None:
        return JSONResponse({"message": "User not found."}, status_code=404)
    else:
        return JSONResponse(user.to_dict(), status_code=200)

@app.get("/users/{user_id}/accounts")
async def get_accounts_endpoint(user_id: str):
    accounts = [{"id": "1", "balance": 50.0}, {"id": "2", "balance": 25.0}]
    return JSONResponse(accounts, status_code=200)

@app.get("/users/{user_id}/accounts/{account_id}")
async def get_account_endpoint(user_id: str, account_id: str):
    account = get_account(user_id, account_id)
    if account is None:
        return JSONResponse({"message": "Account not found."}, status_code=404)
    else:
        return JSONResponse(account.to_dict(), status_code=200)

@app.put("/users/{user_id}/accounts/{account_id}")
async def update_account_endpoint(user_id: str, account_id: str, balance: float):
    try:
        update_account(user_id, account_id, balance)
        return JSONResponse({"message": "Account updated successfully."}, status_code=201)
    except UserNotFoundError as e:
        return JSONResponse({"message": str(e)}, status_code=404)
    except AccountNotFoundError as e:
        return JSONResponse({"message": str(e)}, status_code=404)
