```typescript
import { DomTraverse } from './dom-traverse';
import { FileService } from './file-service';
import { ConfigurationService } from './configuration-service';
import { Record } from './record';

class DomTraverseLib {
  private readonly domTraverse: DomTraverse;
  private readonly fileService: FileService;
  private readonly configurationService: ConfigurationService;

  constructor(domTraverse: DomTraverse, fileService: FileService, configurationService: ConfigurationService) {
    this.domTraverse = domTraverse;
    this.fileService = fileService;
    this.configurationService = configurationService;
  }

  async modifyFileAndInitializeRecords(filename: string): Promise<Record[]> {
    const fileConfig = await this.configurationService.getFileConfig(filename);
    if (!fileConfig) {
      throw new Error(`Invalid configuration for file ${filename}`);
    }

    const { type, range } = fileConfig;
    const records: Record[] = [];

    // Dynamically retrieve file data from the external service
    const fileData = await this.fileService.getFileData(filename);
    if (!fileData) {
      throw new Error(`Failed to retrieve file data for ${filename}`);
    }

    // Initialize arrays for 'long' offset values, 'int' keys, and 'record' structures with values within the specified range
    const longOffsets: number[] = [];
    const intKeys: number[] = [];
    const recordStructs: Record[] = [];

    // Append a sequence of random digits to the filename's extension based on the file type and ensure the appended digits match half the length of the filename's name part (rounded up)
    const extension = `${type}-${Math.floor(Math.random() * 10 ** (filename.length - filename.lastIndexOf('.')))}`;
    const updatedFilename = `${filename}${extension}`;

    // Iterate over the file data and initialize records
    for (let i = 0; i < fileData.length; i++) {
      const record: Record = {
        longOffset: Math.floor(Math.random() * range.long),
        intKey: Math.floor(Math.random() * range.int),
        struct: {
          id: i,
          name: `${filename} ${i}`,
          value: fileData[i]
        }
      };
      longOffsets.push(record.longOffset);
      intKeys.push(record.intKey);
      recordStructs.push(record);
    }

    // Handle memory allocation failures, invalid configurations, and unexpected external service responses
    if (records.length === 0) {
      throw new Error(`Failed to initialize records for ${filename}`);
    }

    return records;
  }
}
