#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <chrono>
#include <vector>
#include <future>

struct UserSession {
    std::string userName;
    int connectionStatus;
    long lastActivityTimestamp;
    std::string userMetadata;
};

struct SessionStats {
    std::string sessionId;
    int connectionStatus;
    long lastActivityTimestamp;
    std::string userMetadata;
};

class RegistryManager {
public:
    static constexpr size_t MAX_ENTRIES = 10000000;

    void updateSession(const UserSession& session) {
        // Lock the registry mutex to prevent race conditions during updates.
        std::lock_guard<std::mutex> lock(registryMutex);

        // Check if the entry already exists in the registry.
        auto it = std::find_if(registry.begin(), registry.end(), [&](const UserSession& s) { return s.userName == session.userName; });
        if (it != registry.end()) {
            *it = session;
        } else {
            // If the entry doesn't exist, add it to the end of the vector.
            registry.push_back(session);
        }
    }

    void updateSessionStats(const SessionStats& stats) {
        // Lock the registry mutex to prevent race conditions during updates.
        std::lock_guard<std::mutex> lock(registryMutex);

        // Check if the entry already exists in the registry.
        auto it = std::find_if(sessionStats.begin(), sessionStats.end(), [&](const SessionStats& s) { return s.sessionId == stats.sessionId; });
        if (it != sessionStats.end()) {
            *it = stats;
        } else {
            // If the entry doesn't exist, add it to the end of the vector.
            sessionStats.push_back(stats);
        }
    }

private:
    std::mutex registryMutex;
    std::vector<UserSession> registry;
    std::vector<SessionStats> sessionStats;
};

class SessionManager {
public:
    SessionManager() : sessionId_(0) {}

    int updateSession(const UserSession& session) {
        // Acquire a lock on the session mutex to prevent race conditions during updates.
        std::lock_guard<std::mutex> lock(sessionMutex);

        // Check if the session already exists in the map.
        auto it = sessions_.find(session.userName);
        if (it != sessions_.end()) {
            return updateExistingSession(*it, session);
        } else {
            return createNewSession(session);
        }
    }

private:
    std::mutex sessionMutex;
    std::map<std::string, UserSession> sessions_;
    int sessionId_;

    int updateExistingSession(UserSession& existingSession, const UserSession& newSession) {
        // Check if the user metadata has changed.
        if (newSession.userMetadata != existingSession.userMetadata) {
            // If it has changed, update the session metadata and set the last activity timestamp to the current time.
            existingSession.userMetadata = newSession.userMetadata;
            existingSession.lastActivityTimestamp = std::chrono::steady_clock::now().time_since_epoch().count();
        } else {
            // If it hasn't changed, update the connection status and set the last activity timestamp to the current time.
            existingSession.connectionStatus = newSession.connectionStatus;
            existingSession.lastActivityTimestamp = std::chrono::steady_clock::now().time_since_epoch().count();
        }
    }

    int createNewSession(const UserSession& session) {
        // Acquire a lock on the session mutex to prevent race conditions during updates.
        std::lock_guard<std::mutex> lock(sessionMutex);

        // Add the new session to the map and set its ID to the next available value.
        sessions_.insert({session.userName, session});
        sessionId_++;

        return sessionId_;
    }
};

class SessionStatsManager {
public:
    void updateSessionStats(const SessionStats& stats) {
        // Acquire a lock on the session mutex to prevent race conditions during updates.
        std::lock_guard<std::mutex> lock(sessionMutex);

        // Check if the entry already exists in the map.
        auto it = sessions_.find(stats.sessionId);
        if (it != sessions_.end()) {
            updateExistingSessionStats(*it, stats);
        } else {
            createNewSessionStats(stats);
        }
    }

private:
    std::mutex sessionMutex;
    std::map<int, SessionStats> sessions_;

    void updateExistingSessionStats(SessionStats& existingStats, const SessionStats& newStats) {
        // Check if the session has been idle for too long.
        if (std::chrono::steady_clock::now().time_since_epoch().count() - existingStats.lastActivityTimestamp > 60000) {
            // If it has, remove the entry from the map.
            sessions_.erase(existingStats);
        } else {
            // Otherwise, update the connection status and set the last activity timestamp to the current time.
            existingStats.connectionStatus = newStats.connectionStatus;
            existingStats.lastActivityTimestamp = std::chrono::steady_clock::now().time_since_epoch().count();
        }
    }

    void createNewSessionStats(const SessionStats& stats) {
        // Acquire a lock on the session mutex to prevent race conditions during updates.
        std::lock_guard<std::mutex> lock(sessionMutex);

        // Add the new session statistics to the map.
        sessions_.insert({stats.sessionId, stats});
    }
};

int main() {
    Registry registry;

    // Create a new session manager and add it to the registry.
    SessionManager* sessionManager = new SessionManager();
    registry.addSessionManager(sessionManager);

    // Create a new session stats manager and add it to the registry.
    SessionStatsManager* sessionStatsManager = new SessionStatsManager();
    registry.addSessionStatsManager(sessionStatsManager);

    // Create a new user session and update it in the session manager.
    UserSession session;
    session.userName = "John Doe";
    session.connectionStatus = 1;
    session.lastActivityTimestamp = std::chrono::steady_clock::now().time_since_epoch().count();
    registry.getSessionManager()->updateSession(session);

    // Update the user session and statistics in the session managers.
    UserSession updatedSession;
    updatedSession.userName = "John Doe";
    updatedSession.connectionStatus = 2;
    updatedSession.lastActivityTimestamp = std::chrono::steady_clock::now().time_since_epoch().count();
    registry.getSessionManager()->updateSession(updatedSession);

    SessionStats updatedStats;
    updatedStats.sessionId = session.id;
    updatedStats.connectionStatus = 2;
    updatedStats.lastActivityTimestamp = std::chrono::steady_clock::now().time_since_epoch().count();
    registry.getSessionStatsManager()->updateSessionStats(updatedStats);

    // Remove the user session and statistics from the session managers.
    registry.getSessionManager()->removeSession(session.id);
    registry.getSessionStatsManager()->removeSession(session.id);

    return 0;
}
```

In this example, we have a `Registry` class that stores multiple instances of different types of managers (e.g., session managers and session statistics managers). Each manager has its own set of methods for adding, removing, and updating entries in the registry.

We create an instance of each manager class and add it to the registry. We then create a new user session and update it in both the session manager and the session statistics manager. Finally, we remove the user session and statistics from the registry.

Note that this is just one possible way to design a registry system. Depending on your specific requirements, you may need to add additional functionality or change the architecture of the registry to better suit your needs.']

['// C++ implementation of a scalable, modular registry system for managing user sessions and session statistics

#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <mutex>
#include <chrono>
#include <thread>
#include <condition_variable>

using namespace std;

// Struct to represent a user session
struct UserSession {
    int id;
    string username;
    string ipAddress;
    bool online;
};

// Struct to represent session statistics
struct SessionStats {
    int totalSessions;
    int activeSessions;
    int inactiveSessions;
};

// Vector of user sessions, synchronized using a mutex
vector<UserSession> sessions;

// Map of user IDs to their corresponding session indices, synchronized using a mutex
unordered_map<int, size_t> idToIndexMap;

// Mutex for protecting access to the vector and map data structures
mutex sessionsMutex;

// Condition variable to signal updates in the vector or map
condition_variable updateCondVar;

// Function to add a new user session
void addSession(int id, string username, string ipAddress) {
    // Acquire the lock on the sessions data structure
    unique_lock<mutex> lock(sessionsMutex);

    // Create a new user session object and push it to the vector
    UserSession session = {id, username, ipAddress, true};
    sessions.push_back(session);

    // Update the map of IDs to indices
    idToIndexMap[id] = sessions.size() - 1;

    // Release the lock on the data structure
    lock.unlock();

    // Notify any waiting threads that an update has occurred
    updateCondVar.notify_all();
}

// Function to remove a user session
void removeSession(int id) {
    // Acquire the lock on the sessions data structure
    unique_lock<mutex> lock(sessionsMutex);

    // Check if the ID exists in the map
    auto it = idToIndexMap.find(id);
    if (it != idToIndexMap.end()) {
        // If so, remove the corresponding session from the vector and update the map
        sessions.erase(sessions.begin() + it->second);
        idToIndexMap.erase(it);
    }

    // Release the lock on the data structure
    lock.unlock();

    // Notify any waiting threads that an update has occurred
    updateCondVar.notify_all();
}

// Function to retrieve session statistics for a given ID
SessionStats getSessionStats(int id) {
    SessionStats stats;

    // Acquire the lock on the sessions data structure
    unique_lock<mutex> lock(sessionsMutex);

    // Check if the ID exists in the map
    auto it = idToIndexMap.find(id);
    if (it != idToIndexMap.end()) {
        // If so, retrieve the corresponding session from the vector and update the statistics
        stats.totalSessions++;
        stats.activeSessions += sessions[it->second].online;
        stats.inactiveSessions += !sessions[it->second].online;
    }

    // Release the lock on the data structure
    lock.unlock();

    return stats;
}

// Function to update the status of a user session (e.g., whether it is online or offline)
void updateSessionStatus(int id, bool online) {
    // Acquire the lock on the sessions data structure
    unique_lock<mutex> lock(sessionsMutex);

    // Check if the ID exists in the map
    auto it = idToIndexMap.find(id);
    if (it != idToIndexMap.end()) {
        // If so, update the corresponding session's status and notify any waiting threads that an update has occurred
        sessions[it->second].online = online;
        lock.unlock();
        updateCondVar.notify_all();
    }
}

// Function to retrieve all user sessions
vector<UserSession> getAllSessions() {
    vector<UserSession> sessionsCopy;

    // Acquire the lock on the sessions data structure
    unique_lock<mutex> lock(sessionsMutex);

    // Copy the contents of the vector to a new vector that can be safely accessed outside the mutex
    for (auto& session : sessions) {
        sessionsCopy.push_back(session);
    }

    // Release the lock on the data structure
    lock.unlock();

    return sessionsCopy;
}

// Function to retrieve all user IDs
vector<int> getAllIds() {
    vector<int> ids;

    // Acquire the lock on the sessions data structure
    unique_lock<mutex> lock(sessionsMutex);

    // Copy the contents of the map to a new vector that can be safely accessed outside the mutex
    for (auto& [id, _] : idToIndexMap) {
        ids.push_back(id);
    }

    // Release the lock on the data structure
    lock.unlock();

    return ids;
}

int main() {
    // Initialize a message broker and a distributed service infrastructure

    // Add a new user session with ID 1, username "John", and IP address "192.168.0.1"
    addSession(1, "John", "192.168.0.1");

    // Remove the user session with ID 1
    removeSession(1);

    // Retrieve the session statistics for ID 1
    SessionStats stats = getSessionStats(1);
    cout << "Total sessions: " << stats.totalSessions << endl;
    cout << "Active sessions: " << stats.activeSessions << endl;
    cout << "Inactive sessions: " << stats.inactiveSessions << endl;

    // Update the status of the user session with ID 1 to offline
    updateSessionStatus(1, false);

    // Retrieve all user IDs
    vector<int> ids = getAllIds();
    for (auto id : ids) {
        cout << "ID: " << id << endl;
    }

    return 0;
}
```
In this example, we have defined a `Session` struct to store information about each user session. The `addSession`, `removeSession`, and `updateSessionStatus` functions add, remove, or update the status of a user session in the vector, respectively. The `getSessionStats` function retrieves the number of total, active, and inactive sessions for a given ID. The `getAllSessions` and `getAllIds` functions retrieve all user sessions and IDs, respectively.

The `main` function initializes a message broker and a distributed service infrastructure, adds a new user session with ID 1, "John", and IP address "192.168.0.1", removes the user session with ID 1, retrieves the session statistics for ID 1, updates the status of the user session with ID 1 to offline, and retrieves all user IDs.

Note that this is just an example and may not be suitable for your specific use case. You may need to modify or add additional functionality depending on your requirements.']

