// Define the linked list class to manage the dynamic linked list of NFAPI_CRC_INDICATION_PDU_T structures
class LinkedList {
 public:
  // Constructor to initialize the linked list
  LinkedList() {
    head_ = NULL;
    tail_ = NULL;
  }

  // Destructor to free the memory of the linked list
  ~LinkedList() {
    while (head_) {
      auto node = head_;
      head_ = head_->next;
      delete node;
    }
  }

  // Method to add a new NFAPI_CRC_INDICATION_PDU_T structure to the linked list
  void push(CRCIndication* data) {
    auto node = new LinkedListNode{data, NULL};
    if (tail_) {
      tail_->next = node;
    } else {
      head_ = node;
    }
    tail_ = node;
  }

  // Method to remove a NFAPI_CRC_INDICATION_PDU_T structure from the linked list
  void pop() {
    if (head_) {
      auto node = head_;
      head_ = head_->next;
      delete node;
    }
  }

  // Method to get the front of the linked list
  CRCIndication* front() {
    return head_ ? head_->data : NULL;
