    // Get the next thread from the thread pool
    ThreadPool::Thread* thread = tp->getNextThread();

    // Create a new CRC indication info structure and assign it to the current thread
    CRCIndicationInfo* crc_indication_info = new CRCIndicationInfo();
    thread->setData(crc_indication_info);

    // Process the packet in real-time using the real-time processing framework
    rtpf->processPacket(tenant_id, RX_UE_INFORMATION_TAG);
  }

  return 0;
}
