package com.pokemon;

import java.util.concurrent.locks.ReentrantLock;

public class PokemonLibrary {
    private static final Map<String, String> pokemonMap = new HashMap<>();
    private static final ReentrantLock lock = new ReentrantLock();

    public static void addPokemon(String key, String name) {
        lock.lock();
        try {
            pokemonMap.put(key, name);
        } finally {
            lock.unlock();
        }
    }

    public static boolean containsPokemon(String key) {
        lock.lock();
        try {
            return pokemonMap.containsKey(key);
        } finally {
            lock.unlock();
        }
    }

    public static String getPokemonName(String key) {
        lock.lock();
        try {
            return pokemonMap.get(key);
        } finally {
            lock.unlock();
        }
    }

    public static void removePokemon(String key) {
        lock.lock();
        try {
            pokemonMap.remove(key);
        } finally {
            lock.unlock();
        }
    }

    public static int getWeaknesses(String type) {
        switch (type) {
            case "fire":
                return 1;
            case "water":
                return 2;
            case "grass":
                return 3;
            default:
                return -1;
        }
    }
}
