    public void addTransaction(Transaction transaction) {
        transactionQueue.addTransaction(transaction);
    }

    public CompletableFuture<Void> processTransactions() {
        return CompletableFuture.runAsync(() -> {
            while (!transactionQueue.getTransactions().isEmpty()) {
                Transaction transaction = transactionQueue.getTransactions().remove();
                TransactionProcessor processor = processorRegistry.getProcessor(transaction.getProcessorName());
                if (processor != null) {
                    try {
                        processor.processTransaction(transaction);
                    } catch (Exception e) {
                        // Handle errors and exceptions appropriately
                    }
                } else {
                    // Unknown transaction processor, drop the transaction
                }
            }
        });
    }
}
