```php
<?php

namespace App\Services;

use OAuth2\Client;
use PDO;
use Psr\Log\LoggerInterface;

class UserManagementService {
  private $logger;
  private $dbConnection;
  private $oauthClient;

  public function __construct(LoggerInterface $logger, PDO $dbConnection, Client $oauthClient) {
    $this->logger = $logger;
    $this->dbConnection = $dbConnection;
    $this->oauthClient = $oauthClient;
  }

  public function getUserProfile($userId) {
    // Perform OAuth authentication and retrieve the user's profile information from the database.
    try {
      $userProfile = $this->dbConnection->query("SELECT * FROM users WHERE id = ?", [$userId])->fetch();
      if (!$userProfile) {
        throw new \Exception("User not found");
      }
      return $userProfile;
    } catch (\PDOException $e) {
      $this->logger->error($e->getMessage());
      throw new \RuntimeException("Database error", 0, $e);
    } catch (\OAuth2\Exception\AuthorizationException $e) {
      $this->logger->warning("Authentication failed: {$e->getMessage()}");
      throw new \RuntimeException("Authentication failed", 0, $e);
    }
  }

  public function updateUserProfile($userId, $profileData) {
    // Validate the input data and perform authorization checks.
    if (!$this->oauthClient->hasToken()) {
      throw new \RuntimeException("Authentication required");
    }
    if ($this->oauthClient->getUserId() !== $userId) {
      throw new \RuntimeException("Operation not allowed for this user");
    }
    // Perform the update operation on the database.
    try {
      $this->dbConnection->query("UPDATE users SET name = ?, email = ? WHERE id = ?", [$profileData["name"], $profileData["email"], $userId]);
      return true;
    } catch (\PDOException $e) {
      $this->logger->error($e->getMessage());
      throw new \RuntimeException("Database error", 0, $e);
    }
  }
}
```
This code block defines a `UserManagementService` class that provides two methods for managing user profiles: `getUserProfile()` and `updateUserProfile()`. The `getUserProfile()` method performs OAuth authentication and retrieves the user's profile information from the database, while the `updateUserProfile()` method validates the input data and performs authorization checks before performing the update operation on the database.

