      return new Promise((resolve, reject) => {
        try {
          const testResults = [];
          for (const test of module.tests) {
            let result;
            try {
              result = await testRunner.runTest(test, options);
            } catch (e) {
              console.error(`Test ${test.name} failed: ${e}`);
              return reject(e);
            }
            testResults.push({ name: test.name, status: result.status });
          }
          resolve(testResults);
        } catch (e) {
          reject(e);
        }
      });
    }
  }

  const dynamicAuthAndTest = new DynamicAuthAndTest();
  return dynamicAuthAndTest.authenticateAndTestModule(moduleName, testFunction);
};
