const reduceAsync = async (array, initialValue, callback) => {
  let result;
  try {
    result = await array.reduce(async (accumulator, currentValue) => {
      const value = await accumulator;
      return callback(value, currentValue);
    }, initialValue);
  } catch (error) {
    console.error(error);
    return error;
  }
  return result;
};
```
