public class PriorityQueuingSystem {
    private final Map<String, String> queue = new HashMap<>();

    public void enqueue(String key, String value) {
        // Queue logic
        if (queue.containsKey(key)) {
            return;
        } else {
            queue.put(key, value);
        }
    }

    public String dequeue() {
        // Dequeue logic
        if (queue.isEmpty()) {
            return null;
        } else {
            return queue.remove(queue.get(0));
        }
    }
}
